class QualificationNotReadyError(RuntimeError):
    """Formal execution is unavailable until the scene freeze is complete."""


def _json_native(
    value: Any,
    *,
    label: str = "JSON value",
    _active_containers: set[int] | None = None,
) -> Any:
    """Return an exact recursively JSON-native copy.

    Tuples normalize to lists before hashing.  Scalar subclasses, mappings
    other than exact dicts, nonfinite floats, and recursive containers fail.
    """

    if value is None or type(value) in {bool, int, str}:
        return value
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError(f"{label} contains a nonfinite float")
        return value
    if type(value) not in {dict, list, tuple}:
        raise TypeError(f"{label} contains non-JSON-native type {type(value).__name__}")
    active = set() if _active_containers is None else _active_containers
    identity = id(value)
    if identity in active:
        raise ValueError(f"{label} contains a recursive container")
    active.add(identity)
    try:
        if type(value) is dict:
            if any(type(key) is not str for key in value):
                raise TypeError(f"{label} object keys must be exact strings")
            return {
                key: _json_native(
                    item,
                    label=f"{label}.{key}",
                    _active_containers=active,
                )
                for key, item in value.items()
            }
        return [
            _json_native(
                item,
                label=f"{label}[{index}]",
                _active_containers=active,
            )
            for index, item in enumerate(value)
        ]
    finally:
        active.remove(identity)


def _canonical_json(value: Any) -> bytes:
    return json.dumps(
        _json_native(value),
        allow_nan=False,
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("ascii")


def canonical_sha256(value: Any) -> str:
    return hashlib.sha256(_canonical_json(value)).hexdigest()


def sha256_bytes(contents: bytes) -> str:
    if type(contents) is not bytes:
        raise TypeError("SHA-256 contents must be exact bytes")
    return hashlib.sha256(contents).hexdigest()


EMPTY_MODEL_STATE_SHA256 = canonical_sha256([])


def validated_sha256(value: Any, *, label: str) -> str:
    if type(value) is not str or len(value) != 64 or value != value.lower():
        raise ValueError(f"{label} must be one lowercase SHA-256")
    try:
        int(value, 16)
    except ValueError as error:
        raise ValueError(f"{label} must be lowercase hexadecimal") from error
    return value


def _strict_json_loads(contents: bytes, *, label: str) -> dict[str, Any]:
    if type(contents) is not bytes or len(contents) > MAX_JSON_BYTES:
        raise TypeError(f"{label} must be bounded exact bytes")

    def reject_constant(value: str) -> None:
        raise ValueError(f"{label} contains nonfinite constant {value!r}")

    def unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"{label} contains duplicate key {key!r}")
            result[key] = value
        return result

    value = json.loads(
        contents.decode("utf-8", errors="strict"),
        parse_constant=reject_constant,
        object_pairs_hook=unique_object,
    )
    if type(value) is not dict:
        raise TypeError(f"{label} root must be one exact object")
    return value


def _exact_equal(actual: Any, expected: Any, *, label: str) -> None:
    if type(actual) is not type(expected):
        raise ValueError(f"{label} exact type differs")
    if type(expected) is dict:
        actual_keys = tuple(actual.keys())
        expected_keys = tuple(expected.keys())
        if any(type(key) is not str for key in (*actual_keys, *expected_keys)):
            raise TypeError(f"{label} exact keys must be built-in strings")
        if len(actual_keys) != len(expected_keys) or sorted(actual_keys) != sorted(expected_keys):
            raise ValueError(f"{label} exact keys differ")
        for key in expected_keys:
            _exact_equal(actual[key], expected[key], label=f"{label}.{key}")
        return
    if type(expected) is list:
        if len(actual) != len(expected):
            raise ValueError(f"{label} exact list length differs")
        for index, item in enumerate(expected):
            _exact_equal(actual[index], item, label=f"{label}[{index}]")
        return
    if actual != expected:
        raise ValueError(f"{label} exact value differs")


def _require_exact_keys(value: Any, expected: frozenset[str], *, label: str) -> None:
    if type(value) is not dict:
        raise TypeError(f"{label} must be one exact dict")
    keys = tuple(value.keys())
    if any(type(key) is not str for key in keys) or any(type(key) is not str for key in expected):
        raise TypeError(f"{label} keys must be built-in strings")
    actual = frozenset(keys)
    if actual != expected:
        raise ValueError(
            f"{label} schema differs: missing={sorted(expected - actual)!r}, "
            f"extra={sorted(actual - expected)!r}"
        )


