GATE_METRIC_SCHEMA = tuple(rule.name for rule in GATE_RULES)
ACTION_GATE_CONSTRAINT_COUNT = 119
ACTION_GATE_CONSTRAINT_SHA256 = "68409749ac369006cd1fde13685e969995f82293b0a22296f7b33fa3c93661d4"
ACTION_GATE_CONSTRAINTS = tuple(
    (rule.name, rule.operator, float(rule.threshold)) for rule in GATE_RULES
)
if (
    len(GATE_METRIC_SCHEMA) != len(set(GATE_METRIC_SCHEMA))
    or len(ACTION_GATE_CONSTRAINTS) != ACTION_GATE_CONSTRAINT_COUNT
    or canonical_sha256(ACTION_GATE_CONSTRAINTS) != ACTION_GATE_CONSTRAINT_SHA256
    or canonical_sha256(ACTION_SENSOR_VJP_GROUPS) != ACTION_SENSOR_VJP_GROUPS_SHA256
    or canonical_sha256(ACTION_SENSOR_VJP_DISPLAY_INDICES)
    != ACTION_SENSOR_VJP_DISPLAY_INDICES_SHA256
    or canonical_sha256(ACTION_SENSOR_VJP_ORDINALS) != ACTION_SENSOR_VJP_ORDINALS_SHA256
):
    raise RuntimeError("known-action frozen gate or gradient protocol differs")


def gate_failures(metrics: Mapping[str, Any]) -> list[str]:
    if type(metrics) is not dict:
        raise TypeError("metrics must be one exact dict")
    expected = set(GATE_METRIC_SCHEMA)
    actual = set(metrics)
    if actual != expected:
        raise ValueError(
            f"metric schema differs: missing={sorted(expected - actual)!r}, "
            f"extra={sorted(actual - expected)!r}"
        )
    failures: list[str] = []
    for rule in GATE_RULES:
        raw = metrics[rule.name]
        if isinstance(raw, bool) or not isinstance(raw, Real):
            raise TypeError(f"metric {rule.name} must be a non-boolean real number")
        value = float(raw)
        if not math.isfinite(value):
            raise ValueError(f"metric {rule.name} must be finite")
        passed = {
            "le": value <= rule.threshold,
            "ge": value >= rule.threshold,
            "eq": value == rule.threshold,
        }[rule.operator]
        if not passed:
            failures.append(
                f"{rule.name}={value:.12g} violates {rule.operator} {rule.threshold:.12g}"
            )
    return failures


