def _accepted_orbital_constraint_rows() -> tuple[tuple[str, str, float], ...]:
    """Validate and expose the immutable accepted reducer surface without imports."""

    rows = FROZEN_ACCEPTED_ORBITAL_CONSTRAINTS
    if (
        type(rows) is not tuple
        or len(rows) != FROZEN_ACCEPTED_ORBITAL_CONSTRAINT_COUNT
        or any(
            type(row) is not tuple
            or len(row) != 3
            or type(row[0]) is not str
            or type(row[1]) is not str
            or row[1] not in {"le", "ge", "eq"}
            or type(row[2]) is not float
            or not math.isfinite(row[2])
            for row in rows
        )
        or canonical_sha256(rows) != FROZEN_ACCEPTED_ORBITAL_CONSTRAINT_MANIFEST_SHA256
    ):
        raise PermissionError("frozen accepted orbital constraint manifest differs")
    names = sorted({row[0] for row in rows})
    duplicate_rows = tuple(row for row in rows if row[0] == "birth_slot_physical_zero_fraction")
    if (
        len(names) != 685
        or canonical_sha256(names) != FROZEN_ACCEPTED_ORBITAL_METRIC_SCHEMA_SHA256
        or duplicate_rows
        != (
            ("birth_slot_physical_zero_fraction", "ge", 0.25),
            ("birth_slot_physical_zero_fraction", "le", 0.75),
        )
    ):
        raise PermissionError("frozen accepted orbital constraint ownership differs")
    return rows


def _accepted_orbital_gate_failures(metrics: Mapping[str, Any]) -> list[str]:
    """Reproduce the accepted owner's exact ordered .9g scalar failures locally."""

    rows = _accepted_orbital_constraint_rows()
    if type(metrics) is not dict:
        raise TypeError("inherited orbital metrics must be one exact dict")
    expected = {row[0] for row in rows}
    if set(metrics) != expected:
        raise ValueError("inherited orbital metric schema differs from its accepted owner")
    native_metrics = _json_native(copy.deepcopy(metrics), label="inherited orbital metrics")
    assert type(native_metrics) is dict
    if any(
        type(value) is not float or not math.isfinite(value) for value in native_metrics.values()
    ):
        raise TypeError("every inherited orbital metric must be one exact finite float")
    failures: list[str] = []
    for name, operator, threshold in rows:
        value = native_metrics[name]
        passed = {
            "le": value <= threshold,
            "ge": value >= threshold,
            "eq": value == threshold,
        }[operator]
        if not passed:
            comparator = {"le": ">", "ge": "<", "eq": "!="}[operator]
            failures.append(f"{name}:{value:.9g}{comparator}{threshold:.9g}")
    return failures


def _accepted_orbital_passing_metrics() -> dict[str, float]:
    """Construct one exact all-pass vector from the immutable ordered manifest."""

    metrics: dict[str, float] = {}
    for name, operator, threshold in _accepted_orbital_constraint_rows():
        metrics.setdefault(name, min(0.0, threshold) if operator == "le" else threshold)
    if _accepted_orbital_gate_failures(metrics):
        raise PermissionError("frozen accepted orbital constraints have no passing vector")
    return metrics


def _crosscheck_accepted_orbital_owner(owner: Any) -> None:
    """Fresh-science-only behavioral cross-check of the imported accepted reducer."""

    reducer = getattr(owner, "gate_failures", None)
    schema = getattr(owner, "GATE_METRIC_SCHEMA", None)
    rows = _accepted_orbital_constraint_rows()
    expected_schema = tuple(sorted({row[0] for row in rows}))
    if type(schema) is not tuple or schema != expected_schema or not callable(reducer):
        raise PermissionError("accepted orbital metric reducer surface changed")
    passing = _accepted_orbital_passing_metrics()
    probes = [passing]
    for name, operator, threshold in rows:
        probe = dict(passing)
        delta = max(1.0, abs(threshold))
        probe[name] = threshold + delta if operator in {"le", "eq"} else threshold - delta
        probes.append(probe)
    for probe in probes:
        expected_failures = _accepted_orbital_gate_failures(probe)
        observed_failures = reducer(probe)
        if (
            type(observed_failures) is not list
            or any(type(item) is not str for item in observed_failures)
            or observed_failures != expected_failures
        ):
            raise PermissionError("accepted orbital metric reducer behavior changed")


def _accepted_orbital_owner() -> Any:
    """Load and cross-check the exact accepted owner on fresh science only."""

    owner_path = (REPOSITORY_ROOT / ACCEPTED_ORBITAL_RELATIVE_PATH).resolve()
    owner_test_path = (REPOSITORY_ROOT / ACCEPTED_ORBITAL_TEST_RELATIVE_PATH).resolve()
    if sha256_bytes(stable_read_bytes(owner_path, label="accepted metric owner")) != (
        FROZEN_ACCEPTED_ORBITAL_SOURCE_SHA256
    ):
        raise PermissionError("accepted orbital metric-owner source changed")
    if sha256_bytes(stable_read_bytes(owner_test_path, label="accepted metric-owner test")) != (
        FROZEN_ACCEPTED_ORBITAL_TEST_SHA256
    ):
        raise PermissionError("accepted orbital metric-owner test changed")
    owner = importlib.import_module(
        "world_model.training.rgbd_two_visible_orbital_camera_qualification"
    )
    origin = getattr(owner, "__file__", None)
    if type(origin) is not str or Path(origin).resolve() != owner_path:
        raise PermissionError("accepted orbital metric owner has a noncanonical import origin")
    if (
        getattr(owner, "FROZEN_CERTIFICATE_SHA256", None)
        != FROZEN_ACCEPTED_ORBITAL_CERTIFICATE_SHA256
    ):
        raise PermissionError("accepted orbital certificate literal changed")
    schema = getattr(owner, "GATE_METRIC_SCHEMA", None)
    if (
        type(schema) is not tuple
        or len(schema) != 685
        or any(type(name) is not str for name in schema)
        or len(set(schema)) != 685
        or canonical_sha256(list(schema)) != FROZEN_ACCEPTED_ORBITAL_METRIC_SCHEMA_SHA256
    ):
        raise PermissionError("accepted orbital metric schema changed")
    _crosscheck_accepted_orbital_owner(owner)
    return owner


def _inherited_orbital_evidence(metrics: Mapping[str, Any]) -> dict[str, Any]:
    """Seal 685 inherited scalars under the frozen pure local reducer."""

    failures = _accepted_orbital_gate_failures(metrics)
    native_metrics = _json_native(copy.deepcopy(metrics), label="inherited orbital metrics")
    assert type(native_metrics) is dict
    _exact_equal(native_metrics, metrics, label="inherited orbital metric normalization")
    body = {
        "schema": "rgbd_known_action_inherited_orbital_evidence_v2",
        "owner": "rgbd_two_visible_orbital_camera_qualification.GATE_METRIC_SCHEMA",
        "owner_source_sha256": FROZEN_ACCEPTED_ORBITAL_SOURCE_SHA256,
        "owner_test_sha256": FROZEN_ACCEPTED_ORBITAL_TEST_SHA256,
        "owner_certificate_sha256": FROZEN_ACCEPTED_ORBITAL_CERTIFICATE_SHA256,
        "metric_schema_sha256": FROZEN_ACCEPTED_ORBITAL_METRIC_SCHEMA_SHA256,
        "metric_count": 685,
        "constraint_count": FROZEN_ACCEPTED_ORBITAL_CONSTRAINT_COUNT,
        "constraint_manifest_sha256": (FROZEN_ACCEPTED_ORBITAL_CONSTRAINT_MANIFEST_SHA256),
        "representative_ordinals": list(INHERITED_OBSERVATION_REPRESENTATIVE_ORDINALS),
        "representative_ordinals_sha256": INHERITED_OBSERVATION_REPRESENTATIVE_SHA256,
        "certificate_stale_minima": copy.deepcopy(FROZEN_ACCEPTED_STALE_CERTIFICATE_MINIMA),
        "reducer": "frozen_local.accepted_owner_gate_failures_exact_order_v1",
        "metrics": native_metrics,
        "metrics_sha256": canonical_sha256(native_metrics),
        "failures": list(failures),
        "failures_sha256": canonical_sha256(failures),
        "passed": not failures,
    }
    return {**body, "evidence_sha256": canonical_sha256(body)}


def _validated_inherited_orbital_evidence(value: Any) -> dict[str, Any]:
    """Purely recompute the accepted 685-gate result from durable evidence."""

    _require_exact_keys(value, INHERITED_ORBITAL_EVIDENCE_SCHEMA, label="inherited evidence")
    rebuilt = _inherited_orbital_evidence(value["metrics"])
    _exact_equal(value, rebuilt, label="inherited orbital evidence")
    return rebuilt


