def _frozen_config_path() -> Path:
    return REPOSITORY_ROOT / CONFIG_RELATIVE_PATH


def _canonical_run_directory() -> Path:
    return REPOSITORY_ROOT / RUN_RELATIVE_PATH


def _activate_runtime_dependencies() -> None:
    """Activate Torch and project runtime bindings only for one fresh attempt."""

    global OrpheusConfig
    global _RUNTIME_DEPENDENCIES_ACTIVE
    global load_config
    global torch

    if _RUNTIME_DEPENDENCIES_ACTIVE:
        config_module = sys.modules.get("world_model.utils.config")
        version_module = sys.modules.get("world_model.utils.version")
        if (
            torch is not sys.modules.get("torch")
            or type(config_module) is not types.ModuleType
            or type(version_module) is not types.ModuleType
            or OrpheusConfig is not getattr(config_module, "OrpheusConfig", None)
            or load_config is not getattr(config_module, "load_config", None)
            or getattr(version_module, "__version__", None) != __version__
            or getattr(version_module, "SPECIFICATION_VERSION", None) != SPECIFICATION_VERSION
            or getattr(version_module, "SIMULATOR_VERSION", None) != SIMULATOR_VERSION
        ):
            raise PermissionError("activated runtime dependency binding changed")
        return
    if any(
        value is not None
        for value in (
            torch,
            OrpheusConfig,
            load_config,
        )
    ):
        raise PermissionError("lightweight recovery module has a partial runtime binding")

    torch_module = importlib.import_module("torch")
    config_module = importlib.import_module("world_model.utils.config")
    version_module = importlib.import_module("world_model.utils.version")
    config_type = getattr(config_module, "OrpheusConfig", None)
    config_loader = getattr(config_module, "load_config", None)
    project_version = getattr(version_module, "__version__", None)
    specification_version = getattr(version_module, "SPECIFICATION_VERSION", None)
    simulator_version = getattr(version_module, "SIMULATOR_VERSION", None)
    if (
        type(torch_module) is not types.ModuleType
        or torch_module.__name__ != "torch"
        or type(config_module) is not types.ModuleType
        or config_module.__name__ != "world_model.utils.config"
        or type(version_module) is not types.ModuleType
        or version_module.__name__ != "world_model.utils.version"
        or type(config_type) is not type
        or not callable(config_loader)
        or project_version != __version__
        or specification_version != SPECIFICATION_VERSION
        or simulator_version != SIMULATOR_VERSION
    ):
        raise PermissionError("fresh-attempt runtime dependency binding differs")
    torch = torch_module
    OrpheusConfig = config_type
    load_config = config_loader
    _RUNTIME_DEPENDENCIES_ACTIVE = True


def _activate_recovery_checkpoint_dependency(
    *,
    _sys: Any = sys,
    _import_module: Any = importlib.import_module,
) -> None:
    """Import only Torch when a classified recovery must authenticate a checkpoint."""

    global torch
    if _RUNTIME_DEPENDENCIES_ACTIVE:
        if torch is not _sys.modules.get("torch"):
            raise PermissionError("fresh runtime Torch binding changed")
        return
    if torch is not None:
        if torch is not _sys.modules.get("torch"):
            raise PermissionError("recovery Torch binding changed")
        return
    project_modules = {
        name for name in _sys.modules if name == "world_model" or name.startswith("world_model.")
    }
    if project_modules != {__name__}:
        raise PermissionError("checkpoint recovery preceded project package isolation")
    torch_module = _import_module("torch")
    if (
        type(torch_module) is not types.ModuleType
        or torch_module.__name__ != "torch"
        or {
            name
            for name in _sys.modules
            if name == "world_model" or name.startswith("world_model.")
        }
        != {__name__}
    ):
        raise PermissionError("checkpoint recovery imported a project runtime dependency")
    torch = torch_module


