def stable_read_bytes(path: Path, *, label: str, maximum: int = MAX_JSON_BYTES) -> bytes:
    if type(path) is not _NATIVE_PATH_TYPE or not path.is_absolute():
        raise TypeError(f"{label} path must be one absolute native Path")
    before = path.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or before.st_size > maximum:
        raise PermissionError(f"{label} must be one bounded single-link regular file")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = os.open(path, flags)
    try:
        opened = os.fstat(descriptor)
        chunks: list[bytes] = []
        total = 0
        while True:
            chunk = os.read(descriptor, 65_536)
            if not chunk:
                break
            chunks.append(chunk)
            total += len(chunk)
            if total > maximum:
                raise ValueError(f"{label} exceeds its byte limit")
        after_open = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    after = path.lstat()
    identity = lambda value: (  # noqa: E731
        value.st_dev,
        value.st_ino,
        value.st_mode,
        value.st_nlink,
        value.st_size,
        value.st_mtime_ns,
        value.st_ctime_ns,
    )
    if identity(before) != identity(opened) or identity(opened) != identity(after_open):
        raise PermissionError(f"{label} changed during descriptor read")
    if identity(after_open) != identity(after):
        raise PermissionError(f"{label} changed during pathname revalidation")
    contents = b"".join(chunks)
    if len(contents) != before.st_size:
        raise PermissionError(f"{label} length changed during read")
    return contents


def require_frozen_config(path: Path) -> OrpheusConfig:
    expected = _frozen_config_path()
    if type(path) is not _NATIVE_PATH_TYPE or path.resolve() != expected.resolve():
        raise ValueError("qualification config path must be the canonical frozen path")
    contents = stable_read_bytes(path.resolve(), label="frozen config")
    if sha256_bytes(contents) != FROZEN_CONFIG_SHA256:
        raise RuntimeError("known-action frozen config SHA-256 differs")
    config = load_config(path)
    assert_known_action_config(config)
    return config


def assert_known_action_config(config: OrpheusConfig) -> None:
    if not isinstance(config, OrpheusConfig):
        raise TypeError("config must be an OrpheusConfig")
    expected = {
        "project_name": "orpheus-rgbd-known-action-planning-v1-cpu",
        "project_seed": 0,
        "objects": (2, 2),
        "gravity": (0.0, 0.0, 0.0),
        "radius": (0.21, 0.21),
        "mass": (1.0, 1.0),
        "drag": (0.05, 0.05),
        "camera": "orbit",
        "external_probability": 0.0,
        "history": 16,
        "analytic": True,
        "hypotheses": False,
    }
    actual = {
        "project_name": config.project.name,
        "project_seed": config.project.seed,
        "objects": (config.simulator.min_objects, config.simulator.max_objects),
        "gravity": config.simulator.gravity,
        "radius": config.simulator.radius_range,
        "mass": config.simulator.mass_range,
        "drag": config.simulator.drag_range,
        "camera": config.simulator.camera_motion,
        "external_probability": config.simulator.external_impulse_probability,
        "history": config.model.rgbd.temporal_history_size,
        "analytic": config.model.dynamics.analytic_free_motion_only,
        "hypotheses": config.runtime.hypothesis_pool_enabled,
    }
    _exact_equal(actual, expected, label="known-action config semantics")
    if (
        not config.model.rgbd.enabled
        or config.model.rgb.enabled
        or config.runtime.modality != "rgbd"
        or config.model.rgbd.proposal_count != 2
        or config.model.filter.enable_learned_corrector
        or config.model.identification.enabled
    ):
        raise ValueError("known-action profile learned/observation semantics differ")


