def _validated_git_oid(value: Any, *, label: str) -> str:
    if type(value) is not str or len(value) != 2 * _GIT_OID_BYTES or value != value.lower():
        raise ValueError(f"{label} must be one lowercase Git object ID")
    try:
        int(value, 16)
    except ValueError as error:
        raise ValueError(f"{label} must be hexadecimal") from error
    return value


def _git_repository_paths(root: Path) -> tuple[Path, Path, Path]:
    if type(root) is not _NATIVE_PATH_TYPE or not root.is_absolute() or root.resolve() != root:
        raise PermissionError("Git root must be one canonical absolute native Path")
    git_dir = root / ".git"
    metadata = git_dir.lstat()
    if not stat.S_ISDIR(metadata.st_mode) or git_dir.resolve() != git_dir:
        raise PermissionError("Git directory must be the canonical .git directory")
    return git_dir, git_dir, root


def _git_environment(root: Path) -> dict[str, str]:
    git_dir, common_dir, work_tree = _git_repository_paths(root)
    return {
        "GIT_DIR": os.fspath(git_dir),
        "GIT_COMMON_DIR": os.fspath(common_dir),
        "GIT_WORK_TREE": os.fspath(work_tree),
        "GIT_INDEX_FILE": os.fspath(git_dir / "index"),
        "GIT_NO_REPLACE_OBJECTS": "1",
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_CONFIG_GLOBAL": os.devnull,
        "GIT_CONFIG_SYSTEM": os.devnull,
        "GIT_ATTR_NOSYSTEM": "1",
        "GIT_LITERAL_PATHSPECS": "1",
        "GIT_OPTIONAL_LOCKS": "0",
        "GIT_TERMINAL_PROMPT": "0",
        "LANG": "C",
        "LC_ALL": "C",
        "PATH": "/usr/bin:/bin",
    }


def _git_command(root: Path, arguments: Sequence[str]) -> list[str]:
    git_dir, _, work_tree = _git_repository_paths(root)
    return [
        _TRUSTED_GIT,
        "--no-replace-objects",
        f"--git-dir={git_dir}",
        f"--work-tree={work_tree}",
        "-c",
        "core.hooksPath=/dev/null",
        "-c",
        "core.fsmonitor=false",
        "-c",
        "core.untrackedCache=false",
        *arguments,
    ]


def _git_bytes(root: Path, arguments: Sequence[str], *, label: str) -> bytes:
    completed = subprocess.run(
        _git_command(root, arguments),
        cwd=root,
        env=_git_environment(root),
        check=True,
        capture_output=True,
        text=False,
    )
    if type(completed.stdout) is not bytes or len(completed.stdout) > _GIT_MAX_OUTPUT_BYTES:
        raise RuntimeError(f"git returned invalid or oversized {label}")
    return completed.stdout


def _git_text(
    root: Path,
    arguments: Sequence[str],
    *,
    label: str,
    allow_empty: bool = False,
) -> str:
    raw = _git_bytes(root, arguments, label=label)
    value = raw.decode("utf-8", errors="strict").strip()
    if not value and not allow_empty:
        raise RuntimeError(f"git returned empty {label}")
    return value


def _null_terminated_git_fields(raw: bytes, *, label: str) -> list[str]:
    if type(raw) is not bytes or not raw or len(raw) > _GIT_MAX_OUTPUT_BYTES:
        raise PermissionError(f"{label} is empty, invalid, or oversized")
    if not raw.endswith(b"\0") or b"\0\0" in raw:
        raise PermissionError(f"{label} lacks exact NUL framing")
    try:
        fields = raw[:-1].decode("utf-8", errors="strict").split("\0")
    except UnicodeDecodeError as error:
        raise PermissionError(f"{label} is not strict UTF-8") from error
    if any(not field or "\n" in field or "\r" in field for field in fields):
        raise PermissionError(f"{label} contains an invalid field")
    return fields


def _canonical_git_config_pairs(raw: bytes, *, label: str) -> list[dict[str, str]]:
    if type(raw) is not bytes or not raw or len(raw) > _GIT_MAX_OUTPUT_BYTES:
        raise PermissionError(f"{label} is empty, invalid, or oversized")
    if not raw.endswith(b"\0") or b"\0\0" in raw:
        raise PermissionError(f"{label} lacks exact NUL record framing")
    pairs: list[dict[str, str]] = []
    for raw_record in raw[:-1].split(b"\0"):
        raw_key, separator, raw_value = raw_record.partition(b"\n")
        if separator != b"\n" or not raw_key or b"\r" in raw_key or b"\n" in raw_key:
            raise PermissionError(f"{label} contains an invalid key/value record")
        try:
            key = raw_key.decode("utf-8", errors="strict").casefold()
            value = raw_value.decode("utf-8", errors="strict")
        except UnicodeDecodeError as error:
            raise PermissionError(f"{label} is not strict UTF-8") from error
        if not key or "\0" in key or "\0" in value:
            raise PermissionError(f"{label} contains an invalid key or value")
        pairs.append({"key": key, "value": value})
    return sorted(pairs, key=lambda pair: (pair["key"], pair["value"]))


def _git_config_path_state(root: Path) -> dict[str, Any]:
    git_dir, _, _ = _git_repository_paths(root)
    local_path = git_dir / "config"
    metadata = local_path.lstat()
    if (
        not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or local_path.resolve() != local_path
    ):
        raise PermissionError("local Git config must be one canonical single-link regular file")
    worktree_path = git_dir / "config.worktree"
    try:
        worktree_path.lstat()
    except FileNotFoundError:
        pass
    else:
        raise PermissionError("per-worktree Git config must be exactly absent")
    return {
        "schema": "rgbd_known_action_git_config_paths_v1",
        "local": {
            "path": os.fspath(local_path),
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "mode": metadata.st_mode,
            "links": metadata.st_nlink,
            "bytes": metadata.st_size,
            "mtime_ns": metadata.st_mtime_ns,
            "ctime_ns": metadata.st_ctime_ns,
        },
        "worktree": {
            "path": os.fspath(worktree_path),
            "state": "absent",
        },
    }


def _forbidden_git_config_key(key: str) -> bool:
    return (
        key == "extensions.worktreeconfig"
        or (key.startswith("remote.") and key.endswith(".pushurl"))
        or (key.startswith("url.") and key.endswith(".insteadof"))
        or (key.startswith("url.") and key.endswith(".pushinsteadof"))
        or key.startswith("include.")
        or key.startswith("includeif.")
    )


def _approved_git_config_snapshot(root: Path) -> dict[str, Any]:
    path_state = _git_config_path_state(root)
    local_pairs = _canonical_git_config_pairs(
        _git_bytes(
            root,
            ["config", "--local", "--no-includes", "--null", "--list"],
            label="local Git config pairs",
        ),
        label="local Git config pairs",
    )
    effective_pairs = _canonical_git_config_pairs(
        _git_bytes(
            root,
            ["config", "--no-includes", "--null", "--list"],
            label="effective Git config pairs",
        ),
        label="effective Git config pairs",
    )
    if _git_config_path_state(root) != path_state:
        raise PermissionError("canonical Git config path changed during snapshot")
    for scope, pairs in (("local", local_pairs), ("effective", effective_pairs)):
        for pair in pairs:
            if _forbidden_git_config_key(pair["key"]):
                raise PermissionError(
                    f"{scope} Git config contains forbidden directive {pair['key']}"
                )
    expected = (
        (f"branch.{_APPROVED_BRANCH}.remote", _APPROVED_REMOTE_NAME),
        (f"branch.{_APPROVED_BRANCH}.merge", _APPROVED_BRANCH_MERGE_REF),
        (f"remote.{_APPROVED_REMOTE_NAME}.url", _APPROVED_REMOTE_URL),
    )
    approved: list[dict[str, str]] = []
    for key, expected_value in expected:
        canonical_key = key.casefold()
        for scope, pairs in (("local", local_pairs), ("effective", effective_pairs)):
            values = [pair["value"] for pair in pairs if pair["key"] == canonical_key]
            if values != [expected_value]:
                raise PermissionError(
                    f"{scope} Git config {canonical_key} is not the approved singleton"
                )
        approved.append({"key": canonical_key, "value": expected_value})
    for pair in local_pairs:
        if effective_pairs.count(pair) < local_pairs.count(pair):
            raise PermissionError("effective Git config omits or overrides a local value")
    return {
        "schema": "rgbd_known_action_git_config_guard_v2",
        "approved": sorted(approved, key=lambda pair: (pair["key"], pair["value"])),
        "config_paths": path_state,
        "local_pairs": local_pairs,
        "effective_pairs": effective_pairs,
    }


def _remote_transport_profile() -> dict[str, Any]:
    environment = {
        "GIT_CONFIG_GLOBAL": os.devnull,
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_CONFIG_SYSTEM": os.devnull,
        "GIT_NO_REPLACE_OBJECTS": "1",
        "GIT_OPTIONAL_LOCKS": "0",
        "GIT_ALLOW_PROTOCOL": "ssh",
        "GIT_PROTOCOL_FROM_USER": "0",
        "GIT_SSH_COMMAND": _REMOTE_SSH_COMMAND_TEMPLATE,
        "GIT_SSH_VARIANT": "ssh",
        "GIT_TERMINAL_PROMPT": "0",
        "LANG": "C",
        "LC_ALL": "C",
        "PATH": "/usr/bin:/bin",
    }
    return {
        "schema": "rgbd_known_action_remote_transport_v1",
        "argv": [
            _TRUSTED_GIT,
            "ls-remote",
            "--exit-code",
            "--refs",
            _APPROVED_REMOTE_URL,
            _APPROVED_BRANCH_MERGE_REF,
        ],
        "cwd": _REMOTE_PROBE_CWD,
        "credential_profile": "owned_stable_ssh_agent_socket_v1",
        "environment": environment,
        "pinned_host_key_fingerprint": _PINNED_GITHUB_HOST_KEY_FINGERPRINT,
        "pinned_known_hosts_sha256": sha256_bytes(_PINNED_GITHUB_HOST_KEY.encode("ascii")),
        "timeout_seconds": _REMOTE_PROBE_TIMEOUT_SECONDS,
        "temporary_directory": _REMOTE_TEMPORARY_DIRECTORY,
    }


def _validated_ssh_agent_socket(
    *,
    _environ: Mapping[str, str] = os.environ,
    _lstat: Any = os.lstat,
    _is_socket: Any = stat.S_ISSOCK,
    _geteuid: Any = os.geteuid,
) -> tuple[str, tuple[int, int, int, int, int, int]]:
    path = _environ.get("SSH_AUTH_SOCK")
    if (
        type(path) is not str
        or not path
        or not os.path.isabs(path)
        or os.path.normpath(path) != path
        or "\0" in path
    ):
        raise PermissionError("SSH agent socket path is absent or noncanonical")
    metadata = _lstat(path)
    if not _is_socket(metadata.st_mode) or metadata.st_uid != _geteuid() or metadata.st_nlink != 1:
        raise PermissionError("SSH agent authority is not one owned live socket")
    identity = (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_nlink,
    )
    return path, identity


def _remote_transport(
    command: Sequence[str],
    *,
    cwd: str,
    env: Mapping[str, str],
    timeout: int,
    known_hosts: bytes,
    _run: Any = subprocess.run,
    _agent: Any = _validated_ssh_agent_socket,
) -> subprocess.CompletedProcess[bytes]:
    if known_hosts != _PINNED_GITHUB_HOST_KEY.encode("ascii"):
        raise PermissionError("remote transport known-host material differs")
    if type(env) is not dict or env != _remote_transport_profile()["environment"]:
        raise PermissionError("remote transport environment differs from the fixed profile")
    agent_path, agent_identity = _agent()
    with tempfile.TemporaryDirectory(
        prefix="rgbd-known-action-host-",
        dir=_REMOTE_TEMPORARY_DIRECTORY,
    ) as temporary:
        known_hosts_path = Path(temporary) / "known_hosts"
        descriptor = os.open(
            known_hosts_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0),
            0o600,
        )
        try:
            written = 0
            while written < len(known_hosts):
                written += os.write(descriptor, known_hosts[written:])
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        exact_environment = dict(env)
        if "SSH_AUTH_SOCK" in exact_environment:
            raise PermissionError("remote transport environment preloads agent authority")
        exact_environment["SSH_AUTH_SOCK"] = agent_path
        template = exact_environment.get("GIT_SSH_COMMAND")
        if template != _REMOTE_SSH_COMMAND_TEMPLATE or template.count("{known_hosts_file}") != 1:
            raise PermissionError("remote transport SSH command template differs")
        exact_environment["GIT_SSH_COMMAND"] = template.replace(
            "{known_hosts_file}", os.fspath(known_hosts_path)
        )
        completed = _run(
            list(command),
            cwd=cwd,
            env=exact_environment,
            check=False,
            capture_output=True,
            text=False,
            timeout=timeout,
        )
        final_agent_path, final_agent_identity = _agent()
        if final_agent_path != agent_path or final_agent_identity != agent_identity:
            raise PermissionError("SSH agent socket changed during remote publication probe")
        return completed


def _probe_remote_publication(commit: str) -> dict[str, Any]:
    commit = _validated_git_oid(commit, label="remote publication commit")
    profile = _remote_transport_profile()
    try:
        completed = _remote_transport(
            profile["argv"],
            cwd=profile["cwd"],
            env=profile["environment"],
            timeout=profile["timeout_seconds"],
            known_hosts=_PINNED_GITHUB_HOST_KEY.encode("ascii"),
        )
    except subprocess.TimeoutExpired as error:
        raise PermissionError("approved remote publication probe timed out") from error
    if (
        type(completed.returncode) is not int
        or completed.returncode != 0
        or type(completed.stdout) is not bytes
        or type(completed.stderr) is not bytes
        or len(completed.stdout) > _REMOTE_PROBE_MAX_OUTPUT_BYTES
        or len(completed.stderr) > _REMOTE_PROBE_MAX_OUTPUT_BYTES
    ):
        raise PermissionError("approved remote publication probe failed or was oversized")
    expected = f"{commit}\t{_APPROVED_BRANCH_MERGE_REF}\n".encode("ascii")
    if completed.stdout != expected:
        raise PermissionError("approved remote advertised ref differs from exact HEAD")
    return {
        "schema": "rgbd_known_action_remote_publication_v1",
        "git_executable": _TRUSTED_GIT,
        "literal_url": _APPROVED_REMOTE_URL,
        "literal_ref": _APPROVED_BRANCH_MERGE_REF,
        "advertised_commit": commit,
        "advertisement_sha256": sha256_bytes(completed.stdout),
        "transport_profile": profile,
    }


def _git_object_oid(kind: str, contents: bytes) -> str:
    if kind not in {"blob", "commit", "tree"} or type(contents) is not bytes:
        raise TypeError("Git object framing requires a supported kind and exact bytes")
    framed = f"{kind} {len(contents)}\0".encode("ascii") + contents
    return hashlib.sha1(framed).hexdigest()


def _verified_git_object(root: Path, oid: str, *, kind: str, label: str) -> bytes:
    oid = _validated_git_oid(oid, label=f"{label} OID")
    reported_kind = _git_text(root, ["cat-file", "-t", oid], label=f"{label} type")
    size_text = _git_text(root, ["cat-file", "-s", oid], label=f"{label} size")
    if not size_text.isascii() or not size_text.isdecimal() or str(int(size_text)) != size_text:
        raise PermissionError(f"{label} Git size is not canonical")
    contents = _git_bytes(root, ["cat-file", kind, oid], label=f"{label} contents")
    if (
        reported_kind != kind
        or int(size_text) != len(contents)
        or _git_object_oid(kind, contents) != oid
    ):
        raise PermissionError(f"{label} Git object framing differs")
    return contents


def _blob_binding(root: Path, commit: str, relative: str, *, label: str) -> dict[str, Any]:
    if (
        type(relative) is not str
        or not relative
        or Path(relative).is_absolute()
        or any(part in {"", ".", ".."} for part in relative.split("/"))
    ):
        raise ValueError(f"{label} path is not one canonical repository-relative path")
    oid = _validated_git_oid(
        _git_text(root, ["rev-parse", f"{commit}:{relative}"], label=f"{label} blob OID"),
        label=f"{label} blob OID",
    )
    blob = _verified_git_object(root, oid, kind="blob", label=label)
    tree_line = _git_bytes(
        root,
        ["ls-tree", "-z", commit, "--", relative],
        label=f"{label} tree entry",
    )
    expected_suffix = b"\t" + relative.encode("utf-8") + b"\0"
    if tree_line.count(b"\0") != 1 or not tree_line.endswith(expected_suffix):
        raise PermissionError(f"{label} tree entry framing differs")
    prefix = tree_line[: -len(expected_suffix)].decode("ascii", errors="strict")
    parts = prefix.split(" ")
    if len(parts) != 3 or parts[1] != "blob" or parts[2] != oid or parts[0] != "100644":
        raise PermissionError(f"{label} must be one regular non-executable Git blob")
    path = root / relative
    first = stable_read_bytes(path, label=f"{label} worktree", maximum=_GIT_MAX_OUTPUT_BYTES)
    second = stable_read_bytes(path, label=f"{label} worktree", maximum=_GIT_MAX_OUTPUT_BYTES)
    if first != second or first != blob:
        raise PermissionError(f"{label} worktree bytes differ from exact HEAD blob")
    return {
        "path": relative,
        "mode": parts[0],
        "blob_oid": oid,
        "blob_sha256": sha256_bytes(blob),
        "worktree_sha256": sha256_bytes(first),
        "bytes": len(blob),
    }


SOURCE_PROVENANCE_SCHEMA = frozenset(
    {
        "schema",
        "repository_root",
        "branch",
        "remote_name",
        "remote_url",
        "branch_merge_ref",
        "commit",
        "tree",
        "upstream_ref",
        "upstream_commit",
        "ahead",
        "behind",
        "dirty",
        "object_format",
        "remote_publication",
        "publication_surface_blobs",
        "publication_surface_sha256",
    }
)
BLOB_BINDING_SCHEMA = frozenset(
    {"path", "mode", "blob_oid", "blob_sha256", "worktree_sha256", "bytes"}
)
REMOTE_PUBLICATION_SCHEMA = frozenset(
    {
        "schema",
        "git_executable",
        "literal_url",
        "literal_ref",
        "advertised_commit",
        "advertisement_sha256",
        "transport_profile",
        "config_guard",
        "config_guard_sha256",
    }
)


def _validated_git_config_pairs(value: Any, *, label: str) -> list[dict[str, str]]:
    if type(value) is not list:
        raise TypeError(f"{label} must be one exact list")
    pairs: list[dict[str, str]] = []
    for index, pair in enumerate(value):
        _require_exact_keys(
            pair,
            frozenset({"key", "value"}),
            label=f"{label} pair {index}",
        )
        key = pair["key"]
        item = pair["value"]
        if (
            type(key) is not str
            or not key
            or key != key.casefold()
            or "\0" in key
            or "\r" in key
            or "\n" in key
            or type(item) is not str
            or "\0" in item
        ):
            raise ValueError(f"{label} pair {index} is noncanonical")
        pairs.append({"key": key, "value": item})
    if pairs != sorted(pairs, key=lambda pair: (pair["key"], pair["value"])):
        raise ValueError(f"{label} pairs are not in canonical sorted order")
    return pairs


def _validated_git_config_paths(value: Any, *, repository_root: str) -> dict[str, Any]:
    _require_exact_keys(
        value,
        frozenset({"schema", "local", "worktree"}),
        label="remote config paths",
    )
    if (
        type(repository_root) is not str
        or not repository_root
        or not os.path.isabs(repository_root)
        or os.path.normpath(repository_root) != repository_root
        or "\0" in repository_root
        or value["schema"] != "rgbd_known_action_git_config_paths_v1"
    ):
        raise ValueError("remote config repository/path schema is noncanonical")
    local = value["local"]
    worktree = value["worktree"]
    _require_exact_keys(
        local,
        frozenset(
            {
                "path",
                "device",
                "inode",
                "mode",
                "links",
                "bytes",
                "mtime_ns",
                "ctime_ns",
            }
        ),
        label="remote local config path",
    )
    _require_exact_keys(
        worktree,
        frozenset({"path", "state"}),
        label="remote worktree config path",
    )
    expected_git_dir = os.path.join(repository_root, ".git")
    expected_local = os.path.join(expected_git_dir, "config")
    expected_worktree = os.path.join(expected_git_dir, "config.worktree")
    numeric_names = ("device", "inode", "mode", "links", "bytes", "mtime_ns", "ctime_ns")
    if (
        local["path"] != expected_local
        or worktree != {"path": expected_worktree, "state": "absent"}
        or any(type(local[name]) is not int for name in numeric_names)
        or local["device"] < 0
        or local["inode"] <= 0
        or not stat.S_ISREG(local["mode"])
        or local["links"] != 1
        or local["bytes"] < 0
        or local["mtime_ns"] < 0
        or local["ctime_ns"] < 0
    ):
        raise ValueError("remote config canonical path state differs")
    return {
        "schema": value["schema"],
        "local": {name: local[name] for name in local},
        "worktree": dict(worktree),
    }


def _validated_git_config_guard(value: Any, *, repository_root: str) -> dict[str, Any]:
    _require_exact_keys(
        value,
        frozenset(
            {
                "schema",
                "approved",
                "config_paths",
                "local_pairs",
                "effective_pairs",
            }
        ),
        label="remote config guard",
    )
    expected_approved = sorted(
        [
            {
                "key": f"branch.{_APPROVED_BRANCH}.remote".casefold(),
                "value": _APPROVED_REMOTE_NAME,
            },
            {
                "key": f"branch.{_APPROVED_BRANCH}.merge".casefold(),
                "value": _APPROVED_BRANCH_MERGE_REF,
            },
            {
                "key": f"remote.{_APPROVED_REMOTE_NAME}.url".casefold(),
                "value": _APPROVED_REMOTE_URL,
            },
        ],
        key=lambda pair: (pair["key"], pair["value"]),
    )
    if value["schema"] != "rgbd_known_action_git_config_guard_v2":
        raise ValueError("remote config guard schema identity differs")
    approved = _validated_git_config_pairs(value["approved"], label="approved Git config")
    if approved != expected_approved:
        raise ValueError("remote approved Git config binding differs")
    config_paths = _validated_git_config_paths(
        value["config_paths"],
        repository_root=repository_root,
    )
    local_pairs = _validated_git_config_pairs(
        value["local_pairs"],
        label="local Git config",
    )
    effective_pairs = _validated_git_config_pairs(
        value["effective_pairs"],
        label="effective Git config",
    )
    for scope, pairs in (("local", local_pairs), ("effective", effective_pairs)):
        forbidden = [pair["key"] for pair in pairs if _forbidden_git_config_key(pair["key"])]
        if forbidden:
            raise ValueError(f"{scope} Git config contains forbidden directive {forbidden[0]}")
        for expected in expected_approved:
            matches = [pair["value"] for pair in pairs if pair["key"] == expected["key"]]
            if matches != [expected["value"]]:
                raise ValueError(
                    f"{scope} Git config {expected['key']} is not the approved singleton"
                )
    command_pairs = [
        {"key": "core.fsmonitor", "value": "false"},
        {"key": "core.hookspath", "value": "/dev/null"},
        {"key": "core.untrackedcache", "value": "false"},
    ]
    expected_effective = sorted(
        [*local_pairs, *command_pairs],
        key=lambda pair: (pair["key"], pair["value"]),
    )
    if effective_pairs != expected_effective:
        raise ValueError("effective Git config is not the exact local-plus-command multimap")
    return {
        "schema": value["schema"],
        "approved": approved,
        "config_paths": config_paths,
        "local_pairs": local_pairs,
        "effective_pairs": effective_pairs,
    }


def capture_published_source(
    root: Path,
    *,
    surface_paths: Mapping[str, str] = PUBLICATION_SURFACE_PATHS,
) -> dict[str, Any]:
    """Capture a clean upstream-equal source with exact Git object bindings."""

    _git_repository_paths(root)
    if type(surface_paths) is not dict or not surface_paths:
        raise TypeError("publication surface paths must be one nonempty exact dict")
    if any(
        type(name) is not str or type(path) is not str for name, path in surface_paths.items()
    ) or len(set(surface_paths.values())) != len(surface_paths):
        raise ValueError("publication surface names and paths must be distinct exact strings")
    status = _git_bytes(
        root,
        ["status", "--porcelain=v1", "-z", "--untracked-files=all"],
        label="worktree status",
    )
    if status:
        raise PermissionError("formal source requires a clean worktree including untracked files")
    object_format = _git_text(
        root,
        ["rev-parse", "--show-object-format"],
        label="object format",
    )
    if object_format != _GIT_OBJECT_FORMAT:
        raise PermissionError("formal source requires the pinned SHA-1 Git object format")
    commit = _validated_git_oid(
        _git_text(root, ["rev-parse", "HEAD"], label="HEAD"),
        label="HEAD",
    )
    branch = _git_text(root, ["symbolic-ref", "--quiet", "--short", "HEAD"], label="branch")
    config_snapshot = _approved_git_config_snapshot(root)
    remote_name = _APPROVED_REMOTE_NAME
    branch_merge_ref = _APPROVED_BRANCH_MERGE_REF
    remote_url = _APPROVED_REMOTE_URL
    upstream_ref = _git_text(
        root,
        ["rev-parse", "--symbolic-full-name", "@{upstream}"],
        label="upstream ref",
    )
    if (
        branch != _APPROVED_BRANCH
        or remote_name != _APPROVED_REMOTE_NAME
        or remote_url != _APPROVED_REMOTE_URL
        or branch_merge_ref != _APPROVED_BRANCH_MERGE_REF
        or upstream_ref != _APPROVED_UPSTREAM_REF
    ):
        raise PermissionError("formal source branch/remote/upstream configuration differs")
    upstream_commit = _validated_git_oid(
        _git_text(root, ["rev-parse", "@{upstream}"], label="upstream commit"),
        label="upstream commit",
    )
    divergence = _git_text(
        root,
        ["rev-list", "--left-right", "--count", "HEAD...@{upstream}"],
        label="upstream divergence",
    ).split()
    if len(divergence) != 2 or any(not item.isdecimal() for item in divergence):
        raise PermissionError("upstream divergence is malformed")
    ahead, behind = map(int, divergence)
    if commit != upstream_commit or ahead != 0 or behind != 0:
        raise PermissionError("formal source must equal its configured upstream exactly")
    commit_bytes = _verified_git_object(root, commit, kind="commit", label="HEAD commit")
    first_line = commit_bytes.split(b"\n", 1)[0]
    if not first_line.startswith(b"tree "):
        raise PermissionError("HEAD commit lacks an exact leading tree binding")
    tree = _validated_git_oid(
        first_line.removeprefix(b"tree ").decode("ascii", errors="strict"),
        label="HEAD tree",
    )
    _verified_git_object(root, tree, kind="tree", label="HEAD tree")
    blobs = {
        name: _blob_binding(root, commit, relative, label=f"publication {name}")
        for name, relative in surface_paths.items()
    }
    remote_publication = _probe_remote_publication(commit)
    post_remote_config_snapshot = _approved_git_config_snapshot(root)
    if post_remote_config_snapshot != config_snapshot:
        raise PermissionError("published source changed during exact Git capture")
    remote_publication["config_guard"] = config_snapshot
    remote_publication["config_guard_sha256"] = canonical_sha256(config_snapshot)
    final_status = _git_bytes(
        root,
        ["status", "--porcelain=v1", "-z", "--untracked-files=all"],
        label="final worktree status",
    )
    final_commit = _validated_git_oid(
        _git_text(root, ["rev-parse", "HEAD"], label="final HEAD"),
        label="final HEAD",
    )
    final_upstream = _validated_git_oid(
        _git_text(root, ["rev-parse", "@{upstream}"], label="final upstream"),
        label="final upstream",
    )
    final_branch = _git_text(
        root,
        ["symbolic-ref", "--quiet", "--short", "HEAD"],
        label="final branch",
    )
    final_config_snapshot = _approved_git_config_snapshot(root)
    final_upstream_ref = _git_text(
        root,
        ["rev-parse", "--symbolic-full-name", "@{upstream}"],
        label="final upstream ref",
    )
    final_divergence = _git_text(
        root,
        ["rev-list", "--left-right", "--count", "HEAD...@{upstream}"],
        label="final upstream divergence",
    ).split()
    if (
        final_status
        or final_commit != commit
        or final_upstream != upstream_commit
        or final_branch != branch
        or final_config_snapshot != config_snapshot
        or final_upstream_ref != upstream_ref
        or final_divergence != ["0", "0"]
    ):
        raise PermissionError("published source changed during exact Git capture")
    source = {
        "schema": "rgbd_known_action_published_source_v2",
        "repository_root": os.fspath(root),
        "branch": branch,
        "remote_name": remote_name,
        "remote_url": remote_url,
        "branch_merge_ref": branch_merge_ref,
        "commit": commit,
        "tree": tree,
        "upstream_ref": upstream_ref,
        "upstream_commit": upstream_commit,
        "ahead": ahead,
        "behind": behind,
        "dirty": False,
        "object_format": object_format,
        "remote_publication": remote_publication,
        "publication_surface_blobs": blobs,
        "publication_surface_sha256": {
            name: binding["blob_sha256"] for name, binding in blobs.items()
        },
    }
    return _validated_source_provenance(source, expected_surface=surface_paths)


def _validated_source_provenance(
    value: Any,
    *,
    expected_surface: Mapping[str, str] = PUBLICATION_SURFACE_PATHS,
) -> dict[str, Any]:
    _require_exact_keys(value, SOURCE_PROVENANCE_SCHEMA, label="source provenance")
    if value["schema"] != "rgbd_known_action_published_source_v2":
        raise ValueError("source provenance schema identity differs")
    for name in ("commit", "tree", "upstream_commit"):
        _validated_git_oid(value[name], label=f"source {name}")
    if (
        type(value["repository_root"]) is not str
        or value["branch"] != _APPROVED_BRANCH
        or value["remote_name"] != _APPROVED_REMOTE_NAME
        or value["remote_url"] != _APPROVED_REMOTE_URL
        or value["branch_merge_ref"] != _APPROVED_BRANCH_MERGE_REF
        or value["upstream_ref"] != _APPROVED_UPSTREAM_REF
        or type(value["ahead"]) is not int
        or type(value["behind"]) is not int
        or value["ahead"] != 0
        or value["behind"] != 0
        or value["dirty"] is not False
        or value["object_format"] != _GIT_OBJECT_FORMAT
        or value["commit"] != value["upstream_commit"]
    ):
        raise ValueError("source provenance clean/upstream binding differs")
    remote = value["remote_publication"]
    _require_exact_keys(remote, REMOTE_PUBLICATION_SCHEMA, label="remote publication")
    advertised = _validated_git_oid(
        remote["advertised_commit"],
        label="remote advertised commit",
    )
    expected_advertisement = f"{value['commit']}\t{_APPROVED_BRANCH_MERGE_REF}\n".encode("ascii")
    _exact_equal(
        remote["transport_profile"],
        _remote_transport_profile(),
        label="remote transport profile",
    )
    config_guard = _validated_git_config_guard(
        remote["config_guard"],
        repository_root=value["repository_root"],
    )
    if (
        remote["schema"] != "rgbd_known_action_remote_publication_v1"
        or remote["git_executable"] != _TRUSTED_GIT
        or remote["literal_url"] != _APPROVED_REMOTE_URL
        or remote["literal_ref"] != _APPROVED_BRANCH_MERGE_REF
        or advertised != value["commit"]
        or advertised != value["upstream_commit"]
        or validated_sha256(
            remote["advertisement_sha256"],
            label="remote advertisement",
        )
        != sha256_bytes(expected_advertisement)
        or validated_sha256(
            remote["config_guard_sha256"],
            label="remote config guard",
        )
        != canonical_sha256(config_guard)
    ):
        raise ValueError("remote publication binding differs")
    blobs = value["publication_surface_blobs"]
    hashes = value["publication_surface_sha256"]
    if type(blobs) is not dict or set(blobs) != set(expected_surface):
        raise ValueError("source publication blob inventory differs")
    if type(hashes) is not dict or set(hashes) != set(expected_surface):
        raise ValueError("source publication hash inventory differs")
    for name, relative in expected_surface.items():
        binding = blobs[name]
        _require_exact_keys(binding, BLOB_BINDING_SCHEMA, label=f"source blob {name}")
        if (
            binding["path"] != relative
            or binding["mode"] != "100644"
            or type(binding["bytes"]) is not int
            or binding["bytes"] < 0
        ):
            raise ValueError(f"source blob {name} binding differs")
        _validated_git_oid(binding["blob_oid"], label=f"source blob {name} OID")
        blob_hash = validated_sha256(binding["blob_sha256"], label=f"source blob {name}")
        if (
            validated_sha256(
                binding["worktree_sha256"],
                label=f"source worktree {name}",
            )
            != blob_hash
            or validated_sha256(hashes[name], label=f"source surface {name}") != blob_hash
        ):
            raise ValueError(f"source blob {name} SHA-256 binding differs")
    native = _json_native(copy.deepcopy(value), label="source provenance")
    assert type(native) is dict
    return native


@dataclass(frozen=True, slots=True)
class _PinnedDirectory:
    path: Path
    parent_path: Path
    child_name: str
    parent_fd: int
    directory_fd: int
    parent_identity: tuple[int, int, int]
    directory_identity: tuple[int, int, int]
    canonical: bool
    mutable: bool
    outer_authority_identity: int | None
    owner_thread: int
    nonce: object


_PIN_REGISTRY: dict[int, _PinnedDirectory] = {}


def _directory_identity(metadata: os.stat_result, *, label: str) -> tuple[int, int, int]:
    if not stat.S_ISDIR(metadata.st_mode) or metadata.st_nlink < 1:
        raise PermissionError(f"{label} must be one live directory")
    return metadata.st_dev, metadata.st_ino, metadata.st_mode


def _path_directory_identity(path: Path, *, label: str) -> tuple[int, int, int]:
    metadata = os.lstat(path)
    if stat.S_ISLNK(metadata.st_mode):
        raise PermissionError(f"{label} must not be a symbolic link")
    return _directory_identity(metadata, label=label)


def _safe_basename(name: str, *, label: str) -> str:
    if (
        type(name) is not str
        or not name
        or name in {".", ".."}
        or os.path.sep in name
        or (os.path.altsep is not None and os.path.altsep in name)
    ):
        raise ValueError(f"{label} must be one exact relative basename")
    return name


def _acquire_pinned_directory(
    path: Path,
    *,
    create: bool,
    canonical: bool,
    outer_authority: _OuterRunnerAuthority | None = None,
    read_only: bool = False,
) -> _PinnedDirectory:
    if type(path) is not _NATIVE_PATH_TYPE or not path.is_absolute() or path.resolve() != path:
        raise TypeError("pinned directory must be one canonical absolute native Path")
    if type(canonical) is not bool:
        raise TypeError("pinned directory canonical marker must be one exact bool")
    if type(read_only) is not bool:
        raise TypeError("pinned directory read-only marker must be one exact bool")
    if read_only and create:
        raise PermissionError("read-only directory acquisition cannot create a namespace")
    if (path == _canonical_run_directory()) is not canonical:
        raise PermissionError(
            "canonical run path and formal pin marker must identify each other exactly"
        )
    formal_authority: _OuterRunnerAuthority | None = None
    if canonical and not read_only:
        registration = _OUTER_RUNNER_AUTHORITY_REGISTRY.get(id(outer_authority))
        if (
            type(outer_authority) is not _OuterRunnerAuthority
            or registration != (outer_authority, "issued")
            or outer_authority.owner_thread != threading.get_ident()
        ):
            raise PermissionError("canonical directory acquisition requires outer authority")
        formal_authority = outer_authority
    elif outer_authority is not None:
        raise PermissionError("noncanonical directory cannot consume outer authority")
    parent_path = path.parent
    child_name = _safe_basename(path.name, label="pinned directory name")
    parent_before = _path_directory_identity(parent_path, label="pinned parent path")
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    parent_fd = os.open(parent_path, directory_flags)
    directory_fd: int | None = None
    try:
        if (
            _directory_identity(os.fstat(parent_fd), label="pinned parent descriptor")
            != parent_before
        ):
            raise PermissionError("pinned parent changed during open")
        if create:
            try:
                os.mkdir(child_name, mode=0o700, dir_fd=parent_fd)
                os.fsync(parent_fd)
            except FileExistsError:
                pass
        child = os.stat(child_name, dir_fd=parent_fd, follow_symlinks=False)
        if stat.S_ISLNK(child.st_mode):
            raise PermissionError("pinned directory entry must not be a symlink")
        child_identity = _directory_identity(child, label="pinned directory entry")
        directory_fd = os.open(child_name, directory_flags, dir_fd=parent_fd)
        opened_identity = _directory_identity(
            os.fstat(directory_fd),
            label="pinned directory descriptor",
        )
        if opened_identity != child_identity:
            raise PermissionError("pinned directory changed during open")
        pin = _PinnedDirectory(
            path=path,
            parent_path=parent_path,
            child_name=child_name,
            parent_fd=parent_fd,
            directory_fd=directory_fd,
            parent_identity=parent_before,
            directory_identity=opened_identity,
            canonical=canonical,
            mutable=not read_only,
            outer_authority_identity=(
                id(formal_authority) if formal_authority is not None else None
            ),
            owner_thread=threading.get_ident(),
            nonce=object(),
        )
        if id(pin) in _PIN_REGISTRY:
            raise PermissionError("pinned directory identity already exists")
        _PIN_REGISTRY[id(pin)] = pin
        if formal_authority is not None:
            _FORMAL_PIN_AUTHORITY_REGISTRY[id(pin)] = (
                formal_authority,
                pin,
                "issued",
            )
            _OUTER_RUNNER_AUTHORITY_REGISTRY[id(formal_authority)] = (
                formal_authority,
                "directory_pinned",
            )
        _validate_pinned_directory(pin)
        return pin
    except BaseException:
        registered_pin = locals().get("pin")
        if isinstance(registered_pin, _PinnedDirectory):
            _PIN_REGISTRY.pop(id(registered_pin), None)
            _FORMAL_PIN_AUTHORITY_REGISTRY.pop(id(registered_pin), None)
        if formal_authority is not None and _OUTER_RUNNER_AUTHORITY_REGISTRY.get(
            id(formal_authority)
        ) == (formal_authority, "directory_pinned"):
            _OUTER_RUNNER_AUTHORITY_REGISTRY[id(formal_authority)] = (
                formal_authority,
                "issued",
            )
        if directory_fd is not None:
            with contextlib.suppress(OSError):
                os.close(directory_fd)
        with contextlib.suppress(OSError):
            os.close(parent_fd)
        raise


def _validate_pinned_directory(pin: _PinnedDirectory) -> None:
    if (
        not isinstance(pin, _PinnedDirectory)
        or _PIN_REGISTRY.get(id(pin)) is not pin
        or pin.owner_thread != threading.get_ident()
    ):
        raise PermissionError("directory pin is forged, closed, or thread-rebound")
    if pin.canonical and pin.mutable:
        formal_registration = _FORMAL_PIN_AUTHORITY_REGISTRY.get(id(pin))
        if (
            formal_registration is None
            or formal_registration[1] is not pin
            or formal_registration[2] not in {"issued", "consumed"}
            or id(formal_registration[0]) != pin.outer_authority_identity
        ):
            raise PermissionError("canonical directory pin lacks its outer authority binding")
    elif pin.outer_authority_identity is not None:
        raise PermissionError("noncanonical directory pin carries formal authority")
    parent_open = _directory_identity(os.fstat(pin.parent_fd), label="pinned parent descriptor")
    directory_open = _directory_identity(
        os.fstat(pin.directory_fd),
        label="pinned directory descriptor",
    )
    child = os.stat(pin.child_name, dir_fd=pin.parent_fd, follow_symlinks=False)
    if stat.S_ISLNK(child.st_mode):
        raise PermissionError("pinned directory namespace became a symlink")
    if (
        parent_open != pin.parent_identity
        or directory_open != pin.directory_identity
        or _directory_identity(child, label="pinned directory entry") != pin.directory_identity
        or _path_directory_identity(pin.parent_path, label="pinned parent path")
        != pin.parent_identity
        or _path_directory_identity(pin.path, label="pinned directory path")
        != pin.directory_identity
    ):
        raise PermissionError("pinned directory namespace binding changed")


def _release_pinned_directory(pin: _PinnedDirectory) -> None:
    problem: BaseException | None = None
    try:
        _validate_pinned_directory(pin)
    except BaseException as error:
        problem = error
    registered = _PIN_REGISTRY.pop(id(pin), None)
    if registered is not pin:
        raise PermissionError("directory pin cannot be released twice")
    formal_registration = _FORMAL_PIN_AUTHORITY_REGISTRY.pop(id(pin), None)
    if formal_registration is not None:
        authority, _, status = formal_registration
        if status == "issued" and _OUTER_RUNNER_AUTHORITY_REGISTRY.get(id(authority)) == (
            authority,
            "directory_pinned",
        ):
            _OUTER_RUNNER_AUTHORITY_REGISTRY[id(authority)] = (authority, "revoked")
    for descriptor in (pin.directory_fd, pin.parent_fd):
        os.close(descriptor)
    if problem is not None:
        raise PermissionError("directory pin closed after namespace validation failed") from problem


def _clear_pinned_directory_registry_for_tests() -> None:
    if any(pin.canonical for pin in _PIN_REGISTRY.values()):
        raise PermissionError("test cleanup cannot retire a formal directory pin")
    for pin in tuple(_PIN_REGISTRY.values()):
        for descriptor in (pin.directory_fd, pin.parent_fd):
            with contextlib.suppress(OSError):
                os.close(descriptor)
    _PIN_REGISTRY.clear()


def _pinned_directory_binding(pin: _PinnedDirectory) -> dict[str, Any]:
    _validate_pinned_directory(pin)
    return {
        "schema": "rgbd_known_action_run_directory_v1",
        "path": os.fspath(pin.path),
        "parent_identity": list(pin.parent_identity),
        "directory_identity": list(pin.directory_identity),
        "canonical": pin.canonical,
        "execution_mode": "formal" if pin.canonical else "fake_test",
    }


def _pinned_directory_capability_binding(pin: _PinnedDirectory) -> dict[str, Any]:
    """Bind in-process authority without contaminating durable physical identity."""

    physical = _pinned_directory_binding(pin)
    return {
        "schema": "rgbd_known_action_run_directory_capability_v1",
        "physical_binding_sha256": canonical_sha256(physical),
        "mutable": pin.mutable,
        "outer_authority_bound": pin.outer_authority_identity is not None,
        "owner_thread": pin.owner_thread,
    }


def _artifact_name(pin: _PinnedDirectory, path: Path, *, label: str) -> str:
    _validate_pinned_directory(pin)
    if type(path) is not _NATIVE_PATH_TYPE or path.parent != pin.path:
        raise ValueError(f"{label} must be directly inside the pinned directory")
    name = _safe_basename(path.name, label=label)
    if pin.canonical and name not in QUALIFICATION_ARTIFACT_NAMES:
        raise PermissionError(f"{label} is not an owned qualification artifact")
    return name


def _require_mutable_pin(pin: _PinnedDirectory) -> None:
    _validate_pinned_directory(pin)
    if pin.mutable is not True:
        raise PermissionError("read-only directory pin cannot publish or replace artifacts")


def _pinned_inventory(pin: _PinnedDirectory) -> frozenset[str]:
    _validate_pinned_directory(pin)
    names = frozenset(entry.name for entry in os.scandir(pin.directory_fd))
    _validate_pinned_directory(pin)
    return names


def _pinned_recovery_inventory_binding(pin: _PinnedDirectory) -> dict[str, Any]:
    """Bind names and inode metadata without reading governed artifact contents."""

    names = sorted(_pinned_inventory(pin))
    entries: list[dict[str, Any]] = []
    for name in names:
        safe_name = _safe_basename(name, label="recovery inventory entry")
        metadata = os.stat(safe_name, dir_fd=pin.directory_fd, follow_symlinks=False)
        identity = _file_identity(metadata)
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            raise PermissionError("recovery inventory entries must be single-link regular files")
        entries.append({"name": safe_name, "identity": list(identity)})
    _validate_pinned_directory(pin)
    return {
        "schema": "rgbd_known_action_ledger_recovery_inventory_v1",
        "entries": entries,
        "entries_sha256": canonical_sha256(entries),
    }


def _validated_recovery_inventory_binding(value: Any) -> dict[str, Any]:
    _require_exact_keys(
        value,
        LEDGER_RECOVERY_INVENTORY_SCHEMA,
        label="ledger recovery inventory",
    )
    entries = value["entries"]
    if (
        value["schema"] != "rgbd_known_action_ledger_recovery_inventory_v1"
        or type(entries) is not list
    ):
        raise ValueError("ledger recovery inventory schema differs")
    validated_entries: list[dict[str, Any]] = []
    previous_name: str | None = None
    for index, entry in enumerate(entries):
        _require_exact_keys(
            entry,
            LEDGER_RECOVERY_INVENTORY_ENTRY_SCHEMA,
            label=f"ledger recovery inventory entry {index}",
        )
        name = _safe_basename(entry["name"], label="ledger recovery inventory name")
        identity = entry["identity"]
        if (
            type(identity) is not list
            or len(identity) != 7
            or any(type(item) is not int for item in identity)
            or previous_name is not None
            and name <= previous_name
        ):
            raise ValueError("ledger recovery inventory ordering/identity differs")
        previous_name = name
        validated_entries.append({"name": name, "identity": list(identity)})
    if value["entries_sha256"] != canonical_sha256(validated_entries):
        raise ValueError("ledger recovery inventory digest differs")
    native = _json_native(
        {
            "schema": value["schema"],
            "entries": validated_entries,
            "entries_sha256": validated_sha256(
                value["entries_sha256"],
                label="ledger recovery inventory entries",
            ),
        },
        label="ledger recovery inventory",
    )
    assert type(native) is dict
    return native


def _pinned_exists(pin: _PinnedDirectory, path: Path, *, label: str) -> bool:
    name = _artifact_name(pin, path, label=label)
    try:
        os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        _validate_pinned_directory(pin)
        return False
    _validate_pinned_directory(pin)
    return True


def _file_identity(metadata: os.stat_result) -> tuple[int, int, int, int, int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
        metadata.st_nlink,
    )


def _pinned_file_identity(pin: _PinnedDirectory, path: Path) -> tuple[int, int, int, int, int]:
    name = _artifact_name(pin, path, label=f"artifact identity {path.name}")
    metadata = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
        raise PermissionError("artifact must be one single-link regular file")
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_nlink,
    )


def _pinned_full_file_identity(
    pin: _PinnedDirectory,
    path: Path,
) -> tuple[int, int, int, int, int, int, int]:
    """Capture the exact seven-field identity used by recovery inventories."""

    name = _artifact_name(pin, path, label=f"full artifact identity {path.name}")
    metadata = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
        raise PermissionError("artifact must be one single-link regular file")
    identity = _file_identity(metadata)
    _validate_pinned_directory(pin)
    return identity


def _pinned_read_bytes(
    pin: _PinnedDirectory,
    path: Path,
    *,
    label: str,
    maximum: int = MAX_JSON_BYTES,
) -> bytes:
    name = _artifact_name(pin, path, label=label)
    before = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
    if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or before.st_size > maximum:
        raise PermissionError(f"{label} must be one bounded single-link regular file")
    descriptor = os.open(
        name,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        dir_fd=pin.directory_fd,
    )
    try:
        opened = os.fstat(descriptor)
        chunks: list[bytes] = []
        total = 0
        while True:
            chunk = os.read(descriptor, 65_536)
            if not chunk:
                break
            chunks.append(chunk)
            total += len(chunk)
            if total > maximum:
                raise ValueError(f"{label} exceeds its byte limit")
        after_open = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    after = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
    expected = _file_identity(before)
    if any(_file_identity(item) != expected for item in (opened, after_open, after)):
        raise PermissionError(f"{label} changed during pinned read")
    contents = b"".join(chunks)
    if len(contents) != before.st_size:
        raise PermissionError(f"{label} length changed during pinned read")
    _validate_pinned_directory(pin)
    return contents


def _write_descriptor(descriptor: int, contents: bytes) -> os.stat_result:
    if type(contents) is not bytes:
        raise TypeError("durable contents must be exact bytes")
    with os.fdopen(descriptor, "wb") as handle:
        handle.write(contents)
        handle.flush()
        os.fsync(handle.fileno())
        metadata = os.fstat(handle.fileno())
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_nlink != 1
            or metadata.st_size != len(contents)
        ):
            raise PermissionError("durable writer descriptor identity differs")
        return metadata


def _reconcile_exact_published_artifact(
    pin: _PinnedDirectory,
    path: Path,
    contents: bytes,
    *,
    expected_inventory: frozenset[str],
) -> tuple[int, int, int, int, int] | None:
    """Boundedly adopt an exact artifact after a post-publication exception."""

    for _ in range(3):
        try:
            os.fsync(pin.directory_fd)
            if _pinned_inventory(pin) != expected_inventory:
                continue
            if _pinned_read_bytes(pin, path, label="reconciled durable artifact") != contents:
                continue
            return _pinned_file_identity(pin, path)
        except (OSError, PermissionError, ValueError):
            continue
    return None


def _pinned_durable_create(
    pin: _PinnedDirectory,
    path: Path,
    contents: bytes,
    *,
    mode: int = 0o600,
) -> tuple[int, int, int, int, int]:
    _require_mutable_pin(pin)
    if type(contents) is not bytes:
        raise TypeError("durable create contents must be exact bytes")
    name = _artifact_name(pin, path, label="durable create")
    before = _pinned_inventory(pin)
    if name in before:
        raise FileExistsError(f"durable artifact must be fresh: {name}")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    expected_inventory = before | frozenset({name})
    descriptor: int | None = None
    try:
        descriptor = os.open(name, flags, mode, dir_fd=pin.directory_fd)
        written = _write_descriptor(descriptor, contents)
        descriptor = None
        os.fsync(pin.directory_fd)
        after = _pinned_inventory(pin)
        if after != expected_inventory:
            raise PermissionError("durable create changed unexpected directory entries")
        metadata = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
        if (metadata.st_dev, metadata.st_ino, metadata.st_size) != (
            written.st_dev,
            written.st_ino,
            written.st_size,
        ):
            raise PermissionError("durable created inode differs from writer")
        if _pinned_read_bytes(pin, path, label="durable created artifact") != contents:
            raise PermissionError("durable created bytes differ")
        return _pinned_file_identity(pin, path)
    except BaseException:
        if descriptor is not None:
            with contextlib.suppress(OSError):
                os.close(descriptor)
        reconciled = _reconcile_exact_published_artifact(
            pin,
            path,
            contents,
            expected_inventory=expected_inventory,
        )
        if reconciled is not None:
            return reconciled
        # Never remove a governed artifact after its O_EXCL publication point;
        # an unknown or incomplete entry is durable fail-closed evidence and
        # must block a retry.
        raise


def _pinned_durable_replace(
    pin: _PinnedDirectory,
    path: Path,
    contents: bytes,
    *,
    mode: int = 0o600,
    _return_full_identity: bool = False,
    _recovery_expected_target_identity: tuple[int, int, int, int, int, int, int] | None = None,
    _recovery_expected_inventory: Mapping[str, Any] | None = None,
    _recovery_terminal: bool = False,
    _replace: Any = os.replace,
) -> (
    tuple[int, int, int, int, int]
    | tuple[
        tuple[int, int, int, int, int],
        tuple[int, int, int, int, int, int, int],
    ]
):
    _require_mutable_pin(pin)
    if (
        type(contents) is not bytes
        or type(_return_full_identity) is not bool
        or type(_recovery_terminal) is not bool
    ):
        raise TypeError("durable replace contents must be exact bytes")
    recovery_mode = _recovery_expected_inventory is not None
    if recovery_mode != (_recovery_expected_target_identity is not None):
        raise PermissionError("durable recovery replacement capability is incomplete")
    if _recovery_terminal and not recovery_mode:
        raise PermissionError("terminal replacement lacks a recovery inventory capability")
    name = _artifact_name(pin, path, label="durable replace target")
    recovery_inventory: dict[str, Any] | None = None
    if recovery_mode:
        if (
            type(_recovery_expected_inventory) is not dict
            or type(_recovery_expected_target_identity) is not tuple
            or len(_recovery_expected_target_identity) != 7
            or any(type(item) is not int for item in _recovery_expected_target_identity)
            or not _return_full_identity
        ):
            raise PermissionError("durable recovery replacement capability differs")
        recovery_inventory = _validated_recovery_inventory_binding(
            copy.deepcopy(_recovery_expected_inventory)
        )
        target_rows = [row for row in recovery_inventory["entries"] if row["name"] == name]
        current_inventory = _validated_recovery_inventory_binding(
            _pinned_recovery_inventory_binding(pin)
        )
        if (
            len(target_rows) != 1
            or tuple(target_rows[0]["identity"]) != _recovery_expected_target_identity
            or current_inventory != recovery_inventory
            or _pinned_full_file_identity(pin, path) != _recovery_expected_target_identity
        ):
            raise PermissionError("durable recovery target changed before staging")
        target_identity = (
            _recovery_expected_target_identity[0],
            _recovery_expected_target_identity[1],
            _recovery_expected_target_identity[3],
            _recovery_expected_target_identity[4],
            _recovery_expected_target_identity[6],
        )
        before = frozenset(row["name"] for row in recovery_inventory["entries"])
    else:
        if not _pinned_exists(pin, path, label="durable replace target"):
            raise FileNotFoundError(f"durable replace target is absent: {name}")
        target_identity = _pinned_file_identity(pin, path)
        before = _pinned_inventory(pin)
    temporary_name = _safe_basename(f".{name}.tmp", label="durable replace temporary")
    if temporary_name in before:
        raise FileExistsError(f"durable replacement temporary is not fresh: {temporary_name}")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    descriptor: int | None = None
    temporary: os.stat_result | None = None
    published = False
    try:
        descriptor = os.open(temporary_name, flags, mode, dir_fd=pin.directory_fd)
        temporary = os.fstat(descriptor)
        written = _write_descriptor(descriptor, contents)
        descriptor = None
        if recovery_inventory is None:
            with_temporary = _pinned_inventory(pin)
            if with_temporary != before | frozenset({temporary_name}):
                raise PermissionError("durable replace changed unexpected directory entries")
            if _pinned_file_identity(pin, path) != target_identity:
                raise PermissionError("durable replace target changed before publication")
        else:
            with_temporary = _validated_recovery_inventory_binding(
                _pinned_recovery_inventory_binding(pin)
            )
            temporary_rows = [
                row for row in with_temporary["entries"] if row["name"] == temporary_name
            ]
            non_temporary_entries = [
                row for row in with_temporary["entries"] if row["name"] != temporary_name
            ]
            non_temporary_inventory = {
                "schema": "rgbd_known_action_ledger_recovery_inventory_v1",
                "entries": non_temporary_entries,
                "entries_sha256": canonical_sha256(non_temporary_entries),
            }
            if (
                len(temporary_rows) != 1
                or tuple(temporary_rows[0]["identity"])[0:4] != _file_identity(written)[0:4]
                or tuple(temporary_rows[0]["identity"])[6] != _file_identity(written)[6]
                or non_temporary_inventory != recovery_inventory
            ):
                raise PermissionError("durable recovery inventory changed before replacement")
        # The exact runner closure authenticates this captured stdlib primitive.
        # Keep the final governed-inventory comparison immediately adjacent to
        # the syscall: no user-space check can close a mutation performed inside
        # a substituted replacement primitive without a forbidden postterminal
        # reread of governed base artifacts.
        _replace(
            temporary_name,
            name,
            src_dir_fd=pin.directory_fd,
            dst_dir_fd=pin.directory_fd,
        )
        published = True
        os.fsync(pin.directory_fd)
        if not _recovery_terminal and _pinned_inventory(pin) != before:
            raise PermissionError("durable replacement left unexpected directory entries")
        metadata = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
        if (metadata.st_dev, metadata.st_ino, metadata.st_size) != (
            written.st_dev,
            written.st_ino,
            written.st_size,
        ):
            raise PermissionError("durable replaced inode differs from writer")
        if _pinned_read_bytes(pin, path, label="durable replaced artifact") != contents:
            raise PermissionError("durable replaced bytes differ")
        final_metadata = os.stat(name, dir_fd=pin.directory_fd, follow_symlinks=False)
        full_identity = _file_identity(final_metadata)
        if full_identity != _file_identity(metadata):
            raise PermissionError("durable replaced identity changed after verification")
        reduced_identity = (
            full_identity[0],
            full_identity[1],
            full_identity[3],
            full_identity[4],
            full_identity[6],
        )
        return (reduced_identity, full_identity) if _return_full_identity else reduced_identity
    except BaseException:
        if descriptor is not None and temporary is None:
            for _ in range(3):
                try:
                    temporary = os.fstat(descriptor)
                    break
                except OSError:
                    continue
        if descriptor is not None:
            with contextlib.suppress(OSError):
                os.close(descriptor)
        reconciled = (
            None
            if _recovery_terminal
            else _reconcile_exact_published_artifact(
                pin,
                path,
                contents,
                expected_inventory=before,
            )
        )
        if reconciled is not None:
            return (
                (reconciled, _pinned_full_file_identity(pin, path))
                if _return_full_identity
                else reconciled
            )
        if not published and temporary is not None:
            try:
                current = os.stat(
                    temporary_name,
                    dir_fd=pin.directory_fd,
                    follow_symlinks=False,
                )
                if (
                    current.st_dev == temporary.st_dev
                    and current.st_ino == temporary.st_ino
                    and stat.S_ISREG(current.st_mode)
                    and current.st_nlink == 1
                    and _pinned_file_identity(pin, path) == target_identity
                ):
                    os.unlink(temporary_name, dir_fd=pin.directory_fd)
                    os.fsync(pin.directory_fd)
            except OSError:
                pass
        raise


def _report_bytes(report: Mapping[str, Any]) -> bytes:
    if type(report) is not dict:
        raise TypeError("report must be one exact dict")
    native = _json_native(report, label="report")
    assert type(native) is dict
    return (
        json.dumps(native, allow_nan=False, ensure_ascii=True, indent=2, sort_keys=True).encode(
            "ascii"
        )
        + b"\n"
    )


def _write_report_fresh(pin: _PinnedDirectory, path: Path, report: Mapping[str, Any]) -> None:
    _pinned_durable_create(pin, path, _report_bytes(report))


