def _materializer_config_native(
    value: Any,
    *,
    label: str,
    active: set[int] | None = None,
) -> Any:
    active = set() if active is None else active
    if type(value) is _NATIVE_PATH_TYPE:
        return {"type": "path", "value": os.fspath(value)}
    if value is None or type(value) in {bool, int, str}:
        return value
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError(f"{label} contains a nonfinite float")
        return value
    if type(value) is dict:
        if any(type(key) is not str for key in value):
            raise TypeError(f"{label} keys must be exact strings")
        identity = id(value)
        if identity in active:
            raise ValueError(f"{label} contains a recursive container")
        active.add(identity)
        try:
            return {
                "type": "dict",
                "items": [
                    [
                        key,
                        _materializer_config_native(
                            value[key],
                            label=f"{label}.{key}",
                            active=active,
                        ),
                    ]
                    for key in sorted(value)
                ],
            }
        finally:
            active.remove(identity)
    if type(value) in {list, tuple}:
        identity = id(value)
        if identity in active:
            raise ValueError(f"{label} contains a recursive container")
        active.add(identity)
        try:
            return {
                "type": "list" if type(value) is list else "tuple",
                "items": [
                    _materializer_config_native(
                        item,
                        label=f"{label}[{index}]",
                        active=active,
                    )
                    for index, item in enumerate(value)
                ],
            }
        finally:
            active.remove(identity)
    raise TypeError(f"{label} contains unsupported type {type(value).__name__}")


def _materializer_config_sha256(config: Any) -> str:
    if type(config) is not dict or not config:
        raise TypeError("closed materializer config must be one exact nonempty dictionary")
    native = _materializer_config_native(config, label="materializer config")
    if type(native) is not dict:
        raise ValueError("materializer config must be one nonempty exact mapping")
    return canonical_sha256(
        {
            "schema": "rgbd_known_action_materializer_config_binding_v1",
            "config": native,
        }
    )


def _exact_native_binding_equal(left: Any, right: Any) -> bool:
    if type(right) is tuple:
        return (
            type(left) is tuple
            and len(left) == len(right)
            and all(
                _exact_native_binding_equal(left_item, right_item)
                for left_item, right_item in zip(left, right, strict=True)
            )
        )
    if type(right) in {str, int, float, bool, bytes, type(None)}:
        return type(left) is type(right) and left == right
    return left is right


def _evaluator_construction_authority_binding(
    authority: _EvaluatorConstructionAuthority,
) -> tuple[Any, ...]:
    if (
        type(authority.stage) is not str
        or authority.stage not in {"development", "qualification"}
        or type(authority.ledger_identity) is not int
        or type(authority.directory_pin) is not _PinnedDirectory
        or type(authority.ledger_path) is not _NATIVE_PATH_TYPE
        or type(authority.ledger_file_identity) is not tuple
        or len(authority.ledger_file_identity) != 7
        or any(type(value) is not int for value in authority.ledger_file_identity)
        or type(authority.ledger_generation) is not int
        or type(authority.ledger_record_sha256) is not str
        or type(authority.config_identity) is not int
        or type(authority.config_sha256) is not str
        or type(authority.owner_thread) is not int
        or type(authority.nonce) is not object
    ):
        raise PermissionError("formal evaluator authority scalar types differ")
    return (
        authority.stage,
        authority.ledger_identity,
        id(authority.directory_pin),
        os.fspath(authority.ledger_path),
        authority.ledger_file_identity,
        authority.ledger_generation,
        authority.ledger_record_sha256,
        authority.config_identity,
        authority.config_sha256,
        authority.owner_thread,
        id(authority.nonce),
    )


