def _materializer_tensor_batch_binding(
    batch: _PublicSensorBatch | _SafeTaskBatch,
) -> tuple[Any, ...]:
    if type(batch) is _PublicSensorBatch:
        horizon: float | None = None
    elif type(batch) is _SafeTaskBatch:
        horizon = batch.fixed_goal_horizon_seconds
    else:
        raise PermissionError("materializer tensor batch is forged")
    if (
        type(batch.port_identity) is not int
        or type(batch.vault_identity) is not int
        or type(batch.split) is not str
        or batch.split not in SPLITS
        or type(batch.ordinals) is not tuple
        or len(batch.ordinals) != BATCH_SIZE
        or any(type(value) is not int for value in batch.ordinals)
        or (horizon is not None and type(horizon) is not float)
        or type(batch.owner_thread) is not int
        or type(batch.nonce) is not object
        or batch._factory_nonce is not _MATERIALIZER_FACTORY_NONCE
    ):
        raise PermissionError("materializer tensor batch scalar types differ")
    return (
        type(batch),
        batch.port_identity,
        batch.vault_identity,
        batch.split,
        batch.ordinals,
        horizon,
        batch.owner_thread,
        id(batch.nonce),
        id(batch._factory_nonce),
    )


