def _code_structure(value: Any) -> dict[str, Any]:
    return {
        "name": value.co_name,
        "qualname": getattr(value, "co_qualname", value.co_name),
        "filename": value.co_filename,
        "firstlineno": value.co_firstlineno,
        "argcount": value.co_argcount,
        "posonlyargcount": value.co_posonlyargcount,
        "kwonlyargcount": value.co_kwonlyargcount,
        "nlocals": value.co_nlocals,
        "stacksize": value.co_stacksize,
        "flags": value.co_flags,
        "code_sha256": sha256_bytes(value.co_code),
        "linetable_sha256": sha256_bytes(value.co_linetable),
        "exceptiontable_sha256": sha256_bytes(getattr(value, "co_exceptiontable", b"")),
        "names": list(value.co_names),
        "varnames": list(value.co_varnames),
        "freevars": list(value.co_freevars),
        "cellvars": list(value.co_cellvars),
    }


def _consume_outer_authorization_record(
    authorization_fd_text: Any,
) -> tuple[dict[str, Any], str, tuple[int, int, int, int]]:
    """Consume one anonymous authorization pipe before inspecting other authority inputs."""

    if (
        type(authorization_fd_text) is not str
        or not authorization_fd_text.isascii()
        or not authorization_fd_text.isdecimal()
    ):
        raise PermissionError("outer authorization descriptor is malformed")
    descriptor = int(authorization_fd_text)
    if descriptor < 3 or str(descriptor) != authorization_fd_text:
        raise PermissionError("outer authorization descriptor is noncanonical")
    before: os.stat_result | None = None
    after: os.stat_result | None = None
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISFIFO(before.st_mode) or before.st_nlink != 0:
            raise PermissionError("outer authorization is not one anonymous pipe")
        os.set_inheritable(descriptor, False)
        if os.get_inheritable(descriptor):
            raise PermissionError("outer authorization descriptor remained inheritable")
        chunks: list[bytes] = []
        total = 0
        while True:
            chunk = os.read(descriptor, 4096)
            if not chunk:
                break
            total += len(chunk)
            if total > _MAX_OUTER_AUTHORIZATION_BYTES:
                raise PermissionError("outer authorization record is oversized")
            chunks.append(chunk)
        after = os.fstat(descriptor)
    finally:
        with contextlib.suppress(OSError):
            os.close(descriptor)
    if before is None or after is None:
        raise PermissionError("outer authorization pipe was not consumed completely")
    identity = lambda item: (  # noqa: E731
        item.st_dev,
        item.st_ino,
        item.st_mode,
        item.st_nlink,
    )
    before_identity = identity(before)
    if before_identity != identity(after):
        raise PermissionError("outer authorization pipe identity changed during consumption")
    contents = b"".join(chunks)
    record = _strict_json_loads(contents, label="outer authorization record")
    if contents != _canonical_json(record):
        raise PermissionError("outer authorization record serialization is not canonical")
    _require_exact_keys(
        record,
        OUTER_AUTHORIZATION_SCHEMA,
        label="outer authorization record",
    )
    body = copy.deepcopy(record)
    supplied_record_sha256 = body.pop("record_sha256")
    if (
        record["schema"] != "rgbd_known_action_outer_authorization_v1"
        or validated_sha256(
            supplied_record_sha256,
            label="outer authorization record self-hash",
        )
        != canonical_sha256(body)
        or type(record["nonce"]) is not str
        or len(record["nonce"]) != 64
        or record["nonce"] != record["nonce"].lower()
        or type(record["argv"]) is not list
        or any(type(value) is not str for value in record["argv"])
        or record["stage"] not in {"development", "qualification"}
        or type(record["outer_pid"]) is not int
        or type(record["expected_child_parent_pid"]) is not int
        or record["outer_pid"] <= 0
        or record["expected_child_parent_pid"] <= 0
    ):
        raise PermissionError("outer authorization record identity differs")
    try:
        int(record["nonce"], 16)
    except ValueError as error:
        raise PermissionError("outer authorization nonce is not lowercase hexadecimal") from error
    for name in (
        "first_receipt_sha256",
        "runner_blob_sha256",
        "source_provenance_sha256",
    ):
        validated_sha256(record[name], label=f"outer authorization {name}")
    digest = sha256_bytes(contents)
    replay_identity = (digest, record["nonce"])
    if replay_identity in _OUTER_AUTHORIZATION_IDENTITY_REGISTRY or any(
        prior_nonce == record["nonce"] for _, prior_nonce in _OUTER_AUTHORIZATION_IDENTITY_REGISTRY
    ):
        raise PermissionError("outer authorization record or nonce was already consumed")
    _OUTER_AUTHORIZATION_IDENTITY_REGISTRY.add(replay_identity)
    return record, digest, before_identity


def _expected_isolated_sys_paths() -> tuple[tuple[str, ...], tuple[str, ...]]:
    paths = sysconfig.get_paths()
    stdlib = os.path.realpath(paths["stdlib"])
    platstdlib = os.path.realpath(paths["platstdlib"])
    archive = os.path.join(
        os.path.dirname(stdlib),
        f"python{sys.version_info.major}{sys.version_info.minor}.zip",
    )
    dynload = os.path.join(stdlib, "lib-dynload")
    preloader = tuple(dict.fromkeys((archive, stdlib, platstdlib, dynload)))
    runtime = tuple(dict.fromkeys((*preloader, paths["purelib"], paths["platlib"])))
    return preloader, runtime


def _validated_bootstrap_environment(
    bootstrap_environment_hex: Any,
    *,
    runner_blob_sha256: str,
) -> tuple[dict[str, Any], str]:
    if (
        type(bootstrap_environment_hex) is not str
        or not bootstrap_environment_hex
        or len(bootstrap_environment_hex) % 2
        or len(bootstrap_environment_hex) > _MAX_OUTER_AUTHORIZATION_BYTES * 2
        or bootstrap_environment_hex != bootstrap_environment_hex.lower()
    ):
        raise PermissionError("bootstrap environment encoding is malformed")
    try:
        contents = bytes.fromhex(bootstrap_environment_hex)
    except ValueError as error:
        raise PermissionError("bootstrap environment encoding is not hexadecimal") from error
    environment = _strict_json_loads(contents, label="bootstrap environment")
    if contents != _canonical_json(environment):
        raise PermissionError("bootstrap environment serialization is not canonical")
    _require_exact_keys(
        environment,
        BOOTSTRAP_ENVIRONMENT_SCHEMA,
        label="bootstrap environment",
    )
    flags = environment["flags"]
    _require_exact_keys(flags, BOOTSTRAP_FLAG_SCHEMA, label="bootstrap flags")
    validated_sha256(
        environment["bootstrap_literal_sha256"],
        label="bootstrap literal",
    )
    validated_sha256(
        environment["runner_preflight_sha256"],
        label="runner preflight",
    )
    actual_safe_path = getattr(sys.flags, "safe_path", None)
    expected_flags = {
        "isolated": 1,
        "no_site": 1,
        "ignore_environment": 1,
        "no_user_site": 1,
        "safe_path": actual_safe_path,
    }
    if actual_safe_path is not None and actual_safe_path != 1:
        raise PermissionError("bootstrap interpreter safe-path flag is disabled")
    if (
        sys.flags.isolated != 1
        or sys.flags.no_site != 1
        or sys.flags.ignore_environment != 1
        or sys.flags.no_user_site != 1
        or flags != expected_flags
    ):
        raise PermissionError("bootstrap interpreter isolation flags differ")
    expected_preloader, expected_runtime = _expected_isolated_sys_paths()
    preloader = environment["preloader_sys_path"]
    runtime = environment["runtime_sys_path"]
    if (
        type(preloader) is not list
        or type(runtime) is not list
        or any(type(value) is not str for value in (*preloader, *runtime))
        or tuple(preloader) != expected_preloader
        or tuple(runtime) != expected_runtime
        or tuple(sys.path) != expected_runtime
    ):
        raise PermissionError("bootstrap interpreter sys.path shape differs")
    cwd = os.path.realpath(os.getcwd())
    repository = os.path.realpath(REPOSITORY_ROOT)
    if any(
        not value or not os.path.isabs(value) or os.path.realpath(value) in {cwd, repository}
        for value in preloader
    ):
        raise PermissionError("bootstrap preloader sys.path contains an unsafe entry")
    if (
        environment["schema"] != "rgbd_known_action_bootstrap_environment_v1"
        or environment["python_version"] != sys.version
        or type(environment["python_hexversion"]) is not int
        or environment["python_hexversion"] != sys.hexversion
        or environment["implementation"] != sys.implementation.name
        or environment["executable"] != sys.executable
        or environment["preloaded_world_model"] != []
        or validated_sha256(
            environment["runner_blob_sha256"],
            label="bootstrap runner blob",
        )
        != runner_blob_sha256
        or validated_sha256(
            environment["preloader_sys_path_sha256"],
            label="bootstrap preloader path",
        )
        != canonical_sha256(preloader)
        or validated_sha256(
            environment["runtime_sys_path_sha256"],
            label="bootstrap runtime path",
        )
        != canonical_sha256(runtime)
    ):
        raise PermissionError("bootstrap environment binding differs")
    return environment, sha256_bytes(contents)


def _nested_code_objects(root: Any) -> dict[str, Any]:
    code_type = type(root)
    result: dict[str, Any] = {}

    def visit(value: Any, parent: str) -> None:
        if not isinstance(value, code_type):
            return
        if hasattr(value, "co_qualname"):
            qualname = value.co_qualname
        elif value.co_name == "<module>":
            qualname = "<module>"
        elif parent:
            qualname = f"{parent}.{value.co_name}"
        else:
            qualname = value.co_name
        result[qualname] = value
        child_parent = "" if value.co_name == "<module>" else qualname
        for item in value.co_consts:
            visit(item, child_parent)

    visit(root, "")
    return result


def _published_runner_contract(runner_bytes: bytes, expected_path: Path) -> dict[str, Any]:
    """Parse, but never execute, the exact published runner contract."""

    if type(runner_bytes) is not bytes:
        raise TypeError("published runner source must be exact bytes")
    try:
        runner_text = runner_bytes.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise PermissionError("published runner source is not strict UTF-8") from error
    tree = ast.parse(runner_text, filename=os.fspath(expected_path), mode="exec")
    bootstrap_assignments = []
    for node in tree.body:
        plain_assignment = isinstance(node, ast.Assign) and any(
            isinstance(target, ast.Name) and target.id == "_BOOTSTRAP" for target in node.targets
        )
        annotated_or_augmented = isinstance(node, (ast.AnnAssign, ast.AugAssign)) and (
            isinstance(node.target, ast.Name) and node.target.id == "_BOOTSTRAP"
        )
        if plain_assignment or annotated_or_augmented:
            bootstrap_assignments.append(node)
    if len(bootstrap_assignments) != 1:
        raise PermissionError("published runner must contain one bootstrap assignment")
    assignment = bootstrap_assignments[0]
    if (
        type(assignment) is not ast.Assign
        or len(assignment.targets) != 1
        or type(assignment.targets[0]) is not ast.Name
        or assignment.targets[0].id != "_BOOTSTRAP"
        or type(assignment.value) is not ast.Constant
        or type(assignment.value.value) is not str
    ):
        raise PermissionError("published runner bootstrap must be one exact string literal")
    bootstrap_source = assignment.value.value
    bootstrap_sha256 = sha256_bytes(bootstrap_source.encode("utf-8"))
    compiled = compile(runner_bytes, os.fspath(expected_path), "exec", dont_inherit=True)
    expected_codes = _nested_code_objects(compiled)
    function_nodes = [node for node in tree.body if type(node) is ast.FunctionDef]
    function_names = tuple(node.name for node in function_nodes)
    if len(function_names) != len(set(function_names)):
        raise PermissionError("published runner contains duplicate top-level helpers")
    loader_nodes = [
        node
        for node in tree.body
        if type(node) is ast.ClassDef and node.name == "_ExactCommitLoader"
    ]
    if len(loader_nodes) != 1:
        raise PermissionError("published runner lacks one exact commit loader")
    loader_methods = tuple(
        node.name for node in loader_nodes[0].body if type(node) is ast.FunctionDef
    )
    if len(loader_methods) != len(set(loader_methods)):
        raise PermissionError("published runner loader contains duplicate methods")
    expected_bootstrap = _nested_code_objects(
        compile(bootstrap_source, "<string>", "exec", dont_inherit=True)
    ).get("_rgbd_known_action_bootstrap")
    if expected_bootstrap is None:
        raise PermissionError("published runner bootstrap entry is absent")
    return {
        "tree": tree,
        "compiled": compiled,
        "expected_codes": expected_codes,
        "function_names": function_names,
        "loader_methods": loader_methods,
        "bootstrap_source": bootstrap_source,
        "bootstrap_sha256": bootstrap_sha256,
        "bootstrap_code": expected_bootstrap,
        "module_doc": ast.get_docstring(tree, clean=False),
    }


