def _private_scoring_receipt(
    *,
    split: str,
    public_seal_sha256: str,
    truth_request: Mapping[str, Any],
    metrics: Mapping[str, Any],
    inherited_orbital_evidence: Mapping[str, Any],
) -> dict[str, Any]:
    request = _validated_truth_request_binding(truth_request, split=split)
    if request["public_seal_sha256"] != public_seal_sha256:
        raise PermissionError("private scoring request/public seal differs")
    metric_values = _json_native(copy.deepcopy(metrics), label=f"{split} private metrics")
    if type(metric_values) is not dict:
        raise TypeError("private scoring metrics must be one exact dict")
    inherited = _validated_inherited_orbital_evidence(inherited_orbital_evidence)
    failures = gate_failures(metric_values)
    failures.extend(f"inherited_orbital:{failure}" for failure in inherited["failures"])
    row_commitments: list[dict[str, Any]] = []
    body = {
        "schema": "rgbd_known_action_fake_test_private_scoring_receipt_v1",
        "split": split,
        "public_seal_sha256": validated_sha256(
            public_seal_sha256,
            label="private scoring public seal",
        ),
        "truth_request": request,
        "truth_request_sha256": canonical_sha256(request),
        "private_scoring_call_count": 1,
        "scoring_mode": "fake_test_no_scene_or_truth",
        "scene_access_count": 0,
        "truth_access_count": 0,
        "private_row_commitment_schema": (
            "rgbd_known_action_private_row_commitment_reserved_for_formal_v2"
        ),
        "private_row_commitments": row_commitments,
        "private_row_commitments_sha256": canonical_sha256(row_commitments),
        "metrics": metric_values,
        "metrics_sha256": canonical_sha256(metric_values),
        "inherited_orbital_evidence": inherited,
        "inherited_orbital_evidence_sha256": canonical_sha256(inherited),
        "failures": failures,
        "passed": not failures,
        "outcome": "passed" if not failures else "gate_failed",
    }
    return {**body, "receipt_sha256": canonical_sha256(body)}


def _validated_formal_private_row_commitments(
    value: Any,
    *,
    split: str,
) -> list[dict[str, Any]]:
    if type(value) is not list or len(value) != SCENES_PER_SPLIT:
        raise ValueError("formal private row commitment inventory differs")
    rows: list[dict[str, Any]] = []
    for ordinal, row in enumerate(value):
        _require_exact_keys(
            row,
            FORMAL_PRIVATE_ROW_COMMITMENT_SCHEMA,
            label=f"{split} formal private row commitment {ordinal}",
        )
        surface = _validated_public_materialization_surface(row["public_surface"])
        nonce_hex = row["blinding_nonce_hex"]
        if (
            row["schema"] != "rgbd_known_action_formal_private_row_commitment_v1"
            or row["split"] != split
            or type(row["ordinal"]) is not int
            or row["ordinal"] != ordinal
            or surface["split"] != split
            or surface["ordinal"] != ordinal
            or row["public_surface_sha256"] != canonical_sha256(surface)
            or type(nonce_hex) is not str
            or len(nonce_hex) != 64
            or nonce_hex != nonce_hex.lower()
        ):
            raise ValueError("formal private row commitment binding differs")
        try:
            nonce = bytes.fromhex(nonce_hex)
        except ValueError as error:
            raise ValueError("formal private row commitment nonce differs") from error
        if (
            len(nonce) != 32
            or validated_sha256(
                row["evaluation_hashes_sha256"],
                label="formal private row evaluation hashes",
            )
            != row["evaluation_hashes_sha256"]
            or validated_sha256(
                row["blinded_commitment"],
                label="formal private row blinded commitment",
            )
            != _blinded_materialization_commitment(surface, nonce)
        ):
            raise ValueError("formal private row commitment digest differs")
        native = _json_native(
            copy.deepcopy(dict(row)),
            label=f"{split} formal private row commitment {ordinal}",
        )
        assert type(native) is dict
        rows.append(native)
    return rows


def _formal_private_scoring_receipt(
    *,
    split: str,
    public_seal_sha256: str,
    truth_request: Mapping[str, Any],
    private_row_commitments: Sequence[Mapping[str, Any]],
    metrics: Mapping[str, Any],
    inherited_orbital_evidence: Mapping[str, Any],
) -> dict[str, Any]:
    request = _validated_truth_request_binding(truth_request, split=split)
    if request["public_seal_sha256"] != public_seal_sha256:
        raise PermissionError("formal private scoring request/public seal differs")
    metric_values = _json_native(copy.deepcopy(metrics), label=f"{split} private metrics")
    if type(metric_values) is not dict:
        raise TypeError("formal private scoring metrics must be one exact dict")
    inherited = _validated_inherited_orbital_evidence(inherited_orbital_evidence)
    commitments = _validated_formal_private_row_commitments(
        [copy.deepcopy(dict(row)) for row in private_row_commitments],
        split=split,
    )
    failures = gate_failures(metric_values)
    failures.extend(f"inherited_orbital:{failure}" for failure in inherited["failures"])
    body = {
        "schema": "rgbd_known_action_formal_private_scoring_receipt_v1",
        "split": split,
        "public_seal_sha256": validated_sha256(
            public_seal_sha256,
            label="formal private scoring public seal",
        ),
        "truth_request": request,
        "truth_request_sha256": canonical_sha256(request),
        "private_scoring_call_count": 1,
        "scoring_mode": "formal_post_public_seal_materializer",
        "scene_access_count": SCENES_PER_SPLIT,
        "truth_access_count": SCENES_PER_SPLIT,
        "private_row_commitment_schema": ("rgbd_known_action_formal_private_row_commitment_v1"),
        "private_row_commitments": commitments,
        "private_row_commitments_sha256": canonical_sha256(commitments),
        "metrics": metric_values,
        "metrics_sha256": canonical_sha256(metric_values),
        "inherited_orbital_evidence": inherited,
        "inherited_orbital_evidence_sha256": canonical_sha256(inherited),
        "failures": failures,
        "passed": not failures,
        "outcome": "passed" if not failures else "gate_failed",
    }
    return {**body, "receipt_sha256": canonical_sha256(body)}


def _validated_private_scoring_receipt(
    value: Any,
    *,
    split: str,
    public_seal_sha256: str,
) -> dict[str, Any]:
    _require_exact_keys(
        value,
        PRIVATE_SCORING_RECEIPT_SCHEMA,
        label=f"{split} private scoring receipt",
    )
    request = _validated_truth_request_binding(value["truth_request"], split=split)
    inherited = _validated_inherited_orbital_evidence(value["inherited_orbital_evidence"])
    metrics = _json_native(copy.deepcopy(value["metrics"]), label=f"{split} private metrics")
    if type(metrics) is not dict:
        raise TypeError("private scoring metrics must be one exact dict")
    expected_failures = gate_failures(metrics)
    expected_failures.extend(f"inherited_orbital:{failure}" for failure in inherited["failures"])
    schema = value["schema"]
    if schema == "rgbd_known_action_fake_test_private_scoring_receipt_v1":
        expected_mode = "fake_test_no_scene_or_truth"
        expected_scene_access_count = 0
        expected_truth_access_count = 0
        expected_commitment_schema = (
            "rgbd_known_action_private_row_commitment_reserved_for_formal_v2"
        )
        commitments: list[dict[str, Any]] = []
        if value["private_row_commitments"] != []:
            raise ValueError(f"{split} fake private scoring receipt carries commitments")
    elif schema == "rgbd_known_action_formal_private_scoring_receipt_v1":
        expected_mode = "formal_post_public_seal_materializer"
        expected_scene_access_count = SCENES_PER_SPLIT
        expected_truth_access_count = SCENES_PER_SPLIT
        expected_commitment_schema = "rgbd_known_action_formal_private_row_commitment_v1"
        commitments = _validated_formal_private_row_commitments(
            value["private_row_commitments"],
            split=split,
        )
    else:
        raise ValueError(f"{split} private scoring receipt schema differs")
    if (
        value["schema"] != schema
        or value["split"] != split
        or value["public_seal_sha256"] != public_seal_sha256
        or request["public_seal_sha256"] != public_seal_sha256
        or value["truth_request_sha256"] != canonical_sha256(request)
        or type(value["private_scoring_call_count"]) is not int
        or value["private_scoring_call_count"] != 1
        or value["scoring_mode"] != expected_mode
        or type(value["scene_access_count"]) is not int
        or value["scene_access_count"] != expected_scene_access_count
        or type(value["truth_access_count"]) is not int
        or value["truth_access_count"] != expected_truth_access_count
        or value["private_row_commitment_schema"] != expected_commitment_schema
        or type(value["private_row_commitments"]) is not list
        or value["private_row_commitments"] != commitments
        or value["private_row_commitments_sha256"] != canonical_sha256(commitments)
        or value["metrics_sha256"] != canonical_sha256(metrics)
        or value["inherited_orbital_evidence_sha256"] != canonical_sha256(inherited)
        or value["failures"] != expected_failures
        or type(value["passed"]) is not bool
        or value["passed"] is not (not expected_failures)
        or value["outcome"] != ("passed" if not expected_failures else "gate_failed")
    ):
        raise ValueError(f"{split} private scoring receipt binding differs")
    body = copy.deepcopy(dict(value))
    supplied = body.pop("receipt_sha256")
    if validated_sha256(supplied, label=f"{split} private receipt") != canonical_sha256(body):
        raise ValueError(f"{split} private scoring receipt self-hash differs")
    native = _json_native(copy.deepcopy(value), label=f"{split} private scoring receipt")
    assert type(native) is dict
    return native


def _capture_materializer_durable_latch(
    ledger: _AccessLedger,
) -> tuple[
    dict[str, Any],
    bytes,
    tuple[int, int, int, int, int],
    tuple[int, int, int, int, int, int, int],
]:
    if type(ledger) is not _AccessLedger:
        raise PermissionError("materializer durable latch ledger is forged")
    ledger._verify_disk()
    if (
        type(ledger._record) is not dict
        or type(ledger._last_bytes) is not bytes
        or type(ledger._last_identity) is not tuple
        or len(ledger._last_identity) != 5
        or any(type(value) is not int for value in ledger._last_identity)
    ):
        raise PermissionError("materializer durable latch state is malformed")
    return (
        copy.deepcopy(ledger._record),
        ledger._last_bytes,
        ledger._last_identity,
        _pinned_full_file_identity(ledger._pin, ledger.path),
    )


def _verify_materializer_durable_latch(
    ledger: _AccessLedger,
    latch: tuple[
        dict[str, Any],
        bytes,
        tuple[int, int, int, int, int],
        tuple[int, int, int, int, int, int, int],
    ],
) -> None:
    if (
        type(ledger) is not _AccessLedger
        or type(latch) is not tuple
        or len(latch) != 4
        or type(latch[0]) is not dict
        or type(latch[1]) is not bytes
        or type(latch[2]) is not tuple
        or len(latch[2]) != 5
        or any(type(value) is not int for value in latch[2])
        or type(latch[3]) is not tuple
        or len(latch[3]) != 7
        or any(type(value) is not int for value in latch[3])
    ):
        raise PermissionError("materializer durable latch proof is forged")
    ledger._verify_disk()
    _exact_equal(ledger._record, latch[0], label="materializer durable ledger latch")
    if (
        ledger._last_bytes != latch[1]
        or ledger._last_identity != latch[2]
        or _pinned_full_file_identity(ledger._pin, ledger.path) != latch[3]
    ):
        raise PermissionError("materializer durable latch changed after transition")


def _validated_materializer_transition_latch(
    latch: tuple[
        dict[str, Any],
        bytes,
        tuple[int, int, int, int, int],
        tuple[int, int, int, int, int, int, int],
    ],
    expected_record: dict[str, Any],
) -> None:
    if type(expected_record) is not dict:
        raise PermissionError("materializer expected durable transition is forged")
    _exact_equal(
        latch[0],
        expected_record,
        label="materializer exact durable transition",
    )
    if latch[1] != _ledger_bytes(expected_record):
        raise PermissionError("materializer durable transition bytes differ")


class _ManifestCapability:
    def __init__(self, *, split: str, ledger: _AccessLedger) -> None:
        if split not in SPLITS:
            raise ValueError("manifest split is invalid")
        self.split = split
        self._ledger = ledger
        self._next_ordinal = 0
        self._active: _BatchCapability | None = None
        self._truth_request: PrivateSplitScoringRequest | None = None
        self._closed = False
        ledger.begin_split(split)

    def begin_batch(self, ordinals: tuple[int, int, int, int]) -> _BatchCapability:
        if self._closed or self._active is not None:
            raise PermissionError("manifest is closed or already has an active batch")
        _ports, batches, registered_tokens, _consumed = _validated_materializer_global_registry_cut(
            ledger=self._ledger
        )
        expected = tuple(range(self._next_ordinal, self._next_ordinal + BATCH_SIZE))
        if (
            type(ordinals) is not tuple
            or len(ordinals) != BATCH_SIZE
            or any(type(value) is not int for value in ordinals)
            or ordinals != expected
        ):
            raise PermissionError("manifest batch must be the next exact four ordinals")
        capability_nonces: tuple[str, str, str, str] | None = None
        nonce_preflight_sha256: str | None = None
        if self._ledger._record["execution_mode"] == "formal":
            capability_nonces, nonce_preflight_sha256 = _preflight_formal_batch_capability_nonces(
                self._ledger,
                split=self.split,
                ordinals=ordinals,
            )
        tokens = tuple(_OrdinalCapability(self.split, ordinal, object()) for ordinal in ordinals)
        batch = _BatchCapability(
            self.split,
            ordinals,
            tokens,
            capability_nonces,
            nonce_preflight_sha256,
            object(),
        )
        registration = _BatchRegistration(
            batch=batch, manifest=self, consumed=set(), status="issued"
        )
        if id(batch) in batches or any(id(token) in registered_tokens for token in tokens):
            raise PermissionError("capability identity was already registered")
        if capability_nonces is not None:
            verified_nonces, verified_preflight_sha256 = _validated_formal_batch_capability_nonces(
                capability_nonces,
                ledger=self._ledger,
                split=self.split,
                ordinals=ordinals,
            )
            if (
                verified_nonces != capability_nonces
                or verified_preflight_sha256 != nonce_preflight_sha256
            ):
                raise PermissionError("formal capability nonce preflight changed before reserve")
            _validated_formal_materializer_before_batch_reserve(self, ordinals)
        self._ledger.reserve_batch(self.split, ordinals)
        _BATCH_REGISTRY[id(batch)] = registration
        for token in tokens:
            _TOKEN_REGISTRY[id(token)] = (token, registration, "issued")
        self._active = batch
        _validated_materializer_global_registry_cut(ledger=self._ledger)
        return batch

    def consume_ordinal(
        self,
        batch: _BatchCapability,
        token: _OrdinalCapability,
        *,
        ordinal: int,
    ) -> None:
        _ports, batches, tokens, _consumed = _validated_materializer_global_registry_cut(
            ledger=self._ledger
        )
        registration = batches.get(id(batch))
        token_registration = tokens.get(id(token))
        if (
            registration is None
            or registration.batch is not batch
            or registration.manifest is not self
            or registration.status != "issued"
            or self._active is not batch
            or token_registration != (token, registration, "issued")
            or type(ordinal) is not int
            or token.split != self.split
            or token.ordinal != ordinal
            or ordinal not in batch.ordinals
            or batch.tokens[ordinal - self._next_ordinal] is not token
            or ordinal in registration.consumed
        ):
            raise PermissionError("ordinal capability is forged, reordered, or replayed")
        registration.consumed.add(ordinal)
        _TOKEN_REGISTRY[id(token)] = (token, registration, "consumed")
        _validated_materializer_global_registry_cut(ledger=self._ledger)

    def complete_batch(
        self,
        batch: _BatchCapability,
        evaluation: Mapping[str, Any],
    ) -> dict[str, Any]:
        if (
            type(batch) is not _BatchCapability
            or type(batch.split) is not str
            or batch.split not in SPLITS
            or type(batch.ordinals) is not tuple
            or len(batch.ordinals) != BATCH_SIZE
            or any(type(ordinal) is not int for ordinal in batch.ordinals)
            or type(batch.tokens) is not tuple
            or len(batch.tokens) != BATCH_SIZE
            or any(type(token) is not _OrdinalCapability for token in batch.tokens)
        ):
            raise PermissionError("batch capability scalar binding differs")
        _ports, batches, tokens, _consumed = _validated_materializer_global_registry_cut(
            ledger=self._ledger
        )
        registration = batches.get(id(batch))
        if (
            type(registration) is not _BatchRegistration
            or registration.batch is not batch
            or registration.manifest is not self
            or type(registration.status) is not str
            or registration.status != "issued"
            or type(registration.consumed) is not set
            or any(type(ordinal) is not int for ordinal in registration.consumed)
            or self._active is not batch
            or registration.consumed != set(batch.ordinals)
            or batch.split != self.split
            or batch.ordinals != tuple(range(self._next_ordinal, self._next_ordinal + BATCH_SIZE))
        ):
            raise PermissionError("batch cannot commit before all four capabilities are consumed")
        token_registrations: list[tuple[_OrdinalCapability, _BatchRegistration, str]] = []
        for offset, token in enumerate(batch.tokens):
            token_registration = tokens.get(id(token))
            if (
                type(token.split) is not str
                or type(token.ordinal) is not int
                or type(token.nonce) is not object
                or token.split != self.split
                or token.ordinal != batch.ordinals[offset]
                or type(token_registration) is not tuple
                or len(token_registration) != 3
                or token_registration[0] is not token
                or token_registration[1] is not registration
                or type(token_registration[2]) is not str
                or token_registration[2] != "consumed"
            ):
                raise PermissionError(
                    "batch cannot commit before all four capabilities are consumed"
                )
            token_registrations.append(token_registration)

        def validated_receipt_from_input() -> dict[str, Any]:
            if type(evaluation) is not dict:
                raise TypeError("batch evaluation must be one exact dictionary")
            validated = _validated_public_batch_evaluation(
                evaluation,
                split=self.split,
                ordinals=batch.ordinals,
            )
            body = {
                "schema": "rgbd_known_action_public_batch_receipt_v2",
                "phase": "public",
                "split": self.split,
                "ordinals": list(batch.ordinals),
                "batch_index": batch.ordinals[0] // BATCH_SIZE,
                "bundle_count": BATCH_SIZE,
                "candidate_count": BATCH_SIZE * CANDIDATE_COUNT,
                "public_evaluation": copy.deepcopy(validated),
                "public_evidence": copy.deepcopy(validated["public_evidence"]),
                "public_evidence_sha256": validated["public_evidence_sha256"],
                "public_metrics": copy.deepcopy(validated["public_metrics"]),
                "public_metrics_sha256": canonical_sha256(validated["public_metrics"]),
                "public_resources": copy.deepcopy(validated["public_resources"]),
                "public_resources_sha256": canonical_sha256(validated["public_resources"]),
                "public_result_sha256": canonical_sha256(validated),
            }
            receipt = {**body, "receipt_sha256": canonical_sha256(body)}
            return _validate_batch_receipt(
                receipt,
                split=self.split,
                batch_index=body["batch_index"],
            )

        if self._ledger._record["execution_mode"] == "formal":
            (
                materializer_evaluation,
                vault_registration,
                envelope_registration,
            ) = _validated_formal_materializer_batch_precommit(
                self,
                batch,
            )
            failure_owner = _capture_materializer_failure_owner(vault_registration)
            core_owner_witness = (
                self,
                batch,
                registration,
                batch.tokens,
                tuple(token_registrations),
            )
            vault_registration.state = "checking_public_commit"
            try:
                receipt = validated_receipt_from_input()
                _validated_open_materializer_envelope(
                    envelope_registration.port,
                    vault_registration,
                    envelope_registration,
                    expected_evaluation=receipt["public_evaluation"],
                )
                _validated_materializer_global_registry_cut(
                    ledger=self._ledger,
                    port=envelope_registration.port,
                )
                expected_record = copy.deepcopy(self._ledger._record)
                expected_state = expected_record["splits"][self.split]
                batch_index = expected_state["public_next_ordinal"] // BATCH_SIZE
                expected_state["public_batch_receipts"].append(copy.deepcopy(receipt))
                expected_state["public_next_ordinal"] += BATCH_SIZE
                expected_state["public_active_batch"] = None
                expected_record["status"] = f"{self.split}_public_batch_{batch_index}_complete"
                expected_record["generation"] += 1
                predecessor_generation = self._ledger._record["generation"]
                self._ledger.commit_batch(self.split, receipt)
                durable_latch = _capture_materializer_durable_latch(self._ledger)
                _validated_materializer_transition_latch(
                    durable_latch,
                    expected_record,
                )
                durable_split = durable_latch[0]["splits"][self.split]
                if (
                    durable_latch[0]["generation"] != predecessor_generation + 1
                    or durable_split["status"] != "public_evaluating"
                    or durable_split["public_active_batch"] is not None
                    or durable_split["public_next_ordinal"] != batch.ordinals[-1] + 1
                    or not durable_split["public_batch_receipts"]
                    or durable_split["public_batch_receipts"][-1] != receipt
                ):
                    raise PermissionError("materializer public commit durable transition differs")
                # The durable receipt has advanced while the exact pending
                # evaluation and B=4 capabilities are intentionally retained
                # until the retirement block below.  Authenticate that narrow
                # transient with the core partition; the full reverse cut runs
                # after all three registries and the in-memory state align.
                postcommit_error, _ports, _batches, _tokens, _consumed = (
                    _partition_exact_materializer_core_registries(
                        postcommit_batch=batch,
                    )
                )
                if postcommit_error is not None:
                    _raise_materializer_registry_corruption(
                        postcommit_error,
                        ledger=self._ledger,
                        port=envelope_registration.port,
                    )
                _validated_open_materializer_envelope(
                    envelope_registration.port,
                    vault_registration,
                    envelope_registration,
                )
                if (
                    vault_registration.state != "checking_public_commit"
                    or not _exact_materializer_vault_root_registration(
                        id(vault_registration.vault),
                        vault_registration,
                    )
                ):
                    raise PermissionError(
                        "materializer public commit latch changed during durable transition"
                    )
                _verify_materializer_durable_latch(self._ledger, durable_latch)
                retired_materializer = _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.pop(
                    id(batch), None
                )
                if retired_materializer is not materializer_evaluation:
                    raise PermissionError("materializer batch binding changed during commit")
                retired_batch = _BATCH_REGISTRY.pop(id(batch), None)
                retired_tokens = tuple(
                    _TOKEN_REGISTRY.pop(id(token), None) for token in batch.tokens
                )
                if retired_batch is not registration or any(
                    retired is not expected
                    for retired, expected in zip(
                        retired_tokens,
                        token_registrations,
                        strict=True,
                    )
                ):
                    raise PermissionError("capability registries changed during atomic retirement")
                registration.status = "retired"
                self._next_ordinal += BATCH_SIZE
                self._active = None
                vault_registration.state = "collecting_public"
                _validated_materializer_global_registry_cut(
                    ledger=self._ledger,
                    port=envelope_registration.port,
                )
                _verify_materializer_durable_latch(self._ledger, durable_latch)
            except BaseException:
                _fail_materializer_vault(
                    vault_registration,
                    owner_witness=failure_owner,
                    core_owner_witness=core_owner_witness,
                )
                raise
            return receipt

        if _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.get(id(batch)) is not None:
            raise PermissionError("fake batch unexpectedly has a formal materializer binding")
        receipt = validated_receipt_from_input()
        self._ledger.commit_batch(self.split, receipt)
        retired_batch = _BATCH_REGISTRY.pop(id(batch), None)
        retired_tokens = tuple(_TOKEN_REGISTRY.pop(id(token), None) for token in batch.tokens)
        if retired_batch is not registration or any(
            retired is not expected
            for retired, expected in zip(retired_tokens, token_registrations, strict=True)
        ):
            raise PermissionError("capability registries changed during atomic retirement")
        registration.status = "retired"
        self._next_ordinal += BATCH_SIZE
        self._active = None
        return receipt

    def seal_public_split(
        self,
        finalization: Mapping[str, Any],
        *,
        batch_results: Sequence[Mapping[str, Any]],
        receipts: Sequence[Mapping[str, Any]],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        if self._closed or self._active is not None or self._next_ordinal != SCENES_PER_SPLIT:
            raise PermissionError("manifest cannot seal before all 64 public ordinals commit")
        if self._ledger._record["execution_mode"] == "formal":
            vault_registration = _validated_formal_materializer_public_seal(self)
            failure_owner = _capture_materializer_failure_owner(vault_registration)
            try:
                validated_finalization = _validated_public_split_finalization(
                    finalization,
                    split=self.split,
                    batch_results=batch_results,
                )
                summary = _public_split_summary(
                    split=self.split,
                    receipts=receipts,
                    finalization=validated_finalization,
                )
                seal = _public_split_seal(summary, split=self.split)
                _validated_materializer_public_inventory(
                    vault_registration.port,
                    vault_registration,
                    expected_child_state="public_finalized",
                    require_bound_digest=True,
                )
                _validated_materializer_global_registry_cut(
                    ledger=self._ledger,
                    port=vault_registration.port,
                )
                expected_record = copy.deepcopy(self._ledger._record)
                expected_state = expected_record["splits"][self.split]
                expected_state["status"] = "public_complete"
                expected_state["public_summary"] = copy.deepcopy(summary)
                expected_state["public_summary_sha256"] = canonical_sha256(summary)
                expected_state["public_seal"] = copy.deepcopy(seal)
                expected_state["public_seal_sha256"] = canonical_sha256(seal)
                expected_record["status"] = f"{self.split}_public_complete"
                expected_record["generation"] += 1
                predecessor_generation = self._ledger._record["generation"]
                self._ledger.complete_public_split(self.split, summary, seal)
                durable_latch = _capture_materializer_durable_latch(self._ledger)
                _validated_materializer_transition_latch(
                    durable_latch,
                    expected_record,
                )
                durable_split = durable_latch[0]["splits"][self.split]
                if (
                    durable_latch[0]["generation"] != predecessor_generation + 1
                    or durable_split["status"] != "public_complete"
                    or durable_split["public_summary"] != summary
                    or durable_split["public_seal"] != seal
                    or durable_split["public_seal_sha256"] != canonical_sha256(seal)
                ):
                    raise PermissionError("materializer public seal durable transition differs")
                _validated_materializer_global_registry_cut(
                    ledger=self._ledger,
                    port=vault_registration.port,
                )
                _validated_materializer_public_inventory(
                    vault_registration.port,
                    vault_registration,
                    expected_child_state="public_finalized",
                    require_bound_digest=True,
                )
                if (
                    vault_registration.state != "checking_public_seal"
                    or not _exact_materializer_vault_root_registration(
                        id(vault_registration.vault),
                        vault_registration,
                    )
                ):
                    raise PermissionError(
                        "materializer public seal latch changed during durable transition"
                    )
                _verify_materializer_durable_latch(self._ledger, durable_latch)
                vault_registration.state = "public_sealed"
                _validated_materializer_global_registry_cut(
                    ledger=self._ledger,
                    port=vault_registration.port,
                )
                _verify_materializer_durable_latch(self._ledger, durable_latch)
            except BaseException:
                _fail_materializer_vault(
                    vault_registration,
                    owner_witness=failure_owner,
                )
                raise
            return summary, seal

        validated_finalization = _validated_public_split_finalization(
            finalization,
            split=self.split,
            batch_results=batch_results,
        )
        summary = _public_split_summary(
            split=self.split,
            receipts=receipts,
            finalization=validated_finalization,
        )
        seal = _public_split_seal(summary, split=self.split)
        self._ledger.complete_public_split(self.split, summary, seal)
        return summary, seal

    def begin_private_scoring(
        self,
        *,
        public_seal: Mapping[str, Any],
    ) -> PrivateSplitScoringRequest:
        if (
            self._closed
            or self._active is not None
            or self._truth_request is not None
            or self._next_ordinal != SCENES_PER_SPLIT
        ):
            raise PermissionError("private scoring request is not at its one post-seal boundary")
        state = self._ledger._record["splits"][self.split]
        if (
            state["status"] != "public_complete"
            or type(state["public_summary"]) is not dict
            or type(state["public_seal"]) is not dict
        ):
            raise PermissionError("private scoring cannot precede the durable public seal")
        validated_seal = _validated_public_split_seal(
            copy.deepcopy(dict(public_seal)),
            split=self.split,
            summary=state["public_summary"],
        )
        if state["public_seal"] != validated_seal:
            raise PermissionError("private scoring request differs from the durable public seal")
        self._ledger.begin_truth_evaluation(self.split)
        state = self._ledger._record["splits"][self.split]
        request_binding = {
            "schema": "rgbd_known_action_split_truth_request_v1",
            "split": self.split,
            "ledger_generation": self._ledger._record["generation"],
            "ledger_record_sha256": canonical_sha256(self._ledger._record),
            "ledger_file_identity": list(self._ledger._last_identity),
            "public_seal_sha256": state["public_seal_sha256"],
        }
        request_bytes = _canonical_json(request_binding)
        request_sha256 = canonical_sha256(request_binding)
        authority = _SplitTruthAuthority(
            split=self.split,
            directory_pin=self._ledger._pin,
            ledger_identity=id(self._ledger),
            ledger_file_identity=self._ledger._last_identity,
            ledger_generation=self._ledger._record["generation"],
            ledger_record_sha256=canonical_sha256(self._ledger._record),
            public_seal_sha256=state["public_seal_sha256"],
            request_bytes=request_bytes,
            request_sha256=request_sha256,
            owner_thread=threading.get_ident(),
            nonce=object(),
        )
        request = PrivateSplitScoringRequest(
            split=self.split,
            public_seal_sha256=state["public_seal_sha256"],
            request_sha256=request_sha256,
            _authority=authority,
            _manifest=self,
        )
        if (
            id(authority) in _TRUTH_AUTHORITY_REGISTRY
            or id(authority) in _TRUTH_AUTHORITY_BINDING_REGISTRY
            or any(
                registration[1] is self and registration[3] in {"issued", "consuming", "consumed"}
                for registration in _TRUTH_AUTHORITY_REGISTRY.values()
            )
        ):
            raise PermissionError("one split truth authority was already issued")
        _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            self,
            request,
            "issued",
            None,
        )
        _TRUTH_AUTHORITY_BINDING_REGISTRY[id(authority)] = _split_truth_authority_binding(authority)
        self._truth_request = request
        return request

    def consume_private_scoring_request(
        self,
        request: PrivateSplitScoringRequest,
    ) -> dict[str, Any]:
        if type(request) is not PrivateSplitScoringRequest:
            raise PermissionError("private scoring request is forged")
        authority = request._authority
        registration = _TRUTH_AUTHORITY_REGISTRY.get(id(authority))
        registered_binding = _TRUTH_AUTHORITY_BINDING_REGISTRY.get(id(authority))
        if (
            registration is None
            or registration[0] is not authority
            or registration[1] is not self
            or registration[2] is not request
            or registration[3] != "issued"
            or registration[4] is not None
            or self._truth_request is not request
            or registered_binding is None
        ):
            raise PermissionError("private scoring request is forged, reentrant, or replayed")
        try:
            current_binding = _split_truth_authority_binding(authority)
        except BaseException:
            _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
                authority,
                self,
                request,
                "failed",
                None,
            )
            raise PermissionError("private scoring request authority was rebound") from None
        if current_binding != registered_binding:
            _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
                authority,
                self,
                request,
                "failed",
                None,
            )
            raise PermissionError("private scoring request authority was rebound")
        _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            self,
            request,
            "consuming",
            None,
        )
        try:
            self._ledger._verify_disk()
            state = self._ledger._record["splits"][self.split]
            request_binding = _validated_truth_request_binding(
                _strict_json_loads(authority.request_bytes, label="split truth request"),
                split=self.split,
            )
            if (
                self._closed
                or request.split != self.split
                or request.public_seal_sha256 != state["public_seal_sha256"]
                or request.request_sha256 != canonical_sha256(request_binding)
                or authority.owner_thread != threading.get_ident()
                or authority.owner_thread != self._ledger._owner_thread
                or authority.split != self.split
                or authority.directory_pin is not self._ledger._pin
                or authority.ledger_identity != id(self._ledger)
                or authority.ledger_file_identity != self._ledger._last_identity
                or authority.ledger_generation != self._ledger._record["generation"]
                or authority.ledger_record_sha256 != canonical_sha256(self._ledger._record)
                or authority.public_seal_sha256 != state["public_seal_sha256"]
                or authority.request_sha256 != canonical_sha256(request_binding)
                or state["status"] != "truth_evaluating"
            ):
                raise PermissionError("private scoring request authority was rebound")
        except BaseException:
            _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
                authority,
                self,
                request,
                "failed",
                None,
            )
            raise
        _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            self,
            request,
            "consumed",
            None,
        )
        return copy.deepcopy(request_binding)

    def close(
        self,
        request: PrivateSplitScoringRequest,
        receipt: Mapping[str, Any],
        result: Mapping[str, Any],
    ) -> None:
        if (
            type(request) is not PrivateSplitScoringRequest
            or type(receipt) is not dict
            or type(result) is not dict
        ):
            raise PermissionError("formal manifest completion arguments are forged")
        authority = request._authority
        registration = _TRUTH_AUTHORITY_REGISTRY.get(id(authority))
        if (
            self._closed
            or self._active is not None
            or self._truth_request is not request
            or registration is None
            or registration[0] is not authority
            or registration[1] is not self
            or registration[2] is not request
            or registration[3] != "consumed"
            or registration[4] is not None
            or _TRUTH_AUTHORITY_BINDING_REGISTRY.get(id(authority))
            != _split_truth_authority_binding(authority)
        ):
            raise PermissionError("manifest lacks one consumed private scoring request")
        state = self._ledger._record["splits"][self.split]
        validated_receipt = _validated_private_scoring_receipt(
            copy.deepcopy(dict(receipt)),
            split=self.split,
            public_seal_sha256=state["public_seal_sha256"],
        )
        formal = self._ledger._record["execution_mode"] == "formal"
        expected_receipt_schema = (
            "rgbd_known_action_formal_private_scoring_receipt_v1"
            if formal
            else "rgbd_known_action_fake_test_private_scoring_receipt_v1"
        )
        if validated_receipt["schema"] != expected_receipt_schema:
            raise PermissionError("manifest private scoring receipt execution mode differs")
        if validated_receipt["truth_request_sha256"] != request.request_sha256:
            raise PermissionError("private scoring receipt names another request")
        materializer: tuple[_TrustedMaterializerPort, _MaterializerSplitVault] | None = None
        if formal:
            slot_identity = _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(
                (id(self._ledger), self.split)
            )
            vault_registration = (
                _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(slot_identity)
                if type(slot_identity) is int
                else None
            )
            if (
                type(vault_registration) is not _MaterializerVaultRegistration
                or vault_registration.ledger is not self._ledger
                or vault_registration.vault.split != self.split
            ):
                raise PermissionError("formal manifest lacks its materializer vault")
            _validate_formal_private_receipt_materializer_binding(
                vault_registration.port,
                vault_registration.vault,
                request,
                validated_receipt,
            )
            materializer = (vault_registration.port, vault_registration.vault)
        receipt_digest = canonical_sha256(validated_receipt)
        _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            self,
            request,
            "receipt_bound",
            receipt_digest,
        )
        try:
            if materializer is not None:
                _complete_materializer_private_consumption(
                    materializer[0],
                    materializer[1],
                    request,
                )
            self._ledger.complete_split(
                self.split,
                result,
                authority=authority,
                receipt=validated_receipt,
            )
        except BaseException:
            current = _TRUTH_AUTHORITY_REGISTRY.get(id(authority))
            if (
                type(current) is tuple
                and len(current) == 5
                and current[0] is authority
                and current[1] is self
                and current[2] is request
                and current[3] == "receipt_bound"
            ):
                _TRUTH_AUTHORITY_REGISTRY[id(authority)] = (
                    authority,
                    self,
                    request,
                    "failed",
                    receipt_digest,
                )
            raise
        self._closed = True

    def abort(self) -> None:
        """Revoke an issued in-memory batch while preserving its durable reservation."""

        batch = self._active
        ownership_changed = False
        truth_request = self._truth_request
        truth_registration = (
            _TRUTH_AUTHORITY_REGISTRY.get(id(truth_request._authority))
            if type(truth_request) is PrivateSplitScoringRequest
            else None
        )
        truth_request_binding_changed = bool(
            truth_request is not None
            and (
                type(truth_request) is not PrivateSplitScoringRequest
                or type(truth_registration) is not tuple
                or len(truth_registration) != 5
                or truth_registration[0] is not truth_request._authority
                or truth_registration[1] is not self
                or truth_registration[2] is not truth_request
                or type(truth_registration[3]) is not str
                or truth_registration[3]
                not in {"issued", "consuming", "consumed", "receipt_bound", "failed"}
            )
        )
        had_live_materializer_root = any(
            type(registration) is _MaterializerVaultRegistration
            and type(registration.ledger) is _AccessLedger
            and registration.ledger is self._ledger
            and type(registration.state) is str
            and registration.state in MATERIALIZER_LIVE_VAULT_STATES
            for registration in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
        )
        try:
            _validated_materializer_global_registry_cut(ledger=self._ledger)
        except PermissionError:
            # The global cut has already partitioned the registries and
            # fail-closed any materializer vault it could recover.  Continue
            # with exact manifest/truth retirement.  Report corruption when
            # this abort owned a live capability; a prior fail-closed call may
            # leave only deliberately immutable terminal tombstones.
            ownership_changed = bool(
                batch is not None or truth_request_binding_changed or had_live_materializer_root
            )
        owned_registrations = {
            identity: registration
            for identity, registration in tuple(_BATCH_REGISTRY.items())
            if registration.manifest is self
        }
        if batch is not None and owned_registrations.get(id(batch)) is None:
            ownership_changed = True
        for identity, authority_registration in tuple(_CONSUMED_ORDINAL_REGISTRY.items()):
            if authority_registration[1]._manifest is self:
                _CONSUMED_ORDINAL_REGISTRY.pop(identity, None)
        for identity, token_registration in tuple(_TOKEN_REGISTRY.items()):
            if token_registration[1].manifest is self:
                if not any(
                    token_registration[1] is registration
                    for registration in owned_registrations.values()
                ):
                    ownership_changed = True
                _TOKEN_REGISTRY.pop(identity, None)
        for identity, registration in owned_registrations.items():
            if _BATCH_REGISTRY.pop(identity, None) is not registration:
                ownership_changed = True
            registration.status = "revoked"
            _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.pop(
                id(registration.batch),
                None,
            )
        self._active = None
        request = self._truth_request
        owned_truth = [
            (identity, registration)
            for identity, registration in tuple(_TRUTH_AUTHORITY_REGISTRY.items())
            if registration[1] is self
        ]
        if request is not None and not any(
            registration[2] is request for _, registration in owned_truth
        ):
            ownership_changed = True
        for identity, registration in owned_truth:
            authority, manifest, registered_request, _state, receipt = registration
            if manifest is not self or id(authority) != identity:
                ownership_changed = True
            _TRUTH_AUTHORITY_REGISTRY[identity] = (
                authority,
                self,
                registered_request,
                "revoked",
                receipt,
            )
        self._truth_request = None
        self._closed = True
        if ownership_changed:
            raise PermissionError("manifest capability registry ownership changed during abort")


SPLIT_RESULT_SCHEMA = frozenset(
    {
        "schema",
        "artifact_kind",
        "split",
        "ordinal_count",
        "batch_count",
        "task_bundle_count",
        "candidate_count",
        "batch_receipt_sha256",
        "batch_evidence",
        "batch_evidence_sha256",
        "public_summary",
        "public_summary_sha256",
        "public_seal",
        "public_seal_sha256",
        "private_scoring_receipt",
        "private_scoring_receipt_sha256",
        "scene_manifest_sha256",
        "metrics",
        "inherited_orbital_evidence",
        "failures",
        "passed",
        "public_evaluation_started",
        "private_scoring_completed",
        "scene_access_count",
        "truth_access_count",
        "access_completed",
        "outcome",
        "model_state_sha256",
        "optimizer_updates",
    }
)


def _validated_split_result(value: Any, *, split: str) -> dict[str, Any]:
    _require_exact_keys(value, SPLIT_RESULT_SCHEMA, label=f"{split} result")
    if (
        value["schema"] != "rgbd_known_action_split_result_v2"
        or value["artifact_kind"] != "rgbd_known_action_split_result"
        or value["split"] != split
        or type(value["ordinal_count"]) is not int
        or type(value["batch_count"]) is not int
        or type(value["task_bundle_count"]) is not int
        or type(value["candidate_count"]) is not int
        or value["ordinal_count"] != SCENES_PER_SPLIT
        or value["batch_count"] != SCENES_PER_SPLIT // BATCH_SIZE
        or value["task_bundle_count"] != SCENES_PER_SPLIT
        or value["candidate_count"] != SCENES_PER_SPLIT * CANDIDATE_COUNT
        or value["scene_manifest_sha256"] != SPLIT_ADDRESS_SHA256[split]
        or type(value["metrics"]) is not dict
        or type(value["failures"]) is not list
        or any(type(item) is not str for item in value["failures"])
        or type(value["passed"]) is not bool
        or value["public_evaluation_started"] is not True
        or value["private_scoring_completed"] is not True
        or type(value["scene_access_count"]) is not int
        or type(value["truth_access_count"]) is not int
        or value["access_completed"] is not True
        or value["outcome"] not in {"passed", "gate_failed"}
        or value["model_state_sha256"] != EMPTY_MODEL_STATE_SHA256
        or type(value["optimizer_updates"]) is not int
        or value["optimizer_updates"] != 0
    ):
        raise ValueError(f"{split} result scalar binding differs")
    validated_sha256(value["batch_receipt_sha256"], label=f"{split} batch receipts")
    if type(value["batch_evidence"]) is not list or len(value["batch_evidence"]) != (
        SCENES_PER_SPLIT // BATCH_SIZE
    ):
        raise ValueError(f"{split} batch evidence inventory differs")
    validated_batch_evidence = [
        _validated_numeric_batch_evidence(
            evidence,
            split=split,
            ordinals=tuple(range(index * BATCH_SIZE, (index + 1) * BATCH_SIZE)),
        )
        for index, evidence in enumerate(value["batch_evidence"])
    ]
    if value["batch_evidence_sha256"] != canonical_sha256(validated_batch_evidence):
        raise ValueError(f"{split} ordered batch evidence hash differs")
    summary = _validated_public_split_summary_shape(value["public_summary"], split=split)
    seal = _validated_public_split_seal(value["public_seal"], split=split, summary=summary)
    if (
        value["public_summary_sha256"] != canonical_sha256(summary)
        or value["public_seal_sha256"] != canonical_sha256(seal)
        or value["batch_receipt_sha256"] != summary["ordered_batch_receipts_sha256"]
        or value["batch_evidence_sha256"] != summary["public_evidence_sha256"]
    ):
        raise ValueError(f"{split} result public seal/hash binding differs")
    private_receipt = _validated_private_scoring_receipt(
        value["private_scoring_receipt"],
        split=split,
        public_seal_sha256=value["public_seal_sha256"],
    )
    if value["private_scoring_receipt_sha256"] != canonical_sha256(private_receipt):
        raise ValueError(f"{split} result private receipt hash differs")
    if (
        value["scene_access_count"] != private_receipt["scene_access_count"]
        or value["truth_access_count"] != private_receipt["truth_access_count"]
    ):
        raise ValueError(f"{split} result private access counts differ")
    inherited = _validated_inherited_orbital_evidence(value["inherited_orbital_evidence"])
    _exact_equal(value["metrics"], private_receipt["metrics"], label=f"{split} private metrics")
    _exact_equal(
        inherited,
        private_receipt["inherited_orbital_evidence"],
        label=f"{split} private inherited evidence",
    )
    expected_failures = copy.deepcopy(private_receipt["failures"])
    if value["failures"] != expected_failures:
        raise ValueError(f"{split} result gate failures differ")
    expected_passed = not expected_failures
    if value["passed"] is not expected_passed or value["outcome"] != (
        "passed" if expected_passed else "gate_failed"
    ):
        raise ValueError(f"{split} result outcome differs")
    native = _json_native(copy.deepcopy(value), label=f"{split} result")
    assert type(native) is dict
    return native


def _split_result_from_private_receipt(
    *,
    split: str,
    state: Mapping[str, Any],
    private_receipt: Mapping[str, Any],
) -> dict[str, Any]:
    if state.get("status") != "truth_evaluating":
        raise PermissionError("split result requires the durable truth-evaluating state")
    receipts = state["public_batch_receipts"]
    summary = _validated_public_split_summary(
        state["public_summary"],
        split=split,
        receipts=receipts,
    )
    seal = _validated_public_split_seal(
        state["public_seal"],
        split=split,
        summary=summary,
    )
    validated_private = _validated_private_scoring_receipt(
        private_receipt,
        split=split,
        public_seal_sha256=state["public_seal_sha256"],
    )
    result = {
        "schema": "rgbd_known_action_split_result_v2",
        "artifact_kind": "rgbd_known_action_split_result",
        "split": split,
        "ordinal_count": SCENES_PER_SPLIT,
        "batch_count": len(receipts),
        "task_bundle_count": SCENES_PER_SPLIT,
        "candidate_count": SCENES_PER_SPLIT * CANDIDATE_COUNT,
        "batch_receipt_sha256": canonical_sha256(receipts),
        "batch_evidence": [copy.deepcopy(receipt["public_evidence"]) for receipt in receipts],
        "batch_evidence_sha256": canonical_sha256(
            [receipt["public_evidence"] for receipt in receipts]
        ),
        "public_summary": copy.deepcopy(summary),
        "public_summary_sha256": canonical_sha256(summary),
        "public_seal": copy.deepcopy(seal),
        "public_seal_sha256": canonical_sha256(seal),
        "private_scoring_receipt": copy.deepcopy(validated_private),
        "private_scoring_receipt_sha256": canonical_sha256(validated_private),
        "scene_manifest_sha256": SPLIT_ADDRESS_SHA256[split],
        "metrics": copy.deepcopy(validated_private["metrics"]),
        "inherited_orbital_evidence": copy.deepcopy(
            validated_private["inherited_orbital_evidence"]
        ),
        "failures": copy.deepcopy(validated_private["failures"]),
        "passed": validated_private["passed"],
        "public_evaluation_started": True,
        "private_scoring_completed": True,
        "scene_access_count": validated_private["scene_access_count"],
        "truth_access_count": validated_private["truth_access_count"],
        "access_completed": True,
        "outcome": validated_private["outcome"],
        "model_state_sha256": EMPTY_MODEL_STATE_SHA256,
        "optimizer_updates": 0,
    }
    return _validated_split_result(result, split=split)


def _evaluate_split(
    *,
    split: str,
    ledger: _AccessLedger,
    evaluator: QualificationEvaluator,
    boundary_guard: Callable[[str], None],
) -> dict[str, Any]:
    boundary_guard(f"before {split} public access")
    manifest = _ManifestCapability(split=split, ledger=ledger)
    try:
        batch_results: list[dict[str, Any]] = []
        receipts: list[dict[str, Any]] = []
        for start in range(0, SCENES_PER_SPLIT, BATCH_SIZE):
            boundary_guard(f"before {split} public batch {start // BATCH_SIZE}")
            ordinals = tuple(range(start, start + BATCH_SIZE))
            batch = manifest.begin_batch(ordinals)
            request = PublicBatchEvaluationRequest(
                split=split,
                ordinals=ordinals,
                tokens=batch.tokens,
                _manifest=manifest,
                _batch=batch,
            )
            raw = evaluator.evaluate_public_batch(request)
            if type(raw) is not dict:
                raise TypeError("public evaluator batch result must be one exact dict")
            validated = _validated_public_batch_evaluation(
                raw,
                split=split,
                ordinals=ordinals,
            )
            receipt = manifest.complete_batch(batch, validated)
            batch_results.append(validated)
            receipts.append(receipt)
            boundary_guard(f"after {split} public batch {start // BATCH_SIZE}")
        boundary_guard(f"before {split} public seal")
        raw_finalization = evaluator.finalize_public_split(split, tuple(batch_results))
        if type(raw_finalization) is not dict:
            raise TypeError("public evaluator split finalization must be one exact dict")
        finalization = _validated_public_split_finalization(
            raw_finalization,
            split=split,
            batch_results=batch_results,
        )
        _, public_seal = manifest.seal_public_split(
            finalization,
            batch_results=batch_results,
            receipts=receipts,
        )
        boundary_guard(f"after {split} public seal")
        private_request = manifest.begin_private_scoring(public_seal=public_seal)
        boundary_guard(f"before {split} private scoring")
        raw_private_receipt = evaluator.score_private_split(private_request)
        if type(raw_private_receipt) is not dict:
            raise TypeError("private evaluator split receipt must be one exact dict")
        state = ledger._record["splits"][split]
        private_receipt = _validated_private_scoring_receipt(
            raw_private_receipt,
            split=split,
            public_seal_sha256=state["public_seal_sha256"],
        )
        validated_result = _split_result_from_private_receipt(
            split=split,
            state=state,
            private_receipt=private_receipt,
        )
        manifest.close(private_request, private_receipt, validated_result)
        boundary_guard(f"after {split} private scoring")
        return validated_result
    except BaseException:
        try:
            evaluator.abort_split(split)
        finally:
            manifest.abort()
        raise


