def _checkpoint_bytes(
    *,
    development_result: Mapping[str, Any],
    source_provenance: Mapping[str, Any],
    execution_mode: ExecutionMode,
    formal_authorization: Mapping[str, Any] | None = None,
) -> bytes:
    if execution_mode not in {"formal", "fake_test"}:
        raise ValueError("checkpoint execution mode is invalid")
    validated_result = _validated_split_result(
        copy.deepcopy(dict(development_result)),
        split="development",
    )
    if validated_result["passed"] is not True:
        raise ValueError("checkpoint requires passed development evidence")
    source = _validated_source_provenance(copy.deepcopy(dict(source_provenance)))
    payload = {
        "artifact_kind": "rgbd_known_action_empty_state_checkpoint",
        "execution_mode": execution_mode,
        "architecture_version": ARCHITECTURE_VERSION,
        "architecture_attempt": ARCHITECTURE_ATTEMPT,
        "model_state": {},
        "model_state_sha256": EMPTY_MODEL_STATE_SHA256,
        "optimizer_state": None,
        "scheduler_state": None,
        "rng_state": None,
        "optimizer_updates": OPTIMIZER_UPDATES,
        "resolved_config_sha256": FROZEN_CONFIG_SHA256,
        "protocol_sha256": bridge_protocol()["protocol_sha256"],
        "scene_binding": _scene_binding_status(),
        "development_result": validated_result,
        "source_provenance": source,
        "project_version": __version__,
        "specification_version": SPECIFICATION_VERSION,
        "simulator_version": SIMULATOR_VERSION,
        "device": "cpu",
        "precision": "float32",
    }
    if execution_mode == "formal":
        payload["formal_authorization"] = _validated_formal_authorization_binding(
            copy.deepcopy(dict(formal_authorization or {}))
        )
    elif formal_authorization is not None:
        raise PermissionError("fake checkpoint cannot carry formal outer authorization")
    _require_exact_keys(
        payload,
        FORMAL_CHECKPOINT_SCHEMA if execution_mode == "formal" else CHECKPOINT_SCHEMA,
        label="checkpoint payload",
    )
    stream = io.BytesIO()
    torch.save(payload, stream)
    contents = stream.getvalue()
    if not contents or len(contents) > MAX_CHECKPOINT_BYTES:
        raise RuntimeError("empty-state checkpoint exceeds its fixed byte budget")
    _validate_checkpoint_payload(
        contents,
        expected_source=source,
        expected_execution_mode=execution_mode,
        expected_formal_authorization=formal_authorization,
    )
    return contents


def _load_checkpoint_payload(
    contents: bytes,
    *,
    expected_execution_mode: ExecutionMode = "formal",
) -> dict[str, Any]:
    """Load only the restricted, tensor-safe empty-state checkpoint surface."""

    if type(contents) is not bytes or not contents or len(contents) > MAX_CHECKPOINT_BYTES:
        raise ValueError("checkpoint bytes are empty, oversized, or not exact bytes")
    _activate_recovery_checkpoint_dependency()
    payload = torch.load(io.BytesIO(contents), map_location="cpu", weights_only=True)
    if type(payload) is not dict:
        raise TypeError("checkpoint root must be one exact dict")
    _require_exact_keys(
        payload,
        (FORMAL_CHECKPOINT_SCHEMA if expected_execution_mode == "formal" else CHECKPOINT_SCHEMA),
        label="checkpoint payload",
    )
    return payload


def _validate_checkpoint_payload(
    contents: bytes,
    *,
    expected_source: Mapping[str, Any],
    expected_execution_mode: ExecutionMode = "formal",
    expected_formal_authorization: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if expected_execution_mode not in {"formal", "fake_test"}:
        raise ValueError("expected checkpoint execution mode is invalid")
    payload = _load_checkpoint_payload(
        contents,
        expected_execution_mode=expected_execution_mode,
    )
    expected_scalars = {
        "artifact_kind": "rgbd_known_action_empty_state_checkpoint",
        "execution_mode": expected_execution_mode,
        "architecture_version": ARCHITECTURE_VERSION,
        "architecture_attempt": ARCHITECTURE_ATTEMPT,
        "model_state_sha256": EMPTY_MODEL_STATE_SHA256,
        "optimizer_state": None,
        "scheduler_state": None,
        "rng_state": None,
        "optimizer_updates": 0,
        "resolved_config_sha256": FROZEN_CONFIG_SHA256,
        "protocol_sha256": bridge_protocol()["protocol_sha256"],
        "scene_binding": _scene_binding_status(),
        "project_version": __version__,
        "specification_version": SPECIFICATION_VERSION,
        "simulator_version": SIMULATOR_VERSION,
        "device": "cpu",
        "precision": "float32",
    }
    for name, expected in expected_scalars.items():
        _exact_equal(payload[name], expected, label=f"checkpoint.{name}")
    if type(payload["model_state"]) is not dict or payload["model_state"]:
        raise ValueError("checkpoint model_state must be one exact empty dict")
    result = _validated_split_result(payload["development_result"], split="development")
    if result["passed"] is not True:
        raise ValueError("checkpoint development evidence must pass")
    source = _validated_source_provenance(payload["source_provenance"])
    expected = _validated_source_provenance(copy.deepcopy(dict(expected_source)))
    _exact_equal(source, expected, label="checkpoint source provenance")
    if expected_execution_mode == "formal":
        authorization = _validated_formal_authorization_binding(payload["formal_authorization"])
        if expected_formal_authorization is not None:
            _exact_equal(
                authorization,
                _validated_formal_authorization_binding(
                    copy.deepcopy(dict(expected_formal_authorization))
                ),
                label="checkpoint formal outer authorization",
            )
    elif expected_formal_authorization is not None:
        raise PermissionError("fake checkpoint validation rejects formal outer authorization")
    return payload


def _artifact_paths(pin: _PinnedDirectory) -> dict[str, Path]:
    _validate_pinned_directory(pin)
    return {
        "development_report": pin.path / DEVELOPMENT_REPORT_NAME,
        "checkpoint": pin.path / CHECKPOINT_NAME,
        "development_ledger": pin.path / DEVELOPMENT_LEDGER_NAME,
        "qualification_report": pin.path / QUALIFICATION_REPORT_NAME,
        "qualification_ledger": pin.path / QUALIFICATION_LEDGER_NAME,
    }


def _validate_run_tree(
    pin: _PinnedDirectory,
    expected: frozenset[str],
    *,
    stage: str,
) -> None:
    if type(expected) is not frozenset:
        raise TypeError("expected run tree must be one exact frozenset")
    actual = _pinned_inventory(pin)
    if actual != expected:
        raise PermissionError(
            f"{stage} run tree differs: missing={sorted(expected - actual)!r}, "
            f"extra={sorted(actual - expected)!r}"
        )


def _save_review_checkpoint(
    pin: _PinnedDirectory,
    *,
    development_result: Mapping[str, Any],
    source_provenance: Mapping[str, Any],
    execution_mode: ExecutionMode,
    formal_authorization: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    path = _artifact_paths(pin)["checkpoint"]
    contents = _checkpoint_bytes(
        development_result=development_result,
        source_provenance=source_provenance,
        execution_mode=execution_mode,
        formal_authorization=formal_authorization,
    )
    # The durable-create helper returns only after it has either completed the
    # publication or reconciled and adopted the exact published bytes.  Avoid
    # a second fallible read after that commit point: a transient read fault
    # must not strand an otherwise exact checkpoint before report intent.
    _pinned_durable_create(pin, path, contents)
    record = {
        "artifact_name": CHECKPOINT_NAME,
        "sha256": sha256_bytes(contents),
        "bytes": len(contents),
        "model_state_sha256": EMPTY_MODEL_STATE_SHA256,
        "model_state_entry_count": 0,
        "optimizer_state_entry_count": 0,
        "rng_state_entry_count": 0,
    }
    _validate_checkpoint_record(record, required=True)
    return record


def _validate_checkpoint_record(value: Any, *, required: bool) -> dict[str, Any] | None:
    if value is None:
        if required:
            raise ValueError("passed development requires a checkpoint record")
        return None
    _require_exact_keys(value, CHECKPOINT_RECORD_SCHEMA, label="checkpoint record")
    if (
        value["artifact_name"] != CHECKPOINT_NAME
        or type(value["bytes"]) is not int
        or not 0 < value["bytes"] <= MAX_CHECKPOINT_BYTES
        or value["model_state_sha256"] != EMPTY_MODEL_STATE_SHA256
        or type(value["model_state_entry_count"]) is not int
        or value["model_state_entry_count"] != 0
        or type(value["optimizer_state_entry_count"]) is not int
        or value["optimizer_state_entry_count"] != 0
        or type(value["rng_state_entry_count"]) is not int
        or value["rng_state_entry_count"] != 0
    ):
        raise ValueError("checkpoint record empty-state binding differs")
    validated_sha256(value["sha256"], label="checkpoint record")
    native = _json_native(copy.deepcopy(value), label="checkpoint record")
    assert type(native) is dict
    return native


def _validated_reviewed_development(value: Any) -> dict[str, str]:
    _require_exact_keys(value, REVIEWED_DEVELOPMENT_SCHEMA, label="reviewed development")
    return {
        name: validated_sha256(value[name], label=f"reviewed development {name}")
        for name in ("checkpoint_sha256", "report_sha256", "ledger_sha256")
    }


def _ledger_bindings(
    *,
    stage: Stage,
    execution_mode: ExecutionMode,
    directory_pin: _PinnedDirectory,
    source_provenance: Mapping[str, Any],
    reviewed_development: Mapping[str, str] | None = None,
    formal_authorization: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if execution_mode not in {"formal", "fake_test"}:
        raise ValueError("ledger execution mode is invalid")
    splits = ("development",) if stage == "development" else PROTECTED_SPLITS
    bindings: dict[str, Any] = {
        "schema": "rgbd_known_action_ledger_bindings_v1",
        "execution_mode": execution_mode,
        "protocol_sha256": bridge_protocol()["protocol_sha256"],
        "resolved_config_sha256": FROZEN_CONFIG_SHA256,
        "scene_binding": _scene_binding_status(),
        "run_directory": _pinned_directory_binding(directory_pin),
        "split_address_sha256": {split: SPLIT_ADDRESS_SHA256[split] for split in splits},
        "source_provenance": _validated_source_provenance(copy.deepcopy(dict(source_provenance))),
    }
    if stage == "development":
        if reviewed_development is not None:
            raise ValueError("development ledger cannot bind reviewed evidence")
    else:
        reviewed = _validated_reviewed_development(copy.deepcopy(dict(reviewed_development or {})))
        bindings["reviewed_development"] = reviewed
        bindings["reviewed_development_nonce_baseline"] = _reviewed_development_nonce_baseline(
            directory_pin,
            expected_ledger_sha256=reviewed["ledger_sha256"],
        )[0]
    if execution_mode == "formal":
        bindings["formal_authorization"] = _validated_formal_authorization_binding(
            copy.deepcopy(dict(formal_authorization or {}))
        )
    elif formal_authorization is not None:
        raise PermissionError("fake ledger bindings cannot carry formal outer authorization")
    native = _json_native(bindings, label=f"{stage} ledger bindings")
    assert type(native) is dict
    return native


def _validated_existing_formal_ledger_bindings(
    value: Any,
    *,
    stage: Stage,
    directory_pin: _PinnedDirectory,
    source_provenance: Mapping[str, Any],
    reviewed_development: Mapping[str, str] | None,
) -> dict[str, Any]:
    """Validate recovery bindings while preserving the first invocation authority."""

    if type(value) is not dict or stage not in {"development", "qualification"}:
        raise TypeError("formal recovery ledger bindings must be one exact stage dictionary")
    source = _validated_source_provenance(copy.deepcopy(dict(source_provenance)))
    original_authorization = _validated_formal_authorization_binding(
        value.get("formal_authorization")
    )
    splits = ("development",) if stage == "development" else PROTECTED_SPLITS
    expected: dict[str, Any] = {
        "schema": "rgbd_known_action_ledger_bindings_v1",
        "execution_mode": "formal",
        "protocol_sha256": bridge_protocol()["protocol_sha256"],
        "resolved_config_sha256": FROZEN_CONFIG_SHA256,
        "scene_binding": _scene_binding_status(),
        "run_directory": _pinned_directory_binding(directory_pin),
        "split_address_sha256": {split: SPLIT_ADDRESS_SHA256[split] for split in splits},
        "source_provenance": source,
        "formal_authorization": original_authorization,
    }
    if stage == "development":
        if reviewed_development is not None:
            raise ValueError("development recovery cannot bind reviewed evidence")
    else:
        reviewed = _validated_reviewed_development(copy.deepcopy(dict(reviewed_development or {})))
        expected["reviewed_development"] = reviewed
        expected["reviewed_development_nonce_baseline"] = (
            _validated_reviewed_development_nonce_baseline(
                value.get("reviewed_development_nonce_baseline")
            )
        )
    _require_exact_keys(value, frozenset(expected), label="formal recovery ledger bindings")
    _exact_equal(value, expected, label="formal recovery ledger bindings")
    native = _json_native(copy.deepcopy(expected), label="formal recovery ledger bindings")
    assert type(native) is dict
    return native


def _authorize_ledger_creation(
    *,
    invocation_seal: _RunnerInvocationSeal,
    stage: Stage,
    directory_pin: _PinnedDirectory,
    source_provenance: Mapping[str, Any],
    bindings: Mapping[str, Any],
    ledger_path: Path,
    reviewed_development: Mapping[str, str] | None = None,
) -> _RunAuthorization:
    _consume_runner_invocation_seal(
        invocation_seal,
        stage=stage,
        directory_pin=directory_pin,
        source_provenance=source_provenance,
        reviewed_development=reviewed_development,
    )
    return _mint_run_authorization(
        invocation_seal=invocation_seal,
        bindings=bindings,
        ledger_path=ledger_path,
    )


def _report_root(
    *,
    stage: Stage,
    execution_mode: ExecutionMode,
    source_provenance: Mapping[str, Any],
    results: Sequence[Mapping[str, Any]],
    pending_ledger_sha256: str | None,
    checkpoint: Mapping[str, Any] | None = None,
    reviewed_development: Mapping[str, str] | None = None,
    formal_authorization: Mapping[str, Any] | None = None,
    error: Mapping[str, str] | None = None,
    opened_splits: Sequence[str] | None = None,
) -> dict[str, Any]:
    if execution_mode not in {"formal", "fake_test"}:
        raise ValueError("report execution mode is invalid")
    expected = ("development",) if stage == "development" else PROTECTED_SPLITS
    result_values = [copy.deepcopy(dict(item)) for item in results]
    result_splits = [item.get("split") for item in result_values]
    opened = list(result_splits if opened_splits is None else opened_splits)
    if error is None:
        passed = len(result_values) == len(expected) and all(
            item.get("passed") is True for item in result_values
        )
        outcome = "passed" if passed else "gate_failed"
        access_completed = True
        error_value = None
    else:
        passed = False
        outcome = "error"
        access_completed = False
        error_value = copy.deepcopy(dict(error))
    report: dict[str, Any] = {
        "artifact_kind": "rgbd_known_action_qualification_report",
        "schema": "rgbd_known_action_qualification_report_v2",
        "stage": stage,
        "execution_mode": execution_mode,
        "architecture_version": ARCHITECTURE_VERSION,
        "architecture_attempt": ARCHITECTURE_ATTEMPT,
        "protocol": bridge_protocol(),
        "resolved_config_sha256": FROZEN_CONFIG_SHA256,
        "scene_binding": _scene_binding_status(),
        "source_provenance": _validated_source_provenance(copy.deepcopy(dict(source_provenance))),
        "split_address_sha256": {
            split: SPLIT_ADDRESS_SHA256[split]
            for split in result_splits
            if type(split) is str and split in SPLIT_ADDRESS_SHA256
        },
        "results": result_values,
        "model_state_sha256": EMPTY_MODEL_STATE_SHA256,
        "learned_parameter_count": 0,
        "module_tensor_buffer_count": 0,
        "persistent_module_state_key_count": 0,
        "optimizer_updates": 0,
        "optimizer_state_entry_count": 0,
        "rng_state_entry_count": 0,
        "passed": passed,
        "pending_ledger_sha256": pending_ledger_sha256,
        "opened_splits": opened,
        "stopped_after": opened[-1] if opened else None,
        "public_evaluation_started": bool(opened),
        "access_completed": access_completed,
        "outcome": outcome,
        "error": error_value,
    }
    if stage == "development":
        report["checkpoint"] = copy.deepcopy(checkpoint)
    else:
        report["reviewed_development"] = copy.deepcopy(reviewed_development)
    if execution_mode == "formal":
        report["formal_authorization"] = _validated_formal_authorization_binding(
            copy.deepcopy(dict(formal_authorization or {}))
        )
    elif formal_authorization is not None:
        raise PermissionError("fake report cannot carry formal outer authorization")
    return _validate_report(
        report,
        stage=stage,
        expected_source=source_provenance,
        expected_execution_mode=execution_mode,
        expected_formal_authorization=formal_authorization,
        allow_pending_template=pending_ledger_sha256 is None,
    )


def _validate_report(
    value: Any,
    *,
    stage: Stage,
    expected_source: Mapping[str, Any],
    expected_execution_mode: ExecutionMode = "formal",
    expected_formal_authorization: Mapping[str, Any] | None = None,
    allow_pending_template: bool = False,
) -> dict[str, Any]:
    if expected_execution_mode not in {"formal", "fake_test"}:
        raise ValueError("expected report execution mode is invalid")
    if type(allow_pending_template) is not bool:
        raise TypeError("report template marker must be one exact bool")
    native = _json_native(copy.deepcopy(value), label=f"{stage} report")
    if type(native) is not dict:
        raise TypeError(f"{stage} report must be one exact dict")
    if native.get("execution_mode") != expected_execution_mode:
        raise ValueError(f"{stage} report execution_mode differs")
    if stage == "development":
        schema = (
            FORMAL_DEVELOPMENT_REPORT_SCHEMA
            if expected_execution_mode == "formal"
            else DEVELOPMENT_REPORT_SCHEMA
        )
    else:
        schema = (
            FORMAL_QUALIFICATION_REPORT_SCHEMA
            if expected_execution_mode == "formal"
            else QUALIFICATION_REPORT_SCHEMA
        )
    _require_exact_keys(native, schema, label=f"{stage} report")
    expected_scalars = {
        "artifact_kind": "rgbd_known_action_qualification_report",
        "schema": "rgbd_known_action_qualification_report_v2",
        "stage": stage,
        "execution_mode": expected_execution_mode,
        "architecture_version": ARCHITECTURE_VERSION,
        "architecture_attempt": ARCHITECTURE_ATTEMPT,
        "protocol": bridge_protocol(),
        "resolved_config_sha256": FROZEN_CONFIG_SHA256,
        "scene_binding": _scene_binding_status(),
        "model_state_sha256": EMPTY_MODEL_STATE_SHA256,
        "learned_parameter_count": 0,
        "module_tensor_buffer_count": 0,
        "persistent_module_state_key_count": 0,
        "optimizer_updates": 0,
        "optimizer_state_entry_count": 0,
        "rng_state_entry_count": 0,
    }
    for name, expected_value in expected_scalars.items():
        _exact_equal(native[name], expected_value, label=f"{stage} report.{name}")
    source = _validated_source_provenance(native["source_provenance"])
    expected_source_value = _validated_source_provenance(copy.deepcopy(dict(expected_source)))
    _exact_equal(source, expected_source_value, label=f"{stage} report source")
    if expected_execution_mode == "formal":
        authorization = _validated_formal_authorization_binding(native["formal_authorization"])
        if expected_formal_authorization is not None:
            _exact_equal(
                authorization,
                _validated_formal_authorization_binding(
                    copy.deepcopy(dict(expected_formal_authorization))
                ),
                label=f"{stage} report formal outer authorization",
            )
    elif expected_formal_authorization is not None:
        raise PermissionError("fake report validation rejects formal outer authorization")
    expected_splits = ["development"] if stage == "development" else list(PROTECTED_SPLITS)
    results = native["results"]
    if type(results) is not list or len(results) > len(expected_splits):
        raise ValueError(f"{stage} report result inventory differs")
    result_splits = [item.get("split") if type(item) is dict else None for item in results]
    if result_splits != expected_splits[: len(result_splits)]:
        raise ValueError(f"{stage} report result order differs")
    validated_results = [
        _validated_split_result(item, split=split)
        for item, split in zip(results, result_splits, strict=True)
    ]
    _exact_equal(results, validated_results, label=f"{stage} report results")
    addresses = native["split_address_sha256"]
    expected_addresses = {split: SPLIT_ADDRESS_SHA256[split] for split in result_splits}
    _exact_equal(addresses, expected_addresses, label=f"{stage} report split addresses")
    outcome = native["outcome"]
    if type(native["passed"]) is not bool or outcome not in {"passed", "gate_failed", "error"}:
        raise ValueError(f"{stage} report outcome schema differs")
    if outcome == "passed":
        if (
            results == []
            or len(results) != len(expected_splits)
            or any(item["passed"] is not True for item in results)
            or native["passed"] is not True
        ):
            raise ValueError(f"{stage} passed report evidence differs")
    elif outcome == "gate_failed":
        if (
            not results
            or any(item["passed"] is not True for item in results[:-1])
            or results[-1]["passed"] is not False
            or native["passed"] is not False
        ):
            raise ValueError(f"{stage} gate-failed report evidence differs")
    elif native["passed"] is not False:
        raise ValueError(f"{stage} error report cannot pass")
    opened = native["opened_splits"]
    if (
        type(opened) is not list
        or opened != expected_splits[: len(opened)]
        or any(type(split) is not str for split in opened)
    ):
        raise ValueError(f"{stage} report opened split prefix differs")
    if outcome == "error":
        if (
            opened[: len(result_splits)] != result_splits
            or len(opened) not in {len(result_splits), len(result_splits) + 1}
            or native["access_completed"] is not False
        ):
            raise ValueError(f"{stage} error report boundary binding differs")
        if allow_pending_template:
            if native["pending_ledger_sha256"] is not None:
                raise ValueError(f"{stage} report template already binds a ledger")
        else:
            validated_sha256(native["pending_ledger_sha256"], label=f"{stage} pre-fail ledger")
        _require_exact_keys(native["error"], frozenset({"type", "message"}), label="error")
        if any(type(native["error"][name]) is not str for name in ("type", "message")):
            raise TypeError("error report fields must be exact strings")
    else:
        if (
            opened != result_splits
            or native["access_completed"] is not True
            or native["error"] is not None
        ):
            raise ValueError(f"{stage} terminal report boundary binding differs")
        if allow_pending_template:
            if native["pending_ledger_sha256"] is not None:
                raise ValueError(f"{stage} report template already binds a ledger")
        else:
            validated_sha256(native["pending_ledger_sha256"], label=f"{stage} pending ledger")
    if native["public_evaluation_started"] is not bool(opened) or native["stopped_after"] != (
        opened[-1] if opened else None
    ):
        raise ValueError(f"{stage} report access summary differs")
    if stage == "development":
        _validate_checkpoint_record(native["checkpoint"], required=native["passed"] is True)
        if native["checkpoint"] is not None and (not results or results[0]["passed"] is not True):
            raise ValueError("development checkpoint was not earned")
    else:
        _validated_reviewed_development(native["reviewed_development"])
    return native


def _complete_report_template(
    template: Mapping[str, Any],
    *,
    pending_ledger_sha256: str,
    stage: Stage,
    expected_source: Mapping[str, Any],
    expected_execution_mode: ExecutionMode,
    expected_formal_authorization: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    validated_template = _validate_report(
        template,
        stage=stage,
        expected_source=expected_source,
        expected_execution_mode=expected_execution_mode,
        expected_formal_authorization=expected_formal_authorization,
        allow_pending_template=True,
    )
    completed = copy.deepcopy(validated_template)
    completed["pending_ledger_sha256"] = validated_sha256(
        pending_ledger_sha256,
        label=f"{stage} publication-intent ledger",
    )
    return _validate_report(
        completed,
        stage=stage,
        expected_source=expected_source,
        expected_execution_mode=expected_execution_mode,
        expected_formal_authorization=expected_formal_authorization,
    )


def _checkpoint_record_from_bytes(
    contents: bytes,
    *,
    source_provenance: Mapping[str, Any],
    execution_mode: ExecutionMode,
    development_results: Sequence[Mapping[str, Any]],
    formal_authorization: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    payload = _validate_checkpoint_payload(
        contents,
        expected_source=source_provenance,
        expected_execution_mode=execution_mode,
        expected_formal_authorization=formal_authorization,
    )
    if len(development_results) != 1:
        raise PermissionError("checkpoint lacks one completed development result")
    _exact_equal(
        payload["development_result"],
        development_results[0],
        label="checkpoint/development result",
    )
    record = {
        "artifact_name": CHECKPOINT_NAME,
        "sha256": sha256_bytes(contents),
        "bytes": len(contents),
        "model_state_sha256": payload["model_state_sha256"],
        "model_state_entry_count": len(payload["model_state"]),
        "optimizer_state_entry_count": 0,
        "rng_state_entry_count": 0,
    }
    validated_record = _validate_checkpoint_record(record, required=True)
    if validated_record is None:
        raise AssertionError("required checkpoint record validation returned no record")
    return validated_record, payload


def _validate_reviewed_development_artifacts(
    *,
    directory_pin: _PinnedDirectory,
    reviewed_development: Mapping[str, str],
    expected_source: Mapping[str, Any],
    expected_execution_mode: ExecutionMode,
    artifact_bytes: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Validate the canonical reviewed trio and every cross-artifact binding."""

    _validate_pinned_directory(directory_pin)
    if expected_execution_mode == "formal":
        if directory_pin.canonical is not True or directory_pin.path != _canonical_run_directory():
            raise PermissionError("formal reviewed artifacts require the canonical run directory")
    elif expected_execution_mode == "fake_test":
        _require_fake_test_directory(directory_pin)
    else:
        raise ValueError("reviewed artifact execution mode is invalid")
    reviewed = _validated_reviewed_development(copy.deepcopy(dict(reviewed_development)))
    if artifact_bytes is None:
        paths = _artifact_paths(directory_pin)
        current = {
            "checkpoint": _pinned_read_bytes(
                directory_pin,
                paths["checkpoint"],
                label="validated reviewed checkpoint",
                maximum=MAX_CHECKPOINT_BYTES,
            ),
            "report": _pinned_read_bytes(
                directory_pin,
                paths["development_report"],
                label="validated reviewed development report",
            ),
            "ledger": _pinned_read_bytes(
                directory_pin,
                paths["development_ledger"],
                label="validated reviewed development ledger",
            ),
        }
    else:
        if type(artifact_bytes) is not dict or set(artifact_bytes) != {
            "checkpoint",
            "report",
            "ledger",
        }:
            raise TypeError("reviewed artifact bytes must be one exact three-entry dict")
        current = dict(artifact_bytes)
        if any(type(contents) is not bytes for contents in current.values()):
            raise TypeError("reviewed artifact contents must be exact bytes")
        if (
            not current["checkpoint"]
            or len(current["checkpoint"]) > MAX_CHECKPOINT_BYTES
            or not current["report"]
            or len(current["report"]) > MAX_JSON_BYTES
            or not current["ledger"]
            or len(current["ledger"]) > MAX_JSON_BYTES
        ):
            raise ValueError("reviewed artifact byte bounds differ")
    actual = {f"{name}_sha256": sha256_bytes(contents) for name, contents in current.items()}
    _exact_equal(actual, reviewed, label="reviewed development artifact bytes")
    source = _validated_source_provenance(copy.deepcopy(dict(expected_source)))
    report = _validate_report(
        _strict_json_loads(current["report"], label="reviewed development report"),
        stage="development",
        expected_source=source,
        expected_execution_mode=expected_execution_mode,
    )
    if current["report"] != _report_bytes(report) or report["passed"] is not True:
        raise ValueError("reviewed development report is not canonical and passed")
    checkpoint_record, checkpoint = _checkpoint_record_from_bytes(
        current["checkpoint"],
        source_provenance=source,
        execution_mode=expected_execution_mode,
        development_results=report["results"],
        formal_authorization=report.get("formal_authorization"),
    )
    _exact_equal(
        report["checkpoint"],
        checkpoint_record,
        label="reviewed report/checkpoint byte binding",
    )
    bindings = _ledger_bindings(
        stage="development",
        execution_mode=expected_execution_mode,
        directory_pin=directory_pin,
        source_provenance=source,
        formal_authorization=report.get("formal_authorization"),
    )
    ledger = _validate_terminal_ledger(
        current["ledger"],
        stage="development",
        expected_bindings=bindings,
        expected_results=report["results"],
        expected_outcome="passed",
        expected_normal_report_sha256=reviewed["report_sha256"],
        expected_pending_ledger_sha256=report["pending_ledger_sha256"],
    )
    if (
        ledger["status"] != "complete_passed"
        or ledger["publication"]["report_sha256"] != reviewed["report_sha256"]
        or ledger["publication"]["pending_ledger_sha256"] != report["pending_ledger_sha256"]
        or ledger["splits"]["development"]["split_result_sha256"]
        != canonical_sha256(report["results"][0])
    ):
        raise ValueError("reviewed development cross-artifact binding differs")
    return report, checkpoint, ledger


@dataclass(frozen=True, slots=True)
class _ReviewedDevelopmentSeal:
    directory_pin: _PinnedDirectory
    execution_mode: ExecutionMode
    reviewed: dict[str, str]
    checkpoint_bytes: bytes
    report_bytes: bytes
    ledger_bytes: bytes
    checkpoint_identity: tuple[int, int, int, int, int]
    report_identity: tuple[int, int, int, int, int]
    ledger_identity: tuple[int, int, int, int, int]
    directory_binding_sha256: str
    source_sha256: str
    reviewed_binding_sha256: str
    owner_thread: int
    nonce: object


_REVIEW_SEAL_REGISTRY: dict[int, _ReviewedDevelopmentSeal] = {}


def _review_development_bundle(
    *,
    directory_pin: _PinnedDirectory,
    reviewed_checkpoint_sha256: str,
    reviewed_report_sha256: str,
    reviewed_development_ledger_sha256: str,
    expected_source: Mapping[str, Any],
    expected_execution_mode: ExecutionMode = "formal",
) -> tuple[dict[str, str], dict[str, Any], _ReviewedDevelopmentSeal]:
    if expected_execution_mode == "formal":
        _validate_pinned_directory(directory_pin)
        if directory_pin.canonical is not True or directory_pin.path != _canonical_run_directory():
            raise PermissionError("formal review requires the exact canonical run directory")
    elif expected_execution_mode == "fake_test":
        _require_fake_test_directory(directory_pin)
    else:
        raise ValueError("reviewed execution mode is invalid")
    reviewed = _validated_reviewed_development(
        {
            "checkpoint_sha256": reviewed_checkpoint_sha256,
            "report_sha256": reviewed_report_sha256,
            "ledger_sha256": reviewed_development_ledger_sha256,
        }
    )
    _validate_run_tree(
        directory_pin,
        DEVELOPMENT_ARTIFACT_NAMES,
        stage="reviewed development",
    )
    paths = _artifact_paths(directory_pin)
    checkpoint = _pinned_read_bytes(
        directory_pin,
        paths["checkpoint"],
        label="reviewed checkpoint",
        maximum=MAX_CHECKPOINT_BYTES,
    )
    report = _pinned_read_bytes(
        directory_pin,
        paths["development_report"],
        label="reviewed development report",
    )
    ledger = _pinned_read_bytes(
        directory_pin,
        paths["development_ledger"],
        label="reviewed development ledger",
    )
    actual = {
        "checkpoint_sha256": sha256_bytes(checkpoint),
        "report_sha256": sha256_bytes(report),
        "ledger_sha256": sha256_bytes(ledger),
    }
    if actual != reviewed:
        raise ValueError("externally reviewed three-hash development seal differs")
    seal = _ReviewedDevelopmentSeal(
        directory_pin=directory_pin,
        execution_mode=expected_execution_mode,
        reviewed=reviewed,
        checkpoint_bytes=checkpoint,
        report_bytes=report,
        ledger_bytes=ledger,
        checkpoint_identity=_pinned_file_identity(directory_pin, paths["checkpoint"]),
        report_identity=_pinned_file_identity(directory_pin, paths["development_report"]),
        ledger_identity=_pinned_file_identity(directory_pin, paths["development_ledger"]),
        directory_binding_sha256=canonical_sha256(_pinned_directory_binding(directory_pin)),
        source_sha256=canonical_sha256(
            _validated_source_provenance(copy.deepcopy(dict(expected_source)))
        ),
        reviewed_binding_sha256=canonical_sha256(reviewed),
        owner_thread=threading.get_ident(),
        nonce=object(),
    )
    if id(seal) in _REVIEW_SEAL_REGISTRY:
        raise PermissionError("reviewed development seal identity already exists")
    _REVIEW_SEAL_REGISTRY[id(seal)] = seal
    validated_report, _ = _revalidate_reviewed_development(
        seal,
        expected_source=expected_source,
        qualification_active=False,
    )
    return reviewed, validated_report, seal


def _revalidate_reviewed_development(
    seal: _ReviewedDevelopmentSeal,
    *,
    expected_source: Mapping[str, Any],
    qualification_active: bool,
    qualification_report_present: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    if (
        not isinstance(seal, _ReviewedDevelopmentSeal)
        or _REVIEW_SEAL_REGISTRY.get(id(seal)) is not seal
        or seal.owner_thread != threading.get_ident()
        or seal.execution_mode not in {"formal", "fake_test"}
    ):
        raise PermissionError("reviewed development seal is forged or thread-rebound")
    pin = seal.directory_pin
    _validate_pinned_directory(pin)
    if (seal.execution_mode == "formal") is not (
        pin.canonical is True and pin.path == _canonical_run_directory()
    ):
        raise PermissionError("reviewed execution mode/run-directory binding differs")
    if canonical_sha256(seal.reviewed) != seal.reviewed_binding_sha256:
        raise PermissionError("reviewed development hash binding was mutated")
    expected_inventory = DEVELOPMENT_ARTIFACT_NAMES
    if qualification_active:
        expected_inventory = frozenset({*expected_inventory, QUALIFICATION_LEDGER_NAME})
    if qualification_report_present:
        if not qualification_active:
            raise ValueError("qualification report cannot exist without its active ledger")
        expected_inventory = frozenset({*expected_inventory, QUALIFICATION_REPORT_NAME})
    _validate_run_tree(pin, expected_inventory, stage="protected reviewed boundary")
    if canonical_sha256(_pinned_directory_binding(pin)) != seal.directory_binding_sha256:
        raise PermissionError("reviewed development run-directory identity changed")
    source = _validated_source_provenance(copy.deepcopy(dict(expected_source)))
    if canonical_sha256(source) != seal.source_sha256:
        raise PermissionError("reviewed development expected source changed")
    paths = _artifact_paths(pin)
    entries = (
        ("checkpoint", paths["checkpoint"], seal.checkpoint_bytes, seal.checkpoint_identity),
        ("report", paths["development_report"], seal.report_bytes, seal.report_identity),
        ("ledger", paths["development_ledger"], seal.ledger_bytes, seal.ledger_identity),
    )
    current: dict[str, bytes] = {}
    for name, path, expected_bytes, expected_identity in entries:
        maximum = MAX_CHECKPOINT_BYTES if name == "checkpoint" else MAX_JSON_BYTES
        if _pinned_file_identity(pin, path) != expected_identity:
            raise PermissionError(f"reviewed development {name} inode changed")
        contents = _pinned_read_bytes(pin, path, label=f"protected {name}", maximum=maximum)
        if (
            contents != expected_bytes
            or _pinned_file_identity(pin, path) != expected_identity
            or sha256_bytes(contents) != seal.reviewed[f"{name}_sha256"]
        ):
            raise PermissionError(f"reviewed development {name} bytes changed")
        current[name] = contents
    report, checkpoint, _ = _validate_reviewed_development_artifacts(
        directory_pin=pin,
        reviewed_development=seal.reviewed,
        expected_source=source,
        expected_execution_mode=seal.execution_mode,
        artifact_bytes=current,
    )
    return report, checkpoint


def _persist_exception_report(
    *,
    directory_pin: _PinnedDirectory,
    stage: Stage,
    source_provenance: Mapping[str, Any],
    ledger: _AccessLedger | None,
    error: BaseException,
    results: Sequence[Mapping[str, Any]],
    checkpoint: Mapping[str, Any] | None = None,
    reviewed_development: Mapping[str, str] | None = None,
    reviewed_seal: _ReviewedDevelopmentSeal | None = None,
) -> str | None:
    """Publish a fail-closed report whose intended bytes are bound by the ledger."""

    if ledger is None or ledger._terminal:
        return None
    error_fields = {"type": type(error).__name__, "message": str(error)}
    try:
        ledger._verify_disk()
        publication_state = ledger._record["publication"].get("state")
        if publication_state in {"normal_intent", "error_intent"}:
            return ledger.recover_publication()
        execution_mode = ledger._record["execution_mode"]
        formal_authorization = ledger._record["bindings"].get("formal_authorization")
        opened = [
            split
            for split in ledger._record["order"]
            if ledger._record["splits"][split]["public_access_started"] is True
        ]
        owned_results = [
            ledger._record["splits"][split]["split_result"]
            for split in ledger._record["order"]
            if ledger._record["splits"][split]["split_result"] is not None
        ]
        owned_checkpoint = checkpoint
        if stage == "development":
            checkpoint_path = _artifact_paths(directory_pin)["checkpoint"]
            if _pinned_exists(
                directory_pin,
                checkpoint_path,
                label="error-path development checkpoint",
            ):
                checkpoint_bytes = _pinned_read_bytes(
                    directory_pin,
                    checkpoint_path,
                    label="error-path development checkpoint",
                    maximum=MAX_CHECKPOINT_BYTES,
                )
                payload = _validate_checkpoint_payload(
                    checkpoint_bytes,
                    expected_source=source_provenance,
                    expected_execution_mode=execution_mode,
                    expected_formal_authorization=formal_authorization,
                )
                if len(owned_results) != 1:
                    raise PermissionError(
                        "published development checkpoint lacks one ledger-owned result"
                    )
                _exact_equal(
                    payload["development_result"],
                    owned_results[0],
                    label="error checkpoint/ledger development result",
                )
                owned_checkpoint = {
                    "artifact_name": CHECKPOINT_NAME,
                    "sha256": sha256_bytes(checkpoint_bytes),
                    "bytes": len(checkpoint_bytes),
                    "model_state_sha256": payload["model_state_sha256"],
                    "model_state_entry_count": len(payload["model_state"]),
                    "optimizer_state_entry_count": 0,
                    "rng_state_entry_count": 0,
                }
            else:
                owned_checkpoint = None
        report = _report_root(
            stage=stage,
            execution_mode=execution_mode,
            source_provenance=source_provenance,
            results=owned_results,
            pending_ledger_sha256=None,
            checkpoint=owned_checkpoint,
            reviewed_development=reviewed_development,
            formal_authorization=formal_authorization,
            error=error_fields,
            opened_splits=opened,
        )
        if stage == "qualification" and reviewed_seal is None:
            raise PermissionError("qualification error publication lacks reviewed seal")
        ledger.prepare_error_publication(report)
        _, _, report_digest = ledger.publish_prepared_report()
        ledger.fail()
        return report_digest
    except BaseException:
        return None


def _checkpoint_record_from_existing(
    directory_pin: _PinnedDirectory,
    *,
    source_provenance: Mapping[str, Any],
    execution_mode: ExecutionMode,
    development_results: Sequence[Mapping[str, Any]],
    formal_authorization: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    path = _artifact_paths(directory_pin)["checkpoint"]
    if not _pinned_exists(directory_pin, path, label="recoverable checkpoint"):
        return None
    contents = _pinned_read_bytes(
        directory_pin,
        path,
        label="recoverable checkpoint",
        maximum=MAX_CHECKPOINT_BYTES,
    )
    record, _ = _checkpoint_record_from_bytes(
        contents,
        source_provenance=source_provenance,
        execution_mode=execution_mode,
        development_results=development_results,
        formal_authorization=formal_authorization,
    )
    return record


def _validate_existing_formal_terminal_attempt(
    *,
    directory_pin: _PinnedDirectory,
    stage: Stage,
    source_provenance: Mapping[str, Any],
    reviewed_development: Mapping[str, str] | None,
    ledger_contents: bytes,
    authorization: _LedgerRecoveryAuthorization,
) -> tuple[str, str]:
    """Recognize one terminal formal bundle without rewriting any artifact."""

    registration = _LEDGER_RECOVERY_AUTHORIZATION_REGISTRY.get(id(authorization))
    if (
        type(authorization) is not _LedgerRecoveryAuthorization
        or registration is None
        or registration[0] is not authorization
        or registration[2] != "consumed"
        or authorization.stage != stage
        or authorization.directory_pin is not directory_pin
        or type(ledger_contents) is not bytes
    ):
        raise PermissionError("terminal recognition lacks its consumed recovery authority")
    parsed = _parse_ledger_bytes(ledger_contents, label=f"existing formal {stage} ledger")
    bindings = _validated_existing_formal_ledger_bindings(
        parsed.get("bindings"),
        stage=stage,
        directory_pin=directory_pin,
        source_provenance=source_provenance,
        reviewed_development=reviewed_development,
    )
    source = bindings["source_provenance"]
    original_authorization = bindings["formal_authorization"]
    paths = _artifact_paths(directory_pin)
    report_path = paths[f"{stage}_report"]
    report_bytes = _pinned_read_bytes(
        directory_pin,
        report_path,
        label=f"existing terminal formal {stage} report",
    )
    _validated_live_recovery_inventory(
        authorization,
        expected_state="consumed",
        label=f"post-report-read terminal {stage}",
    )
    report = _validate_report(
        _strict_json_loads(report_bytes, label=f"existing terminal formal {stage} report"),
        stage=stage,
        expected_source=source,
        expected_execution_mode="formal",
        expected_formal_authorization=original_authorization,
    )
    if report_bytes != _report_bytes(report):
        raise ValueError(f"existing terminal formal {stage} report is not canonical")
    if stage == "development":
        expected_inventory = frozenset(
            {
                DEVELOPMENT_LEDGER_NAME,
                DEVELOPMENT_REPORT_NAME,
                *((CHECKPOINT_NAME,) if report["checkpoint"] is not None else ()),
            }
        )
        checkpoint = _checkpoint_record_from_existing(
            directory_pin,
            source_provenance=source,
            execution_mode="formal",
            development_results=report["results"],
            formal_authorization=original_authorization,
        )
        _validated_live_recovery_inventory(
            authorization,
            expected_state="consumed",
            label="post-checkpoint-read terminal development",
        )
        _exact_equal(
            checkpoint,
            report["checkpoint"],
            label="existing terminal formal development checkpoint/report",
        )
    else:
        expected_inventory = QUALIFICATION_ARTIFACT_NAMES
        reviewed = _validated_reviewed_development(copy.deepcopy(dict(reviewed_development or {})))
        _exact_equal(
            report["reviewed_development"],
            reviewed,
            label="existing terminal formal qualification reviewed hashes",
        )
        if report["outcome"] != "error":
            _validate_reviewed_development_artifacts(
                directory_pin=directory_pin,
                reviewed_development=reviewed,
                expected_source=source,
                expected_execution_mode="formal",
            )
            _validated_live_recovery_inventory(
                authorization,
                expected_state="consumed",
                label="post-reviewed-read terminal qualification",
            )
            recomputed_baseline, _ = _reviewed_development_nonce_baseline(
                directory_pin,
                expected_ledger_sha256=reviewed["ledger_sha256"],
            )
            _validated_live_recovery_inventory(
                authorization,
                expected_state="consumed",
                label="post-nonce-read terminal qualification",
            )
            _exact_equal(
                recomputed_baseline,
                bindings["reviewed_development_nonce_baseline"],
                label="terminal formal qualification reviewed nonce baseline",
            )
    _validate_run_tree(
        directory_pin,
        expected_inventory,
        stage=f"existing terminal formal {stage}",
    )
    report_sha256 = sha256_bytes(report_bytes)
    terminal = _validate_terminal_ledger(
        ledger_contents,
        stage=stage,
        expected_bindings=bindings,
        expected_results=report["results"],
        expected_outcome=report["outcome"],
        expected_error_report_sha256=(report_sha256 if report["outcome"] == "error" else None),
        expected_normal_report_sha256=(report_sha256 if report["outcome"] != "error" else None),
        expected_pending_ledger_sha256=report["pending_ledger_sha256"],
    )
    if (
        terminal["publication"]["report_sha256"] != report_sha256
        or terminal["publication"]["pending_ledger_sha256"] != report["pending_ledger_sha256"]
    ):
        raise ValueError("existing terminal formal report/ledger binding differs")
    _validated_live_recovery_inventory(
        authorization,
        expected_state="consumed",
        label=f"completed read-only terminal {stage}",
    )
    _revoke_ledger_recovery_authorization(authorization)
    return sha256_bytes(ledger_contents), terminal["status"]


def _formal_recovery_exit_code(status: str) -> int:
    if status == "complete_passed":
        return 0
    if status in {"complete_failed", "terminal_error"}:
        return 1
    raise ValueError("formal recovery did not reach one terminal status")


def _recover_existing_formal_attempt(
    *,
    directory_pin: _PinnedDirectory,
    stage: Stage,
    source_provenance: Mapping[str, Any],
    authorization: _LedgerRecoveryAuthorization,
    reviewed_development: Mapping[str, str] | None = None,
) -> int:
    """Recover one formal attempt without reopening evidence or constructing science."""

    paths = _artifact_paths(directory_pin)
    ledger_path = paths[f"{stage}_ledger"]
    _consume_ledger_recovery_authorization(
        authorization,
        stage=stage,
        directory_pin=directory_pin,
        source_provenance=source_provenance,
        ledger_path=ledger_path,
    )
    ledger_contents = _pinned_read_bytes(
        directory_pin,
        ledger_path,
        label=f"formal startup {stage} ledger",
    )
    _validated_live_recovery_inventory(
        authorization,
        expected_state="consumed",
        label=f"post-startup-ledger-read {stage}",
    )
    parsed = _parse_ledger_bytes(ledger_contents, label=f"formal startup {stage} ledger")
    if parsed.get("status") in {"complete_passed", "complete_failed", "terminal_error"}:
        _, status = _validate_existing_formal_terminal_attempt(
            directory_pin=directory_pin,
            stage=stage,
            source_provenance=source_provenance,
            reviewed_development=reviewed_development,
            ledger_contents=ledger_contents,
            authorization=authorization,
        )
        return _formal_recovery_exit_code(status)
    ledger = _AccessLedger.adopt_formal_recoverable(
        ledger_path,
        contents=ledger_contents,
        stage=stage,
        directory_pin=directory_pin,
        authorization=authorization,
        source_provenance=source_provenance,
        reviewed_development=reviewed_development,
    )
    _validated_live_recovery_inventory(
        authorization,
        expected_state="consumed",
        label=f"post-adoption-ledger-read {stage}",
    )
    bindings = ledger._record["bindings"]
    original_authorization = bindings["formal_authorization"]
    publication_state = ledger._record["publication"]["state"]
    if publication_state in {"normal_intent", "error_intent"}:
        report_name = (
            DEVELOPMENT_REPORT_NAME if stage == "development" else QUALIFICATION_REPORT_NAME
        )
        if stage == "development":
            template_checkpoint = ledger._record["publication"]["report_template"]["checkpoint"]
            intent_base_inventory = frozenset(
                {
                    DEVELOPMENT_LEDGER_NAME,
                    *((CHECKPOINT_NAME,) if template_checkpoint is not None else ()),
                }
            )
        else:
            intent_base_inventory = frozenset(
                {*DEVELOPMENT_ARTIFACT_NAMES, QUALIFICATION_LEDGER_NAME}
            )
        actual_inventory = _pinned_inventory(directory_pin)
        if actual_inventory not in {
            intent_base_inventory,
            frozenset({*intent_base_inventory, report_name}),
        }:
            raise PermissionError("formal publication-intent inventory differs")
        kind: Literal["normal", "error"] = (
            "normal" if publication_state == "normal_intent" else "error"
        )
        pending, report, report_bytes, report_digest, report_identity = (
            ledger._prevalidate_recovery_publication(
                kind=kind,
                authorization=authorization,
            )
        )
        if kind == "normal":
            outcome: Literal["complete_passed", "complete_failed", "terminal_error"] = (
                "complete_passed" if report["outcome"] == "passed" else "complete_failed"
            )
            action: Literal["recover_existing_normal_intent", "recover_existing_error_intent"] = (
                "recover_existing_normal_intent"
            )
        else:
            outcome = "terminal_error"
            action = "recover_existing_error_intent"
        receipt = _ledger_recovery_receipt(
            authorization,
            predecessor_ledger_bytes=ledger._last_bytes,
            predecessor_generation=ledger._record["generation"],
            placement="terminal",
            action=action,
            outcome=outcome,
            report_sha256=report_digest,
        )
        if pending != receipt["predecessor_ledger_sha256"]:
            raise PermissionError("formal intent recovery predecessor digest differs")
        ledger._publish_prevalidated_recovery(
            authorization=authorization,
            kind=kind,
            pending=pending,
            report=report,
            report_bytes=report_bytes,
            report_digest=report_digest,
            preexisting_report_identity=report_identity,
            terminal_receipt=receipt,
        )
        _revoke_ledger_recovery_authorization(authorization)
        return _formal_recovery_exit_code(ledger._record["status"])

    results = ledger._owned_results()
    checkpoint: dict[str, Any] | None = None
    recovery_error: dict[str, str] | None = None
    try:
        normal_status = ledger._normal_outcome_status()
    except RuntimeError:
        normal_status = None
    _validated_live_recovery_inventory(
        authorization,
        expected_state="consumed",
        label=f"post-outcome-ledger-read {stage}",
    )
    if stage == "development":
        unbound_inventory = frozenset(
            {
                DEVELOPMENT_LEDGER_NAME,
                *((CHECKPOINT_NAME,) if normal_status == "complete_passed" else ()),
            }
        )
    else:
        unbound_inventory = frozenset({*DEVELOPMENT_ARTIFACT_NAMES, QUALIFICATION_LEDGER_NAME})
    _validate_run_tree(
        directory_pin,
        unbound_inventory,
        stage=f"formal unbound {stage} recovery",
    )
    if normal_status is not None:
        if stage == "development":
            checkpoint = _checkpoint_record_from_existing(
                directory_pin,
                source_provenance=bindings["source_provenance"],
                execution_mode="formal",
                development_results=results,
                formal_authorization=original_authorization,
            )
            _validate_checkpoint_record(
                checkpoint,
                required=normal_status == "complete_passed",
            )
            _validated_live_recovery_inventory(
                authorization,
                expected_state="consumed",
                label="post-checkpoint-read unbound development",
            )
        else:
            reviewed = _validated_reviewed_development(
                copy.deepcopy(dict(reviewed_development or {}))
            )
            _exact_equal(
                reviewed,
                bindings["reviewed_development"],
                label="recovered formal qualification reviewed binding",
            )
            try:
                _validate_reviewed_development_artifacts(
                    directory_pin=directory_pin,
                    reviewed_development=reviewed,
                    expected_source=bindings["source_provenance"],
                    expected_execution_mode="formal",
                )
                _validated_live_recovery_inventory(
                    authorization,
                    expected_state="consumed",
                    label="post-reviewed-artifact-read unbound qualification",
                )
                recomputed_baseline, _ = _reviewed_development_nonce_baseline(
                    directory_pin,
                    expected_ledger_sha256=reviewed["ledger_sha256"],
                )
                _validated_live_recovery_inventory(
                    authorization,
                    expected_state="consumed",
                    label="post-reviewed-nonce-read unbound qualification",
                )
                _exact_equal(
                    recomputed_baseline,
                    bindings["reviewed_development_nonce_baseline"],
                    label="recovered formal qualification reviewed nonce baseline",
                )
            except (EOFError, OSError, PermissionError, RuntimeError, ValueError):
                recovery_error = {
                    "type": "ReviewedDevelopmentMutation",
                    "message": (
                        "reviewed development artifact or nonce baseline differed during "
                        "formal startup recovery"
                    ),
                }
            _validated_live_recovery_inventory(
                authorization,
                expected_state="consumed",
                label="post-reviewed-read unbound qualification",
            )
        if recovery_error is None:
            template = _report_root(
                stage=stage,
                execution_mode="formal",
                source_provenance=bindings["source_provenance"],
                results=results,
                pending_ledger_sha256=None,
                checkpoint=checkpoint,
                reviewed_development=reviewed_development,
                formal_authorization=original_authorization,
            )
            pending, report = ledger._prepare_publication_intent(
                template,
                kind="normal",
                recovery_authorization=authorization,
                recovery_action="prepare_completed_unbound",
                recovery_outcome=normal_status,
            )
            kind: Literal["normal", "error"] = "normal"
        else:
            template = _report_root(
                stage=stage,
                execution_mode="formal",
                source_provenance=bindings["source_provenance"],
                results=results,
                pending_ledger_sha256=None,
                reviewed_development=reviewed_development,
                formal_authorization=original_authorization,
                error=recovery_error,
                opened_splits=ledger._opened_splits(),
            )
            pending, report = ledger._prepare_publication_intent(
                template,
                kind="error",
                recovery_authorization=authorization,
                recovery_action="terminalize_reviewed_mutation",
                recovery_outcome="terminal_error",
            )
            kind = "error"
    else:
        interrupted_error = _interrupted_recovery_error(ledger._record)
        template = _report_root(
            stage=stage,
            execution_mode="formal",
            source_provenance=bindings["source_provenance"],
            results=results,
            pending_ledger_sha256=None,
            reviewed_development=reviewed_development,
            formal_authorization=original_authorization,
            error=interrupted_error,
            opened_splits=ledger._opened_splits(),
        )
        pending, report = ledger._prepare_publication_intent(
            template,
            kind="error",
            recovery_authorization=authorization,
            recovery_action="interrupt_nonterminal",
            recovery_outcome="terminal_error",
        )
        kind = "error"
    report_bytes = _report_bytes(report)
    report_digest = sha256_bytes(report_bytes)
    ledger._publish_prevalidated_recovery(
        authorization=authorization,
        kind=kind,
        pending=pending,
        report=report,
        report_bytes=report_bytes,
        report_digest=report_digest,
        preexisting_report_identity=None,
    )
    _revoke_ledger_recovery_authorization(authorization)
    return _formal_recovery_exit_code(ledger._record["status"])


def _validate_existing_terminal_attempt_for_tests(
    *,
    directory_pin: _PinnedDirectory,
    stage: Stage,
    source_provenance: Mapping[str, Any],
    reviewed_development: Mapping[str, str] | None,
) -> str:
    """Recognize one exact terminal fake bundle without rewriting any artifact."""

    _require_fake_test_directory(directory_pin)
    source = _validated_source_provenance(copy.deepcopy(dict(source_provenance)))
    paths = _artifact_paths(directory_pin)
    report_path = paths[f"{stage}_report"]
    ledger_path = paths[f"{stage}_ledger"]
    report_bytes = _pinned_read_bytes(
        directory_pin,
        report_path,
        label=f"existing terminal {stage} report",
    )
    report = _validate_report(
        _strict_json_loads(report_bytes, label=f"existing terminal {stage} report"),
        stage=stage,
        expected_source=source,
        expected_execution_mode="fake_test",
    )
    if report_bytes != _report_bytes(report):
        raise ValueError(f"existing terminal {stage} report is not canonical")
    if stage == "development":
        expected_inventory = frozenset(
            {
                DEVELOPMENT_LEDGER_NAME,
                DEVELOPMENT_REPORT_NAME,
                *((CHECKPOINT_NAME,) if report["checkpoint"] is not None else ()),
            }
        )
        checkpoint = _checkpoint_record_from_existing(
            directory_pin,
            source_provenance=source,
            execution_mode="fake_test",
            development_results=report["results"],
        )
        _exact_equal(
            checkpoint,
            report["checkpoint"],
            label="existing terminal development checkpoint/report",
        )
    else:
        expected_inventory = QUALIFICATION_ARTIFACT_NAMES
        reviewed = _validated_reviewed_development(copy.deepcopy(dict(reviewed_development or {})))
        _exact_equal(
            report["reviewed_development"],
            reviewed,
            label="existing terminal qualification reviewed hashes",
        )
        if report["outcome"] != "error":
            _validate_reviewed_development_artifacts(
                directory_pin=directory_pin,
                reviewed_development=reviewed,
                expected_source=source,
                expected_execution_mode="fake_test",
            )
    _validate_run_tree(
        directory_pin,
        expected_inventory,
        stage=f"existing terminal {stage}",
    )
    bindings = _ledger_bindings(
        stage=stage,
        execution_mode="fake_test",
        directory_pin=directory_pin,
        source_provenance=source,
        reviewed_development=reviewed_development,
    )
    ledger_bytes = _pinned_read_bytes(
        directory_pin,
        ledger_path,
        label=f"existing terminal {stage} ledger",
    )
    report_sha256 = sha256_bytes(report_bytes)
    terminal = _validate_terminal_ledger(
        ledger_bytes,
        stage=stage,
        expected_bindings=bindings,
        expected_results=report["results"],
        expected_outcome=report["outcome"],
        expected_error_report_sha256=(report_sha256 if report["outcome"] == "error" else None),
        expected_normal_report_sha256=(report_sha256 if report["outcome"] != "error" else None),
        expected_pending_ledger_sha256=report["pending_ledger_sha256"],
    )
    if (
        terminal["publication"]["report_sha256"] != report_sha256
        or terminal["publication"]["pending_ledger_sha256"] != report["pending_ledger_sha256"]
    ):
        raise ValueError("existing terminal report/ledger binding differs")
    return sha256_bytes(ledger_bytes)


def _recover_existing_attempt_for_tests(
    *,
    directory_pin: _PinnedDirectory,
    stage: Stage,
    source_provenance: Mapping[str, Any],
    reviewed_development: Mapping[str, str] | None = None,
) -> str:
    """Fake-only startup adopter; never evaluates, rematerializes, or reopens a split."""

    _require_fake_test_directory(directory_pin)
    if _validated_invocation_inventory(directory_pin, stage=stage) != "recovery":
        raise PermissionError("startup recovery requires one existing ledger")
    source = _validated_source_provenance(copy.deepcopy(dict(source_provenance)))
    paths = _artifact_paths(directory_pin)
    ledger_contents = _pinned_read_bytes(
        directory_pin,
        paths[f"{stage}_ledger"],
        label=f"startup {stage} ledger",
    )
    parsed = _parse_ledger_bytes(ledger_contents, label=f"startup {stage} ledger")
    if parsed["status"] in {"complete_passed", "complete_failed", "terminal_error"}:
        return _validate_existing_terminal_attempt_for_tests(
            directory_pin=directory_pin,
            stage=stage,
            source_provenance=source,
            reviewed_development=reviewed_development,
        )
    bindings = _ledger_bindings(
        stage=stage,
        execution_mode="fake_test",
        directory_pin=directory_pin,
        source_provenance=source,
        reviewed_development=reviewed_development,
    )
    seal = _mint_fake_runner_invocation_seal_for_tests(
        stage=stage,
        directory_pin=directory_pin,
        source_provenance=source,
        reviewed_development=reviewed_development,
    )
    authorization = _authorize_ledger_creation(
        invocation_seal=seal,
        stage=stage,
        directory_pin=directory_pin,
        source_provenance=source,
        bindings=bindings,
        ledger_path=paths[f"{stage}_ledger"],
        reviewed_development=reviewed_development,
    )
    ledger = _AccessLedger.adopt_recoverable(
        paths[f"{stage}_ledger"],
        stage=stage,
        bindings=bindings,
        directory_pin=directory_pin,
        authorization=authorization,
    )
    publication_state = ledger._record["publication"]["state"]
    if publication_state in {"normal_intent", "error_intent"}:
        return ledger.recover_publication()
    results = ledger._owned_results()
    checkpoint = (
        _checkpoint_record_from_existing(
            directory_pin,
            source_provenance=source,
            execution_mode="fake_test",
            development_results=results,
        )
        if stage == "development"
        else None
    )
    recovery_error: dict[str, str] | None = None
    try:
        ledger._normal_outcome_status()
        if stage == "development" and results and results[0]["passed"] is True:
            _validate_checkpoint_record(checkpoint, required=True)
        if stage == "qualification":
            reviewed = _validated_reviewed_development(
                copy.deepcopy(dict(reviewed_development or {}))
            )
            _exact_equal(
                reviewed,
                ledger._record["bindings"]["reviewed_development"],
                label="recovered qualification reviewed binding",
            )
            try:
                _validate_reviewed_development_artifacts(
                    directory_pin=directory_pin,
                    reviewed_development=reviewed,
                    expected_source=source,
                    expected_execution_mode="fake_test",
                )
            except Exception as error:
                recovery_error = {
                    "type": type(error).__name__,
                    "message": f"final reviewed development validation failed: {error}",
                }
        if recovery_error is not None:
            raise RuntimeError("qualification normal recovery was refused")
        template = _report_root(
            stage=stage,
            execution_mode="fake_test",
            source_provenance=source,
            results=results,
            pending_ledger_sha256=None,
            checkpoint=checkpoint,
            reviewed_development=reviewed_development,
        )
        ledger.prepare_publication(template)
    except (RuntimeError, ValueError):
        error_fields = recovery_error or _interrupted_recovery_error(ledger._record)
        template = _report_root(
            stage=stage,
            execution_mode="fake_test",
            source_provenance=source,
            results=results,
            pending_ledger_sha256=None,
            checkpoint=checkpoint,
            reviewed_development=reviewed_development,
            error=error_fields,
            opened_splits=ledger._opened_splits(),
        )
        ledger.prepare_error_publication(template)
    ledger.publish_prepared_report()
    return ledger.finish() if ledger._record["publication"]["kind"] == "normal" else ledger.fail()


def _execute_development_for_tests(
    *,
    directory_pin: _PinnedDirectory,
    evaluator: QualificationEvaluator,
    source_provenance: Mapping[str, Any],
) -> int:
    """Exercise the complete development state machine with injected fake data only."""

    _require_fake_test_directory(directory_pin)
    _validate_run_tree(directory_pin, frozenset(), stage="fake development preflight")
    source = _validated_source_provenance(copy.deepcopy(dict(source_provenance)))
    paths = _artifact_paths(directory_pin)
    bindings = _ledger_bindings(
        stage="development",
        execution_mode="fake_test",
        directory_pin=directory_pin,
        source_provenance=source,
    )
    ledger: _AccessLedger | None = None
    results: list[dict[str, Any]] = []
    checkpoint: dict[str, Any] | None = None
    try:
        invocation_seal = _mint_fake_runner_invocation_seal_for_tests(
            stage="development",
            directory_pin=directory_pin,
            source_provenance=source,
        )
        authorization = _authorize_ledger_creation(
            invocation_seal=invocation_seal,
            stage="development",
            directory_pin=directory_pin,
            source_provenance=source,
            bindings=bindings,
            ledger_path=paths["development_ledger"],
        )
        ledger = _AccessLedger(
            paths["development_ledger"],
            stage="development",
            bindings=bindings,
            directory_pin=directory_pin,
            authorization=authorization,
        )

        def guard(_label: str) -> None:
            assert ledger is not None
            ledger._verify_disk()

        result = _evaluate_split(
            split="development",
            ledger=ledger,
            evaluator=evaluator,
            boundary_guard=guard,
        )
        results.append(result)
        if result["passed"]:
            checkpoint = _save_review_checkpoint(
                directory_pin,
                development_result=result,
                source_provenance=source,
                execution_mode="fake_test",
            )
        report_template = _report_root(
            stage="development",
            execution_mode="fake_test",
            source_provenance=source,
            results=results,
            pending_ledger_sha256=None,
            checkpoint=checkpoint,
        )
        ledger.prepare_publication(report_template)
        ledger.publish_prepared_report()
        ledger.finish()
        return 0 if result["passed"] else 1
    except BaseException as error:
        _persist_exception_report(
            directory_pin=directory_pin,
            stage="development",
            source_provenance=source,
            ledger=ledger,
            error=error,
            results=results,
            checkpoint=checkpoint,
        )
        raise


def _execute_qualification_for_tests(
    *,
    directory_pin: _PinnedDirectory,
    evaluator: QualificationEvaluator,
    source_provenance: Mapping[str, Any],
    reviewed_checkpoint_sha256: str,
    reviewed_report_sha256: str,
    reviewed_development_ledger_sha256: str,
) -> int:
    """Exercise protected boundaries with an externally supplied three-hash seal."""

    _require_fake_test_directory(directory_pin)
    source = _validated_source_provenance(copy.deepcopy(dict(source_provenance)))
    reviewed, _, seal = _review_development_bundle(
        directory_pin=directory_pin,
        reviewed_checkpoint_sha256=reviewed_checkpoint_sha256,
        reviewed_report_sha256=reviewed_report_sha256,
        reviewed_development_ledger_sha256=reviewed_development_ledger_sha256,
        expected_source=source,
        expected_execution_mode="fake_test",
    )
    paths = _artifact_paths(directory_pin)
    bindings = _ledger_bindings(
        stage="qualification",
        execution_mode="fake_test",
        directory_pin=directory_pin,
        source_provenance=source,
        reviewed_development=reviewed,
    )
    ledger: _AccessLedger | None = None
    results: list[dict[str, Any]] = []
    try:
        invocation_seal = _mint_fake_runner_invocation_seal_for_tests(
            stage="qualification",
            directory_pin=directory_pin,
            source_provenance=source,
            reviewed_development=reviewed,
        )
        authorization = _authorize_ledger_creation(
            invocation_seal=invocation_seal,
            stage="qualification",
            directory_pin=directory_pin,
            source_provenance=source,
            bindings=bindings,
            ledger_path=paths["qualification_ledger"],
            reviewed_development=reviewed,
        )
        ledger = _AccessLedger(
            paths["qualification_ledger"],
            stage="qualification",
            bindings=bindings,
            directory_pin=directory_pin,
            authorization=authorization,
        )

        def guard(_label: str) -> None:
            assert ledger is not None
            ledger._verify_disk()
            _revalidate_reviewed_development(
                seal,
                expected_source=source,
                qualification_active=True,
            )

        for split in PROTECTED_SPLITS:
            result = _evaluate_split(
                split=split,
                ledger=ledger,
                evaluator=evaluator,
                boundary_guard=guard,
            )
            results.append(result)
            if not result["passed"]:
                break
        guard("before protected terminal publication")
        report_template = _report_root(
            stage="qualification",
            execution_mode="fake_test",
            source_provenance=source,
            results=results,
            pending_ledger_sha256=None,
            reviewed_development=reviewed,
        )
        # This is the final fallible protected-input check.  Once the normal
        # intent is durable, only deterministic report publication and the
        # terminal ledger replacement may follow; exception recovery must
        # never turn a failed reviewed-bundle check into a passed terminal.
        _revalidate_reviewed_development(
            seal,
            expected_source=source,
            qualification_active=True,
        )
        ledger.prepare_publication(report_template)
        _, report, _ = ledger.publish_prepared_report()
        ledger.finish()
        return 0 if report["passed"] else 1
    except BaseException as error:
        _persist_exception_report(
            directory_pin=directory_pin,
            stage="qualification",
            source_provenance=source,
            ledger=ledger,
            error=error,
            results=results,
            reviewed_development=reviewed,
            reviewed_seal=seal,
        )
        raise


def _formal_scene_module() -> Any:
    """Import the frozen pure scene only after static byte validation."""

    _require_scene_freeze()
    scene = importlib.import_module("world_model.training.rgbd_known_action_scene")
    origin = getattr(scene, "__file__", None)
    expected = (REPOSITORY_ROOT / SCENE_RELATIVE_PATH).resolve()
    if type(origin) is not str or Path(origin).resolve() != expected:
        raise PermissionError("known-action scene has a noncanonical import origin")
    if sha256_bytes(stable_read_bytes(expected, label="imported known-action scene")) != (
        FROZEN_SCENE_SOURCE_SHA256
    ):
        raise PermissionError("imported known-action scene bytes changed")
    exact = {
        "BUNDLES_PER_SPLIT": SCENES_PER_SPLIT,
        "CANDIDATES_PER_BUNDLE": CANDIDATE_COUNT,
        "HISTORY_FRAME_COUNT": HISTORY_FRAME_COUNT,
        "HORIZONS_SECONDS": HORIZONS_SECONDS,
        "FROZEN_NORMALIZED_SCENE_SOURCE_SHA256": FROZEN_SCENE_NORMALIZED_SOURCE_SHA256,
        "FROZEN_INPUT_BINDING_SHA256": FROZEN_SCENE_INPUT_BINDING_SHA256,
        "FROZEN_DESCRIPTOR_SHA256": FROZEN_SCENE_DESCRIPTOR_SHA256,
        "FROZEN_CERTIFICATE_SHA256": FROZEN_SCENE_CERTIFICATE_SHA256,
        "FROZEN_MANIFEST_SHA256": FROZEN_SCENE_MANIFEST_SHA256,
        "FROZEN_TRACE_SHA256": FROZEN_SCENE_TRACE_SHA256,
    }
    for name, expected_value in exact.items():
        if getattr(scene, name, None) != expected_value:
            raise PermissionError(f"imported scene literal {name} differs")
    return scene


def _accepted_config_for_inherited_surface(
    config: OrpheusConfig,
    owner: Any,
) -> OrpheusConfig:
    """Return the accepted identity view after proving all executable fields equal."""

    assert_known_action_config(config)
    accepted_path = REPOSITORY_ROOT / "configs/rgbd_two_visible_orbital_camera_cpu.yaml"
    accepted = owner.require_frozen_config(accepted_path)
    known_tree = asdict(config)
    accepted_tree = asdict(accepted)
    known_tree["project"]["name"] = accepted_tree["project"]["name"]
    known_tree["project"]["seed"] = accepted_tree["project"]["seed"]
    known_tree["source_path"] = accepted_tree["source_path"]
    _exact_equal(known_tree, accepted_tree, label="known/accepted executable config surface")
    return accepted


def _aggregate_inherited_orbital_metrics(
    records: Sequence[Mapping[str, Any]],
    *,
    owner: Any,
    config: OrpheusConfig,
    split: str,
) -> dict[str, float]:
    """Reduce the 32 observation-distinct rows through the accepted 685-gate surface."""

    representative = set(INHERITED_OBSERVATION_REPRESENTATIVE_ORDINALS)
    selected = [record for record in records if set(record["ordinals"]).issubset(representative)]
    if (
        len(records) != SCENES_PER_SPLIT // BATCH_SIZE
        or len(selected) != len(INHERITED_OBSERVATION_REPRESENTATIVE_ORDINALS) // BATCH_SIZE
        or [ordinal for record in selected for ordinal in record["ordinals"]]
        != list(INHERITED_OBSERVATION_REPRESENTATIVE_ORDINALS)
    ):
        raise RuntimeError("inherited orbital representative inventory differs")

    accumulated: dict[str, list[torch.Tensor]] = {
        name: []
        for name in (
            "current_position_error",
            "current_velocity_error",
            "future_position_error",
            "future_velocity_error",
            "stationary_position_error",
            "zero_velocity_error",
            "semigroup_position",
            "semigroup_velocity",
            "public_direct_position",
            "public_direct_velocity",
            "analytic_position_agreement",
            "analytic_velocity_agreement",
            "query_time_error",
            "history_sample_count",
            "history_valid_count",
            "history_span_error",
            "direct_metric_position_owner_error",
            "final_belief_camera_error",
            "stale_camera_current_position_error",
            "stale_camera_current_velocity_error",
            "stale_camera_horizon_2_00_position_error",
        )
    }
    camera_strata: list[torch.Tensor] = []
    stale_identity_switch_count = 0.0
    stale_association_ambiguous_pair_count = 0.0
    stale_history_valid_count_min = math.inf
    first_batch: Mapping[str, Any] | None = None
    identity_switch_count = 0
    identity_correct = 0
    identity_total = 0
    persistent_ids: list[torch.Tensor] = []
    persistent_id_mismatch_count = 0
    birth_slot_zero = 0
    birth_mapping_count = 0
    active_count = 0
    active_total = 0
    rollout_active_count = 0
    rollout_active_total = 0
    association_matched = 0
    association_opportunities = 0
    association_ambiguous = 0
    hungarian_margins: list[float] = []
    position_margins: list[float] = []
    matched_appearance: list[float] = []
    cross_appearance_distance: list[float] = []
    direct_calls: list[int] = []
    direct_valid = 0
    direct_total = 0
    direct_position_fields = 0
    direct_position_change_max = 0.0
    position_owner_counts: list[int] = []
    packet_counts: list[int] = []
    predict_counts: list[int] = []
    alias_count = 0
    runtime_state_bytes_max = 0
    preflight_values: dict[str, list[float]] = {}
    scene_signatures: set[str] = set()
    palette_swapped = 0

    for record in selected:
        batch = record["batch"]
        output = record["output"]
        if first_batch is None:
            first_batch = batch
        for row, evidence in zip(
            record["scene_rows"],
            record["preflight"],
            strict=True,
        ):
            scene_signatures.add(canonical_sha256(row))
            palette_swapped += int(row["palette_swapped"])
            for name, value in evidence.items():
                preflight_values.setdefault(name, []).append(float(value))
        stale = owner._stale_camera_batch_metrics(batch, config)
        belief = output["belief"]
        trajectory = output["trajectory"]
        history = output["history"]
        observed = output["observed_positions"]
        birth_mapping = record["physical_by_slot"]
        birth_slot_zero += int((birth_mapping[:, 0] == 0).sum().detach().cpu())
        birth_mapping_count += birth_mapping.shape[0]
        for frame_offset, frame_index in enumerate(owner.HISTORY_FRAME_INDICES):
            frame_mapping, _ = owner._birth_physical_mapping(
                observed[:, frame_offset],
                batch["objects"]["position"][:, frame_index, :2],
            )
            identity_switch_count += int(
                (frame_mapping != birth_mapping).any(dim=-1).sum().detach().cpu()
            )
            identity_correct += int((frame_mapping == birth_mapping).all(dim=-1).sum()) * 2
            identity_total += frame_mapping.shape[0] * 2
        anchor_position = owner._gather_physical_by_slot(
            batch["objects"]["position"][:, owner.ANCHOR_FRAME_INDEX, :2],
            birth_mapping,
        )
        anchor_velocity = owner._gather_physical_by_slot(
            batch["objects"]["velocity"][:, owner.ANCHOR_FRAME_INDEX, :2],
            birth_mapping,
        )
        future_position = record["truth_none_position"]
        future_velocity = record["truth_none_velocity"]
        accumulated["current_position_error"].append(
            (belief.objects.position - anchor_position).cpu()
        )
        accumulated["current_velocity_error"].append(
            (belief.objects.velocity - anchor_velocity).cpu()
        )
        accumulated["future_position_error"].append((trajectory.positions - future_position).cpu())
        accumulated["future_velocity_error"].append((trajectory.velocities - future_velocity).cpu())
        accumulated["stationary_position_error"].append(
            (belief.objects.position[:, None] - future_position).cpu()
        )
        accumulated["zero_velocity_error"].append((-anchor_velocity).cpu())
        for name in (
            "semigroup_position",
            "semigroup_velocity",
            "public_direct_position",
            "public_direct_velocity",
            "analytic_position_agreement",
            "analytic_velocity_agreement",
            "query_time_error",
            "direct_metric_position_owner_error",
            "final_belief_camera_error",
        ):
            accumulated[name].append(output[name].cpu())
        accumulated["stale_camera_current_position_error"].append(stale["current_position_error"])
        accumulated["stale_camera_current_velocity_error"].append(stale["current_velocity_error"])
        accumulated["stale_camera_horizon_2_00_position_error"].append(
            stale["horizon_2_00_position_error"]
        )
        stale_identity_switch_count += float(stale["identity_switch_count"])
        stale_association_ambiguous_pair_count += float(stale["association_ambiguous_pair_count"])
        stale_history_valid_count_min = min(
            stale_history_valid_count_min,
            float(stale["history_valid_count_min"]),
        )
        stratum = batch["metadata"]["camera_stratum"]
        if not isinstance(stratum, torch.Tensor) or stratum.shape != (BATCH_SIZE,):
            raise RuntimeError("inherited camera-stratum metadata was not row-preserved")
        camera_strata.append(stratum.to(torch.int64).cpu())
        sample_count = history.sample_mask.sum(dim=-1)
        valid_count = history.valid_mask.sum(dim=-1)
        span = history.timestamps[..., -1] - history.timestamps[..., 0]
        accumulated["history_sample_count"].append(sample_count.cpu())
        accumulated["history_valid_count"].append(valid_count.cpu())
        accumulated["history_span_error"].append(
            (span - owner.DEFAULT_GATES.history_span_seconds).abs().cpu()
        )
        identities = output["identities"]
        persistent_ids.append(identities.cpu())
        expected_ids = torch.tensor([0, 1], dtype=torch.int64, device=identities.device)
        persistent_id_mismatch_count += int(
            identities.ne(expected_ids.view(1, 1, 2)).sum().detach().cpu()
        )
        active = output["active_masks"]
        active_count += int(active.sum().detach().cpu())
        active_total += active.numel()
        rollout_active_count += int(trajectory.active_mask.sum().detach().cpu())
        rollout_active_total += trajectory.active_mask.numel()
        association = output["association_audit"]
        association_matched += int(association["matched"])
        association_opportunities += int(association["opportunities"])
        association_ambiguous += int(association["ambiguous"])
        hungarian_margins.extend(association["hungarian_margins"])
        position_margins.extend(association["position_margins"])
        matched_appearance.extend(association["appearance_cosines"])
        cross_appearance_distance.extend(association["cross_appearance_distances"])
        correction = output["correction_audit"]
        direct_calls.append(int(correction["calls"]))
        direct_valid += int(correction["valid"])
        direct_total += int(correction["total"])
        direct_position_fields += int(correction["position_fields"])
        direct_position_change_max = max(
            direct_position_change_max,
            float(correction["position_change_max_abs"]),
        )
        position_owner_counts.append(int(output["position_owner_count"]))
        packet_counts.append(int(output["packet_count"]))
        predict_counts.append(int(output["predict_count"]))
        alias_count += int(output["output_alias_count"])
        runtime_state_bytes_max = max(
            runtime_state_bytes_max,
            int(output["runtime_tensor_bytes"]),
        )

    if first_batch is None:
        raise RuntimeError("inherited orbital representative set is empty")
    tensors = {name: torch.cat(values) for name, values in accumulated.items()}
    current_position_rmse = owner._rmse(tensors["current_position_error"])
    current_velocity_rmse = owner._rmse(tensors["current_velocity_error"])
    future_position_rmse = [
        owner._rmse(tensors["future_position_error"][:, index])
        for index in range(len(HORIZONS_SECONDS))
    ]
    future_velocity_rmse = [
        owner._rmse(tensors["future_velocity_error"][:, index])
        for index in range(len(HORIZONS_SECONDS))
    ]
    stationary_rmse = [
        owner._rmse(tensors["stationary_position_error"][:, index])
        for index in range(len(HORIZONS_SECONDS))
    ]
    zero_velocity_rmse = owner._rmse(tensors["zero_velocity_error"])
    stale_current_position_rmse = owner._rmse(tensors["stale_camera_current_position_error"])
    stale_current_velocity_rmse = owner._rmse(tensors["stale_camera_current_velocity_error"])
    stale_horizon_2_00_position_rmse = owner._rmse(
        tensors["stale_camera_horizon_2_00_position_error"]
    )
    strata = torch.cat(camera_strata)
    epsilon = torch.finfo(torch.float64).eps
    model = owner.new_public_model(config)
    learned = tuple(parameter for parameter in model.parameters() if parameter.requires_grad)
    buffers = tuple(model.buffers())
    state_tensors = tuple(model.state_dict().values())
    certificate = owner.scene_family_certificate()
    if certificate["certificate_sha256"] != FROZEN_ACCEPTED_ORBITAL_CERTIFICATE_SHA256:
        raise RuntimeError("accepted inherited orbital certificate differs")
    ideal_minimum = certificate["ideal_stale_camera_control"]["minimum_joint_rmse"]
    requested_count = len(INHERITED_OBSERVATION_REPRESENTATIVE_ORDINALS)
    metrics: dict[str, float] = {
        "current_position_rmse_m": current_position_rmse,
        "current_velocity_rmse_mps": current_velocity_rmse,
        "maximum_position_error_growth_slope_mps": max(
            max(0.0, error - current_position_rmse) / horizon
            for horizon, error in zip(HORIZONS_SECONDS, future_position_rmse, strict=True)
        ),
        "early_stationary_additive_regression_m": max(
            future_position_rmse[index] - stationary_rmse[index] for index in (0, 1)
        ),
        "long_stationary_rmse_ratio": max(
            future_position_rmse[index] / max(stationary_rmse[index], epsilon)
            for index in (2, 3, 4)
        ),
        "zero_velocity_rmse_ratio": current_velocity_rmse / max(zero_velocity_rmse, epsilon),
        "stale_camera_current_position_rmse_m": stale_current_position_rmse,
        "correct_to_stale_current_position_rmse_ratio": current_position_rmse
        / max(stale_current_position_rmse, epsilon),
        "stale_camera_current_velocity_rmse_mps": stale_current_velocity_rmse,
        "correct_to_stale_current_velocity_rmse_ratio": current_velocity_rmse
        / max(stale_current_velocity_rmse, epsilon),
        "stale_camera_horizon_2_00_position_rmse_m": stale_horizon_2_00_position_rmse,
        "correct_to_stale_horizon_2_00_position_rmse_ratio": future_position_rmse[-1]
        / max(stale_horizon_2_00_position_rmse, epsilon),
        "stale_camera_identity_switch_count": stale_identity_switch_count,
        "stale_camera_association_ambiguous_pair_count": (stale_association_ambiguous_pair_count),
        "stale_camera_history_valid_count_min": stale_history_valid_count_min,
        "certificate_ideal_stale_camera_current_position_rmse_m": ideal_minimum[
            "current_position_rmse_m"
        ],
        "certificate_ideal_stale_camera_current_velocity_rmse_mps": ideal_minimum[
            "current_velocity_rmse_mps"
        ],
        "certificate_ideal_stale_camera_horizon_2_00_position_rmse_m": ideal_minimum[
            "horizon_2_00_position_rmse_m"
        ],
        "certificate_physical_trajectory_count": float(certificate["physical_trajectory_count"]),
        "certificate_camera_appearance_combination_count": float(
            certificate["camera_appearance_combination_count"]
        ),
        "identity_switch_count": float(identity_switch_count),
        "persistent_id_mismatch_count": float(persistent_id_mismatch_count),
        "identity_coverage": identity_correct / identity_total,
        "persistent_object_id_min": float(torch.cat(persistent_ids).min()),
        "persistent_object_id_max": float(torch.cat(persistent_ids).max()),
        "association_pair_coverage": (
            association_matched / association_opportunities if association_opportunities else 0.0
        ),
        "association_ambiguous_pair_count": float(association_ambiguous),
        "minimum_hungarian_margin": min(hungarian_margins, default=float("nan")),
        "minimum_position_assignment_margin_m": min(
            position_margins,
            default=float("nan"),
        ),
        "minimum_matched_appearance_cosine": min(
            matched_appearance,
            default=float("nan"),
        ),
        "minimum_cross_appearance_cosine_distance": min(
            cross_appearance_distance,
            default=float("nan"),
        ),
        "physical_palette_swap_fraction": palette_swapped / requested_count,
        "birth_slot_physical_zero_fraction": birth_slot_zero / birth_mapping_count,
        "unique_scene_specification_fraction": len(scene_signatures) / requested_count,
        "active_fraction": active_count / active_total,
        "rollout_active_fraction": rollout_active_count / rollout_active_total,
        "history_sample_count_min": float(tensors["history_sample_count"].min()),
        "history_sample_count_max": float(tensors["history_sample_count"].max()),
        "history_valid_count_min": float(tensors["history_valid_count"].min()),
        "history_valid_count_max": float(tensors["history_valid_count"].max()),
        "history_span_max_abs_error_seconds": float(tensors["history_span_error"].max()),
        "direct_velocity_calls_per_batch_min": float(min(direct_calls)),
        "direct_velocity_calls_per_batch_max": float(max(direct_calls)),
        "direct_velocity_valid_fraction": direct_valid / direct_total if direct_total else 0.0,
        "position_owner_count_min": float(min(position_owner_counts)),
        "position_owner_count_max": float(max(position_owner_counts)),
        "direct_position_field_count": float(direct_position_fields),
        "direct_velocity_position_change_max_abs_m": direct_position_change_max,
        "direct_metric_position_owner_max_abs_m": float(
            tensors["direct_metric_position_owner_error"].max()
        ),
        "final_belief_camera_max_abs_error": float(tensors["final_belief_camera_error"].max()),
        "semigroup_position_max_abs_m": float(tensors["semigroup_position"].max()),
        "semigroup_velocity_max_abs_mps": float(tensors["semigroup_velocity"].max()),
        "public_direct_position_max_abs_m": float(tensors["public_direct_position"].max()),
        "public_direct_velocity_max_abs_mps": float(tensors["public_direct_velocity"].max()),
        "analytic_position_agreement_max_abs_m": float(
            tensors["analytic_position_agreement"].max()
        ),
        "analytic_velocity_agreement_max_abs_mps": float(
            tensors["analytic_velocity_agreement"].max()
        ),
        "public_rollout_output_alias_count": float(alias_count),
        "public_query_time_max_abs_seconds": float(tensors["query_time_error"].max()),
        "ingested_frame_count_min": float(min(packet_counts)),
        "ingested_frame_count_max": float(max(packet_counts)),
        "public_predict_calls_per_batch_min": float(min(predict_counts)),
        "public_predict_calls_per_batch_max": float(max(predict_counts)),
        "persistent_runtime_tensor_state_bytes_max": float(runtime_state_bytes_max),
        "learned_parameter_count": float(sum(value.numel() for value in learned)),
        "learned_parameter_bytes": float(
            sum(value.numel() * value.element_size() for value in learned)
        ),
        "module_tensor_buffer_count": float(len(buffers)),
        "persistent_module_state_key_count": float(len(state_tensors)),
        "persistent_module_state_bytes": float(
            sum(value.numel() * value.element_size() for value in state_tensors)
        ),
        "optimizer_updates": 0.0,
        "optimizer_state_entry_count": 0.0,
    }
    for object_index in owner.OBJECT_INDICES:
        for axis_index, axis in enumerate(owner.AXIS_NAMES):
            metrics[f"current_position_rmse_m/object_{object_index}/{axis}"] = owner._rmse(
                tensors["current_position_error"][:, object_index, axis_index]
            )
            metrics[f"current_velocity_rmse_mps/object_{object_index}/{axis}"] = owner._rmse(
                tensors["current_velocity_error"][:, object_index, axis_index]
            )
    for horizon_index, horizon in enumerate(HORIZONS_SECONDS):
        label = f"{horizon:.2f}"
        metrics[f"horizon_{label}_position_rmse_m"] = future_position_rmse[horizon_index]
        metrics[f"horizon_{label}_velocity_rmse_mps"] = future_velocity_rmse[horizon_index]
        for object_index in owner.OBJECT_INDICES:
            for axis_index, axis in enumerate(owner.AXIS_NAMES):
                metrics[f"horizon_{label}_position_rmse_m/object_{object_index}/{axis}"] = (
                    owner._rmse(
                        tensors["future_position_error"][:, horizon_index, object_index, axis_index]
                    )
                )
                metrics[f"horizon_{label}_velocity_rmse_mps/object_{object_index}/{axis}"] = (
                    owner._rmse(
                        tensors["future_velocity_error"][:, horizon_index, object_index, axis_index]
                    )
                )
    for camera_stratum in range(8):
        mask = strata == camera_stratum
        if not bool(mask.any()):
            raise RuntimeError(f"camera stratum {camera_stratum} is absent from inherited {split}")
        phase_index = camera_stratum // 2
        direction = owner.CAMERA_DIRECTIONS[camera_stratum % 2]
        suffix = f"phase_{phase_index}/direction_{direction:+d}"
        correct_position = owner._rmse(tensors["current_position_error"][mask])
        correct_velocity = owner._rmse(tensors["current_velocity_error"][mask])
        correct_future = owner._rmse(tensors["future_position_error"][mask, -1])
        stale_position = owner._rmse(tensors["stale_camera_current_position_error"][mask])
        stale_velocity = owner._rmse(tensors["stale_camera_current_velocity_error"][mask])
        stale_future = owner._rmse(tensors["stale_camera_horizon_2_00_position_error"][mask])
        metrics[f"stale_camera_current_position_rmse_m/{suffix}"] = stale_position
        metrics[f"correct_to_stale_current_position_rmse_ratio/{suffix}"] = correct_position / max(
            stale_position, epsilon
        )
        metrics[f"stale_camera_current_velocity_rmse_mps/{suffix}"] = stale_velocity
        metrics[f"correct_to_stale_current_velocity_rmse_ratio/{suffix}"] = correct_velocity / max(
            stale_velocity, epsilon
        )
        metrics[f"stale_camera_horizon_2_00_position_rmse_m/{suffix}"] = stale_future
        metrics[f"correct_to_stale_horizon_2_00_position_rmse_ratio/{suffix}"] = (
            correct_future / max(stale_future, epsilon)
        )
        metrics[f"current_position_rmse_m/{suffix}"] = correct_position
        metrics[f"current_velocity_rmse_mps/{suffix}"] = correct_velocity
        for horizon_index, horizon in enumerate(HORIZONS_SECONDS):
            label = f"{horizon:.2f}"
            metrics[f"horizon_{label}_position_rmse_m/{suffix}"] = owner._rmse(
                tensors["future_position_error"][mask, horizon_index]
            )
            metrics[f"horizon_{label}_velocity_rmse_mps/{suffix}"] = owner._rmse(
                tensors["future_velocity_error"][mask, horizon_index]
            )
    for name, values in preflight_values.items():
        metrics[name] = (
            max(values)
            if "maximum" in name or "max_abs" in name or name == "preflight_event_count"
            else min(values)
        )
    metrics.update(owner._ambiguity_fail_closed_metrics(config, first_batch))
    metrics.update(owner._gradient_metrics(config, first_batch))
    metrics.update(owner._latency_metrics(config, first_batch))
    if set(metrics) != set(owner.GATE_METRIC_SCHEMA):
        raise RuntimeError(
            "inherited orbital metric keys differ from the exact accepted 685-scalar schema"
        )
    result = {name: float(value) for name, value in metrics.items()}
    if any(not math.isfinite(value) for value in result.values()):
        raise FloatingPointError("inherited orbital metric is nonfinite")
    return result


def _formal_camera_frame(scene: Any, camera_stratum: int, timestamp: float) -> Any:
    camera_module = importlib.import_module("world_model.simulator.camera")
    pure = scene.pure_orbital_camera_frame(camera_stratum, timestamp)
    frame = camera_module.CameraFrame(
        timestamp=float(pure.timestamp),
        world_from_camera=pure.world_from_camera.clone(),
        camera_from_world=pure.camera_from_world.clone(),
        intrinsics=pure.intrinsics.clone(),
        position=pure.position.clone(),
        target=pure.target.clone(),
    )
    frame.validate()
    return frame


def _accepted_specification_view(scene: Any, owner: Any, specification: Any) -> Any:
    return owner.OrbitalCameraSceneSpecification(
        position=specification.position_tensor(),
        velocity=specification.velocity_tensor(),
        albedo=specification.albedo_tensor(),
        palette_swapped=specification.palette_swapped,
        split=specification.split,
        split_primitive_index=specification.primitive_index,
        physical_index=specification.primitive_index,
        a=specification.a,
        b=specification.b,
        camera_stratum=specification.camera_stratum,
        phase_index=specification.phase_index,
        direction_index=specification.direction_index,
        direction=specification.direction,
        theta0=scene.CAMERA_PHASES_RADIANS[specification.phase_index],
    )


@dataclass(frozen=True, slots=True)
class _ConsumedOrdinalAuthority:
    split: str
    ordinal: int
    token: _OrdinalCapability
    token_receipt: dict[str, Any]
    nonce: object


_CONSUMED_ORDINAL_REGISTRY: dict[
    int,
    tuple[_ConsumedOrdinalAuthority, BatchEvaluationRequest, set[str]],
] = {}


def _capability_nonce_hex() -> str:
    """Return one precomputed receipt nonce before any registry transition."""

    return os.urandom(32).hex()


def _revoke_materialization_authorities(request: BatchEvaluationRequest) -> None:
    """Retire every scene-materialization authority owned by one request."""

    registry_corruption: PermissionError | None = None
    retained_registrations: list[
        tuple[
            int,
            tuple[_ConsumedOrdinalAuthority, BatchEvaluationRequest, set[str]],
        ]
    ] = []
    for identity, registration in tuple(_CONSUMED_ORDINAL_REGISTRY.items()):
        if (
            type(identity) is not int
            or type(registration) is not tuple
            or len(registration) != 3
            or type(registration[0]) is not _ConsumedOrdinalAuthority
            or type(registration[1]) is not PublicBatchEvaluationRequest
            or type(registration[2]) is not set
            or any(type(value) is not str for value in registration[2])
        ):
            registry_corruption = PermissionError(
                "consumed ordinal registry was corrupted during revocation"
            )
            continue
        if registration[1] is not request:
            retained_registrations.append((identity, registration))
    _CONSUMED_ORDINAL_REGISTRY.clear()
    _CONSUMED_ORDINAL_REGISTRY.update(retained_registrations)
    if registry_corruption is not None:
        raise registry_corruption


def _retire_failed_materialization_request_capabilities(
    request: PublicBatchEvaluationRequest,
    *,
    owner_witness: tuple[
        _ManifestCapability,
        _BatchCapability,
        _BatchRegistration,
        tuple[_OrdinalCapability, ...],
        tuple[tuple[_OrdinalCapability, _BatchRegistration, str], ...],
    ],
) -> None:
    """Fail-close one recognized reserved B=4 request without ledger replay."""

    if (
        type(request) is not PublicBatchEvaluationRequest
        or type(request._manifest) is not _ManifestCapability
        or type(request._manifest._ledger) is not _AccessLedger
        or type(request.split) is not str
        or request.split not in SPLITS
    ):
        raise PermissionError("failed materialization request is forged")
    registry_error = _burn_materializer_core_capabilities(
        ledger=request._manifest._ledger,
        split=request.split,
        owner_witness=owner_witness,
    )
    if registry_error is not None:
        raise registry_error


def _authorize_formal_batch(
    request: BatchEvaluationRequest,
) -> tuple[
    _ConsumedOrdinalAuthority,
    _ConsumedOrdinalAuthority,
    _ConsumedOrdinalAuthority,
    _ConsumedOrdinalAuthority,
]:
    """Consume one exact active B=4 request before any scene row exists."""

    if type(request) is not BatchEvaluationRequest:
        raise PermissionError("formal materialization requires an exact batch request")
    request._manifest._ledger._verify_disk()
    formal_ledger = request._manifest._ledger
    if (
        formal_ledger._record["execution_mode"] != "formal"
        or formal_ledger._pin.canonical is not True
        or formal_ledger._pin.mutable is not True
        or formal_ledger._pin.path != _canonical_run_directory()
    ):
        raise PermissionError("formal materialization requires a governed formal ledger")
    _ports, batches, tokens, consumed = _validated_materializer_global_registry_cut(
        ledger=formal_ledger,
    )
    registration = batches.get(id(request._batch))
    if (
        registration is None
        or registration.batch is not request._batch
        or registration.manifest is not request._manifest
        or registration.status != "issued"
        or request._manifest._active is not request._batch
        or request.split != request._batch.split
        or type(request.ordinals) is not tuple
        or len(request.ordinals) != BATCH_SIZE
        or any(type(value) is not int for value in request.ordinals)
        or any(
            actual is not expected
            for actual, expected in zip(request.tokens, request._batch.tokens, strict=True)
        )
        or any(
            actual != expected
            for actual, expected in zip(request.ordinals, request._batch.ordinals, strict=True)
        )
    ):
        raise PermissionError("formal materialization request is forged, inactive, or replayed")
    reservation = request._manifest._ledger.record
    reservation_state = reservation["splits"].get(request.split)
    if (
        type(reservation_state) is not dict
        or reservation_state.get("public_active_batch") != list(request.ordinals)
        or type(reservation.get("generation")) is not int
    ):
        raise PermissionError("formal batch lacks its exact durable reservation generation")
    reservation_sha256 = canonical_sha256(reservation)

    # Validate the complete B=4 capability set before generating nonces or
    # changing any in-memory state.  In particular, a forged fourth token must
    # not consume the first three.
    if registration.consumed:
        raise PermissionError("formal batch capability set is already partly consumed")
    for offset, (ordinal, token) in enumerate(zip(request.ordinals, request.tokens, strict=True)):
        if isinstance(ordinal, bool) or type(ordinal) is not int:
            raise PermissionError("formal ordinal must be one exact integer")
        token_registration = tokens.get(id(token))
        if (
            token is not request._batch.tokens[offset]
            or token.split != request.split
            or token.ordinal != ordinal
            or token_registration is None
            or token_registration[0] is not token
            or token_registration[1] is not registration
            or token_registration[2] != "issued"
            or any(item[0].token is token for item in consumed.values())
        ):
            raise PermissionError("formal B=4 token set is forged, reordered, or replayed")

    # Entropy syntax, intra-B=4 uniqueness, and attempt-global replay checks
    # already ran twice before the durable reservation and capability registry
    # transitions in ``begin_batch``.  Authenticate that exact private batch
    # payload here without acquiring entropy or touching historical state.
    nonces = _validated_capability_nonce_quad(
        request._batch.capability_nonces,
        label="formal preflight capability nonces",
    )
    validated_sha256(
        request._batch.capability_nonce_preflight_sha256,
        label="formal capability nonce preflight",
    )

    # Every remaining operation that can fail (receipt hashing, object
    # allocation, and dictionary growth) happens against local values.  The
    # final registry transition is then rolled back exactly on the exceptional
    # path.
    authorities: list[_ConsumedOrdinalAuthority] = []
    authority_entries: dict[
        int, tuple[_ConsumedOrdinalAuthority, BatchEvaluationRequest, set[str]]
    ] = {}
    for ordinal, token, nonce in zip(request.ordinals, request.tokens, nonces, strict=True):
        token_body = {
            "schema": "rgbd_known_action_ordinal_capability_receipt_v1",
            "split": request.split,
            "ordinal": ordinal,
            "batch_index": request.ordinals[0] // BATCH_SIZE,
            "reservation_generation": reservation["generation"],
            "reservation_sha256": reservation_sha256,
            "capability_nonce": nonce,
        }
        token_receipt = {**token_body, "receipt_sha256": canonical_sha256(token_body)}
        authority = _ConsumedOrdinalAuthority(
            request.split,
            ordinal,
            token,
            token_receipt,
            object(),
        )
        if id(authority) in _CONSUMED_ORDINAL_REGISTRY or id(authority) in authority_entries:
            raise PermissionError("formal ordinal authority identity was reused")
        authority_entries[id(authority)] = (
            authority,
            request,
            {"base", "palette"},
        )
        authorities.append(authority)

    old_consumed = set(registration.consumed)
    old_tokens = {id(token): tokens[id(token)] for token in request.tokens}
    try:
        registration.consumed.update(request.ordinals)
        for token in request.tokens:
            _TOKEN_REGISTRY[id(token)] = (token, registration, "consumed")
        _CONSUMED_ORDINAL_REGISTRY.update(authority_entries)
    except BaseException:
        registration.consumed.clear()
        registration.consumed.update(old_consumed)
        for identity, value in old_tokens.items():
            _TOKEN_REGISTRY[identity] = value
        for identity in authority_entries:
            _CONSUMED_ORDINAL_REGISTRY.pop(identity, None)
        raise
    _validated_materializer_global_registry_cut(ledger=formal_ledger)
    return tuple(authorities)  # type: ignore[return-value]


def _begin_formal_public_science_materialization(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    request: PublicBatchEvaluationRequest,
) -> tuple[
    _ConsumedOrdinalAuthority,
    _ConsumedOrdinalAuthority,
    _ConsumedOrdinalAuthority,
    _ConsumedOrdinalAuthority,
]:
    """Bind one B=4 materialization before any scene or truth constructor runs."""

    registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset({"collecting_public"}),
    )
    ledger = registration.ledger
    expected_ordinals = tuple(
        range(registration.next_ordinal, registration.next_ordinal + BATCH_SIZE)
    )
    state = ledger._record["splits"][vault.split]
    if (
        type(request) is not PublicBatchEvaluationRequest
        or request.split != vault.split
        or request.ordinals != expected_ordinals
        or request._manifest._ledger is not ledger
        or request._manifest.split != vault.split
        or request._manifest._active is not request._batch
        or request._batch.ordinals != expected_ordinals
        or state["status"] != "public_evaluating"
        or state["public_next_ordinal"] != registration.next_ordinal
        or state["public_active_batch"] != list(expected_ordinals)
        or len(registration.envelopes) != registration.next_ordinal // BATCH_SIZE
    ):
        raise PermissionError("formal science materialization request binding differs")
    failure_owner = _capture_materializer_failure_owner(registration)
    registration.state = "checking_public_issue"
    try:
        return _authorize_formal_batch(request)
    except BaseException:
        _fail_materializer_vault(
            registration,
            owner_witness=failure_owner,
        )
        raise


def _consume_materialization_variant(
    authority: _ConsumedOrdinalAuthority,
    *,
    split: str,
    ordinal: int,
    variant: str,
) -> None:
    registry_error, _ports, _batches, tokens, consumed = (
        _partition_exact_materializer_core_registries()
    )
    registration = consumed.get(id(authority))
    if registry_error is not None:
        if type(registration) is tuple and len(registration) == 3:
            _raise_materializer_registry_corruption(
                registry_error,
                ledger=registration[1]._manifest._ledger,
            )
        raise registry_error
    if (
        type(authority) is not _ConsumedOrdinalAuthority
        or registration is None
        or registration[0] is not authority
        or authority.split != split
        or authority.ordinal != ordinal
        or authority.token.split != split
        or authority.token.ordinal != ordinal
        or variant not in registration[2]
        or type(tokens.get(id(authority.token))) is not tuple
        or tokens[id(authority.token)][2] != "consumed"
    ):
        raise PermissionError("formal ordinal authority is forged, cross-bound, or replayed")
    registration[2].remove(variant)
    if not registration[2]:
        _CONSUMED_ORDINAL_REGISTRY.pop(id(authority), None)
    _validated_materializer_global_registry_cut(
        ledger=registration[1]._manifest._ledger,
    )


def _render_authorized_episode(
    *,
    authority: _ConsumedOrdinalAuthority,
    variant: str,
    scene: Any,
    owner: Any,
    config: OrpheusConfig,
    specification: Any,
    albedo_override: torch.Tensor | None = None,
) -> dict[str, Any]:
    """Render one already-authorized direct state with no simulator RNG."""

    _consume_materialization_variant(
        authority,
        split=specification.split,
        ordinal=specification.ordinal,
        variant=variant,
    )
    sphere_world_module = importlib.import_module("world_model.simulator.sphere_world")
    physics_module = importlib.import_module("world_model.simulator.physics")
    renderer_module = importlib.import_module("world_model.simulator.renderer")
    labels_module = importlib.import_module("world_model.simulator.labels")
    episode_module = importlib.import_module("world_model.simulator.episode")
    resolved = sphere_world_module.SphereWorldConfig.from_config(config)
    albedo = specification.albedo_tensor()
    accepted_spec = _accepted_specification_view(scene, owner, specification)
    if albedo_override is not None:
        if (
            not isinstance(albedo_override, torch.Tensor)
            or albedo_override.shape != (2, 3)
            or albedo_override.dtype != torch.float32
        ):
            raise TypeError("palette control albedo must be float32 [2,3]")
        albedo = albedo_override.clone()
        accepted_spec = replace(
            accepted_spec,
            albedo=albedo.clone(),
            palette_swapped=not accepted_spec.palette_swapped,
        )
    state = physics_module.SphereState(
        object_id=torch.tensor([0, 1], dtype=torch.int64),
        active=torch.ones(2, dtype=torch.bool),
        position=specification.position_tensor(),
        velocity=specification.velocity_tensor(),
        radius=torch.full((2, 1), 0.21, dtype=torch.float32),
        mass=torch.ones((2, 1), dtype=torch.float32),
        restitution=torch.full((2, 1), 0.7, dtype=torch.float32),
        drag=torch.full((2, 1), 0.05, dtype=torch.float32),
        friction=torch.full((2, 1), 0.2, dtype=torch.float32),
        albedo=albedo,
        orientation=torch.tensor([[0.0, 0.0, 0.0, 1.0]], dtype=torch.float32).expand(2, -1).clone(),
        angular_velocity=torch.zeros((2, 3), dtype=torch.float32),
        sleeping=torch.zeros(2, dtype=torch.bool),
        sleep_counter=torch.zeros(2, dtype=torch.int64),
    )
    state.validate()
    physics_config = physics_module.PhysicsConfig(
        gravity=resolved.gravity,
        bounds=resolved.world_bounds,
        max_substep=1.0 / resolved.physics_rate,
        solver_iterations=resolved.solver_iterations,
    )
    zero_external_impulse = torch.zeros_like(state.velocity)

    rgb_frames: list[torch.Tensor] = []
    depth_frames: list[torch.Tensor] = []
    state_records: list[dict[str, torch.Tensor]] = []
    label_records: list[dict[str, torch.Tensor]] = []
    event_records: list[dict[str, torch.Tensor]] = []
    world_from_camera: list[torch.Tensor] = []
    camera_from_world: list[torch.Tensor] = []
    intrinsics: list[torch.Tensor] = []
    camera_position: list[torch.Tensor] = []
    camera_target: list[torch.Tensor] = []
    timestamps = torch.arange(resolved.sequence_frames, dtype=torch.float32) / resolved.frame_rate
    pending = physics_module.empty_physics_events(resolved.n_max)
    for frame_index, timestamp_tensor in enumerate(timestamps):
        timestamp = float(timestamp_tensor)
        camera = _formal_camera_frame(scene, specification.camera_stratum, timestamp)
        rendered = renderer_module.render_spheres(
            state,
            camera,
            resolved.image_size,
            edge_softness_pixels=resolved.edge_softness_pixels,
            noise_std=0.0,
            generator=None,
        )
        labels = labels_module.make_perception_labels(state, rendered, resolved.image_size)
        labels_module.validate_perception_labels(
            labels, max_objects=2, image_size=resolved.image_size
        )
        rgb_frames.append(rendered.rgb)
        depth_frames.append(rendered.depth_buffer.unsqueeze(0))
        state_records.append(owner._state_record(state, rendered.visible_fraction))
        label_records.append(labels)
        event_records.append(
            owner._event_record(
                pending,
                created=(
                    torch.ones(2, dtype=torch.bool)
                    if frame_index == 0
                    else torch.zeros(2, dtype=torch.bool)
                ),
                removed=torch.zeros(2, dtype=torch.bool),
                interval_start=max(0.0, timestamp - resolved.observation_dt),
            )
        )
        world_from_camera.append(camera.world_from_camera)
        camera_from_world.append(camera.camera_from_world)
        intrinsics.append(camera.intrinsics)
        camera_position.append(camera.position)
        camera_target.append(camera.target)
        if frame_index + 1 < resolved.sequence_frames:
            state, pending = physics_module.advance_spheres(
                state,
                resolved.observation_dt,
                physics_config,
                external_impulse=zero_external_impulse,
            )
    world_from = torch.stack(world_from_camera)
    camera_from = torch.stack(camera_from_world)
    intrinsics_tensor = torch.stack(intrinsics)
    linear_camera, angular_camera = owner._camera_velocities(world_from, timestamps)
    objects = owner._stack_records(state_records)
    labels = owner._stack_records(label_records)
    for key in (
        "projected_center",
        "projected_center_pixels",
        "apparent_radius",
        "apparent_radius_normalized",
        "inverse_depth",
        "camera_depth",
        "projected_valid",
    ):
        objects[key] = labels[key]
    episode: dict[str, Any] = {
        "rgb": torch.stack(rgb_frames).to(torch.float32),
        "depth": torch.stack(depth_frames).to(torch.float32),
        "timestamps": timestamps,
        "frame_mask": torch.ones(resolved.sequence_frames, dtype=torch.bool),
        "camera": {
            "world_from_camera": world_from,
            "camera_from_world": camera_from,
            "intrinsics": intrinsics_tensor,
            "position": torch.stack(camera_position),
            "target": torch.stack(camera_target),
            "linear_velocity": linear_camera,
            "angular_velocity": angular_camera,
            "calibrated": torch.ones(resolved.sequence_frames, dtype=torch.bool),
        },
        "objects": objects,
        "events": owner._stack_records(event_records),
        "labels": labels,
        "seed": 0,
        "num_objects": 2,
        "metadata": {
            "simulator": "sphere_world",
            "simulator_version": SIMULATOR_VERSION,
            "distribution": resolved.distribution,
            "scenario": "known_action_qualification_owned_orbital_prefix",
            "camera_trajectory": "qualification_owned_exact_orbit",
            "camera_calibration_owner": "qualification_known_extrinsics",
            "frame_rate": resolved.frame_rate,
            "physics_rate": resolved.physics_rate,
            "palette_swapped": bool(accepted_spec.palette_swapped),
            "split": specification.split,
            "physical_index": specification.primitive_index,
            "split_primitive_index": specification.primitive_index,
            "primitive_a": specification.a,
            "primitive_b": specification.b,
            "camera_stratum": specification.camera_stratum,
            "camera_phase_index": specification.phase_index,
            "camera_direction_index": specification.direction_index,
            "camera_direction": specification.direction,
            "ordinal": specification.ordinal,
        },
    }
    episode_module.validate_episode(episode, resolved)
    owner.preflight_two_visible_orbital_camera_episode(
        episode,
        config=config,
        specification=accepted_spec,
    )
    return episode


def _construct_authorized_formal_batch(
    request: BatchEvaluationRequest,
    *,
    authorities: tuple[
        _ConsumedOrdinalAuthority,
        _ConsumedOrdinalAuthority,
        _ConsumedOrdinalAuthority,
        _ConsumedOrdinalAuthority,
    ],
    scene: Any,
    owner: Any,
    config: OrpheusConfig,
) -> tuple[
    tuple[Any, ...],
    list[dict[str, Any]],
    list[dict[str, Any]],
    tuple[dict[str, Any], ...],
]:
    """Consume one B=4 capability, then construct its base and palette rows."""

    if (
        type(authorities) is not tuple
        or len(authorities) != BATCH_SIZE
        or any(type(authority) is not _ConsumedOrdinalAuthority for authority in authorities)
        or any(
            authority.split != request.split
            or authority.ordinal != request.ordinals[index]
            or authority.token is not request.tokens[index]
            or _CONSUMED_ORDINAL_REGISTRY.get(id(authority))
            != (authority, request, {"base", "palette"})
            for index, authority in enumerate(authorities)
        )
    ):
        raise PermissionError("formal science materialization authority binding differs")
    try:
        # No scene API or scene tensor constructor is called before all four
        # tokens have transitioned together above.
        specifications = tuple(
            scene.scene_specification(request.split, ordinal) for ordinal in request.ordinals
        )
        base: list[dict[str, Any]] = []
        palette: list[dict[str, Any]] = []
        for authority, specification in zip(authorities, specifications, strict=True):
            base.append(
                _render_authorized_episode(
                    authority=authority,
                    variant="base",
                    scene=scene,
                    owner=owner,
                    config=config,
                    specification=specification,
                )
            )
            palette.append(
                _render_authorized_episode(
                    authority=authority,
                    variant="palette",
                    scene=scene,
                    owner=owner,
                    config=config,
                    specification=specification,
                    albedo_override=specification.albedo_tensor().flip(0),
                )
            )
        if any(registration[1] is request for registration in _CONSUMED_ORDINAL_REGISTRY.values()):
            raise PermissionError("formal B=4 materialization left an authority unconsumed")
        return (
            specifications,
            base,
            palette,
            tuple(copy.deepcopy(authority.token_receipt) for authority in authorities),
        )
    except BaseException:
        _revoke_materialization_authorities(request)
        raise


def _process_max_rss_bytes() -> int:
    value = int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
    return value if sys.platform == "darwin" else value * 1024


def _current_process_rss_bytes() -> int:
    """Sample current RSS with the protocol-pinned psutil implementation."""

    psutil = importlib.import_module("psutil")
    if getattr(psutil, "__version__", None) != "7.2.2":
        raise PermissionError("formal current-RSS owner must be exact psutil 7.2.2")
    rss = psutil.Process(os.getpid()).memory_info().rss
    if isinstance(rss, bool) or type(rss) is not int or rss <= 0:
        raise RuntimeError("current process RSS sample is malformed")
    return rss


def _live_tensor_bytes(value: Any, *, seen: set[int] | None = None) -> int:
    """Count unique live tensor storages reachable from a result value."""

    visited = set() if seen is None else seen
    if isinstance(value, torch.Tensor):
        if value.numel() == 0:
            return 0
        storage = value.untyped_storage()
        identity = storage.data_ptr()
        if identity in visited:
            return 0
        visited.add(identity)
        return storage.nbytes()
    if isinstance(value, Mapping):
        return sum(_live_tensor_bytes(item, seen=visited) for item in value.values())
    if isinstance(value, (tuple, list)):
        return sum(_live_tensor_bytes(item, seen=visited) for item in value)
    if hasattr(value, "__dataclass_fields__"):
        return sum(
            _live_tensor_bytes(getattr(value, name), seen=visited)
            for name in value.__dataclass_fields__
        )
    return 0


def _tensor_digest(digest: Any, label: str, value: torch.Tensor) -> None:
    tensor = value.detach().cpu().contiguous().clone()
    metadata = _canonical_json(
        {
            "label": label,
            "dtype": str(tensor.dtype),
            "shape": list(tensor.shape),
        }
    )
    digest.update(b"orpheus-known-action-evidence-v1\x00")
    digest.update(len(metadata).to_bytes(8, "little"))
    digest.update(metadata)
    array = tensor.numpy()
    payload = array.astype(array.dtype.newbyteorder("<"), copy=False).tobytes(order="C")
    digest.update(len(payload).to_bytes(8, "little"))
    digest.update(payload)


def _tensor_group_sha256(values: Sequence[tuple[str, torch.Tensor]]) -> str:
    digest = hashlib.sha256()
    labels: set[str] = set()
    for label, value in values:
        if type(label) is not str or not label or label in labels:
            raise ValueError("numeric evidence tensor labels must be unique nonempty strings")
        if not isinstance(value, torch.Tensor):
            raise TypeError("numeric evidence values must be tensors")
        labels.add(label)
        _tensor_digest(digest, label, value)
    return digest.hexdigest()


def _observation_prefix_sha256(episode: Mapping[str, Any]) -> str:
    """Hash exactly the sixteen public packet tensor inputs, never truth rows."""

    digest = hashlib.sha256()
    history = slice(0, HISTORY_FRAME_COUNT)
    _tensor_digest(digest, "rgb", episode["rgb"][history])
    _tensor_digest(digest, "depth", episode["depth"][history])
    _tensor_digest(digest, "timestamps", episode["timestamps"][history])
    for name in ("world_from_camera", "intrinsics"):
        _tensor_digest(digest, f"camera/{name}", episode["camera"][name][history])
    return digest.hexdigest()


PUBLIC_MATERIALIZATION_SURFACE_SCHEMA = frozenset(
    {
        "schema",
        "split",
        "ordinal",
        "batch_index",
        "fixed_goal_horizon_seconds",
        "materializer_port_sha256",
        "token_receipt_sha256",
        "sensor_sha256",
        "safe_task_sha256",
        "public_runtime_sha256",
    }
)
PUBLIC_MATERIALIZER_EVALUATION_HASH_SCHEMA = frozenset(
    {
        "schema",
        "public_evaluation_sha256",
        "public_evidence_sha256",
        "public_metrics_sha256",
        "public_resources_sha256",
    }
)


def _require_exact_materializer_tensor_metadata(
    value: Any,
    *,
    shape: tuple[int, ...],
    dtype: Any,
    label: str,
) -> Any:
    if torch is None or type(value) is not torch.Tensor:
        raise TypeError(f"{label} must be one exact Torch tensor")
    if (
        tuple(value.shape) != shape
        or value.dtype != dtype
        or value.device.type != "cpu"
        or value.layout != torch.strided
        or not value.is_contiguous()
        or value.requires_grad is not False
        or value.grad_fn is not None
    ):
        raise ValueError(f"{label} shape/dtype/device/gradient binding differs")
    storage = value.untyped_storage()
    if (
        value._base is not None
        or value.storage_offset() != 0
        or storage.nbytes() != value.numel() * value.element_size()
        or storage.resizable() is not True
        or storage.is_shared()
    ):
        raise ValueError(f"{label} shape/dtype/storage/gradient binding differs")
    return value


def _require_exact_materializer_tensor(
    value: Any,
    *,
    shape: tuple[int, ...],
    dtype: Any,
    label: str,
) -> Any:
    value = _require_exact_materializer_tensor_metadata(
        value,
        shape=shape,
        dtype=dtype,
        label=label,
    )
    if value.dtype.is_floating_point and not bool(torch.isfinite(value).all()):
        raise ValueError(f"{label} contains a nonfinite value")
    return value


def _materializer_tensor_storage_inventory(
    value: Any,
    *,
    label: str,
) -> tuple[tuple[str, int, int], ...]:
    rows: list[tuple[str, int, int]] = []

    def visit(item: Any, path: str) -> None:
        if torch is not None and type(item) is torch.Tensor:
            if item.numel() <= 0:
                raise ValueError(f"{path} must have nonempty tensor storage")
            storage = item.untyped_storage()
            pointer = int(storage.data_ptr())
            size = int(storage.nbytes())
            if (
                pointer <= 0
                or size != item.numel() * item.element_size()
                or item._base is not None
                or item.storage_offset() != 0
                or storage.resizable() is not True
                or storage.is_shared()
            ):
                raise ValueError(f"{path} is a view or partial-storage tensor")
            rows.append((path, pointer, size))
            return
        if type(item) is dict:
            if any(type(key) is not str for key in item):
                raise TypeError(f"{path} tensor mapping keys must be exact strings")
            for key in sorted(item):
                visit(item[key], f"{path}.{key}")
            return
        if type(item) in {list, tuple}:
            for index, child in enumerate(item):
                visit(child, f"{path}[{index}]")
            return
        raise TypeError(f"{path} contains non-tensor storage value {type(item).__name__}")

    visit(value, label)
    for index, (left_path, left_pointer, left_size) in enumerate(rows):
        left_end = left_pointer + left_size
        for right_path, right_pointer, right_size in rows[index + 1 :]:
            right_end = right_pointer + right_size
            if left_pointer < right_end and right_pointer < left_end:
                raise PermissionError(
                    f"materializer tensors {left_path!r} and {right_path!r} alias storage"
                )
    return tuple(rows)


def _clone_materializer_tensor(value: Any) -> Any:
    if torch is None or type(value) is not torch.Tensor:
        raise TypeError("materializer clone requires one exact Torch tensor")
    return value.detach().cpu().contiguous().clone()


def _clone_materializer_tensor_mapping(value: Mapping[str, Any]) -> dict[str, Any]:
    if type(value) is not dict:
        raise TypeError("materializer tensor batch must be one exact dictionary")
    keys = tuple(value.keys())
    if any(type(name) is not str for name in keys):
        raise TypeError("materializer tensor batch keys must be built-in strings")
    return {name: _clone_materializer_tensor(value[name]) for name in keys}


def _require_exact_ordered_string_keys(
    value: Any,
    expected: tuple[str, ...],
    *,
    label: str,
) -> None:
    if type(value) is not dict:
        raise ValueError(f"{label} allowlist/order differs")
    keys = tuple(value.keys())
    if any(type(key) is not str for key in keys) or keys != expected:
        raise ValueError(f"{label} allowlist/order differs")


def _require_materializer_source_tensor_metadata(
    value: Any,
    specifications: tuple[tuple[str, tuple[int, ...], Any], ...],
    *,
    label: str,
) -> None:
    expected_keys = tuple(name for name, _shape, _dtype in specifications)
    _require_exact_ordered_string_keys(value, expected_keys, label=label)
    for name, shape, dtype in specifications:
        _require_exact_materializer_tensor_metadata(
            value[name],
            shape=shape,
            dtype=dtype,
            label=f"{label} source {name}",
        )


def _validated_public_sensor_tensors(value: Any) -> dict[str, Any]:
    _require_exact_ordered_string_keys(
        value,
        PUBLIC_SENSOR_TENSOR_KEYS,
        label="public sensor tensor",
    )
    expected = {
        "rgb": ((BATCH_SIZE, HISTORY_FRAME_COUNT, 3, 64, 64), torch.float32),
        "depth": ((BATCH_SIZE, HISTORY_FRAME_COUNT, 1, 64, 64), torch.float32),
        "timestamps": ((BATCH_SIZE, HISTORY_FRAME_COUNT), torch.float32),
        "world_from_camera": (
            (BATCH_SIZE, HISTORY_FRAME_COUNT, 4, 4),
            torch.float32,
        ),
        "intrinsics": ((BATCH_SIZE, HISTORY_FRAME_COUNT, 3, 3), torch.float32),
    }
    validated = {
        name: _require_exact_materializer_tensor(
            value[name],
            shape=shape,
            dtype=dtype,
            label=f"public sensor {name}",
        )
        for name, (shape, dtype) in expected.items()
    }
    if not bool(validated["rgb"].ge(0.0).all() and validated["rgb"].le(1.0).all()):
        raise ValueError("public RGB values must lie in [0, 1]")
    if not bool(
        validated["depth"].ge(MATERIALIZER_SENSOR_DEPTH_METERS[0]).all()
        and validated["depth"].le(MATERIALIZER_SENSOR_DEPTH_METERS[1]).all()
    ):
        raise ValueError("public depth values must lie in the frozen [0, 8] metre range")
    timestamps = validated["timestamps"]
    expected_timestamps = (
        torch.arange(HISTORY_FRAME_COUNT, dtype=torch.float32)
        .div(1.0 / MATERIALIZER_SENSOR_TIMESTEP_SECONDS)
        .expand(BATCH_SIZE, HISTORY_FRAME_COUNT)
    )
    if not torch.equal(timestamps, expected_timestamps):
        raise ValueError("public timestamps differ from exact float32 arange(16)/20")
    world_from_camera = validated["world_from_camera"]
    expected_last_row = torch.tensor(
        [0.0, 0.0, 0.0, 1.0],
        dtype=torch.float32,
    ).expand(BATCH_SIZE, HISTORY_FRAME_COUNT, 4)
    if not torch.equal(world_from_camera[..., 3, :], expected_last_row):
        raise ValueError("world-from-camera homogeneous last row differs")
    rotation = world_from_camera[..., :3, :3]
    identity = torch.eye(3, dtype=torch.float32).expand(
        BATCH_SIZE,
        HISTORY_FRAME_COUNT,
        3,
        3,
    )
    gram = rotation.transpose(-1, -2) @ rotation
    determinant = torch.linalg.det(rotation)
    if not bool(
        rotation.abs().le(1.0 + MATERIALIZER_CAMERA_ROTATION_TOLERANCE).all()
        and torch.allclose(
            gram,
            identity,
            rtol=0.0,
            atol=MATERIALIZER_CAMERA_ROTATION_TOLERANCE,
        )
        and torch.allclose(
            determinant,
            torch.ones_like(determinant),
            rtol=0.0,
            atol=MATERIALIZER_CAMERA_ROTATION_TOLERANCE,
        )
    ):
        raise ValueError("world-from-camera rotation calibration differs")
    translation = world_from_camera[..., :3, 3]
    horizontal_radius = torch.linalg.vector_norm(translation[..., (0, 2)], dim=-1)
    translation_steps = torch.linalg.vector_norm(
        translation[:, 1:] - translation[:, :-1],
        dim=-1,
    )
    relative_rotation = rotation[:, :-1].transpose(-1, -2) @ rotation[:, 1:]
    relative_trace = relative_rotation.diagonal(dim1=-2, dim2=-1).sum(dim=-1)
    angular_steps = torch.acos(((relative_trace - 1.0) * 0.5).clamp(-1.0, 1.0))
    if not bool(
        translation[..., 0]
        .abs()
        .le(MATERIALIZER_CAMERA_ORBIT_RADIUS_METERS + MATERIALIZER_CAMERA_POSITION_TOLERANCE)
        .all()
        and translation[..., 2]
        .abs()
        .le(MATERIALIZER_CAMERA_ORBIT_RADIUS_METERS + MATERIALIZER_CAMERA_POSITION_TOLERANCE)
        .all()
        and translation[..., 1]
        .sub(MATERIALIZER_CAMERA_HEIGHT_METERS)
        .abs()
        .le(MATERIALIZER_CAMERA_POSITION_TOLERANCE)
        .all()
        and horizontal_radius.sub(MATERIALIZER_CAMERA_ORBIT_RADIUS_METERS)
        .abs()
        .le(MATERIALIZER_CAMERA_POSITION_TOLERANCE)
        .all()
        and translation_steps.ge(MATERIALIZER_CAMERA_TRANSLATION_STEP_METERS[0]).all()
        and translation_steps.le(MATERIALIZER_CAMERA_TRANSLATION_STEP_METERS[1]).all()
        and angular_steps.ge(MATERIALIZER_CAMERA_ANGULAR_STEP_RADIANS[0]).all()
        and angular_steps.le(MATERIALIZER_CAMERA_ANGULAR_STEP_RADIANS[1]).all()
    ):
        raise ValueError("world-from-camera frozen orbital calibration bounds differ")
    intrinsics = validated["intrinsics"]
    expected_intrinsics = torch.tensor(
        MATERIALIZER_CAMERA_INTRINSICS,
        dtype=torch.float32,
    ).expand(BATCH_SIZE, HISTORY_FRAME_COUNT, 3, 3)
    if not torch.equal(intrinsics, expected_intrinsics):
        raise ValueError("camera intrinsics calibration differs")
    _materializer_tensor_storage_inventory(validated, label="public sensors")
    return validated


def _validated_safe_task_batch_tensors(value: Any) -> dict[str, Any]:
    _require_exact_ordered_string_keys(
        value,
        SAFE_TASK_TENSOR_KEYS,
        label="safe task tensor",
    )
    expected = {
        "observable_handle_prototype": ((BATCH_SIZE, 3), torch.float32),
        "candidate_timestamps": ((BATCH_SIZE, CANDIDATE_COUNT), torch.float32),
        "candidate_impulses_world": (
            (BATCH_SIZE, CANDIDATE_COUNT, 3),
            torch.float32,
        ),
        "goal_positions_world": ((BATCH_SIZE, 3), torch.float32),
        "opposite_goal_positions_world": ((BATCH_SIZE, 3), torch.float32),
        "alternate_handle_prototype": ((BATCH_SIZE, 3), torch.float32),
    }
    validated = {
        name: _require_exact_materializer_tensor(
            value[name],
            shape=shape,
            dtype=dtype,
            label=f"safe task {name}",
        )
        for name, (shape, dtype) in expected.items()
    }
    candidate_timestamps = validated["candidate_timestamps"]
    if not bool(
        candidate_timestamps.gt(0.0).all()
        and candidate_timestamps.eq(candidate_timestamps[:, :1]).all()
        and candidate_timestamps.le(MATERIALIZER_FIXED_GOAL_HORIZON_SECONDS).all()
    ):
        raise ValueError("each candidate row must share one positive timestamp within 2.0 seconds")
    for name in ("observable_handle_prototype", "alternate_handle_prototype"):
        if not bool(
            torch.linalg.vector_norm(validated[name], dim=-1).gt(0.0).all()
            and validated[name].ge(0.0).all()
            and validated[name].le(1.0).all()
        ):
            raise ValueError(f"safe task {name} must be one nonzero [0, 1] prototype")
    if bool(
        validated["observable_handle_prototype"]
        .eq(validated["alternate_handle_prototype"])
        .all(dim=-1)
        .any()
    ):
        raise ValueError("alternate public handle prototype must differ")
    if bool(
        validated["goal_positions_world"]
        .eq(validated["opposite_goal_positions_world"])
        .all(dim=-1)
        .any()
    ):
        raise ValueError("opposite public goal must differ")
    for name in ("goal_positions_world", "opposite_goal_positions_world"):
        goals = validated[name]
        if not all(
            bool(goals[:, axis].ge(lower).all() and goals[:, axis].le(upper).all())
            for axis, (lower, upper) in enumerate(MATERIALIZER_GOAL_POSITION_BOUNDS)
        ):
            raise ValueError(f"safe task {name} lies outside frozen scene bounds")
    impulses = validated["candidate_impulses_world"]
    sign_matches = impulses[:, :, None, :].eq(-impulses[:, None, :, :]).all(dim=-1)
    if (
        CANDIDATE_COUNT != 8
        or not bool(impulses.ne(0.0).any(dim=-1).all())
        or not bool(impulses.abs().le(0.0065).all())
        or not bool(sign_matches.sum(dim=-1).eq(1).all())
    ):
        raise ValueError("candidate impulses must form four exact nonzero sign pairs")
    _materializer_tensor_storage_inventory(validated, label="safe tasks")
    return validated


def _expected_materializer_action_rows(
    *,
    split: Split,
    ordinals: tuple[int, int, int, int],
) -> tuple[torch.Tensor, torch.Tensor]:
    if (
        type(split) is not str
        or split not in SPLITS
        or type(ordinals) is not tuple
        or len(ordinals) != BATCH_SIZE
        or any(type(ordinal) is not int or ordinal not in ORDINALS for ordinal in ordinals)
    ):
        raise ValueError("materializer action-row address differs")
    row_permutation = dict(MATERIALIZER_ACTION_ROW_PERMUTATIONS)[split]
    timestamps: list[list[float]] = []
    impulses: list[list[list[float]]] = []
    for ordinal in ordinals:
        primitive_index = ordinal // 16
        scene_index = ordinal % 8
        row_binding = row_permutation[primitive_index]
        timestamps.append([float(21 + primitive_index) / 20.0] * CANDIDATE_COUNT)
        magnitude_x = float(21 + row_binding) / 4000.0
        magnitude_y = float(19 + primitive_index) / 4000.0
        magnitude_z = float(23 + ((primitive_index + row_binding) % 4)) / 4000.0
        row: list[list[float]] = []
        for display_index in range(CANDIDATE_COUNT):
            canonical_index = (display_index + 2 * scene_index) % CANDIDATE_COUNT
            row.append(
                [
                    magnitude_x if canonical_index & 1 else -magnitude_x,
                    magnitude_y if canonical_index & 2 else -magnitude_y,
                    magnitude_z if canonical_index & 4 else -magnitude_z,
                ]
            )
        impulses.append(row)
    return (
        torch.tensor(timestamps, dtype=torch.float32),
        torch.tensor(impulses, dtype=torch.float32),
    )


def _validate_exact_materializer_safe_rows(
    value: Mapping[str, Any],
    *,
    split: Split,
    ordinals: tuple[int, int, int, int],
) -> None:
    expected_timestamps, expected_impulses = _expected_materializer_action_rows(
        split=split,
        ordinals=ordinals,
    )
    palette = torch.tensor(
        MATERIALIZER_HANDLE_PROTOTYPE_PALETTE,
        dtype=torch.float32,
    )
    handle_rows = torch.tensor(
        [(ordinal % 16) // 8 for ordinal in ordinals],
        dtype=torch.int64,
    )
    if (
        not torch.equal(value["candidate_timestamps"], expected_timestamps)
        or not torch.equal(value["candidate_impulses_world"], expected_impulses)
        or not torch.equal(value["observable_handle_prototype"], palette[handle_rows])
        or not torch.equal(
            value["alternate_handle_prototype"],
            palette[1 - handle_rows],
        )
    ):
        raise ValueError("safe task rows differ from the frozen ordinal formulas")


def _validated_public_runtime_tensors(value: Any) -> dict[str, Any]:
    _require_exact_ordered_string_keys(
        value,
        PUBLIC_RUNTIME_TENSOR_KEYS,
        label="public runtime tensor",
    )
    horizon_count = len(HORIZONS_SECONDS)
    expected = {
        "resolved_persistent_id": ((BATCH_SIZE,), torch.int64),
        "persistent_id_by_slot": ((BATCH_SIZE, 2), torch.int64),
        "candidate_positions": (
            (BATCH_SIZE, CANDIDATE_COUNT, horizon_count, 2, 3),
            torch.float32,
        ),
        "candidate_velocities": (
            (BATCH_SIZE, CANDIDATE_COUNT, horizon_count, 2, 3),
            torch.float32,
        ),
        "candidate_total_cost": ((BATCH_SIZE, CANDIDATE_COUNT), torch.float32),
        "selected_display_index": ((BATCH_SIZE,), torch.int64),
        "none_positions": ((BATCH_SIZE, horizon_count, 2, 3), torch.float32),
        "none_velocities": ((BATCH_SIZE, horizon_count, 2, 3), torch.float32),
    }
    validated = {
        name: _require_exact_materializer_tensor(
            value[name],
            shape=shape,
            dtype=dtype,
            label=f"public runtime {name}",
        )
        for name, (shape, dtype) in expected.items()
    }
    resolved = validated["resolved_persistent_id"]
    slots = validated["persistent_id_by_slot"]
    selected = validated["selected_display_index"]
    if (
        not bool(resolved.ge(0).all() and slots.ge(0).all())
        or not bool(slots[:, 0].ne(slots[:, 1]).all())
        or not bool(slots.eq(resolved[:, None]).sum(dim=-1).eq(1).all())
        or not bool(selected.ge(0).all() and selected.lt(CANDIDATE_COUNT).all())
        or not bool(validated["candidate_total_cost"].ge(0.0).all())
        or not torch.equal(selected, validated["candidate_total_cost"].argmin(dim=-1))
    ):
        raise ValueError("public runtime persistent-ID/planner output binding differs")
    _materializer_tensor_storage_inventory(validated, label="public runtime")
    return validated


def _materializer_row_tensor_sha256(
    value: Mapping[str, Any],
    *,
    row_index: int,
    namespace: str,
    keys: Sequence[str],
) -> str:
    if type(row_index) is not int or not 0 <= row_index < BATCH_SIZE:
        raise ValueError("materializer row index differs")
    return _tensor_group_sha256([(f"{namespace}/{name}", value[name][row_index]) for name in keys])


def _materializer_port_public_sha256(port: _TrustedMaterializerPort) -> str:
    if type(port) is not _TrustedMaterializerPort:
        raise PermissionError("public materializer port binding is forged")
    return canonical_sha256(
        {
            "schema": "rgbd_known_action_materializer_port_public_binding_v1",
            "stage": port.stage,
            "ledger_path": os.fspath(port.ledger_path),
            "ledger_generation": port.ledger_generation,
            "ledger_record_sha256": port.ledger_record_sha256,
            "config_sha256": port.config_sha256,
        }
    )


def _validated_public_materialization_surface(value: Any) -> dict[str, Any]:
    _require_exact_keys(
        value,
        PUBLIC_MATERIALIZATION_SURFACE_SCHEMA,
        label="public materialization surface",
    )
    if (
        type(value["schema"]) is not str
        or type(value["split"]) is not str
        or type(value["ordinal"]) is not int
        or type(value["batch_index"]) is not int
        or type(value["fixed_goal_horizon_seconds"]) is not float
    ):
        raise ValueError("public materialization surface scalar types differ")
    if (
        value["schema"] != "rgbd_known_action_public_materialization_surface_v1"
        or value["split"] not in SPLITS
        or not 0 <= value["ordinal"] < SCENES_PER_SPLIT
        or value["batch_index"] != value["ordinal"] // BATCH_SIZE
        or value["fixed_goal_horizon_seconds"] != MATERIALIZER_FIXED_GOAL_HORIZON_SECONDS
    ):
        raise ValueError("public materialization surface scalar binding differs")
    for name in (
        "materializer_port_sha256",
        "token_receipt_sha256",
        "sensor_sha256",
        "safe_task_sha256",
        "public_runtime_sha256",
    ):
        validated_sha256(value[name], label=f"public materialization {name}")
    native = _json_native(copy.deepcopy(value), label="public materialization surface")
    assert type(native) is dict
    return native


def _blinded_materialization_commitment(
    public_surface: Mapping[str, Any],
    nonce: bytes,
) -> str:
    if type(nonce) is not bytes or len(nonce) != 32:
        raise ValueError("materialization blinding nonce must be exactly 32 bytes")
    validated = _validated_public_materialization_surface(public_surface)
    body = _canonical_json(validated)
    digest = hashlib.sha256()
    digest.update(MATERIALIZER_BLINDED_COMMITMENT_DOMAIN)
    digest.update(len(body).to_bytes(8, "little"))
    digest.update(body)
    digest.update(len(nonce).to_bytes(8, "little"))
    digest.update(nonce)
    return digest.hexdigest()


def _validated_public_materializer_evaluation_hashes(value: Any) -> dict[str, Any]:
    _require_exact_keys(
        value,
        PUBLIC_MATERIALIZER_EVALUATION_HASH_SCHEMA,
        label="public materializer evaluation hashes",
    )
    if type(value["schema"]) is not str:
        raise TypeError("public materializer evaluation hash schema must be a string")
    if value["schema"] != "rgbd_known_action_public_materializer_evaluation_hashes_v1":
        raise ValueError("public materializer evaluation hash schema differs")
    for name in (
        "public_evaluation_sha256",
        "public_evidence_sha256",
        "public_metrics_sha256",
        "public_resources_sha256",
    ):
        validated_sha256(value[name], label=f"public materializer {name}")
    native = _json_native(copy.deepcopy(value), label="public materializer evaluation hashes")
    assert type(native) is dict
    return native


def _public_materializer_evaluation_hashes(
    evaluation: Mapping[str, Any],
    *,
    split: str,
    ordinals: tuple[int, int, int, int],
) -> dict[str, Any]:
    if type(evaluation) is not dict:
        raise TypeError("public materializer evaluation must be one exact dictionary")
    validated = _validated_public_batch_evaluation(
        evaluation,
        split=split,
        ordinals=ordinals,
    )
    return _validated_public_materializer_evaluation_hashes(
        {
            "schema": "rgbd_known_action_public_materializer_evaluation_hashes_v1",
            "public_evaluation_sha256": canonical_sha256(validated),
            "public_evidence_sha256": canonical_sha256(validated["public_evidence"]),
            "public_metrics_sha256": canonical_sha256(validated["public_metrics"]),
            "public_resources_sha256": canonical_sha256(validated["public_resources"]),
        }
    )


def _validate_safe_task_tensors(value: Any, *, batch_size: int = BATCH_SIZE) -> None:
    if type(value) is not dict:
        raise TypeError("safe task collation must return one exact dict")
    expected = {
        "observable_handle_role": ((batch_size,), torch.int64),
        "observable_handle_prototype": ((batch_size, 3), torch.float32),
        "candidate_timestamps": ((batch_size, CANDIDATE_COUNT), torch.float32),
        "candidate_impulses_world": ((batch_size, CANDIDATE_COUNT, 3), torch.float32),
        "goal_positions_world": ((batch_size, 3), torch.float32),
        "goal_horizons": ((batch_size,), torch.float32),
    }
    if set(value) != set(expected):
        raise ValueError("safe task tensor schema differs")
    for name, (shape, dtype) in expected.items():
        tensor = value[name]
        if (
            not isinstance(tensor, torch.Tensor)
            or tensor.shape != shape
            or tensor.dtype != dtype
            or tensor.device.type != "cpu"
            or not bool(torch.isfinite(tensor).all())
        ):
            raise ValueError(f"safe task tensor {name} shape/dtype/device/value differs")
    if not bool(value["goal_horizons"].eq(HORIZONS_SECONDS[-1]).all()):
        raise ValueError("safe task goal horizon differs")


def _materialize_actions(
    *,
    safe: Mapping[str, torch.Tensor],
    object_id: torch.Tensor,
    belief: Any,
) -> tuple[Any, ...]:
    """Build heterogeneous B=4 actions only from safe tensors and resolved IDs."""

    actions_module = importlib.import_module("world_model.dynamics.actions")
    if object_id.shape != (BATCH_SIZE,) or object_id.dtype != torch.int64:
        raise ValueError("resolved action IDs must be int64 [4]")
    actions = tuple(
        actions_module.WorldImpulseAction(
            timestamp=safe["candidate_timestamps"][:, display]
            .to(device=belief.device, dtype=belief.dtype)
            .clone(),
            object_id=object_id.to(device=belief.device).clone(),
            impulse_world=safe["candidate_impulses_world"][:, display]
            .to(device=belief.device, dtype=belief.dtype)
            .clone(),
        )
        for display in range(CANDIDATE_COUNT)
    )
    if any(action.impulse_world.shape != (BATCH_SIZE, 3) for action in actions):
        raise RuntimeError("heterogeneous action construction collapsed a batch dimension")
    return actions


def _physical_by_slot(
    output: Mapping[str, Any], batch: Mapping[str, Any], owner: Any
) -> torch.Tensor:
    mapping, _ = owner._birth_physical_mapping(
        output["observed_positions"][:, 0],
        batch["objects"]["position"][:, 0, :2],
    )
    if mapping.shape != (BATCH_SIZE, 2) or mapping.dtype != torch.int64:
        raise RuntimeError("public birth mapping audit is malformed")
    return mapping


def _gather_truth_by_slot(value: torch.Tensor, physical_by_slot: torch.Tensor) -> torch.Tensor:
    if value.shape[0] != physical_by_slot.shape[0] or value.shape[-2:] != (2, 3):
        raise ValueError("truth gather requires [B,...,2,3] and [B,2]")
    shape = (value.shape[0],) + (1,) * (value.ndim - 3) + (2, 1)
    index = physical_by_slot.reshape(shape).expand(*value.shape[:-2], 2, 3)
    return torch.gather(value, dim=-2, index=index)


def _slot_values_by_physical(value: torch.Tensor, physical_by_slot: torch.Tensor) -> torch.Tensor:
    physical_to_slot = physical_by_slot.argsort(dim=-1)
    shape = (value.shape[0],) + (1,) * (value.ndim - 3) + (2, 1)
    index = physical_to_slot.reshape(shape).expand(*value.shape[:-2], 2, 3)
    return torch.gather(value, dim=-2, index=index)


def _exact_tensor_mismatch_count(left: torch.Tensor, right: torch.Tensor) -> int:
    if left.shape != right.shape or left.dtype != right.dtype or left.device != right.device:
        return max(left.numel(), right.numel(), 1)
    return int(left.ne(right).sum().detach().cpu())


def _tensor_leaf_map(value: Any, *, label: str) -> dict[str, torch.Tensor]:
    """Return the exact tensor leaves of a small belief/trajectory value."""

    leaves: dict[str, torch.Tensor] = {}
    active: set[int] = set()

    def visit(item: Any, path: str) -> None:
        if isinstance(item, torch.Tensor):
            if path in leaves:
                raise ValueError(f"{label} has a duplicate tensor path")
            leaves[path] = item
            return
        if isinstance(item, Mapping):
            identity = id(item)
            if identity in active:
                raise ValueError(f"{label} contains a recursive mapping")
            active.add(identity)
            try:
                for key in sorted(item):
                    if type(key) is not str:
                        raise TypeError(f"{label} mapping keys must be exact strings")
                    visit(item[key], f"{path}.{key}" if path else key)
            finally:
                active.remove(identity)
            return
        if isinstance(item, (tuple, list)):
            identity = id(item)
            if identity in active:
                raise ValueError(f"{label} contains a recursive sequence")
            active.add(identity)
            try:
                for index, child in enumerate(item):
                    visit(child, f"{path}[{index}]")
            finally:
                active.remove(identity)
            return
        fields = getattr(item, "__dataclass_fields__", None)
        if type(fields) is dict:
            identity = id(item)
            if identity in active:
                raise ValueError(f"{label} contains a recursive dataclass")
            active.add(identity)
            try:
                for name in fields:
                    visit(getattr(item, name), f"{path}.{name}" if path else name)
            finally:
                active.remove(identity)

    visit(value, "")
    if not leaves:
        raise ValueError(f"{label} contains no tensor leaves")
    return leaves


def _tensor_structure_mismatch_count(left: Any, right: Any, *, label: str) -> int:
    """Count exact tensor element mismatches across one shared structure."""

    left_leaves = _tensor_leaf_map(left, label=f"{label} left")
    right_leaves = _tensor_leaf_map(right, label=f"{label} right")
    if set(left_leaves) != set(right_leaves):
        return max(len(set(left_leaves) ^ set(right_leaves)), 1)
    return sum(
        _exact_tensor_mismatch_count(left_leaves[name], right_leaves[name])
        for name in sorted(left_leaves)
    )


def _tensor_structure_storage_alias_count(left: Any, right: Any, *, label: str) -> int:
    """Count overlapping byte ranges in shared nonempty tensor storages."""

    left_leaves = _tensor_leaf_map(left, label=f"{label} left")
    right_leaves = _tensor_leaf_map(right, label=f"{label} right")

    def byte_range(tensor: torch.Tensor) -> tuple[int, int, int] | None:
        if not tensor.numel():
            return None
        minimum = tensor.storage_offset()
        maximum = minimum
        for size, stride in zip(tensor.shape, tensor.stride(), strict=True):
            extent = (size - 1) * stride
            minimum += min(0, extent)
            maximum += max(0, extent)
        item_size = tensor.element_size()
        return (
            tensor.untyped_storage().data_ptr(),
            minimum * item_size,
            (maximum + 1) * item_size,
        )

    left_ranges = [byte_range(tensor) for tensor in left_leaves.values()]
    right_ranges = [byte_range(tensor) for tensor in right_leaves.values()]
    return sum(
        left_range[0] == right_range[0]
        and max(left_range[1], right_range[1]) < min(left_range[2], right_range[2])
        for left_range in left_ranges
        for right_range in right_ranges
        if left_range is not None and right_range is not None
    )


ORDINAL_CAPABILITY_RECEIPT_SCHEMA = frozenset(
    {
        "schema",
        "split",
        "ordinal",
        "batch_index",
        "reservation_generation",
        "reservation_sha256",
        "capability_nonce",
        "receipt_sha256",
    }
)
NUMERIC_ROW_EVIDENCE_SCHEMA = frozenset(
    {
        "schema",
        "split",
        "ordinal",
        "row_index",
        "token_receipt",
        "scene_row_sha256",
        "packet_prefix_numeric_sha256",
        "safe_task_numeric_sha256",
        "public_runtime_numeric_sha256",
        "control_numeric_sha256",
        "receipt_sha256",
    }
)
NUMERIC_BATCH_EVIDENCE_SCHEMA = frozenset(
    {
        "schema",
        "split",
        "ordinals",
        "batch_index",
        "tensor_digest_recipe",
        "row_receipts",
        "ordered_row_receipts_sha256",
        "restricted_rows_exposed",
    }
)


def _validated_capability_nonce(value: Any, *, label: str) -> str:
    if (
        type(value) is not str
        or len(value) != 64
        or any(character not in "0123456789abcdef" for character in value)
    ):
        raise ValueError(f"{label} must be exact lowercase ASCII hexadecimal")
    return value


def _validated_capability_nonce_quad(
    value: Any,
    *,
    label: str,
) -> tuple[str, str, str, str]:
    if type(value) is not tuple or len(value) != BATCH_SIZE:
        raise TypeError(f"{label} must be one exact four-entry tuple")
    validated = tuple(
        _validated_capability_nonce(item, label=f"{label} entry {index}")
        for index, item in enumerate(value)
    )
    if len(set(validated)) != BATCH_SIZE:
        raise ValueError(f"{label} must contain four distinct nonces")
    return validated  # type: ignore[return-value]


def _validated_token_receipt(value: Any, *, split: str, ordinal: int) -> dict[str, Any]:
    _require_exact_keys(value, ORDINAL_CAPABILITY_RECEIPT_SCHEMA, label="ordinal token receipt")
    if (
        value["schema"] != "rgbd_known_action_ordinal_capability_receipt_v1"
        or value["split"] != split
        or type(value["ordinal"]) is not int
        or value["ordinal"] != ordinal
        or type(value["batch_index"]) is not int
        or value["batch_index"] != ordinal // BATCH_SIZE
        or type(value["reservation_generation"]) is not int
        or value["reservation_generation"] < 1
    ):
        raise ValueError("ordinal token receipt address/generation/nonce differs")
    validated_sha256(value["reservation_sha256"], label="ordinal reservation")
    _validated_capability_nonce(
        value["capability_nonce"],
        label="ordinal capability nonce",
    )
    body = dict(value)
    supplied = body.pop("receipt_sha256")
    if validated_sha256(supplied, label="ordinal receipt") != canonical_sha256(body):
        raise ValueError("ordinal token receipt self-hash differs")
    return copy.deepcopy(dict(value))


def _numeric_row_evidence(
    *,
    split: str,
    ordinal: int,
    row_index: int,
    token_receipt: Mapping[str, Any],
    scene_row: Mapping[str, Any],
    episode: Mapping[str, Any],
    safe: Mapping[str, torch.Tensor],
    output: Mapping[str, Any],
    plan: Any,
    rho_plan: Any,
    opposite_plan: Any,
    wrong_plan: Any,
    palette_plan: Any,
) -> dict[str, Any]:
    token = _validated_token_receipt(token_receipt, split=split, ordinal=ordinal)
    history = slice(0, HISTORY_FRAME_COUNT)
    packet_digest = _tensor_group_sha256(
        (
            ("rgb", episode["rgb"][history]),
            ("depth", episode["depth"][history]),
            ("timestamps", episode["timestamps"][history]),
            ("world_from_camera", episode["camera"]["world_from_camera"][history]),
            ("intrinsics", episode["camera"]["intrinsics"][history]),
        )
    )
    task_digest = _tensor_group_sha256(
        tuple((name, value[row_index]) for name, value in sorted(safe.items()))
    )
    belief = output["belief"]
    public_values: list[tuple[str, torch.Tensor]] = [
        ("anchor_object_id", belief.objects.object_id[row_index]),
        ("anchor_position", belief.objects.position[row_index]),
        ("anchor_velocity", belief.objects.velocity[row_index]),
        ("anchor_appearance", belief.objects.appearance[row_index]),
        ("plan_cost", plan.total_cost[row_index]),
        ("plan_choice", plan.selected_index[row_index : row_index + 1]),
        ("plan_object_id_by_slot", plan.object_id_by_slot[row_index]),
    ]
    for candidate, trajectory in enumerate(plan.trajectories):
        public_values.extend(
            (
                (f"candidate_{candidate}/timestamps", trajectory.timestamps[row_index]),
                (f"candidate_{candidate}/positions", trajectory.positions[row_index]),
                (f"candidate_{candidate}/velocities", trajectory.velocities[row_index]),
                (
                    f"candidate_{candidate}/fast_log_variance",
                    trajectory.fast_log_variance[row_index],
                ),
                (f"candidate_{candidate}/active", trajectory.active_mask[row_index]),
                (f"candidate_{candidate}/event_logits", trajectory.event_logits[row_index]),
                (
                    f"candidate_{candidate}/known_action_applied",
                    trajectory.auxiliary["known_action_applied"][row_index],
                ),
                (
                    f"candidate_{candidate}/known_impulse_world",
                    trajectory.auxiliary["known_impulse_world"][row_index],
                ),
            )
        )
    public_digest = _tensor_group_sha256(tuple(public_values))
    control_digest = _tensor_group_sha256(
        (
            ("rho_cost", rho_plan.total_cost[row_index]),
            ("rho_choice", rho_plan.selected_index[row_index : row_index + 1]),
            ("opposite_cost", opposite_plan.total_cost[row_index]),
            (
                "opposite_choice",
                opposite_plan.selected_index[row_index : row_index + 1],
            ),
            ("wrong_handle_cost", wrong_plan.total_cost[row_index]),
            (
                "wrong_handle_choice",
                wrong_plan.selected_index[row_index : row_index + 1],
            ),
            ("palette_cost", palette_plan.total_cost[row_index]),
            (
                "palette_choice",
                palette_plan.selected_index[row_index : row_index + 1],
            ),
        )
    )
    body = {
        "schema": "rgbd_known_action_public_numeric_row_evidence_v2",
        "split": split,
        "ordinal": ordinal,
        "row_index": row_index,
        "token_receipt": token,
        "scene_row_sha256": canonical_sha256(scene_row),
        "packet_prefix_numeric_sha256": packet_digest,
        "safe_task_numeric_sha256": task_digest,
        "public_runtime_numeric_sha256": public_digest,
        "control_numeric_sha256": control_digest,
    }
    return {**body, "receipt_sha256": canonical_sha256(body)}


def _validated_numeric_batch_evidence(
    value: Any,
    *,
    split: str,
    ordinals: tuple[int, int, int, int],
) -> dict[str, Any]:
    _require_exact_keys(value, NUMERIC_BATCH_EVIDENCE_SCHEMA, label="numeric batch evidence")
    if (
        value["schema"] != "rgbd_known_action_public_numeric_batch_evidence_v2"
        or value["split"] != split
        or type(value["ordinals"]) is not list
        or any(type(item) is not int for item in value["ordinals"])
        or value["ordinals"] != list(ordinals)
        or type(value["batch_index"]) is not int
        or value["batch_index"] != ordinals[0] // BATCH_SIZE
        or value["tensor_digest_recipe"] != "length_framed_little_endian_dtype_shape_C_order_v1"
        or value["restricted_rows_exposed"] is not False
        or type(value["row_receipts"]) is not list
        or len(value["row_receipts"]) != BATCH_SIZE
    ):
        raise ValueError("numeric batch evidence address/schema differs")
    rows: list[dict[str, Any]] = []
    reservation_pairs: set[tuple[int, str]] = set()
    nonces: set[str] = set()
    for row_index, (ordinal, row) in enumerate(zip(ordinals, value["row_receipts"], strict=True)):
        _require_exact_keys(row, NUMERIC_ROW_EVIDENCE_SCHEMA, label="numeric row evidence")
        if (
            row["schema"] != "rgbd_known_action_public_numeric_row_evidence_v2"
            or row["split"] != split
            or type(row["ordinal"]) is not int
            or row["ordinal"] != ordinal
            or type(row["row_index"]) is not int
            or row["row_index"] != row_index
        ):
            raise ValueError("numeric row evidence address differs")
        for name in (
            "scene_row_sha256",
            "packet_prefix_numeric_sha256",
            "safe_task_numeric_sha256",
            "public_runtime_numeric_sha256",
            "control_numeric_sha256",
        ):
            validated_sha256(row[name], label=f"numeric row {name}")
        token = _validated_token_receipt(row["token_receipt"], split=split, ordinal=ordinal)
        reservation_pairs.add((token["reservation_generation"], token["reservation_sha256"]))
        if token["capability_nonce"] in nonces:
            raise ValueError("B=4 token receipt nonces must be distinct")
        nonces.add(token["capability_nonce"])
        body = dict(row)
        supplied = body.pop("receipt_sha256")
        if validated_sha256(supplied, label="numeric row receipt") != canonical_sha256(body):
            raise ValueError("numeric row evidence self-hash differs")
        rows.append(copy.deepcopy(dict(row)))
    if len(reservation_pairs) != 1:
        raise ValueError("B=4 token receipts do not share one durable reservation generation")
    if value["ordered_row_receipts_sha256"] != canonical_sha256(
        [row["receipt_sha256"] for row in rows]
    ):
        raise ValueError("numeric batch ordered row receipt hash differs")
    native = _json_native(copy.deepcopy(value), label="numeric batch evidence")
    assert type(native) is dict
    return native


def _replay_validated_ledger_nonce_prefix(
    parsed: Any,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Replay one exact durable ledger prefix and return ordered nonce provenance."""

    expected_schema = (
        LEDGER_ERROR_SCHEMA
        if type(parsed) is dict and parsed.get("status") == "terminal_error"
        else LEDGER_BASE_SCHEMA
    )
    _require_exact_keys(parsed, expected_schema, label="nonce-prefix ledger")
    expected_order = (
        ["development"]
        if parsed["stage"] == "development"
        else list(PROTECTED_SPLITS)
        if parsed["stage"] == "qualification"
        else None
    )
    if (
        expected_order is None
        or parsed["order"] != expected_order
        or type(parsed["order"]) is not list
        or any(type(split) is not str for split in parsed["order"])
        or parsed["execution_mode"] not in {"formal", "fake_test"}
        or type(parsed["bindings"]) is not dict
        or type(parsed["batch_size"]) is not int
        or parsed["batch_size"] != BATCH_SIZE
        or type(parsed["scenes_per_split"]) is not int
        or parsed["scenes_per_split"] != SCENES_PER_SPLIT
        or parsed["attempt_reserved"] is not True
        or type(parsed["generation"]) is not int
        or parsed["generation"] < 0
        or type(parsed["splits"]) is not dict
        or set(parsed["splits"]) != set(expected_order)
    ):
        raise ValueError("nonce-prefix ledger root binding differs")
    order = list(expected_order)
    simulated: dict[str, Any] = {
        "schema": "rgbd_known_action_access_ledger_v2",
        "artifact_kind": "rgbd_known_action_exactly_once_access_ledger",
        "architecture_attempt": ARCHITECTURE_ATTEMPT,
        "stage": parsed["stage"],
        "execution_mode": parsed["execution_mode"],
        "order": order,
        "bindings": copy.deepcopy(parsed["bindings"]),
        "batch_size": BATCH_SIZE,
        "scenes_per_split": SCENES_PER_SPLIT,
        "splits": {split: _empty_split_state() for split in order},
        "attempt_reserved": True,
        "status": "reserved",
        "generation": 0,
        "publication": _empty_publication_state(),
    }

    def transition(candidate: dict[str, Any]) -> None:
        nonlocal simulated
        candidate = copy.deepcopy(candidate)
        candidate["generation"] = simulated["generation"] + 1
        simulated = candidate

    provenance: list[dict[str, Any]] = []
    seen_nonces: dict[str, dict[str, Any]] = {}
    seen_unopened = False
    for split in order:
        target = parsed["splits"][split]
        _require_exact_keys(target, LEDGER_SPLIT_STATE_SCHEMA, label=f"nonce-prefix split {split}")
        if type(target["public_batch_receipts"]) is not list:
            raise TypeError("nonce-prefix public batch receipts must be one exact list")
        if target["status"] == "unopened":
            seen_unopened = True
            _exact_equal(target, _empty_split_state(), label=f"nonce-prefix unopened {split}")
            _exact_equal(
                simulated["splits"][split],
                target,
                label=f"replayed ledger split {split}",
            )
            continue
        if seen_unopened or target["status"] not in {
            "public_evaluating",
            "public_complete",
            "truth_evaluating",
            "passed",
            "failed",
        }:
            raise ValueError("nonce-prefix ledger opens a non-prefix or invalid split")
        candidate = copy.deepcopy(simulated)
        candidate["splits"][split]["status"] = "public_evaluating"
        candidate["splits"][split]["public_access_started"] = True
        candidate["status"] = f"{split}_public_access_started"
        transition(candidate)
        for batch_index, receipt in enumerate(target["public_batch_receipts"]):
            ordinals = tuple(range(batch_index * BATCH_SIZE, (batch_index + 1) * BATCH_SIZE))
            validated_receipt = _validate_batch_receipt(
                receipt,
                split=split,
                batch_index=batch_index,
            )
            _exact_equal(
                validated_receipt,
                receipt,
                label=f"nonce-prefix {split} batch {batch_index} receipt",
            )
            candidate = copy.deepcopy(simulated)
            candidate["splits"][split]["public_active_batch"] = list(ordinals)
            candidate["status"] = f"{split}_public_batch_{batch_index}_reserved"
            transition(candidate)
            reservation_generation = simulated["generation"]
            reservation_sha256 = canonical_sha256(simulated)
            evidence = validated_receipt["public_evidence"]
            for ordinal, row in zip(ordinals, evidence["row_receipts"], strict=True):
                token = row["token_receipt"]
                if (
                    token["reservation_generation"] != reservation_generation
                    or token["reservation_sha256"] != reservation_sha256
                ):
                    raise ValueError(
                        "ordinal token receipt differs from its replayed durable reservation"
                    )
                nonce = _validated_capability_nonce(
                    token["capability_nonce"],
                    label="replayed ordinal capability nonce",
                )
                entry = {
                    "split": split,
                    "batch_index": batch_index,
                    "ordinal": ordinal,
                    "capability_nonce": nonce,
                }
                _require_exact_keys(
                    entry,
                    CAPABILITY_NONCE_PROVENANCE_SCHEMA,
                    label="capability nonce provenance",
                )
                if nonce in seen_nonces:
                    raise ValueError(
                        "ordinal capability nonce was reused across the ledger: "
                        f"{seen_nonces[nonce]!r} then {entry!r}"
                    )
                seen_nonces[nonce] = entry
                provenance.append(entry)
            candidate = copy.deepcopy(simulated)
            state = candidate["splits"][split]
            state["public_batch_receipts"].append(copy.deepcopy(validated_receipt))
            state["public_next_ordinal"] += BATCH_SIZE
            state["public_active_batch"] = None
            candidate["status"] = f"{split}_public_batch_{batch_index}_complete"
            transition(candidate)
        if target["public_active_batch"] is not None:
            expected_active = tuple(
                range(
                    len(target["public_batch_receipts"]) * BATCH_SIZE,
                    (len(target["public_batch_receipts"]) + 1) * BATCH_SIZE,
                )
            )
            if (
                type(target["public_active_batch"]) is not list
                or any(type(ordinal) is not int for ordinal in target["public_active_batch"])
                or tuple(target["public_active_batch"]) != expected_active
                or expected_active[-1] >= SCENES_PER_SPLIT
            ):
                raise ValueError("nonce-prefix active batch address differs")
            ordinals = expected_active
            candidate = copy.deepcopy(simulated)
            candidate["splits"][split]["public_active_batch"] = list(ordinals)
            candidate["status"] = f"{split}_public_batch_{ordinals[0] // BATCH_SIZE}_reserved"
            transition(candidate)
        if target["status"] in {"public_complete", "truth_evaluating", "passed", "failed"}:
            if (
                len(target["public_batch_receipts"]) != SCENES_PER_SPLIT // BATCH_SIZE
                or target["public_next_ordinal"] != SCENES_PER_SPLIT
                or target["public_active_batch"] is not None
            ):
                raise ValueError("sealed public split receipt inventory differs")
            summary = _validated_public_split_summary(
                target["public_summary"],
                split=split,
                receipts=target["public_batch_receipts"],
            )
            seal = _validated_public_split_seal(
                target["public_seal"],
                split=split,
                summary=summary,
            )
            if target["public_summary_sha256"] != canonical_sha256(summary) or target[
                "public_seal_sha256"
            ] != canonical_sha256(seal):
                raise ValueError("sealed public split digest differs")
            candidate = copy.deepcopy(simulated)
            state = candidate["splits"][split]
            state["status"] = "public_complete"
            state["public_summary"] = copy.deepcopy(summary)
            state["public_summary_sha256"] = canonical_sha256(summary)
            state["public_seal"] = copy.deepcopy(seal)
            state["public_seal_sha256"] = canonical_sha256(seal)
            candidate["status"] = f"{split}_public_complete"
            transition(candidate)
        if target["status"] in {"truth_evaluating", "passed", "failed"}:
            candidate = copy.deepcopy(simulated)
            candidate["splits"][split]["status"] = "truth_evaluating"
            candidate["status"] = f"{split}_truth_evaluating"
            transition(candidate)
        if target["status"] in {"passed", "failed"}:
            private_receipt = _validated_private_scoring_receipt(
                target["private_scoring_receipt"],
                split=split,
                public_seal_sha256=target["public_seal_sha256"],
            )
            request = private_receipt["truth_request"]
            if request["ledger_generation"] != simulated["generation"] or request[
                "ledger_record_sha256"
            ] != canonical_sha256(simulated):
                raise ValueError("private scoring request differs from replayed truth cut")
            result = _validated_split_result(target["split_result"], split=split)
            if target["private_scoring_receipt_sha256"] != canonical_sha256(
                private_receipt
            ) or target["split_result_sha256"] != canonical_sha256(result):
                raise ValueError("completed split private/result digest differs")
            _exact_equal(
                result["public_summary"],
                target["public_summary"],
                label=f"replayed {split} result/public summary",
            )
            _exact_equal(
                result["public_seal"],
                target["public_seal"],
                label=f"replayed {split} result/public seal",
            )
            _exact_equal(
                result["private_scoring_receipt"],
                private_receipt,
                label=f"replayed {split} private receipt",
            )
            candidate = copy.deepcopy(simulated)
            state = candidate["splits"][split]
            state["status"] = target["status"]
            state["private_scoring_receipt"] = copy.deepcopy(private_receipt)
            state["private_scoring_receipt_sha256"] = canonical_sha256(private_receipt)
            state["split_result"] = copy.deepcopy(result)
            state["split_result_sha256"] = canonical_sha256(result)
            candidate["status"] = f"{split}_{target['status']}"
            transition(candidate)
        _exact_equal(
            simulated["splits"][split],
            target,
            label=f"replayed ledger split {split}",
        )

    expected_provenance = sorted(
        provenance,
        key=lambda entry: (
            order.index(entry["split"]),
            entry["batch_index"],
            entry["ordinal"],
        ),
    )
    if provenance != expected_provenance:
        raise ValueError("capability nonce provenance is not in canonical ledger order")
    return simulated, provenance


def _nonce_provenance_rows_sha256(rows: Any) -> str:
    if type(rows) is not list:
        raise TypeError("capability nonce provenance rows must be one exact list")
    validated: list[dict[str, Any]] = []
    for index, row in enumerate(rows):
        _require_exact_keys(
            row,
            CAPABILITY_NONCE_PROVENANCE_SCHEMA,
            label=f"capability nonce provenance row {index}",
        )
        if (
            type(row["split"]) is not str
            or type(row["batch_index"]) is not int
            or row["batch_index"] < 0
            or type(row["ordinal"]) is not int
            or row["ordinal"] < 0
            or row["batch_index"] != row["ordinal"] // BATCH_SIZE
        ):
            raise ValueError("capability nonce provenance address differs")
        validated.append(
            {
                "split": row["split"],
                "batch_index": row["batch_index"],
                "ordinal": row["ordinal"],
                "capability_nonce": _validated_capability_nonce(
                    row["capability_nonce"],
                    label=f"capability nonce provenance row {index}",
                ),
            }
        )
    return canonical_sha256(
        {
            "schema": "rgbd_known_action_capability_nonce_provenance_rows_v1",
            "rows": validated,
        }
    )


def _validated_reviewed_development_nonce_baseline(value: Any) -> dict[str, Any]:
    _require_exact_keys(
        value,
        REVIEWED_DEVELOPMENT_NONCE_BASELINE_SCHEMA,
        label="reviewed development nonce baseline",
    )
    if (
        value["schema"] != "rgbd_known_action_reviewed_development_nonce_baseline_v1"
        or type(value["count"]) is not int
        or value["count"] != SCENES_PER_SPLIT
    ):
        raise ValueError("reviewed development nonce baseline schema/count differs")
    return {
        "schema": value["schema"],
        "ordered_rows_sha256": validated_sha256(
            value["ordered_rows_sha256"],
            label="reviewed development ordered nonce rows",
        ),
        "count": value["count"],
    }


def _reviewed_development_nonce_baseline(
    directory_pin: _PinnedDirectory,
    *,
    expected_ledger_sha256: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Derive the exact 64-row reviewed-development nonce baseline."""

    _validate_pinned_directory(directory_pin)
    expected_digest = validated_sha256(
        expected_ledger_sha256,
        label="reviewed development ledger for nonce baseline",
    )
    ledger_path = _artifact_paths(directory_pin)["development_ledger"]
    contents = _pinned_read_bytes(
        directory_pin,
        ledger_path,
        label="reviewed development nonce-baseline ledger",
    )
    if sha256_bytes(contents) != expected_digest:
        raise PermissionError("reviewed development nonce-baseline ledger hash differs")
    parsed = _parse_ledger_bytes(contents, label="reviewed development nonce-baseline ledger")
    parsed.pop("record_sha256")
    if (
        parsed.get("stage") != "development"
        or parsed.get("status") != "complete_passed"
        or parsed.get("order") != ["development"]
    ):
        raise ValueError("reviewed development nonce baseline requires one passed ledger")
    _, rows = _replay_validated_ledger_nonce_prefix(parsed)
    expected_addresses = [
        ("development", ordinal // BATCH_SIZE, ordinal) for ordinal in range(SCENES_PER_SPLIT)
    ]
    actual_addresses = [(row["split"], row["batch_index"], row["ordinal"]) for row in rows]
    nonces = [row["capability_nonce"] for row in rows]
    if (
        len(rows) != SCENES_PER_SPLIT
        or actual_addresses != expected_addresses
        or len(set(nonces)) != SCENES_PER_SPLIT
        or any(
            _validated_capability_nonce(nonce, label="reviewed development capability nonce")
            != nonce
            for nonce in nonces
        )
    ):
        raise ValueError("reviewed development nonce baseline is not exact 64-row unique history")
    binding = _validated_reviewed_development_nonce_baseline(
        {
            "schema": "rgbd_known_action_reviewed_development_nonce_baseline_v1",
            "ordered_rows_sha256": _nonce_provenance_rows_sha256(rows),
            "count": len(rows),
        }
    )
    return binding, rows


def _validated_formal_batch_capability_nonces(
    value: Any,
    *,
    ledger: _AccessLedger,
    split: str,
    ordinals: tuple[int, int, int, int],
) -> tuple[tuple[str, str, str, str], str]:
    """Validate one candidate B=4 against the durable attempt-wide history."""

    if type(ledger) is not _AccessLedger:
        raise TypeError("formal capability nonce preflight requires one exact ledger")
    if (
        type(split) is not str
        or type(ordinals) is not tuple
        or len(ordinals) != BATCH_SIZE
        or any(type(ordinal) is not int for ordinal in ordinals)
        or ordinals != tuple(range(ordinals[0], ordinals[0] + BATCH_SIZE))
    ):
        raise TypeError("formal capability nonce preflight address differs")
    candidates = _validated_capability_nonce_quad(
        value,
        label="formal candidate capability nonces",
    )
    ledger._verify_disk()
    record = copy.deepcopy(ledger._record)
    state = record["splits"].get(split)
    if (
        type(state) is not dict
        or state.get("status") != "public_evaluating"
        or type(state.get("public_next_ordinal")) is not int
        or ordinals[0] != state["public_next_ordinal"]
        or state.get("public_active_batch") not in (None, list(ordinals))
        or record["publication"] != _empty_publication_state()
    ):
        raise PermissionError("formal capability nonce preflight lacks the next open batch")
    simulated, current_rows = _replay_validated_ledger_nonce_prefix(record)
    _exact_equal(simulated, record, label="current durable nonce-prefix ledger")
    reviewed_binding: dict[str, Any] | None = None
    reviewed_rows: list[dict[str, Any]] = []
    if ledger.stage == "qualification":
        reviewed_binding = _validated_reviewed_development_nonce_baseline(
            record["bindings"].get("reviewed_development_nonce_baseline")
        )
        recomputed_binding, reviewed_rows = _reviewed_development_nonce_baseline(
            ledger._pin,
            expected_ledger_sha256=record["bindings"]["reviewed_development"]["ledger_sha256"],
        )
        _exact_equal(
            recomputed_binding,
            reviewed_binding,
            label="qualification reviewed nonce baseline",
        )
    elif ledger.stage != "development":
        raise ValueError("formal capability nonce preflight ledger stage differs")
    prior_by_nonce: dict[str, dict[str, Any]] = {}
    for row in [*reviewed_rows, *current_rows]:
        nonce = row["capability_nonce"]
        if nonce in prior_by_nonce:
            raise PermissionError(
                "formal capability nonce was already reused in the durable attempt history"
            )
        prior_by_nonce[nonce] = row
    for ordinal, nonce in zip(ordinals, candidates, strict=True):
        if nonce in prior_by_nonce:
            raise PermissionError(
                "formal capability nonce candidate collides with durable provenance "
                f"{prior_by_nonce[nonce]!r} for {split}/{ordinal}"
            )
    preflight = {
        "schema": "rgbd_known_action_capability_nonce_preflight_v1",
        "stage": ledger.stage,
        "split": split,
        "batch_index": ordinals[0] // BATCH_SIZE,
        "ordinals": list(ordinals),
        "current_rows_count": len(current_rows),
        "current_rows_sha256": _nonce_provenance_rows_sha256(current_rows),
        "reviewed_development_nonce_baseline": reviewed_binding,
        "candidate_nonces": list(candidates),
    }
    return candidates, canonical_sha256(preflight)


def _preflight_formal_batch_capability_nonces(
    ledger: _AccessLedger,
    *,
    split: str,
    ordinals: tuple[int, int, int, int],
) -> tuple[tuple[str, str, str, str], str]:
    """Acquire candidate entropy without mutating the ledger or capabilities."""

    candidates = tuple(_capability_nonce_hex() for _ in range(BATCH_SIZE))
    try:
        return _validated_formal_batch_capability_nonces(
            candidates,
            ledger=ledger,
            split=split,
            ordinals=ordinals,
        )
    except (TypeError, ValueError) as error:
        raise RuntimeError("formal capability nonce source returned malformed entropy") from error


def _validate_ledger_transition_chain(parsed: Mapping[str, Any]) -> None:
    """Replay every durable transition and authenticate token reservations."""

    simulated, _ = _replay_validated_ledger_nonce_prefix(dict(parsed))

    def transition(candidate: dict[str, Any]) -> None:
        nonlocal simulated
        candidate = copy.deepcopy(candidate)
        candidate["generation"] = simulated["generation"] + 1
        simulated = candidate

    publication = parsed["publication"]
    kind = publication["kind"]
    intent = copy.deepcopy(dict(parsed))
    intent.pop("error", None)
    intent["status"] = f"publication_intent_{kind}"
    intent["generation"] = publication["intent_generation"]
    intent["publication"] = copy.deepcopy(publication)
    if "recovery_receipts" in intent["publication"]:
        intent_receipts = [
            receipt
            for receipt in intent["publication"]["recovery_receipts"]
            if receipt["placement"] == "intent"
        ]
        if intent_receipts:
            intent["publication"]["recovery_receipts"] = intent_receipts
        else:
            intent["publication"].pop("recovery_receipts")
    intent["publication"]["state"] = f"{kind}_intent"
    intent["publication"]["pending_ledger_sha256"] = None
    intent["publication"]["report_sha256"] = None
    if sha256_bytes(_ledger_bytes(intent)) != publication["pending_ledger_sha256"]:
        raise ValueError("terminal publication does not bind its replayed intent ledger")
    predecessor = copy.deepcopy(intent)
    predecessor["status"] = publication["predecessor_status"]
    predecessor["generation"] = publication["intent_generation"] - 1
    predecessor["publication"] = _empty_publication_state()
    if sha256_bytes(_ledger_bytes(predecessor)) != publication["predecessor_ledger_sha256"]:
        raise ValueError("publication intent does not bind its predecessor ledger")
    _exact_equal(simulated, predecessor, label="replayed publication predecessor")
    transition(intent)
    _exact_equal(simulated, intent, label="replayed publication intent")
    transition(dict(parsed))
    _exact_equal(simulated, dict(parsed), label="replayed terminal ledger")


def _consume_formal_evaluator_authority(
    authority: _EvaluatorConstructionAuthority,
    *,
    config: Any,
    evaluator: object,
) -> tuple[_AccessLedger, _MaterializerConstructionAuthority]:
    progress = _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS.get(id(evaluator))
    if (
        type(authority) is not _EvaluatorConstructionAuthority
        or type(evaluator) is not _FormalKnownActionEvaluator
        or type(progress) is not tuple
        or len(progress) != 3
        or progress[0] is not evaluator
        or progress[1] is not authority
        or progress[2] is not None
    ):
        raise PermissionError("formal evaluator construction requires one ledger authority")
    registration = _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.get(id(authority))
    if (
        type(registration) is not tuple
        or len(registration) != 5
        or registration[0] is not authority
        or type(registration[1]) is not _AccessLedger
        or type(registration[3]) is not str
        or registration[3] != "issued"
        or type(registration[4]) is not tuple
    ):
        if type(registration) is tuple and len(registration) == 5:
            _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
                authority,
                registration[1],
                registration[2],
                "failed",
                registration[4],
            )
        raise PermissionError("formal evaluator constructor authority is forged or replayed")
    ledger = registration[1]
    evaluator_binding = registration[4]
    try:
        current_evaluator_binding = _evaluator_construction_authority_binding(authority)
    except BaseException:
        _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            ledger,
            registration[2],
            "failed",
            evaluator_binding,
        )
        raise PermissionError("formal evaluator constructor authority was rebound") from None
    if registration[2] is not config or not _exact_native_binding_equal(
        evaluator_binding,
        current_evaluator_binding,
    ):
        _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            ledger,
            registration[2],
            "failed",
            evaluator_binding,
        )
        raise PermissionError("formal evaluator constructor authority was rebound")
    _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
        authority,
        ledger,
        config,
        "consuming",
        evaluator_binding,
    )
    materializer_authority: _MaterializerConstructionAuthority | None = None
    try:
        ledger._verify_disk()
        config_sha256 = _materializer_config_sha256(config)
        if (
            authority.owner_thread != threading.get_ident()
            or authority.owner_thread != ledger._owner_thread
            or authority.stage != ledger.stage
            or authority.ledger_identity != id(ledger)
            or authority.directory_pin is not ledger._pin
            or authority.ledger_path != ledger.path
            or authority.ledger_file_identity
            != _pinned_full_file_identity(ledger._pin, ledger.path)
            or authority.ledger_generation != ledger._record["generation"]
            or authority.ledger_record_sha256 != canonical_sha256(ledger._record)
            or authority.config_identity != id(config)
            or authority.config_sha256 != config_sha256
            or ledger._record["bindings"]["resolved_config_sha256"] != FROZEN_CONFIG_SHA256
            or ledger._record["execution_mode"] != "formal"
            or ledger._record["status"] != "reserved"
        ):
            raise PermissionError("formal evaluator constructor authority was rebound")
        materializer_authority = _MaterializerConstructionAuthority(
            stage=authority.stage,
            evaluator_authority_identity=id(authority),
            evaluator_authority_nonce=authority.nonce,
            ledger_identity=id(ledger),
            directory_pin=ledger._pin,
            ledger_path=ledger.path,
            ledger_file_identity=authority.ledger_file_identity,
            ledger_generation=ledger._record["generation"],
            ledger_record_sha256=canonical_sha256(ledger._record),
            config_identity=id(config),
            config_sha256=config_sha256,
            owner_thread=ledger._owner_thread,
            nonce=object(),
            _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
        )
        if id(materializer_authority) in _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY or any(
            type(item) is not _MaterializerConstructionRegistration or item.ledger is ledger
            for item in _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.values()
        ):
            raise PermissionError("one materializer construction authority already exists")
        materializer_registration = _MaterializerConstructionRegistration(
            authority=materializer_authority,
            evaluator_authority=authority,
            ledger=ledger,
            config=config,
            binding=_materializer_construction_authority_binding(materializer_authority),
            state="issued",
        )
        _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY[id(materializer_authority)] = (
            materializer_registration
        )
        _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS[id(evaluator)] = (
            evaluator,
            authority,
            materializer_authority,
        )
    except BaseException:
        if materializer_authority is not None:
            materializer_registration = _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.get(
                id(materializer_authority)
            )
            if (
                type(materializer_registration) is _MaterializerConstructionRegistration
                and materializer_registration.authority is materializer_authority
            ):
                materializer_registration.state = "failed"
            _MATERIALIZER_CONSTRUCTION_IN_PROGRESS.discard(id(materializer_authority))
        _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS.pop(id(evaluator), None)
        _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
            authority,
            ledger,
            config,
            "failed",
            evaluator_binding,
        )
        raise
    _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
        authority,
        ledger,
        config,
        "consumed",
        evaluator_binding,
    )
    return ledger, materializer_authority


def _construct_trusted_materializer_port(
    authority: _MaterializerConstructionAuthority,
    *,
    config: Any,
    evaluator: object,
) -> _TrustedMaterializerPort:
    if type(authority) is not _MaterializerConstructionAuthority:
        raise PermissionError("materializer port construction requires one exact authority")
    construction_error, construction_registrations = (
        _partition_exact_materializer_construction_registry()
    )
    registration = construction_registrations.get(id(authority))
    progress = _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS.get(id(evaluator))
    if (
        construction_error is not None
        or type(registration) is not _MaterializerConstructionRegistration
        or registration.authority is not authority
        or type(registration.ledger) is not _AccessLedger
        or type(progress) is not tuple
        or len(progress) != 3
        or progress[0] is not evaluator
        or progress[1] is not registration.evaluator_authority
        or progress[2] is not authority
    ):
        if (
            type(registration) is _MaterializerConstructionRegistration
            and registration.authority is authority
        ):
            registration.state = "failed"
        raise PermissionError("materializer construction authority is forged, rebound, or replayed")
    registration_state = registration.state
    if type(registration_state) is not str or registration_state != "issued":
        if type(registration_state) is not str:
            registration.state = "failed"
        raise PermissionError("materializer construction authority is forged, rebound, or replayed")
    if registration.config is not config or id(authority) in _MATERIALIZER_CONSTRUCTION_IN_PROGRESS:
        registration.state = "failed"
        raise PermissionError("materializer construction authority was rebound")
    try:
        current_materializer_binding = _materializer_construction_authority_binding(authority)
    except BaseException:
        registration.state = "failed"
        raise PermissionError("materializer construction authority was rebound") from None
    if not _exact_native_binding_equal(
        registration.binding,
        current_materializer_binding,
    ):
        registration.state = "failed"
        raise PermissionError("materializer construction authority was rebound")
    ledger = registration.ledger
    _MATERIALIZER_CONSTRUCTION_IN_PROGRESS.add(id(authority))
    try:
        ledger._verify_disk()
        config_sha256 = _materializer_config_sha256(config)
        evaluator_authority = registration.evaluator_authority
        evaluator_registration = _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.get(
            id(evaluator_authority)
        )
        port_registry_error, ports, _batches, _tokens, _consumed = (
            _partition_exact_materializer_core_registries()
        )
        if (
            port_registry_error is not None
            or authority.owner_thread != threading.get_ident()
            or authority.owner_thread != ledger._owner_thread
            or authority.stage != ledger.stage
            or authority.evaluator_authority_identity != id(evaluator_authority)
            or authority.evaluator_authority_nonce is not evaluator_authority.nonce
            or authority.ledger_identity != id(ledger)
            or authority.directory_pin is not ledger._pin
            or authority.ledger_path != ledger.path
            or authority.ledger_file_identity
            != _pinned_full_file_identity(ledger._pin, ledger.path)
            or authority.ledger_generation != ledger._record["generation"]
            or authority.ledger_record_sha256 != canonical_sha256(ledger._record)
            or authority.config_identity != id(config)
            or authority.config_sha256 != config_sha256
            or type(evaluator_registration) is not tuple
            or len(evaluator_registration) != 5
            or evaluator_registration[0] is not evaluator_authority
            or evaluator_registration[1] is not ledger
            or evaluator_registration[2] is not config
            or type(evaluator_registration[3]) is not str
            or evaluator_registration[3] != "consumed"
            or type(evaluator_registration[4]) is not tuple
            or not _exact_native_binding_equal(
                evaluator_registration[4],
                _evaluator_construction_authority_binding(evaluator_authority),
            )
            or ledger._record["execution_mode"] != "formal"
            or ledger._record["status"] != "reserved"
            or any(item.ledger is ledger for item in ports.values())
        ):
            raise PermissionError("materializer construction authority was rebound")
        port = _TrustedMaterializerPort(
            stage=authority.stage,
            construction_authority_identity=id(authority),
            construction_authority_nonce=authority.nonce,
            ledger_identity=id(ledger),
            directory_pin=ledger._pin,
            ledger_path=ledger.path,
            ledger_file_identity=authority.ledger_file_identity,
            ledger_generation=authority.ledger_generation,
            ledger_record_sha256=authority.ledger_record_sha256,
            config_identity=id(config),
            config_sha256=config_sha256,
            owner_thread=ledger._owner_thread,
            nonce=object(),
            _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
        )
        if id(port) in ports:
            raise PermissionError("materializer port identity already exists")
        port_registration = _MaterializerPortRegistration(
            port=port,
            authority=authority,
            ledger=ledger,
            config=config,
            evaluator=evaluator,
            binding=_trusted_materializer_port_binding(port),
            state="active",
        )
        _TRUSTED_MATERIALIZER_PORT_REGISTRY[id(port)] = port_registration
        registration.state = "consumed"
        return port
    except BaseException:
        registration.state = "failed"
        raise
    finally:
        _MATERIALIZER_CONSTRUCTION_IN_PROGRESS.discard(id(authority))


def _materializer_vault_requires_cleanup(
    registration: _MaterializerVaultRegistration,
) -> bool:
    if type(registration) is not _MaterializerVaultRegistration:
        return True
    for registry, expected_type in (
        (
            _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY,
            _MaterializerEnvelopeRegistration,
        ),
        (_PUBLIC_SENSOR_BATCH_REGISTRY, _MaterializerTensorBatchRegistration),
        (_SAFE_TASK_BATCH_REGISTRY, _MaterializerTensorBatchRegistration),
        (_SEALED_MATERIALIZATION_ROW_REGISTRY, _MaterializerRowRegistration),
    ):
        if any(
            type(identity) is not int or type(child) is not expected_type
            for identity, child in registry.items()
        ):
            return True
    state = registration.state
    if (
        type(state) is not str
        or state not in MATERIALIZER_TERMINAL_VAULT_STATES
        or registration.terminal_marker is not _MATERIALIZER_VAULT_TERMINAL_MARKER
        or registration.private_request is not None
        or registration.private_request_binding is not None
        or registration.commitment_inventory_sha256 is not None
        or type(registration.envelopes) is not list
        or type(registration.sensor_batches) is not list
        or type(registration.task_batches) is not list
        or type(registration.rows) is not list
    ):
        return True
    try:
        for registry, kind in (
            (_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY, "envelope"),
            (_PUBLIC_SENSOR_BATCH_REGISTRY, "sensor"),
            (_SAFE_TASK_BATCH_REGISTRY, "task"),
            (_SEALED_MATERIALIZATION_ROW_REGISTRY, "row"),
        ):
            if any(
                not _exact_materializer_child_registration(
                    identity,
                    child,
                    kind=kind,
                )
                for identity, child in registry.items()
            ):
                return True
        if not _exact_materializer_vault_root_registration(
            id(registration.vault),
            registration,
        ):
            return True
    except BaseException:
        return True
    expected_slot = (id(registration.ledger), registration.vault.split)
    owned_slots = [
        (slot, vault_identity)
        for slot, vault_identity in tuple(_MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.items())
        if (
            type(slot) is tuple
            and len(slot) == 2
            and type(slot[0]) is int
            and type(slot[1]) is str
            and slot[0] == expected_slot[0]
            and slot[1] == expected_slot[1]
        )
        or (type(vault_identity) is int and vault_identity == id(registration.vault))
    ]
    exact_slots = [
        (slot, vault_identity)
        for slot, vault_identity in owned_slots
        if type(slot) is tuple
        and len(slot) == 2
        and type(slot[0]) is int
        and type(slot[1]) is str
        and type(vault_identity) is int
        and slot == expected_slot
        and vault_identity == id(registration.vault)
    ]
    if (
        registration.state == "failed"
        and (len(owned_slots) > 1 or len(exact_slots) != len(owned_slots))
        or registration.state != "failed"
        and (len(owned_slots) != 1 or len(exact_slots) != 1)
    ):
        return True
    owned_envelopes = {id(value) for value in registration.envelopes}
    owned_sensor_batches = {id(value) for value in registration.sensor_batches}
    owned_task_batches = {id(value) for value in registration.task_batches}
    owned_rows = {id(value) for value in registration.rows}
    for identity, child in _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items():
        if identity not in owned_envelopes and child.vault is not registration.vault:
            continue
        if (
            child.request is not None
            or child.sensor_batch is not None
            or child.task_batch is not None
            or child.runtime_tensors is not None
            or child.public_bodies is not None
            or child.blinding_nonces is not None
            or child.evaluation_hashes is not None
            or child.evaluation_hashes_binding_sha256 is not None
            or type(child.state) is not str
            or child.state != "retired"
        ):
            return True
    for registry, owned in (
        (_PUBLIC_SENSOR_BATCH_REGISTRY, owned_sensor_batches),
        (_SAFE_TASK_BATCH_REGISTRY, owned_task_batches),
    ):
        for identity, child in registry.items():
            if identity not in owned and child.vault is not registration.vault:
                continue
            if (
                child.tensors is not None
                or type(child.state) is not str
                or child.state not in {"retired", "revoked"}
            ):
                return True
    for identity, child in _SEALED_MATERIALIZATION_ROW_REGISTRY.items():
        if identity not in owned_rows and child.vault is not registration.vault:
            continue
        if type(child.state) is not str or child.state not in {"retired", "revoked"}:
            return True
    for identity, value in _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.items():
        if (
            type(identity) is not int
            or type(value) is not tuple
            or len(value) != 4
            or type(value[2]) is not _PublicMaterializationEnvelope
        ):
            return True
        if id(value[2]) in owned_envelopes or (
            type(value[2].vault_identity) is int
            and value[2].vault_identity == id(registration.vault)
        ):
            return True
    return False


def _exact_lower_sha256(value: object) -> bool:
    return (
        type(value) is str
        and len(value) == 64
        and all(character in "0123456789abcdef" for character in value)
    )


def _exact_materializer_construction_registration(
    identity: object,
    registration: object,
) -> bool:
    """Validate one construction tombstone without registry lookup hooks."""

    if (
        type(identity) is not int
        or type(registration) is not _MaterializerConstructionRegistration
        or type(registration.authority) is not _MaterializerConstructionAuthority
        or identity != id(registration.authority)
        or type(registration.evaluator_authority) is not _EvaluatorConstructionAuthority
        or type(registration.ledger) is not _AccessLedger
        or type(registration.ledger._owner_thread) is not int
        or type(registration.ledger.stage) is not str
        or registration.ledger.stage not in SPLITS
        or type(registration.ledger._pin) is not _PinnedDirectory
        or type(registration.ledger.path) is not _NATIVE_PATH_TYPE
        or type(registration.config) is not dict
        or any(type(key) is not str for key in registration.config)
        or type(registration.binding) is not tuple
        or type(registration.state) is not str
        or registration.state not in {"issued", "consuming", "consumed", "failed", "revoked"}
    ):
        return False
    evaluator_matches = [
        candidate
        for candidate_identity, candidate in tuple(
            _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.items()
        )
        if type(candidate_identity) is int
        and candidate_identity == id(registration.evaluator_authority)
        and type(candidate) is tuple
        and len(candidate) == 5
    ]
    if len(evaluator_matches) != 1:
        return False
    evaluator_registration = evaluator_matches[0]
    if (
        evaluator_registration[0] is not registration.evaluator_authority
        or evaluator_registration[1] is not registration.ledger
        or evaluator_registration[2] is not registration.config
        or type(evaluator_registration[3]) is not str
        or evaluator_registration[3] not in {"consuming", "consumed", "failed"}
        or type(evaluator_registration[4]) is not tuple
    ):
        return False
    try:
        authority_binding = _materializer_construction_authority_binding(registration.authority)
        evaluator_binding = _evaluator_construction_authority_binding(
            registration.evaluator_authority
        )
        config_sha256 = _materializer_config_sha256(registration.config)
    except BaseException:
        return False
    authority = registration.authority
    evaluator_authority = registration.evaluator_authority
    ledger = registration.ledger
    return bool(
        _exact_native_binding_equal(registration.binding, authority_binding)
        and _exact_native_binding_equal(evaluator_registration[4], evaluator_binding)
        and authority.stage == evaluator_authority.stage == ledger.stage
        and authority.evaluator_authority_identity == id(evaluator_authority)
        and authority.evaluator_authority_nonce is evaluator_authority.nonce
        and authority.ledger_identity == evaluator_authority.ledger_identity == id(ledger)
        and authority.directory_pin is evaluator_authority.directory_pin is ledger._pin
        and authority.ledger_path == evaluator_authority.ledger_path == ledger.path
        and authority.ledger_file_identity == evaluator_authority.ledger_file_identity
        and authority.ledger_generation == evaluator_authority.ledger_generation
        and authority.ledger_record_sha256 == evaluator_authority.ledger_record_sha256
        and authority.config_identity
        == evaluator_authority.config_identity
        == id(registration.config)
        and authority.config_sha256 == evaluator_authority.config_sha256 == config_sha256
        and authority.owner_thread == evaluator_authority.owner_thread == ledger._owner_thread
    )


def _partition_exact_materializer_construction_registry() -> tuple[
    PermissionError | None,
    dict[int, _MaterializerConstructionRegistration],
]:
    corruption: PermissionError | None = None
    retained: dict[int, _MaterializerConstructionRegistration] = {}
    for identity, registration in tuple(_MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.items()):
        valid = _exact_materializer_construction_registration(identity, registration)
        canonical_identity = (
            id(registration.authority)
            if type(registration) is _MaterializerConstructionRegistration
            and type(registration.authority) is _MaterializerConstructionAuthority
            else None
        )
        if not valid or canonical_identity in retained:
            corruption = PermissionError(
                "materializer construction authority registry was corrupted"
            )
            if type(registration) is _MaterializerConstructionRegistration:
                registration.state = "failed"
            if (
                canonical_identity is not None
                and type(identity) is int
                and identity == canonical_identity
                and canonical_identity not in retained
            ):
                retained[canonical_identity] = registration
            continue
        retained[canonical_identity] = registration
    _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.clear()
    _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.update(retained)
    return corruption, retained


def _partition_exact_materializer_core_registries(
    *,
    postcommit_batch: _BatchCapability | None = None,
) -> tuple[
    PermissionError | None,
    dict[int, _MaterializerPortRegistration],
    dict[int, _BatchRegistration],
    dict[int, tuple[_OrdinalCapability, _BatchRegistration, str]],
    dict[int, tuple[_ConsumedOrdinalAuthority, PublicBatchEvaluationRequest, set[str]]],
]:
    """Hook-free partition and reverse-check of port/batch/token authorities."""

    corruption, construction_registrations = _partition_exact_materializer_construction_registry()

    ports: dict[int, _MaterializerPortRegistration] = {}
    for key, registration in tuple(_TRUSTED_MATERIALIZER_PORT_REGISTRY.items()):
        canonical_identity = (
            id(registration.port)
            if type(registration) is _MaterializerPortRegistration
            and type(registration.port) is _TrustedMaterializerPort
            else None
        )
        valid = bool(
            type(registration) is _MaterializerPortRegistration
            and type(registration.port) is _TrustedMaterializerPort
            and type(registration.authority) is _MaterializerConstructionAuthority
            and type(registration.ledger) is _AccessLedger
            and type(registration.ledger._owner_thread) is int
            and type(registration.ledger.stage) is str
            and registration.ledger.stage in {"development", "qualification"}
            and type(registration.ledger._pin) is _PinnedDirectory
            and type(registration.ledger.path) is _NATIVE_PATH_TYPE
            and type(registration.config) is dict
            and all(type(name) is str for name in registration.config)
            and type(registration.binding) is tuple
            and type(registration.state) is str
            and registration.state in {"active", "closed", "failed", "revoked"}
        )
        if valid:
            try:
                construction_registration = construction_registrations.get(
                    id(registration.authority)
                )
                authority_binding = _materializer_construction_authority_binding(
                    registration.authority
                )
                config_sha256 = _materializer_config_sha256(registration.config)
                valid = bool(
                    _exact_native_binding_equal(
                        registration.binding,
                        _trusted_materializer_port_binding(registration.port),
                    )
                    and registration.port.owner_thread
                    == registration.ledger._owner_thread
                    == registration.authority.owner_thread
                    and registration.port.stage
                    == registration.ledger.stage
                    == registration.authority.stage
                    and registration.port.construction_authority_identity
                    == id(registration.authority)
                    and registration.port.construction_authority_nonce
                    is registration.authority.nonce
                    and registration.port.ledger_identity == id(registration.ledger)
                    and registration.port.directory_pin is registration.ledger._pin
                    and registration.port.ledger_path == registration.ledger.path
                    and registration.port.ledger_file_identity
                    == registration.authority.ledger_file_identity
                    and registration.port.ledger_generation
                    == registration.authority.ledger_generation
                    and registration.port.ledger_record_sha256
                    == registration.authority.ledger_record_sha256
                    and registration.port.config_identity == id(registration.config)
                    and registration.port.config_sha256 == config_sha256
                    and registration.authority.ledger_identity == id(registration.ledger)
                    and registration.authority.directory_pin is registration.ledger._pin
                    and registration.authority.ledger_path == registration.ledger.path
                    and registration.authority.config_identity == id(registration.config)
                    and registration.authority.config_sha256 == config_sha256
                    and type(authority_binding) is tuple
                    and type(construction_registration) is _MaterializerConstructionRegistration
                    and construction_registration.authority is registration.authority
                    and construction_registration.ledger is registration.ledger
                    and construction_registration.config is registration.config
                    and (
                        registration.state in {"active", "closed", "revoked"}
                        and construction_registration.state == "consumed"
                        or registration.state == "failed"
                        and construction_registration.state in {"consumed", "failed"}
                    )
                )
            except BaseException:
                valid = False
        identity = canonical_identity if valid else None
        if not valid or type(key) is not int or key != identity or identity in ports:
            corruption = PermissionError(
                "trusted materializer port registry binding differs; registry was corrupted"
            )
            if type(registration) is _MaterializerPortRegistration:
                registration.state = "failed"
            if valid and identity not in ports:
                ports[identity] = registration
            elif (
                canonical_identity is not None
                and type(key) is int
                and key == canonical_identity
                and canonical_identity not in ports
            ):
                ports[canonical_identity] = registration
            elif (
                canonical_identity is None
                and type(key) is int
                and type(registration) is _MaterializerPortRegistration
                and key not in ports
            ):
                # Preserve the canonical registry slot when the stored port
                # pointer itself was corrupted.  Dropping it would erase the
                # witness and make exact restoration impossible; every deep cut
                # still rejects the retained registration until that pointer is
                # restored.
                ports[key] = registration
            continue
        ports[identity] = registration
    _TRUSTED_MATERIALIZER_PORT_REGISTRY.clear()
    _TRUSTED_MATERIALIZER_PORT_REGISTRY.update(ports)

    ports_by_authority: dict[int, list[_MaterializerPortRegistration]] = {}
    for port_registration in ports.values():
        ports_by_authority.setdefault(id(port_registration.authority), []).append(port_registration)
    for authority_identity, construction_registration in construction_registrations.items():
        owned_ports = ports_by_authority.get(authority_identity, [])
        construction_state = construction_registration.state
        if construction_state == "consumed":
            reverse_is_exact = len(owned_ports) == 1
        elif construction_state == "failed":
            reverse_is_exact = len(owned_ports) <= 1 and all(
                port_registration.state == "failed" for port_registration in owned_ports
            )
        else:
            reverse_is_exact = not owned_ports
        if not reverse_is_exact:
            corruption = PermissionError(
                "materializer construction authority/port reverse bijection "
                "binding differs or was corrupted"
            )
            construction_registration.state = "failed"
            for port_registration in owned_ports:
                if port_registration.state in {"active", "closed"}:
                    port_registration.state = "failed"

    batches: dict[int, _BatchRegistration] = {}
    for key, registration in tuple(_BATCH_REGISTRY.items()):
        batch = registration.batch if type(registration) is _BatchRegistration else None
        manifest = registration.manifest if type(registration) is _BatchRegistration else None
        valid = bool(
            type(registration) is _BatchRegistration
            and type(batch) is _BatchCapability
            and type(batch.split) is str
            and batch.split in SPLITS
            and type(batch.ordinals) is tuple
            and len(batch.ordinals) == BATCH_SIZE
            and all(type(ordinal) is int for ordinal in batch.ordinals)
            and type(batch.tokens) is tuple
            and len(batch.tokens) == BATCH_SIZE
            and all(type(token) is _OrdinalCapability for token in batch.tokens)
            and (
                batch.capability_nonces is None
                or (
                    type(batch.capability_nonces) is tuple
                    and len(batch.capability_nonces) == BATCH_SIZE
                    and all(type(value) is str for value in batch.capability_nonces)
                )
            )
            and (
                batch.capability_nonce_preflight_sha256 is None
                or type(batch.capability_nonce_preflight_sha256) is str
            )
            and type(batch.nonce) is object
            and type(manifest) is _ManifestCapability
            and type(manifest.split) is str
            and manifest.split in SPLITS
            and type(manifest._ledger) is _AccessLedger
            and type(manifest._ledger._owner_thread) is int
            and type(manifest._next_ordinal) is int
            and type(manifest._closed) is bool
            and type(registration.consumed) is set
            and all(type(ordinal) is int for ordinal in registration.consumed)
            and registration.consumed.issubset(set(batch.ordinals))
            and type(registration.status) is str
            and registration.status == "issued"
        )
        identity = id(batch) if valid else None
        if not valid or type(key) is not int or key != identity or identity in batches:
            corruption = PermissionError("batch capability registry cut was corrupted")
            if valid and identity not in batches:
                batches[identity] = registration
            continue
        batches[identity] = registration
    _BATCH_REGISTRY.clear()
    _BATCH_REGISTRY.update(batches)

    tokens: dict[int, tuple[_OrdinalCapability, _BatchRegistration, str]] = {}
    for key, registration in tuple(_TOKEN_REGISTRY.items()):
        valid = bool(
            type(registration) is tuple
            and len(registration) == 3
            and type(registration[0]) is _OrdinalCapability
            and type(registration[1]) is _BatchRegistration
            and type(registration[2]) is str
            and registration[2] in {"issued", "consumed"}
            and type(registration[0].split) is str
            and registration[0].split in SPLITS
            and type(registration[0].ordinal) is int
            and type(registration[0].nonce) is object
        )
        identity = id(registration[0]) if valid else None
        if not valid or type(key) is not int or key != identity or identity in tokens:
            corruption = PermissionError("ordinal token registry cut was corrupted")
            if valid and identity not in tokens:
                tokens[identity] = registration
            continue
        tokens[identity] = registration
    _TOKEN_REGISTRY.clear()
    _TOKEN_REGISTRY.update(tokens)

    consumed: dict[
        int,
        tuple[_ConsumedOrdinalAuthority, PublicBatchEvaluationRequest, set[str]],
    ] = {}
    for key, registration in tuple(_CONSUMED_ORDINAL_REGISTRY.items()):
        valid = bool(
            type(registration) is tuple
            and len(registration) == 3
            and type(registration[0]) is _ConsumedOrdinalAuthority
            and type(registration[1]) is PublicBatchEvaluationRequest
            and type(registration[2]) is set
            and all(type(value) is str for value in registration[2])
            and type(registration[0].split) is str
            and registration[0].split in SPLITS
            and type(registration[0].ordinal) is int
            and type(registration[0].token) is _OrdinalCapability
            and type(registration[0].token_receipt) is dict
            and all(type(name) is str for name in registration[0].token_receipt)
            and type(registration[0].nonce) is object
        )
        identity = id(registration[0]) if valid else None
        if not valid or type(key) is not int or key != identity or identity in consumed:
            corruption = PermissionError("consumed ordinal registry authority cut was corrupted")
            if valid and identity not in consumed:
                consumed[identity] = registration
            continue
        consumed[identity] = registration
    _CONSUMED_ORDINAL_REGISTRY.clear()
    _CONSUMED_ORDINAL_REGISTRY.update(consumed)

    if postcommit_batch is not None and type(postcommit_batch) is not _BatchCapability:
        corruption = PermissionError("postcommit materializer batch is forged")

    token_owner_counts: dict[int, int] = {}
    manifest_owner_counts: dict[int, int] = {}
    ledger_split_owner_counts: dict[tuple[int, str], int] = {}
    for _batch_identity, registration in batches.items():
        batch = registration.batch
        manifest = registration.manifest
        manifest_owner_counts[id(manifest)] = manifest_owner_counts.get(id(manifest), 0) + 1
        owner = (id(manifest._ledger), manifest.split)
        ledger_split_owner_counts[owner] = ledger_split_owner_counts.get(owner, 0) + 1
        ledger_record = manifest._ledger._record
        split_states = ledger_record.get("splits") if type(ledger_record) is dict else None
        split_state = (
            split_states.get(manifest.split)
            if type(split_states) is dict and all(type(name) is str for name in split_states)
            else None
        )
        durable_active = (
            type(split_state) is dict
            and all(type(name) is str for name in split_state)
            and type(split_state.get("status")) is str
            and split_state.get("status") == "public_evaluating"
            and type(split_state.get("public_next_ordinal")) is int
            and split_state.get("public_next_ordinal") == batch.ordinals[0]
            and type(split_state.get("public_active_batch")) is list
            and all(type(ordinal) is int for ordinal in split_state.get("public_active_batch"))
            and split_state.get("public_active_batch") == list(batch.ordinals)
        )
        durable_postcommit = bool(
            batch is postcommit_batch
            and type(split_state) is dict
            and all(type(name) is str for name in split_state)
            and type(split_state.get("status")) is str
            and split_state.get("status") == "public_evaluating"
            and type(split_state.get("public_next_ordinal")) is int
            and split_state.get("public_next_ordinal") == batch.ordinals[-1] + 1
            and split_state.get("public_active_batch") is None
            and type(split_state.get("public_batch_receipts")) is list
            and len(split_state.get("public_batch_receipts")) == batch.ordinals[0] // BATCH_SIZE + 1
        )
        if (
            manifest._active is not batch
            or manifest.split != batch.split
            or manifest._ledger._owner_thread != threading.get_ident()
            or batch.ordinals
            != tuple(range(manifest._next_ordinal, manifest._next_ordinal + BATCH_SIZE))
            or manifest_owner_counts[id(manifest)] != 1
            or ledger_split_owner_counts[owner] != 1
            or not (durable_active or durable_postcommit)
        ):
            corruption = PermissionError("active batch/manifest registry bijection was corrupted")
        for token_index, token in enumerate(batch.tokens):
            matching = [
                item for item in tokens.values() if item[0] is token and item[1] is registration
            ]
            expected_state = (
                "consumed" if batch.ordinals[token_index] in registration.consumed else "issued"
            )
            if (
                len(matching) != 1
                or matching[0][2] != expected_state
                or token.split != batch.split
                or token.ordinal != batch.ordinals[token_index]
            ):
                corruption = PermissionError("batch/token registry reverse bijection was corrupted")
            token_owner_counts[id(token)] = token_owner_counts.get(id(token), 0) + 1
    if any(count != 1 for count in token_owner_counts.values()) or any(
        not any(
            item.batch is token_registration[1].batch and token_registration[0] is token
            for item in batches.values()
            for token in item.batch.tokens
        )
        for token_registration in tokens.values()
    ):
        corruption = PermissionError("orphan token registry binding was corrupted")

    authority_counts: dict[int, dict[int, int]] = {}
    batch_request_identities: dict[int, set[int]] = {}
    relational_consumed: dict[
        int,
        tuple[_ConsumedOrdinalAuthority, PublicBatchEvaluationRequest, set[str]],
    ] = {}
    for authority_identity, (authority, request, variants) in consumed.items():
        batch_registration = batches.get(id(request._batch))
        token_registration = tokens.get(id(authority.token))
        receipt = authority.token_receipt
        receipt_scalars_are_exact = bool(
            type(receipt) is dict
            and all(type(name) is str for name in receipt)
            and type(receipt.get("schema")) is str
            and type(receipt.get("split")) is str
            and type(receipt.get("ordinal")) is int
            and type(receipt.get("batch_index")) is int
            and type(receipt.get("reservation_generation")) is int
            and type(receipt.get("reservation_sha256")) is str
            and type(receipt.get("capability_nonce")) is str
            and type(receipt.get("receipt_sha256")) is str
        )
        receipt_is_exact = False
        if receipt_scalars_are_exact:
            try:
                receipt_is_exact = (
                    _validated_token_receipt(
                        receipt,
                        split=authority.split,
                        ordinal=authority.ordinal,
                    )
                    == receipt
                )
            except BaseException:
                receipt_is_exact = False
        if (
            type(request.split) is not str
            or request.split not in SPLITS
            or type(request.ordinals) is not tuple
            or len(request.ordinals) != BATCH_SIZE
            or any(type(ordinal) is not int for ordinal in request.ordinals)
            or type(request.tokens) is not tuple
            or len(request.tokens) != BATCH_SIZE
            or any(type(token) is not _OrdinalCapability for token in request.tokens)
            or type(request._manifest) is not _ManifestCapability
            or type(request._batch) is not _BatchCapability
            or type(batch_registration) is not _BatchRegistration
            or batch_registration.batch is not request._batch
            or batch_registration.manifest is not request._manifest
            or request._manifest._active is not request._batch
            or request.split != request._batch.split
            or request.ordinals != request._batch.ordinals
            or authority.split != request.split
            or authority.ordinal not in request.ordinals
            or authority.token is not request.tokens[request.ordinals.index(authority.ordinal)]
            or authority.ordinal not in batch_registration.consumed
            or type(token_registration) is not tuple
            or len(token_registration) != 3
            or token_registration[0] is not authority.token
            or token_registration[1] is not batch_registration
            or type(token_registration[2]) is not str
            or token_registration[2] != "consumed"
            or not receipt_is_exact
            or not variants
            or not variants.issubset({"base", "palette"})
        ):
            corruption = PermissionError(
                "consumed authority/request registry bijection was corrupted"
            )
            continue
        relational_consumed[authority_identity] = (authority, request, variants)
        ordinal_counts = authority_counts.setdefault(id(request), {})
        ordinal_counts[authority.ordinal] = ordinal_counts.get(authority.ordinal, 0) + 1
        batch_request_identities.setdefault(id(request._batch), set()).add(id(request))
    if any(
        any(count != 1 for count in ordinal_counts.values())
        for ordinal_counts in authority_counts.values()
    ) or any(len(identities) != 1 for identities in batch_request_identities.values()):
        corruption = PermissionError(
            "consumed authority set is not one unique request/ordinal binding"
        )
    for request_identity, ordinal_counts in authority_counts.items():
        request_registration = next(
            (value for value in relational_consumed.values() if id(value[1]) == request_identity),
            None,
        )
        if request_registration is None:
            continue
        request = request_registration[1]
        batch_registration = batches.get(id(request._batch))
        remaining = {
            authority.ordinal: variants
            for authority, candidate, variants in relational_consumed.values()
            if candidate is request
        }
        ordered_remaining = sorted(remaining)
        first_remaining_index = (
            request.ordinals.index(ordered_remaining[0])
            if ordered_remaining
            else len(request.ordinals)
        )
        expected_remaining = list(request.ordinals[first_remaining_index:])
        progressive_root_count = sum(
            1
            for root in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
            if type(root) is _MaterializerVaultRegistration
            and type(root.ledger) is _AccessLedger
            and type(root.vault) is _MaterializerSplitVault
            and type(root.vault.split) is str
            and root.ledger is request._manifest._ledger
            and root.vault.split == request.split
            and type(root.state) is str
            and root.state == "checking_public_issue"
        )
        progressive_variant_cut = bool(
            progressive_root_count == 1
            and ordered_remaining == expected_remaining
            and remaining[ordered_remaining[0]] in ({"base", "palette"}, {"palette"})
            and all(remaining[ordinal] == {"base", "palette"} for ordinal in ordered_remaining[1:])
        )
        if (
            type(batch_registration) is not _BatchRegistration
            or batch_registration.consumed != set(request.ordinals)
            or (set(ordinal_counts) != set(request.ordinals) and not progressive_variant_cut)
        ):
            corruption = PermissionError(
                "consumed authority set differs from exact batch consumption"
            )
    consumed = relational_consumed
    _CONSUMED_ORDINAL_REGISTRY.clear()
    _CONSUMED_ORDINAL_REGISTRY.update(consumed)
    return corruption, ports, batches, tokens, consumed


def _scrub_rejected_materializer_child(registration: object) -> None:
    if type(registration) is _MaterializerEnvelopeRegistration:
        request = registration.request
        if type(request) is PublicBatchEvaluationRequest:
            with contextlib.suppress(BaseException):
                _revoke_materialization_authorities(request)
        registration.request = None
        registration.sensor_batch = None
        registration.task_batch = None
        registration.runtime_tensors = None
        registration.public_bodies = None
        registration.blinding_nonces = None
        registration.evaluation_hashes = None
        registration.evaluation_hashes_binding_sha256 = None
        registration.state = "retired"
    elif type(registration) is _MaterializerTensorBatchRegistration:
        registration.tensors = None
        registration.state = "revoked"
    elif type(registration) is _MaterializerRowRegistration:
        registration.state = "revoked"


def _exact_materializer_child_registration(
    identity: object,
    registration: object,
    *,
    kind: Literal["envelope", "sensor", "task", "row"],
) -> bool:
    try:
        if kind == "envelope":
            if (
                type(identity) is not int
                or type(registration) is not _MaterializerEnvelopeRegistration
                or type(registration.envelope) is not _PublicMaterializationEnvelope
                or identity != id(registration.envelope)
                or type(registration.port) is not _TrustedMaterializerPort
                or type(registration.vault) is not _MaterializerSplitVault
                or (
                    registration.request is not None
                    and type(registration.request) is not PublicBatchEvaluationRequest
                )
                or (
                    registration.sensor_batch is not None
                    and type(registration.sensor_batch) is not _PublicSensorBatch
                )
                or (
                    registration.task_batch is not None
                    and type(registration.task_batch) is not _SafeTaskBatch
                )
                or (
                    registration.runtime_tensors is not None
                    and (
                        type(registration.runtime_tensors) is not dict
                        or any(type(key) is not str for key in registration.runtime_tensors)
                    )
                )
                or (
                    registration.public_bodies is not None
                    and (
                        type(registration.public_bodies) is not tuple
                        or len(registration.public_bodies) != BATCH_SIZE
                        or any(
                            type(body) is not dict or any(type(key) is not str for key in body)
                            for body in registration.public_bodies
                        )
                    )
                )
                or (
                    registration.blinding_nonces is not None
                    and (
                        type(registration.blinding_nonces) is not tuple
                        or len(registration.blinding_nonces) != BATCH_SIZE
                        or any(
                            type(value) is not bytes or len(value) != 32
                            for value in registration.blinding_nonces
                        )
                    )
                )
                or type(registration.rows) is not tuple
                or len(registration.rows) != BATCH_SIZE
                or any(type(row) is not _SealedMaterializationRow for row in registration.rows)
                or len({id(row) for row in registration.rows}) != BATCH_SIZE
                or (
                    registration.evaluation_hashes is not None
                    and (
                        type(registration.evaluation_hashes) is not dict
                        or any(type(key) is not str for key in registration.evaluation_hashes)
                        or frozenset(registration.evaluation_hashes.keys())
                        != PUBLIC_MATERIALIZER_EVALUATION_HASH_SCHEMA
                        or any(
                            type(value) is not str
                            for value in registration.evaluation_hashes.values()
                        )
                    )
                )
                or (
                    registration.evaluation_hashes_binding_sha256 is not None
                    and not _exact_lower_sha256(registration.evaluation_hashes_binding_sha256)
                )
                or type(registration.binding) is not tuple
                or type(registration.state) is not str
                or registration.state not in {"issued", "evaluated", "public_finalized", "retired"}
            ):
                return False
            if not _exact_native_binding_equal(
                registration.binding,
                _materializer_envelope_binding(registration.envelope),
            ):
                return False
            if registration.state == "issued":
                return bool(
                    type(registration.request) is PublicBatchEvaluationRequest
                    and type(registration.sensor_batch) is _PublicSensorBatch
                    and type(registration.task_batch) is _SafeTaskBatch
                    and type(registration.runtime_tensors) is dict
                    and type(registration.public_bodies) is tuple
                    and type(registration.blinding_nonces) is tuple
                    and registration.evaluation_hashes is None
                    and registration.evaluation_hashes_binding_sha256 is None
                )
            if registration.state in {"evaluated", "public_finalized"}:
                if type(registration.evaluation_hashes) is not dict:
                    return False
                validated_hashes = _validated_public_materializer_evaluation_hashes(
                    registration.evaluation_hashes
                )
                return bool(
                    registration.request is None
                    and type(registration.sensor_batch) is _PublicSensorBatch
                    and type(registration.task_batch) is _SafeTaskBatch
                    and type(registration.runtime_tensors) is dict
                    and type(registration.public_bodies) is tuple
                    and type(registration.blinding_nonces) is tuple
                    and _exact_lower_sha256(registration.evaluation_hashes_binding_sha256)
                    and registration.evaluation_hashes_binding_sha256
                    == canonical_sha256(validated_hashes)
                )
            return bool(
                registration.request is None
                and registration.sensor_batch is None
                and registration.task_batch is None
                and registration.runtime_tensors is None
                and registration.public_bodies is None
                and registration.blinding_nonces is None
                and registration.evaluation_hashes is None
                and registration.evaluation_hashes_binding_sha256 is None
            )
        if kind in {"sensor", "task"}:
            expected_batch_type = _PublicSensorBatch if kind == "sensor" else _SafeTaskBatch
            if (
                type(identity) is not int
                or type(registration) is not _MaterializerTensorBatchRegistration
                or type(registration.batch) is not expected_batch_type
                or identity != id(registration.batch)
                or type(registration.port) is not _TrustedMaterializerPort
                or type(registration.vault) is not _MaterializerSplitVault
                or type(registration.envelope) is not _PublicMaterializationEnvelope
                or (
                    registration.tensors is not None
                    and (
                        type(registration.tensors) is not dict
                        or any(type(key) is not str for key in registration.tensors)
                    )
                )
                or type(registration.binding) is not tuple
                or type(registration.state) is not str
                or registration.state
                not in {"issued", "evaluated", "public_finalized", "retired", "revoked"}
            ):
                return False
            if not _exact_native_binding_equal(
                registration.binding,
                _materializer_tensor_batch_binding(registration.batch),
            ):
                return False
            return (
                type(registration.tensors) is dict
                if registration.state in {"issued", "evaluated", "public_finalized"}
                else registration.tensors is None
            )
        if (
            kind != "row"
            or type(identity) is not int
            or type(registration) is not _MaterializerRowRegistration
            or type(registration.row) is not _SealedMaterializationRow
            or identity != id(registration.row)
            or type(registration.envelope) is not _PublicMaterializationEnvelope
            or type(registration.vault) is not _MaterializerSplitVault
            or type(registration.binding) is not tuple
            or type(registration.state) is not str
            or registration.state
            not in {"issued", "evaluated", "public_finalized", "retired", "revoked"}
        ):
            return False
        return _exact_native_binding_equal(
            registration.binding,
            _materializer_row_binding(registration.row),
        )
    except BaseException:
        return False


def _quarantine_malformed_materializer_child_registries() -> PermissionError | None:
    registry_corruption, _ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    specifications = (
        (
            _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY,
            "envelope",
        ),
        (
            _PUBLIC_SENSOR_BATCH_REGISTRY,
            "sensor",
        ),
        (
            _SAFE_TASK_BATCH_REGISTRY,
            "task",
        ),
        (
            _SEALED_MATERIALIZATION_ROW_REGISTRY,
            "row",
        ),
    )
    for registry, kind in specifications:
        retained: list[tuple[int, object]] = []
        for identity, child_registration in tuple(registry.items()):
            if not _exact_materializer_child_registration(
                identity,
                child_registration,
                kind=kind,
            ):
                registry_corruption = PermissionError(
                    f"materializer {kind} registry was corrupted during scrub"
                )
                _scrub_rejected_materializer_child(child_registration)
                primary = (
                    child_registration.envelope
                    if type(child_registration) is _MaterializerEnvelopeRegistration
                    else child_registration.batch
                    if type(child_registration) is _MaterializerTensorBatchRegistration
                    else child_registration.row
                    if type(child_registration) is _MaterializerRowRegistration
                    else None
                )
                if primary is not None:
                    retained.append((id(primary), child_registration))
            else:
                retained.append((identity, child_registration))
        registry.clear()
        registry.update(retained)

    roots = {
        identity: registration
        for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items())
        if _exact_materializer_vault_root_registration(identity, registration)
    }
    envelopes = dict(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY)
    relational: tuple[tuple[dict[int, Any], Literal["envelope", "sensor", "task", "row"]], ...] = (
        (_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY, "envelope"),
        (_PUBLIC_SENSOR_BATCH_REGISTRY, "sensor"),
        (_SAFE_TASK_BATCH_REGISTRY, "task"),
        (_SEALED_MATERIALIZATION_ROW_REGISTRY, "row"),
    )
    for registry, kind in relational:
        retained = []
        for identity, child in tuple(registry.items()):
            root = roots.get(id(child.vault))
            valid = (
                bool(
                    type(root) is _MaterializerVaultRegistration
                    and root.vault is child.vault
                    and root.port is child.port
                )
                if kind != "row"
                else bool(
                    type(root) is _MaterializerVaultRegistration and root.vault is child.vault
                )
            )
            if kind == "envelope":
                valid = bool(
                    valid
                    and type(root.envelopes) is list
                    and any(item is child.envelope for item in root.envelopes)
                )
            elif kind in {"sensor", "task"}:
                envelope_registration = envelopes.get(id(child.envelope))
                expected_inventory = (
                    root.sensor_batches
                    if type(root) is _MaterializerVaultRegistration
                    and kind == "sensor"
                    and type(root.sensor_batches) is list
                    else root.task_batches
                    if type(root) is _MaterializerVaultRegistration
                    and type(root.task_batches) is list
                    else ()
                )
                valid = bool(
                    valid
                    and type(envelope_registration) is _MaterializerEnvelopeRegistration
                    and envelope_registration.envelope is child.envelope
                    and envelope_registration.vault is child.vault
                    and envelope_registration.port is child.port
                    and (
                        type(root.state) is str
                        and root.state in MATERIALIZER_TERMINAL_VAULT_STATES
                        or (
                            envelope_registration.sensor_batch is child.batch
                            if kind == "sensor"
                            else envelope_registration.task_batch is child.batch
                        )
                    )
                    and any(item is child.batch for item in expected_inventory)
                )
            else:
                envelope_registration = envelopes.get(id(child.envelope))
                valid = bool(
                    valid
                    and type(envelope_registration) is _MaterializerEnvelopeRegistration
                    and envelope_registration.envelope is child.envelope
                    and envelope_registration.vault is child.vault
                    and any(item is child.row for item in envelope_registration.rows)
                )
            if valid:
                retained.append((identity, child))
            else:
                registry_corruption = PermissionError(
                    f"materializer {kind} registry crossbinding was corrupted during scrub"
                )
                _scrub_rejected_materializer_child(child)
                retained.append((identity, child))
        registry.clear()
        registry.update(retained)
    evaluation_error = _quarantine_malformed_materializer_evaluation_registry()
    if evaluation_error is not None:
        registry_corruption = evaluation_error
    return registry_corruption


def _quarantine_malformed_materializer_evaluation_registry() -> PermissionError | None:
    def exact_active_binding(
        identity: int,
        batch: _BatchCapability,
        manifest: _ManifestCapability,
        envelope: _PublicMaterializationEnvelope,
    ) -> bool:
        registration = _BATCH_REGISTRY.get(identity)
        if (
            type(batch.split) is not str
            or batch.split not in SPLITS
            or type(batch.ordinals) is not tuple
            or len(batch.ordinals) != BATCH_SIZE
            or any(type(ordinal) is not int for ordinal in batch.ordinals)
            or type(batch.tokens) is not tuple
            or len(batch.tokens) != BATCH_SIZE
            or any(type(token) is not _OrdinalCapability for token in batch.tokens)
            or type(batch.capability_nonces) is not tuple
            or len(batch.capability_nonces) != BATCH_SIZE
            or any(type(nonce) is not str for nonce in batch.capability_nonces)
            or type(batch.capability_nonce_preflight_sha256) is not str
            or type(batch.nonce) is not object
            or type(manifest.split) is not str
            or manifest.split not in SPLITS
            or type(manifest._ledger) is not _AccessLedger
            or type(manifest._ledger._record) is not dict
            or type(manifest._ledger._record.get("execution_mode")) is not str
            or type(manifest._next_ordinal) is not int
            or type(registration) is not _BatchRegistration
            or registration.batch is not batch
            or registration.manifest is not manifest
            or type(registration.consumed) is not set
            or any(type(ordinal) is not int for ordinal in registration.consumed)
            or registration.consumed != set(batch.ordinals)
            or type(registration.status) is not str
            or registration.status != "issued"
            or manifest._active is not batch
            or batch.split != manifest.split
            or batch.ordinals != envelope.ordinals
            or manifest._next_ordinal != batch.ordinals[0]
            or manifest._ledger._record.get("execution_mode") != "formal"
            or type(manifest._ledger._owner_thread) is not int
            or manifest._ledger._owner_thread != threading.get_ident()
            or envelope.owner_thread != threading.get_ident()
            or envelope.split != manifest.split
        ):
            return False
        for offset, token in enumerate(batch.tokens):
            if (
                type(token.split) is not str
                or type(token.ordinal) is not int
                or type(token.nonce) is not object
                or token.split != manifest.split
                or token.ordinal != batch.ordinals[offset]
            ):
                return False
            token_registration = _TOKEN_REGISTRY.get(id(token))
            if (
                type(token_registration) is not tuple
                or len(token_registration) != 3
                or token_registration[0] is not token
                or token_registration[1] is not registration
                or type(token_registration[2]) is not str
                or token_registration[2] != "consumed"
            ):
                return False
        return True

    registry_corruption: PermissionError | None = None
    envelope_registrations = {
        identity: registration
        for identity, registration in tuple(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items())
        if type(identity) is int and type(registration) is _MaterializerEnvelopeRegistration
    }
    roots = {
        identity: registration
        for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items())
        if _exact_materializer_vault_root_registration(identity, registration)
    }
    candidates: list[
        tuple[
            int,
            tuple[
                _BatchCapability,
                _ManifestCapability,
                _PublicMaterializationEnvelope,
                str,
            ],
        ]
    ] = []
    for identity, value in tuple(_MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.items()):
        valid = bool(
            type(identity) is int
            and type(value) is tuple
            and len(value) == 4
            and type(value[0]) is _BatchCapability
            and identity == id(value[0])
            and type(value[1]) is _ManifestCapability
            and type(value[2]) is _PublicMaterializationEnvelope
            and _exact_lower_sha256(value[3])
        )
        envelope_registration = envelope_registrations.get(id(value[2])) if valid else None
        root = (
            roots.get(id(envelope_registration.vault))
            if type(envelope_registration) is _MaterializerEnvelopeRegistration
            else None
        )
        hashes = (
            envelope_registration.evaluation_hashes
            if type(envelope_registration) is _MaterializerEnvelopeRegistration
            else None
        )
        hash_keys = tuple(hashes.keys()) if type(hashes) is dict else ()
        batch = value[0] if valid else None
        manifest = value[1] if valid else None
        envelope = value[2] if valid else None
        try:
            envelope_scalars_are_exact = bool(valid and _materializer_envelope_binding(envelope))
        except BaseException:
            envelope_scalars_are_exact = False
        ledger_state = (
            root.ledger._record["splits"].get(root.vault.split)
            if type(root) is _MaterializerVaultRegistration
            and type(root.ledger) is _AccessLedger
            and type(root.ledger._record) is dict
            and type(root.ledger._record.get("splits")) is dict
            and type(root.vault) is _MaterializerSplitVault
            and type(root.vault.split) is str
            else None
        )
        batch_index = (
            envelope.ordinals[0] // BATCH_SIZE
            if type(envelope) is _PublicMaterializationEnvelope
            and type(envelope.ordinals) is tuple
            and len(envelope.ordinals) == BATCH_SIZE
            and all(type(ordinal) is int for ordinal in envelope.ordinals)
            else None
        )
        durable_receipts = (
            ledger_state.get("public_batch_receipts") if type(ledger_state) is dict else None
        )
        active_batch = (
            ledger_state.get("public_active_batch") if type(ledger_state) is dict else None
        )
        precommit_cut = bool(
            type(batch_index) is int
            and type(durable_receipts) is list
            and len(durable_receipts) == batch_index
            and type(active_batch) is list
            and len(active_batch) == BATCH_SIZE
            and all(type(ordinal) is int for ordinal in active_batch)
            and active_batch == list(envelope.ordinals)
            and ledger_state.get("public_next_ordinal") == envelope.ordinals[0]
        )
        postcommit_cut = False
        if (
            type(batch_index) is int
            and type(durable_receipts) is list
            and len(durable_receipts) == batch_index + 1
            and active_batch is None
            and ledger_state.get("public_next_ordinal") == envelope.ordinals[-1] + 1
            and type(root) is _MaterializerVaultRegistration
            and type(root.state) is str
            and root.state == "checking_public_commit"
        ):
            try:
                durable_receipt = _validate_batch_receipt(
                    durable_receipts[batch_index],
                    split=root.vault.split,
                    batch_index=batch_index,
                )
                postcommit_cut = canonical_sha256(durable_receipt["public_evaluation"]) == value[3]
            except BaseException:
                postcommit_cut = False
        valid = bool(
            valid
            and envelope_scalars_are_exact
            and type(envelope_registration) is _MaterializerEnvelopeRegistration
            and envelope_registration.envelope is value[2]
            and type(root) is _MaterializerVaultRegistration
            and root.vault is envelope_registration.vault
            and root.port is envelope_registration.port
            and type(value[1].split) is str
            and value[1].split in SPLITS
            and value[1]._ledger is root.ledger
            and value[1].split == root.vault.split
            and type(hashes) is dict
            and all(type(key) is str for key in hash_keys)
            and frozenset(hash_keys) == PUBLIC_MATERIALIZER_EVALUATION_HASH_SCHEMA
            and _exact_lower_sha256(hashes.get("public_evaluation_sha256"))
            and hashes.get("public_evaluation_sha256") == value[3]
            and type(envelope_registration.state) is str
            and envelope_registration.state == "evaluated"
            and type(ledger_state) is dict
            and type(ledger_state.get("status")) is str
            and type(ledger_state.get("public_next_ordinal")) is int
            and ledger_state.get("status") == "public_evaluating"
            and (precommit_cut or postcommit_cut)
            and exact_active_binding(identity, batch, manifest, envelope)
        )
        if valid:
            candidates.append((identity, value))
        else:
            registry_corruption = PermissionError(
                "materializer evaluation registry was corrupted during scrub"
            )
            if type(envelope_registration) is _MaterializerEnvelopeRegistration:
                _scrub_rejected_materializer_child(envelope_registration)
    envelope_counts: dict[int, int] = {}
    for _identity, value in candidates:
        envelope_identity = id(value[2])
        envelope_counts[envelope_identity] = envelope_counts.get(envelope_identity, 0) + 1
    retained: list[
        tuple[
            int,
            tuple[
                _BatchCapability,
                _ManifestCapability,
                _PublicMaterializationEnvelope,
                str,
            ],
        ]
    ] = []
    for identity, value in candidates:
        if envelope_counts[id(value[2])] == 1:
            retained.append((identity, value))
        else:
            registry_corruption = PermissionError(
                "materializer evaluation registry has aliased envelope ownership"
            )
            envelope_registration = envelope_registrations.get(id(value[2]))
            if type(envelope_registration) is _MaterializerEnvelopeRegistration:
                _scrub_rejected_materializer_child(envelope_registration)
    retained_envelope_identities = {id(value[2]) for _identity, value in retained}
    for envelope_identity, envelope_registration in envelope_registrations.items():
        if type(envelope_registration.state) is not str:
            registry_corruption = PermissionError(
                "materializer evaluation envelope state is malformed"
            )
            _scrub_rejected_materializer_child(envelope_registration)
            continue
        if envelope_registration.state != "evaluated":
            continue
        if envelope_registration.evaluation_hashes is None:
            registry_corruption = PermissionError(
                "materializer evaluated envelope lacks its exact evaluation binding"
            )
            _scrub_rejected_materializer_child(envelope_registration)
            continue
        root = roots.get(id(envelope_registration.vault))
        if (
            type(root) is not _MaterializerVaultRegistration
            or type(root.ledger) is not _AccessLedger
            or type(root.vault) is not _MaterializerSplitVault
            or type(root.ledger._record) is not dict
            or type(root.ledger._record.get("splits")) is not dict
            or any(type(key) is not str for key in root.ledger._record.get("splits"))
        ):
            continue
        ledger_state = root.ledger._record["splits"].get(root.vault.split)
        if type(ledger_state) is not dict:
            continue
        batch_index = envelope_registration.envelope.ordinals[0] // BATCH_SIZE
        durable_receipts = ledger_state.get("public_batch_receipts")
        active_batch = ledger_state.get("public_active_batch")
        pending = bool(
            type(durable_receipts) is list
            and (
                (
                    batch_index == len(durable_receipts)
                    and type(active_batch) is list
                    and len(active_batch) == BATCH_SIZE
                    and all(type(ordinal) is int for ordinal in active_batch)
                    and active_batch == list(envelope_registration.envelope.ordinals)
                )
                or (
                    batch_index + 1 == len(durable_receipts)
                    and active_batch is None
                    and type(root.state) is str
                    and root.state == "checking_public_commit"
                )
            )
        )
        if pending != (envelope_identity in retained_envelope_identities):
            registry_corruption = PermissionError(
                "materializer evaluation registry is not a complete pending-envelope bijection"
            )
            _scrub_rejected_materializer_child(envelope_registration)
            retained = [item for item in retained if id(item[1][2]) != envelope_identity]
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.clear()
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.update(retained)
    return registry_corruption


def _quarantine_malformed_materializer_vault_slot_registry() -> PermissionError | None:
    registry_corruption: PermissionError | None = None
    expected_slots: dict[tuple[int, Split], int] = {}
    duplicate_slots: set[tuple[int, Split]] = set()
    for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items()):
        root_is_exact = _exact_materializer_vault_root_registration(
            identity,
            registration,
        )
        # Root quarantine can preserve a terminal ownership witness while a
        # frozen vault/envelope scalar is still carrying the detected mutation.
        # Keep an already-existing reverse slot in that state: the deep
        # tombstone cut remains false until the scalar itself is restored, but
        # quarantine must not destroy an otherwise authentic ownership edge.
        root_is_quarantined_terminal = bool(
            type(identity) is int
            and type(registration) is _MaterializerVaultRegistration
            and type(registration.vault) is _MaterializerSplitVault
            and id(registration.vault) == identity
            and type(registration.ledger) is _AccessLedger
            and type(registration.vault.split) is str
            and registration.vault.split in SPLITS
            and type(registration.binding) is tuple
            and type(registration.state) is str
            and registration.state in MATERIALIZER_TERMINAL_VAULT_STATES
            and registration.terminal_marker is _MATERIALIZER_VAULT_TERMINAL_MARKER
        )
        if not root_is_exact and not root_is_quarantined_terminal:
            registry_corruption = PermissionError(
                "materializer vault slot root was corrupted during scrub"
            )
            continue
        slot = (id(registration.ledger), registration.vault.split)
        if slot in expected_slots:
            duplicate_slots.add(slot)
            registry_corruption = PermissionError(
                "materializer vault slot registry has duplicate root ownership"
            )
        else:
            expected_slots[slot] = identity
    for slot in duplicate_slots:
        expected_slots.pop(slot, None)

    retained_slots: list[tuple[tuple[int, Split], int]] = []
    seen_slots: set[tuple[int, Split]] = set()
    for slot, vault_identity in tuple(_MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.items()):
        if (
            type(slot) is tuple
            and len(slot) == 2
            and type(slot[0]) is int
            and type(slot[1]) is str
            and slot[1] in SPLITS
            and type(vault_identity) is int
            and slot not in seen_slots
            and expected_slots.get(slot) == vault_identity
        ):
            retained_slots.append((slot, vault_identity))
            seen_slots.add(slot)
        else:
            registry_corruption = PermissionError(
                "materializer vault slot registry was corrupted during scrub"
            )
    if seen_slots != set(expected_slots):
        registry_corruption = PermissionError(
            "materializer vault slot registry is incomplete during scrub"
        )
    _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.clear()
    _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.update(retained_slots)
    return registry_corruption


def _exact_materializer_vault_root_registration(
    identity: object,
    registration: object,
) -> bool:
    if (
        type(identity) is not int
        or type(registration) is not _MaterializerVaultRegistration
        or type(registration.vault) is not _MaterializerSplitVault
        or id(registration.vault) != identity
        or type(registration.port) is not _TrustedMaterializerPort
        or type(registration.ledger) is not _AccessLedger
        or type(registration.ledger._record) is not dict
        or type(registration.ledger._record.get("splits")) is not dict
        or type(registration.envelopes) is not list
        or any(
            type(envelope) is not _PublicMaterializationEnvelope
            for envelope in registration.envelopes
        )
        or len({id(envelope) for envelope in registration.envelopes}) != len(registration.envelopes)
        or type(registration.sensor_batches) is not list
        or any(type(batch) is not _PublicSensorBatch for batch in registration.sensor_batches)
        or len({id(batch) for batch in registration.sensor_batches})
        != len(registration.sensor_batches)
        or type(registration.task_batches) is not list
        or any(type(batch) is not _SafeTaskBatch for batch in registration.task_batches)
        or len({id(batch) for batch in registration.task_batches}) != len(registration.task_batches)
        or type(registration.rows) is not list
        or any(type(row) is not _SealedMaterializationRow for row in registration.rows)
        or len({id(row) for row in registration.rows}) != len(registration.rows)
        or len(registration.envelopes) != len(registration.sensor_batches)
        or len(registration.envelopes) != len(registration.task_batches)
        or type(registration.next_ordinal) is not int
        or registration.next_ordinal < 0
        or registration.next_ordinal > SCENES_PER_SPLIT
        or registration.next_ordinal % BATCH_SIZE
        or (
            registration.commitment_inventory_sha256 is not None
            and (
                type(registration.commitment_inventory_sha256) is not str
                or len(registration.commitment_inventory_sha256) != 64
                or any(
                    character not in "0123456789abcdef"
                    for character in registration.commitment_inventory_sha256
                )
            )
        )
        or (
            registration.private_request is not None
            and type(registration.private_request) is not PrivateSplitScoringRequest
        )
        or (
            registration.private_request_binding is not None
            and type(registration.private_request_binding) is not tuple
        )
        or (registration.private_request is None) != (registration.private_request_binding is None)
        or type(registration.binding) is not tuple
        or type(registration.state) is not str
        or registration.state
        not in MATERIALIZER_LIVE_VAULT_STATES | MATERIALIZER_TERMINAL_VAULT_STATES
        or type(registration.vault.port_identity) is not int
        or type(registration.vault.ledger_identity) is not int
        or registration.vault.port_identity != id(registration.port)
        or registration.vault.ledger_identity != id(registration.ledger)
    ):
        return False
    early_states = {
        "collecting_public",
        "checking_public_issue",
        "checking_public_evaluation",
        "checking_public_commit",
        "checking_public_finalize",
    }
    finalized_states = {
        "public_finalized",
        "checking_public_seal",
        "public_sealed",
        "checking_private_bind",
    }
    private_states = {"private_consuming", "checking_private_complete"}
    if registration.state in early_states and (
        registration.commitment_inventory_sha256 is not None
        or registration.private_request is not None
        or registration.private_request_binding is not None
    ):
        return False
    if registration.state in finalized_states and (
        not _exact_lower_sha256(registration.commitment_inventory_sha256)
        or registration.private_request is not None
        or registration.private_request_binding is not None
    ):
        return False
    if registration.state in private_states and (
        not _exact_lower_sha256(registration.commitment_inventory_sha256)
        or type(registration.private_request) is not PrivateSplitScoringRequest
        or type(registration.private_request_binding) is not tuple
    ):
        return False
    if registration.state in MATERIALIZER_TERMINAL_VAULT_STATES and (
        registration.commitment_inventory_sha256 is not None
        or registration.private_request is not None
        or registration.private_request_binding is not None
    ):
        return False
    split_states = registration.ledger._record.get("splits")
    if type(split_states) is not dict or any(type(key) is not str for key in split_states):
        return False
    try:
        binding_matches = _exact_native_binding_equal(
            registration.binding,
            _materializer_vault_binding(registration.vault),
        )
        private_binding_matches = bool(
            registration.private_request is None
            or _exact_native_binding_equal(
                registration.private_request_binding,
                _materializer_private_request_binding(registration.private_request),
            )
        )
    except BaseException:
        return False
    if not binding_matches or not private_binding_matches:
        return False
    envelope_registrations = {
        child_identity: child
        for child_identity, child in tuple(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items())
        if type(child_identity) is int and type(child) is _MaterializerEnvelopeRegistration
    }
    sensor_registrations = {
        child_identity: child
        for child_identity, child in tuple(_PUBLIC_SENSOR_BATCH_REGISTRY.items())
        if type(child_identity) is int and type(child) is _MaterializerTensorBatchRegistration
    }
    task_registrations = {
        child_identity: child
        for child_identity, child in tuple(_SAFE_TASK_BATCH_REGISTRY.items())
        if type(child_identity) is int and type(child) is _MaterializerTensorBatchRegistration
    }
    row_registrations = {
        child_identity: child
        for child_identity, child in tuple(_SEALED_MATERIALIZATION_ROW_REGISTRY.items())
        if type(child_identity) is int and type(child) is _MaterializerRowRegistration
    }
    terminal = registration.state in MATERIALIZER_TERMINAL_VAULT_STATES
    ledger_state = split_states.get(registration.vault.split)
    if type(ledger_state) is not dict or any(type(key) is not str for key in ledger_state):
        return False
    durable_next_ordinal = ledger_state.get("public_next_ordinal")
    durable_active_batch = ledger_state.get("public_active_batch")
    if (
        type(durable_next_ordinal) is not int
        or durable_next_ordinal < 0
        or durable_next_ordinal > SCENES_PER_SPLIT
        or durable_next_ordinal % BATCH_SIZE
        or (
            durable_active_batch is not None
            and (
                type(durable_active_batch) is not list
                or len(durable_active_batch) != BATCH_SIZE
                or any(type(ordinal) is not int for ordinal in durable_active_batch)
            )
        )
    ):
        return False
    durable_batch_count = durable_next_ordinal // BATCH_SIZE
    if terminal:
        terminal_next_ordinals = {durable_next_ordinal}
        if durable_active_batch is not None:
            terminal_next_ordinals.add(durable_next_ordinal + BATCH_SIZE)
        evaluated_batch_count = registration.next_ordinal // BATCH_SIZE
        if (
            registration.next_ordinal not in terminal_next_ordinals
            or registration.next_ordinal > SCENES_PER_SPLIT
            or evaluated_batch_count > len(registration.envelopes)
            or len(registration.envelopes) not in {evaluated_batch_count, evaluated_batch_count + 1}
        ):
            return False
    else:
        if len(registration.envelopes) not in {
            durable_batch_count,
            durable_batch_count + 1,
        }:
            return False
        if len(registration.envelopes) == durable_batch_count + 1:
            if durable_active_batch is None:
                return False
        elif durable_active_batch is not None and registration.state not in {
            "collecting_public",
            "checking_public_issue",
        }:
            return False
    owned_envelope_identities: set[int] = set()
    envelope_row_identities: set[int] = set()
    expected_root_rows: list[_SealedMaterializationRow] = []
    derived_evaluated_batch_count = 0
    for batch_index, (envelope, sensor_batch, task_batch) in enumerate(
        zip(
            registration.envelopes,
            registration.sensor_batches,
            registration.task_batches,
            strict=True,
        )
    ):
        try:
            _materializer_envelope_binding(envelope)
            _materializer_tensor_batch_binding(sensor_batch)
            _materializer_tensor_batch_binding(task_batch)
        except BaseException:
            return False
        envelope_registration = envelope_registrations.get(id(envelope))
        sensor_registration = sensor_registrations.get(id(sensor_batch))
        task_registration = task_registrations.get(id(task_batch))
        expected_ordinals = tuple(range(batch_index * BATCH_SIZE, (batch_index + 1) * BATCH_SIZE))
        if (
            type(envelope_registration) is not _MaterializerEnvelopeRegistration
            or envelope_registration.envelope is not envelope
            or envelope_registration.port is not registration.port
            or envelope_registration.vault is not registration.vault
            or envelope.port_identity != id(registration.port)
            or envelope.vault_identity != id(registration.vault)
            or envelope.split != registration.vault.split
            or envelope.owner_thread != registration.vault.owner_thread
            or type(sensor_registration) is not _MaterializerTensorBatchRegistration
            or sensor_registration.batch is not sensor_batch
            or sensor_registration.port is not registration.port
            or sensor_registration.vault is not registration.vault
            or sensor_registration.envelope is not envelope
            or type(task_registration) is not _MaterializerTensorBatchRegistration
            or task_registration.batch is not task_batch
            or task_registration.port is not registration.port
            or task_registration.vault is not registration.vault
            or task_registration.envelope is not envelope
            or sensor_batch.port_identity != id(registration.port)
            or sensor_batch.vault_identity != id(registration.vault)
            or sensor_batch.split != registration.vault.split
            or sensor_batch.ordinals != expected_ordinals
            or sensor_batch.owner_thread != registration.vault.owner_thread
            or task_batch.port_identity != id(registration.port)
            or task_batch.vault_identity != id(registration.vault)
            or task_batch.split != registration.vault.split
            or task_batch.ordinals != expected_ordinals
            or task_batch.owner_thread != registration.vault.owner_thread
            or type(envelope_registration.rows) is not tuple
            or len(envelope_registration.rows) != BATCH_SIZE
            or envelope.ordinals != expected_ordinals
            or (
                not terminal
                and (
                    envelope_registration.sensor_batch is not sensor_batch
                    or envelope_registration.task_batch is not task_batch
                )
            )
        ):
            return False
        owned_envelope_identities.add(id(envelope))
        for row_index, row in enumerate(envelope_registration.rows):
            try:
                _materializer_row_binding(row)
            except BaseException:
                return False
            row_registration = row_registrations.get(id(row))
            if (
                type(row_registration) is not _MaterializerRowRegistration
                or row_registration.row is not row
                or row_registration.envelope is not envelope
                or row_registration.vault is not registration.vault
                or row.port_identity != id(registration.port)
                or row.vault_identity != id(registration.vault)
                or row.envelope_identity != id(envelope)
                or row.split != registration.vault.split
                or row.ordinal != expected_ordinals[row_index]
                or row.owner_thread != registration.vault.owner_thread
            ):
                return False
            envelope_row_identities.add(id(row))
        if terminal:
            expected_terminal_child_state = (
                "retired" if registration.state == "consumed" else "revoked"
            )
            if (
                envelope_registration.state != "retired"
                or envelope_registration.request is not None
                or envelope_registration.sensor_batch is not None
                or envelope_registration.task_batch is not None
                or envelope_registration.runtime_tensors is not None
                or envelope_registration.public_bodies is not None
                or envelope_registration.blinding_nonces is not None
                or envelope_registration.evaluation_hashes is not None
                or envelope_registration.evaluation_hashes_binding_sha256 is not None
                or sensor_registration.state != expected_terminal_child_state
                or sensor_registration.tensors is not None
                or task_registration.state != expected_terminal_child_state
                or task_registration.tensors is not None
                or any(
                    row_registrations[id(row)].state != expected_terminal_child_state
                    for row in envelope_registration.rows
                )
            ):
                return False
            if batch_index < evaluated_batch_count:
                expected_root_rows.extend(envelope_registration.rows)
        else:
            expected_child_state = (
                "public_finalized"
                if registration.state
                in {
                    "public_finalized",
                    "public_sealed",
                    "checking_public_seal",
                    "checking_private_bind",
                    "private_consuming",
                    "checking_private_complete",
                }
                else "evaluated"
                if batch_index < durable_batch_count
                else envelope_registration.state
            )
            if batch_index == durable_batch_count and (
                durable_active_batch != list(expected_ordinals)
                or type(envelope_registration.state) is not str
                or envelope_registration.state not in {"issued", "evaluated"}
                or (
                    registration.state == "checking_public_commit"
                    and envelope_registration.state != "evaluated"
                )
                or (
                    registration.state in {"checking_public_issue", "checking_public_evaluation"}
                    and envelope_registration.state != "issued"
                )
            ):
                return False
            if (
                envelope_registration.state != expected_child_state
                or sensor_registration.state != expected_child_state
                or task_registration.state != expected_child_state
                or any(
                    row_registrations[id(row)].state != expected_child_state
                    for row in envelope_registration.rows
                )
            ):
                return False
            if envelope_registration.state in {"evaluated", "public_finalized"}:
                derived_evaluated_batch_count += 1
                expected_root_rows.extend(envelope_registration.rows)
    if not terminal and registration.next_ordinal != (derived_evaluated_batch_count * BATCH_SIZE):
        return False
    if len(registration.rows) != len(expected_root_rows) or any(
        actual is not expected
        for actual, expected in zip(registration.rows, expected_root_rows, strict=True)
    ):
        return False
    if any(
        child.vault is registration.vault and child_identity not in owned_envelope_identities
        for child_identity, child in envelope_registrations.items()
    ):
        return False
    if registration.state in MATERIALIZER_TERMINAL_VAULT_STATES:
        return registration.terminal_marker is _MATERIALIZER_VAULT_TERMINAL_MARKER
    return registration.terminal_marker is None


def _quarantine_malformed_materializer_vault_registry() -> PermissionError | None:
    registry_corruption: PermissionError | None = None
    retained_vaults: list[tuple[int, _MaterializerVaultRegistration]] = []
    for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items()):
        if _exact_materializer_vault_root_registration(identity, registration):
            retained_vaults.append((identity, registration))
            continue
        registry_corruption = PermissionError(
            "materializer vault registry was corrupted during scrub"
        )
        if type(identity) is not int:
            continue
        preserved_registration_binding = (
            registration.binding
            if type(registration) is _MaterializerVaultRegistration
            and type(registration.binding) is tuple
            else None
        )
        registration_was_terminal = bool(
            type(registration) is _MaterializerVaultRegistration
            and type(registration.state) is str
            and registration.state in MATERIALIZER_TERMINAL_VAULT_STATES
        )
        binding_was_native = bool(
            type(preserved_registration_binding) is tuple
            and len(preserved_registration_binding) == 6
            and type(preserved_registration_binding[0]) is int
            and type(preserved_registration_binding[1]) is int
            and type(preserved_registration_binding[2]) is str
            and preserved_registration_binding[2] in SPLITS
            and type(preserved_registration_binding[3]) is int
            and type(preserved_registration_binding[4]) is int
            and type(preserved_registration_binding[5]) is int
        )
        binding_was_exact = False
        if (
            type(registration) is _MaterializerVaultRegistration
            and type(registration.vault) is _MaterializerSplitVault
            and type(preserved_registration_binding) is tuple
        ):
            with contextlib.suppress(BaseException):
                binding_was_exact = _exact_native_binding_equal(
                    preserved_registration_binding,
                    _materializer_vault_binding(registration.vault),
                )
        durable_split_was_present = False
        durable_progress_was_committed = False
        if (
            type(registration) is _MaterializerVaultRegistration
            and type(registration.ledger) is _AccessLedger
            and type(registration.ledger._record) is dict
            and type(registration.ledger._record.get("splits")) is dict
            and type(registration.vault) is _MaterializerSplitVault
            and type(registration.vault.split) is str
        ):
            durable_state = registration.ledger._record["splits"].get(registration.vault.split)
            durable_split_was_present = type(durable_state) is dict
            durable_progress_was_committed = bool(
                durable_split_was_present
                and type(durable_state.get("public_next_ordinal")) is int
                and durable_state["public_next_ordinal"] > 0
            )
        preserve_malformed_binding = bool(
            binding_was_native or registration_was_terminal or durable_progress_was_committed
        )
        if type(registration) is _MaterializerVaultRegistration:
            with contextlib.suppress(BaseException):
                _scrub_materializer_vault(registration, state="failed")
            if _exact_materializer_vault_root_registration(identity, registration):
                retained_vaults.append((identity, registration))
                continue
            # Preserve the same terminal root when its ownership skeleton is
            # still exact.  Rebuilding its ordered inventories here would erase
            # the corruption witness (for example a reordered row prefix) and
            # let test-only disposal accept state that has not been restored.
            if (
                type(registration.vault) is _MaterializerSplitVault
                and id(registration.vault) == identity
                and (
                    type(registration.port) is _TrustedMaterializerPort or registration_was_terminal
                )
                and type(registration.ledger) is _AccessLedger
                and type(registration.envelopes) is list
                and all(
                    type(envelope) is _PublicMaterializationEnvelope
                    for envelope in registration.envelopes
                )
                and type(registration.sensor_batches) is list
                and all(type(batch) is _PublicSensorBatch for batch in registration.sensor_batches)
                and type(registration.task_batches) is list
                and all(type(batch) is _SafeTaskBatch for batch in registration.task_batches)
                and type(registration.rows) is list
                and all(type(row) is _SealedMaterializationRow for row in registration.rows)
                and (
                    durable_split_was_present
                    or registration.envelopes
                    or registration.sensor_batches
                    or registration.task_batches
                    or registration.rows
                    or any(
                        type(vault_identity) is int and vault_identity == identity
                        for vault_identity in _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.values()
                    )
                )
                and type(registration.binding) is tuple
                and (binding_was_exact or preserve_malformed_binding)
                and type(registration.state) is str
                and registration.state in MATERIALIZER_TERMINAL_VAULT_STATES
                and registration.terminal_marker is _MATERIALIZER_VAULT_TERMINAL_MARKER
            ):
                retained_vaults.append((identity, registration))
                continue
        envelope_registrations = [
            child
            for child in _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.values()
            if type(child) is _MaterializerEnvelopeRegistration
            and (
                id(child.vault) == identity
                or (
                    type(child.envelope) is _PublicMaterializationEnvelope
                    and type(child.envelope.vault_identity) is int
                    and child.envelope.vault_identity == identity
                )
            )
        ]
        envelope_identities = {id(child.envelope) for child in envelope_registrations}
        sensor_registrations = [
            child
            for child in _PUBLIC_SENSOR_BATCH_REGISTRY.values()
            if type(child) is _MaterializerTensorBatchRegistration
            and (
                id(child.vault) == identity
                or id(child.envelope) in envelope_identities
                or (
                    type(child.batch) is _PublicSensorBatch
                    and type(child.batch.vault_identity) is int
                    and child.batch.vault_identity == identity
                )
            )
        ]
        task_registrations = [
            child
            for child in _SAFE_TASK_BATCH_REGISTRY.values()
            if type(child) is _MaterializerTensorBatchRegistration
            and (
                id(child.vault) == identity
                or id(child.envelope) in envelope_identities
                or (
                    type(child.batch) is _SafeTaskBatch
                    and type(child.batch.vault_identity) is int
                    and child.batch.vault_identity == identity
                )
            )
        ]
        row_registrations = [
            child
            for child in _SEALED_MATERIALIZATION_ROW_REGISTRY.values()
            if type(child) is _MaterializerRowRegistration
            and (
                id(child.vault) == identity
                or id(child.envelope) in envelope_identities
                or (
                    type(child.row) is _SealedMaterializationRow
                    and type(child.row.vault_identity) is int
                    and child.row.vault_identity == identity
                )
            )
        ]
        retained_evaluations = []
        for evaluation_identity, evaluation_registration in tuple(
            _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.items()
        ):
            if (
                type(evaluation_identity) is not int
                or type(evaluation_registration) is not tuple
                or len(evaluation_registration) != 4
                or type(evaluation_registration[0]) is not _BatchCapability
                or type(evaluation_registration[1]) is not _ManifestCapability
                or type(evaluation_registration[2]) is not _PublicMaterializationEnvelope
                or type(evaluation_registration[2].vault_identity) is not int
                or type(evaluation_registration[3]) is not str
            ):
                registry_corruption = PermissionError(
                    "materializer evaluation registry was corrupted during scrub"
                )
            elif evaluation_registration[2].vault_identity != identity:
                retained_evaluations.append((evaluation_identity, evaluation_registration))
        _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.clear()
        _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.update(retained_evaluations)
        for child in envelope_registrations:
            if child.request is not None:
                with contextlib.suppress(BaseException):
                    _revoke_materialization_authorities(child.request)
            child.request = None
            child.sensor_batch = None
            child.task_batch = None
            child.runtime_tensors = None
            child.public_bodies = None
            child.blinding_nonces = None
            child.evaluation_hashes = None
            child.evaluation_hashes_binding_sha256 = None
            child.state = "retired"
        for child in (*sensor_registrations, *task_registrations):
            child.tensors = None
            child.state = "revoked"
        for child in row_registrations:
            child.state = "revoked"
        if envelope_registrations:
            envelope_inventory_is_orderable = all(
                type(child.envelope) is _PublicMaterializationEnvelope
                and type(child.envelope.ordinals) is tuple
                and len(child.envelope.ordinals) == BATCH_SIZE
                and all(type(ordinal) is int for ordinal in child.envelope.ordinals)
                for child in envelope_registrations
            )
            ordered_envelope_registrations = (
                sorted(
                    envelope_registrations,
                    key=lambda child: child.envelope.ordinals[0],
                )
                if envelope_inventory_is_orderable
                else []
            )
            vault = (
                registration.vault
                if type(registration) is _MaterializerVaultRegistration
                and type(registration.vault) is _MaterializerSplitVault
                and id(registration.vault) == identity
                else envelope_registrations[0].vault
            )
            port = (
                registration.port
                if type(registration) is _MaterializerVaultRegistration
                and type(registration.port) is _TrustedMaterializerPort
                else envelope_registrations[0].port
            )
            port_registration = _TRUSTED_MATERIALIZER_PORT_REGISTRY.get(id(port))
            # Preserve the pre-corruption root witness.  Re-deriving this tuple
            # from a mutated frozen capability would bless the attacker value
            # and make test-only terminal disposal indistinguishable from a
            # genuinely authenticated tombstone.
            reconstructed_binding = (
                preserved_registration_binding if preserve_malformed_binding else None
            )
            if (
                reconstructed_binding is None
                and type(vault) is _MaterializerSplitVault
                and type(port) is _TrustedMaterializerPort
                and type(port_registration) is _MaterializerPortRegistration
                and type(port_registration.ledger) is _AccessLedger
                and vault.port_identity == id(port)
                and vault.ledger_identity == id(port_registration.ledger)
                and vault.owner_thread == threading.get_ident()
            ):
                # If the root value itself was replaced, its binding is no
                # longer available to preserve.  The still-factory-sealed
                # vault capability, exact child ownership, and exact port /
                # ledger reverse links jointly authenticate reconstruction.
                # Existing malformed roots never take this path, so their
                # original binding remains the corruption witness.
                with contextlib.suppress(BaseException):
                    reconstructed_binding = _materializer_vault_binding(vault)
            if (
                type(vault) is _MaterializerSplitVault
                and id(vault) == identity
                and type(port) is _TrustedMaterializerPort
                and type(port_registration) is _MaterializerPortRegistration
                and type(port_registration.ledger) is _AccessLedger
                and type(reconstructed_binding) is tuple
                and ordered_envelope_registrations
            ):
                reconstructed_next_ordinal = (
                    registration.next_ordinal
                    if type(registration) is _MaterializerVaultRegistration
                    and type(registration.next_ordinal) is int
                    and 0 <= registration.next_ordinal <= SCENES_PER_SPLIT
                    and not registration.next_ordinal % BATCH_SIZE
                    and registration.next_ordinal
                    <= len(ordered_envelope_registrations) * BATCH_SIZE
                    else 0
                )
                ordered_sensor_batches: list[_PublicSensorBatch] = []
                ordered_task_batches: list[_SafeTaskBatch] = []
                ordered_rows: list[_SealedMaterializationRow] = []
                for batch_index, envelope_registration in enumerate(ordered_envelope_registrations):
                    sensor_matches = [
                        child.batch
                        for child in sensor_registrations
                        if child.envelope is envelope_registration.envelope
                        and type(child.batch) is _PublicSensorBatch
                    ]
                    task_matches = [
                        child.batch
                        for child in task_registrations
                        if child.envelope is envelope_registration.envelope
                        and type(child.batch) is _SafeTaskBatch
                    ]
                    if len(sensor_matches) != 1 or len(task_matches) != 1:
                        ordered_sensor_batches = []
                        ordered_task_batches = []
                        ordered_rows = []
                        break
                    ordered_sensor_batches.append(sensor_matches[0])
                    ordered_task_batches.append(task_matches[0])
                    if batch_index < reconstructed_next_ordinal // BATCH_SIZE:
                        ordered_rows.extend(envelope_registration.rows)
                if len(ordered_sensor_batches) != len(ordered_envelope_registrations):
                    continue
                retained_vaults.append(
                    (
                        identity,
                        _MaterializerVaultRegistration(
                            vault=vault,
                            port=port,
                            ledger=port_registration.ledger,
                            envelopes=[child.envelope for child in ordered_envelope_registrations],
                            sensor_batches=ordered_sensor_batches,
                            task_batches=ordered_task_batches,
                            rows=ordered_rows,
                            next_ordinal=reconstructed_next_ordinal,
                            commitment_inventory_sha256=None,
                            private_request=None,
                            private_request_binding=None,
                            binding=reconstructed_binding,
                            terminal_marker=_MATERIALIZER_VAULT_TERMINAL_MARKER,
                            state="failed",
                        ),
                    )
                )
    if registry_corruption is not None:
        _MATERIALIZER_SPLIT_VAULT_REGISTRY.clear()
        _MATERIALIZER_SPLIT_VAULT_REGISTRY.update(retained_vaults)
    slot_registry_error = _quarantine_malformed_materializer_vault_slot_registry()
    if slot_registry_error is not None:
        registry_corruption = slot_registry_error
    return registry_corruption


def _materializer_vault_matches_expected_port(
    registration: _MaterializerVaultRegistration,
    *,
    port: _TrustedMaterializerPort,
    ledger: _AccessLedger | None,
) -> bool:
    if (
        type(registration) is not _MaterializerVaultRegistration
        or type(port) is not _TrustedMaterializerPort
        or (ledger is not None and type(ledger) is not _AccessLedger)
    ):
        return False
    if registration.port is port or (ledger is not None and registration.ledger is ledger):
        return True
    vault = registration.vault
    if type(vault) is not _MaterializerSplitVault:
        return False
    if type(vault.port_identity) is int and vault.port_identity == id(port):
        return True
    if ledger is None:
        return False
    if type(vault.ledger_identity) is int and vault.ledger_identity == id(ledger):
        return True
    return any(
        type(slot) is tuple
        and len(slot) == 2
        and type(slot[0]) is int
        and type(vault_identity) is int
        and slot[0] == id(ledger)
        and vault_identity == id(vault)
        for slot, vault_identity in _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.items()
    )


def _materializer_vault_is_owned_by_port(
    registration: _MaterializerVaultRegistration,
    port_registration: _MaterializerPortRegistration,
    *,
    expected_port: _TrustedMaterializerPort | None = None,
) -> bool:
    if type(port_registration) is not _MaterializerPortRegistration:
        return False
    port = port_registration.port if expected_port is None else expected_port
    return _materializer_vault_matches_expected_port(
        registration,
        port=port,
        ledger=(
            port_registration.ledger if type(port_registration.ledger) is _AccessLedger else None
        ),
    )


def _burn_materializer_core_capabilities(
    *,
    ledger: _AccessLedger,
    split: str | None,
    owner_witness: tuple[
        _ManifestCapability,
        _BatchCapability,
        _BatchRegistration,
        tuple[_OrdinalCapability, ...],
        tuple[tuple[_OrdinalCapability, _BatchRegistration, str], ...],
    ]
    | None = None,
) -> PermissionError | None:
    """Retire one ledger/split capability cut before fail-burn returns."""

    if type(ledger) is not _AccessLedger or (
        split is not None and (type(split) is not str or split not in SPLITS)
    ):
        raise PermissionError("materializer core burn owner is forged")
    witnessed_manifest: _ManifestCapability | None = None
    witnessed_batch: _BatchCapability | None = None
    witnessed_registration: _BatchRegistration | None = None
    witnessed_tokens: tuple[_OrdinalCapability, ...] = ()
    witnessed_token_registrations: tuple[
        tuple[_OrdinalCapability, _BatchRegistration, str], ...
    ] = ()
    if owner_witness is not None:
        if (
            type(owner_witness) is not tuple
            or len(owner_witness) != 5
            or type(owner_witness[0]) is not _ManifestCapability
            or type(owner_witness[1]) is not _BatchCapability
            or type(owner_witness[2]) is not _BatchRegistration
            or type(owner_witness[3]) is not tuple
            or len(owner_witness[3]) != BATCH_SIZE
            or any(type(token) is not _OrdinalCapability for token in owner_witness[3])
            or type(owner_witness[4]) is not tuple
            or len(owner_witness[4]) != BATCH_SIZE
            or any(
                type(value) is not tuple
                or len(value) != 3
                or type(value[0]) is not _OrdinalCapability
                or type(value[1]) is not _BatchRegistration
                or type(value[2]) is not str
                for value in owner_witness[4]
            )
        ):
            raise PermissionError("materializer core burn witness is forged")
        (
            witnessed_manifest,
            witnessed_batch,
            witnessed_registration,
            witnessed_tokens,
            witnessed_token_registrations,
        ) = owner_witness
    core_error, _ports, batches, tokens, consumed = _partition_exact_materializer_core_registries()
    owned_batch_registrations = {
        id(registration): registration
        for registration in batches.values()
        if registration.manifest._ledger is ledger
        and (split is None or registration.manifest.split == split)
    }
    if witnessed_registration is not None:
        owned_batch_registrations[id(witnessed_registration)] = witnessed_registration
    for _token, registration, _state in tokens.values():
        if (
            registration.manifest._ledger is ledger
            and (split is None or registration.manifest.split == split)
            or witnessed_batch is not None
            and registration.batch is witnessed_batch
            or witnessed_registration is not None
            and registration is witnessed_registration
        ):
            owned_batch_registrations[id(registration)] = registration
    owned_manifests: dict[int, _ManifestCapability] = {
        id(registration.manifest): registration.manifest
        for registration in owned_batch_registrations.values()
    }
    if witnessed_manifest is not None:
        owned_manifests[id(witnessed_manifest)] = witnessed_manifest
    retained_evaluations: list[
        tuple[
            int,
            tuple[
                _BatchCapability,
                _ManifestCapability,
                _PublicMaterializationEnvelope,
                str,
            ],
        ]
    ] = []
    for identity, value in tuple(_MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.items()):
        if (
            type(identity) is not int
            or type(value) is not tuple
            or len(value) != 4
            or type(value[0]) is not _BatchCapability
            or type(value[1]) is not _ManifestCapability
            or type(value[2]) is not _PublicMaterializationEnvelope
            or not _exact_lower_sha256(value[3])
        ):
            core_error = PermissionError(
                "materializer evaluation registry was corrupted during core burn"
            )
            continue
        if (
            value[1]._ledger is ledger
            and (split is None or value[1].split == split)
            or witnessed_batch is not None
            and value[0] is witnessed_batch
            or witnessed_manifest is not None
            and value[1] is witnessed_manifest
        ):
            owned_manifests[id(value[1])] = value[1]
            continue
        retained_evaluations.append((identity, value))
    retained_batches = [
        (identity, registration)
        for identity, registration in batches.items()
        if id(registration) not in owned_batch_registrations
        and (witnessed_batch is None or registration.batch is not witnessed_batch)
        and (witnessed_manifest is None or registration.manifest is not witnessed_manifest)
    ]
    retained_tokens = [
        (identity, registration)
        for identity, registration in tokens.items()
        if id(registration[1]) not in owned_batch_registrations
        and not any(registration[0] is token for token in witnessed_tokens)
        and (witnessed_batch is None or registration[1].batch is not witnessed_batch)
        and (witnessed_manifest is None or registration[1].manifest is not witnessed_manifest)
    ]
    retained_consumed = [
        (identity, registration)
        for identity, registration in consumed.items()
        if not (
            registration[1]._manifest._ledger is ledger
            and (split is None or registration[1].split == split)
            or witnessed_batch is not None
            and registration[1]._batch is witnessed_batch
            or witnessed_manifest is not None
            and registration[1]._manifest is witnessed_manifest
            or any(registration[0].token is token for token in witnessed_tokens)
        )
    ]
    for registration in owned_batch_registrations.values():
        registration.status = "revoked"
    for manifest in owned_manifests.values():
        manifest._active = None
    _BATCH_REGISTRY.clear()
    _BATCH_REGISTRY.update(retained_batches)
    _TOKEN_REGISTRY.clear()
    _TOKEN_REGISTRY.update(retained_tokens)
    _CONSUMED_ORDINAL_REGISTRY.clear()
    _CONSUMED_ORDINAL_REGISTRY.update(retained_consumed)
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.clear()
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.update(retained_evaluations)
    # The witness records are captured before an external durable callback.
    # They may already have been removed or replaced in the global maps, but
    # they remain the exact capabilities that this transaction must burn.
    if witnessed_registration is not None:
        witnessed_registration.status = "revoked"
    for token_registration in witnessed_token_registrations:
        if token_registration[1] is witnessed_registration:
            witnessed_registration.status = "revoked"
    if witnessed_manifest is not None:
        witnessed_manifest._active = None
    return core_error


def _raise_materializer_registry_corruption(
    error: BaseException,
    *,
    ledger: _AccessLedger,
    port: _TrustedMaterializerPort | None = None,
) -> None:
    cleanup_error: BaseException | None = None
    completed_cleanup_error: BaseException | None = None
    for registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
        if type(registration) is not _MaterializerVaultRegistration or (
            registration.ledger is not ledger
            and (
                port is None
                or not _materializer_vault_matches_expected_port(
                    registration,
                    port=port,
                    ledger=ledger,
                )
            )
        ):
            continue
        if _materializer_vault_requires_cleanup(registration):
            try:
                _fail_materializer_vault(
                    registration,
                    preserve_registered_binding=True,
                )
            except BaseException as caught:
                try:
                    cleanup_is_incomplete = _materializer_vault_requires_cleanup(registration)
                except BaseException:
                    cleanup_is_incomplete = True
                if cleanup_is_incomplete:
                    cleanup_error = caught
                else:
                    completed_cleanup_error = caught
        registration_port = registration.port
        if type(registration_port) is _TrustedMaterializerPort:
            port_registration = _TRUSTED_MATERIALIZER_PORT_REGISTRY.get(id(registration_port))
            if type(port_registration) is _MaterializerPortRegistration:
                port_registration.state = "failed"
    if port is not None:
        port_registration = _TRUSTED_MATERIALIZER_PORT_REGISTRY.get(id(port))
        if type(port_registration) is _MaterializerPortRegistration:
            port_registration.state = "failed"
    # A registry-cut failure burns every still-live capability owned by this
    # ledger.  Retaining a relationally valid alias would otherwise make every
    # later cut fail again and leave a retryable reserved batch behind.
    burn_error = _burn_materializer_core_capabilities(
        ledger=ledger,
        split=None,
    )
    _core_error, ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    for port_registration in ports.values():
        if port_registration.ledger is ledger and port_registration.state == "active":
            port_registration.state = "failed"
    if cleanup_error is None and burn_error is not None:
        completed_cleanup_error = burn_error
    if cleanup_error is not None:
        raise error from cleanup_error
    if completed_cleanup_error is not None:
        raise error from completed_cleanup_error
    raise error


def _validated_materializer_global_registry_cut(
    *,
    ledger: _AccessLedger | None,
    port: _TrustedMaterializerPort | None = None,
) -> tuple[
    dict[int, _MaterializerPortRegistration],
    dict[int, _BatchRegistration],
    dict[int, tuple[_OrdinalCapability, _BatchRegistration, str]],
    dict[int, tuple[_ConsumedOrdinalAuthority, PublicBatchEvaluationRequest, set[str]]],
]:
    """Authenticate one complete hook-free materializer registry cut."""

    if ledger is not None and type(ledger) is not _AccessLedger:
        raise PermissionError("materializer registry cut ledger is forged")
    if port is not None and type(port) is not _TrustedMaterializerPort:
        raise PermissionError("materializer registry cut port is forged")
    error, ports, batches, tokens, consumed = _partition_exact_materializer_core_registries()
    vault_error = _quarantine_malformed_materializer_vault_registry()
    if vault_error is not None:
        described_vault_error = PermissionError(
            f"materializer vault registry was corrupted: {vault_error}"
        )
        error = (
            described_vault_error
            if error is None
            else PermissionError(f"{error}; {described_vault_error}")
        )
    child_error = _quarantine_malformed_materializer_child_registries()
    if child_error is not None:
        error = child_error if error is None else PermissionError(f"{error}; {child_error}")
    # Child quarantine can reveal that a previously exact root inventory was
    # only exact because it referenced a cross-bound child.  Revalidate roots
    # after that destructive cut so the surviving graph is terminally exact.
    post_child_vault_error = _quarantine_malformed_materializer_vault_registry()
    if post_child_vault_error is not None:
        described_vault_error = PermissionError(
            f"materializer vault registry was corrupted: {post_child_vault_error}"
        )
        error = (
            described_vault_error
            if error is None
            else PermissionError(f"{error}; {described_vault_error}")
        )
    # Repartition after child/root fail-closing so the returned capability
    # snapshots describe the exact surviving global cut.
    core_error, ports, batches, tokens, consumed = _partition_exact_materializer_core_registries()
    if core_error is not None:
        error = core_error if error is None else PermissionError(f"{error}; {core_error}")

    active_port_owners: set[int] = set()
    for registration in ports.values():
        if registration.state != "active":
            continue
        owner = id(registration.ledger)
        if owner in active_port_owners:
            error = PermissionError("active materializer port registry has duplicate ownership")
        active_port_owners.add(owner)
    for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items()):
        if not _exact_materializer_vault_root_registration(identity, registration):
            root_error = PermissionError("materializer vault root registry was corrupted")
            error = root_error if error is None else PermissionError(f"{error}; {root_error}")
            continue
        port_registration = ports.get(id(registration.port))
        if (
            type(port_registration) is not _MaterializerPortRegistration
            or port_registration.port is not registration.port
            or port_registration.ledger is not registration.ledger
        ):
            reverse_error = PermissionError("materializer port/vault reverse bijection differs")
            error = reverse_error if error is None else PermissionError(f"{error}; {reverse_error}")

    issued_request_counts: dict[int, int] = {}
    for envelope_registration in tuple(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.values()):
        if (
            type(envelope_registration) is not _MaterializerEnvelopeRegistration
            or type(envelope_registration.state) is not str
            or envelope_registration.state != "issued"
        ):
            continue
        request = envelope_registration.request
        if type(request) is not PublicBatchEvaluationRequest:
            error = PermissionError("issued materializer envelope lacks one exact request")
            continue
        issued_request_counts[id(request)] = issued_request_counts.get(id(request), 0) + 1
        root = _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(id(envelope_registration.vault))
        batch_registration = batches.get(id(request._batch))
        matches = [
            (authority, variants)
            for authority, candidate, variants in consumed.values()
            if candidate is request
        ]
        if (
            type(request.split) is not str
            or request.split not in SPLITS
            or type(request.ordinals) is not tuple
            or len(request.ordinals) != BATCH_SIZE
            or any(type(ordinal) is not int for ordinal in request.ordinals)
            or type(request.tokens) is not tuple
            or len(request.tokens) != BATCH_SIZE
            or any(type(token) is not _OrdinalCapability for token in request.tokens)
            or type(request._manifest) is not _ManifestCapability
            or type(request._batch) is not _BatchCapability
            or type(root) is not _MaterializerVaultRegistration
            or root.vault is not envelope_registration.vault
            or root.port is not envelope_registration.port
            or request._manifest._ledger is not root.ledger
            or request._manifest.split != root.vault.split
            or request._manifest._active is not request._batch
            or type(batch_registration) is not _BatchRegistration
            or batch_registration.batch is not request._batch
            or batch_registration.manifest is not request._manifest
            or request.split != envelope_registration.envelope.split
            or request.split != request._batch.split
            or request.ordinals != envelope_registration.envelope.ordinals
            or request.ordinals != request._batch.ordinals
            or any(
                actual is not expected
                for actual, expected in zip(
                    request.tokens,
                    request._batch.tokens,
                    strict=True,
                )
            )
            or len(matches) != BATCH_SIZE
            or {authority.ordinal for authority, _variants in matches} != set(request.ordinals)
            or len({id(authority.token) for authority, _variants in matches}) != BATCH_SIZE
            or any(variants != {"base", "palette"} for _authority, variants in matches)
            or any(
                authority.token is not request.tokens[request.ordinals.index(authority.ordinal)]
                for authority, _variants in matches
            )
        ):
            error = PermissionError("issued materializer envelope authority inventory differs")
    if any(count != 1 for count in issued_request_counts.values()):
        error = PermissionError("issued materializer requests have duplicate envelope ownership")
    grouped_unissued_requests: dict[int, PublicBatchEvaluationRequest] = {}
    for _authority, request, _variants in consumed.values():
        if id(request) in issued_request_counts:
            continue
        grouped_unissued_requests[id(request)] = request
    for request in grouped_unissued_requests.values():
        matching_roots = [
            root
            for root in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
            if type(root) is _MaterializerVaultRegistration
            and root.ledger is request._manifest._ledger
            and root.vault.split == request.split
            and type(root.state) is str
            and root.state == "checking_public_issue"
        ]
        request_authorities = [
            (authority, variants)
            for authority, candidate, variants in consumed.values()
            if candidate is request
        ]
        if (
            len(matching_roots) != 1
            or type(request._batch) is not _BatchCapability
            or type(request._manifest) is not _ManifestCapability
            or request._manifest._active is not request._batch
            or batches.get(id(request._batch)) is None
            or not 1 <= len(request_authorities) <= BATCH_SIZE
            or len({authority.ordinal for authority, _ in request_authorities})
            != len(request_authorities)
            or any(
                authority.ordinal not in request.ordinals
                or authority.token is not request.tokens[request.ordinals.index(authority.ordinal)]
                for authority, _ in request_authorities
            )
            or any(
                variants not in ({"base", "palette"}, {"palette"})
                for _authority, variants in request_authorities
            )
        ):
            error = PermissionError(
                "consumed materializer request is orphaned from its issue transaction"
            )

    if ledger is not None:
        ledger_has_active_materializer_port = any(
            registration.ledger is ledger and registration.state == "active"
            for registration in ports.values()
        )
        for registration in batches.values():
            if registration.manifest._ledger is not ledger:
                continue
            matching_roots = [
                root
                for root in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
                if type(root) is _MaterializerVaultRegistration
                and root.ledger is ledger
                and root.vault.split == registration.manifest.split
            ]
            root_slot_is_exact = bool(
                len(matching_roots) == 1
                and _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(
                    (id(ledger), registration.manifest.split)
                )
                == id(matching_roots[0].vault)
            )
            if (
                len(matching_roots) > 1
                or ledger_has_active_materializer_port
                and not root_slot_is_exact
            ):
                active_root_error = PermissionError(
                    "active batch lacks one exact materializer vault/slot ownership"
                )
                error = (
                    active_root_error
                    if error is None
                    else PermissionError(f"{error}; {active_root_error}")
                )
    if error is not None:
        if ledger is not None:
            _raise_materializer_registry_corruption(
                error,
                ledger=ledger,
                port=port,
            )
        raise error
    return ports, batches, tokens, consumed


def _trusted_materializer_port_registration(
    port: _TrustedMaterializerPort,
    *,
    evaluator: object | None = None,
    expected_state: str = "active",
) -> _MaterializerPortRegistration:
    if type(port) is not _TrustedMaterializerPort:
        raise PermissionError("materializer port is forged")
    registry_error, ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    registration = ports.get(id(port))
    if registry_error is not None:
        if type(registration) is _MaterializerPortRegistration:
            registration.state = "failed"
        cleanup_error: BaseException | None = None
        recovered_ledger: _AccessLedger | None = None
        for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
            if (
                type(vault_registration) is _MaterializerVaultRegistration
                and type(vault_registration.vault) is _MaterializerSplitVault
                and (
                    vault_registration.port is port
                    or (
                        type(vault_registration.vault.port_identity) is int
                        and vault_registration.vault.port_identity == id(port)
                    )
                )
            ):
                if type(vault_registration.ledger) is _AccessLedger:
                    if recovered_ledger is None:
                        recovered_ledger = vault_registration.ledger
                    elif recovered_ledger is not vault_registration.ledger:
                        cleanup_error = PermissionError(
                            "materializer port registry recovery found multiple ledgers"
                        )
                try:
                    _scrub_materializer_vault(vault_registration, state="failed")
                except BaseException as caught:
                    cleanup_error = caught
        if recovered_ledger is not None:
            _raise_materializer_registry_corruption(
                registry_error,
                ledger=recovered_ledger,
                port=port,
            )
        if cleanup_error is not None:
            raise cleanup_error
        raise registry_error
    if type(registration) is not _MaterializerPortRegistration:
        cleanup_error: BaseException | None = None
        for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
            if _materializer_vault_matches_expected_port(
                vault_registration,
                port=port,
                ledger=None,
            ) and _materializer_vault_requires_cleanup(vault_registration):
                try:
                    _scrub_materializer_vault(vault_registration, state="failed")
                except BaseException as error:
                    cleanup_error = error
        _TRUSTED_MATERIALIZER_PORT_REGISTRY.pop(id(port), None)
        if cleanup_error is not None:
            raise cleanup_error
        raise PermissionError("materializer port binding differs")
    _validated_materializer_global_registry_cut(
        ledger=registration.ledger,
        port=port,
    )
    if registration.port is not port:
        cleanup_error: BaseException | None = None
        try:
            for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
                if _materializer_vault_is_owned_by_port(
                    vault_registration,
                    registration,
                    expected_port=port,
                ) and _materializer_vault_requires_cleanup(vault_registration):
                    try:
                        _scrub_materializer_vault(
                            vault_registration,
                            state="failed",
                        )
                    except BaseException as error:
                        cleanup_error = error
        finally:
            registration.state = "failed"
        if cleanup_error is not None:
            raise cleanup_error
        raise PermissionError("materializer port binding differs")
    if (
        type(registration.ledger) is not _AccessLedger
        or type(registration.authority) is not _MaterializerConstructionAuthority
        or type(registration.config) is not dict
        or type(registration.binding) is not tuple
    ):
        cleanup_error = None
        try:
            for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
                if _materializer_vault_is_owned_by_port(
                    vault_registration,
                    registration,
                    expected_port=port,
                ) and _materializer_vault_requires_cleanup(vault_registration):
                    try:
                        _scrub_materializer_vault(
                            vault_registration,
                            state="failed",
                        )
                    except BaseException as error:
                        cleanup_error = error
        finally:
            registration.state = "failed"
        if cleanup_error is not None:
            raise cleanup_error
        raise PermissionError("materializer port binding differs")
    registration_state = registration.state
    if type(registration_state) is not str or registration_state != expected_state:
        for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
            if _materializer_vault_is_owned_by_port(
                vault_registration,
                registration,
                expected_port=port,
            ) and _materializer_vault_requires_cleanup(vault_registration):
                _scrub_materializer_vault(vault_registration, state="failed")
        raise PermissionError("materializer port binding differs")
    try:
        ledger = registration.ledger
        if (
            type(ledger._owner_thread) is not int
            or type(ledger.stage) is not str
            or ledger.stage not in {"development", "qualification"}
            or type(ledger._pin) is not _PinnedDirectory
            or type(ledger.path) is not _NATIVE_PATH_TYPE
        ):
            raise PermissionError("materializer port ledger scalars differ")
        _materializer_construction_authority_binding(registration.authority)
        if (
            not _exact_native_binding_equal(
                registration.binding,
                _trusted_materializer_port_binding(port),
            )
            or (evaluator is not None and registration.evaluator is not evaluator)
            or port.owner_thread != threading.get_ident()
            or port.owner_thread != registration.ledger._owner_thread
            or port.stage != registration.ledger.stage
            or port.construction_authority_identity != id(registration.authority)
            or port.construction_authority_nonce is not registration.authority.nonce
            or port.ledger_identity != id(registration.ledger)
            or port.directory_pin is not registration.ledger._pin
            or port.ledger_path != registration.ledger.path
            or port.ledger_file_identity != registration.authority.ledger_file_identity
            or port.ledger_generation != registration.authority.ledger_generation
            or port.ledger_record_sha256 != registration.authority.ledger_record_sha256
            or port.config_identity != id(registration.config)
            or port.config_sha256 != _materializer_config_sha256(registration.config)
        ):
            raise PermissionError("materializer port binding differs")
        registration.ledger._verify_disk()
    except BaseException:
        if type(registration.state) is not str or registration.state == "active":
            registration.state = "failed"
        for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
            if _materializer_vault_is_owned_by_port(
                vault_registration,
                registration,
                expected_port=port,
            ) and _materializer_vault_requires_cleanup(vault_registration):
                _scrub_materializer_vault(vault_registration, state="failed")
        raise
    return registration


def _materializer_vault_registration(
    vault: _MaterializerSplitVault,
    *,
    port: _TrustedMaterializerPort,
    expected_states: frozenset[str],
) -> _MaterializerVaultRegistration:
    if type(vault) is not _MaterializerSplitVault:
        raise PermissionError("materializer split vault is forged")
    port_registration = _trusted_materializer_port_registration(port)
    registry_error = _quarantine_malformed_materializer_child_registries()
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        registry_error = vault_registry_error
    if registry_error is not None:
        _raise_materializer_registry_corruption(
            registry_error,
            ledger=port_registration.ledger,
            port=port,
        )
    registration = _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(id(vault))
    if (
        type(registration) is not _MaterializerVaultRegistration
        or registration.vault is not vault
        or registration.port is not port
        or registration.ledger is not port_registration.ledger
        or type(registration.state) is not str
        or registration.state not in expected_states
    ):
        raise PermissionError("materializer split vault binding differs")
    slot_identity = _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(
        (id(registration.ledger), vault.split)
    )
    if (
        not _exact_native_binding_equal(
            registration.binding,
            _materializer_vault_binding(vault),
        )
        or vault.port_identity != id(port)
        or vault.ledger_identity != id(registration.ledger)
        or vault.owner_thread != threading.get_ident()
        or vault.owner_thread != port.owner_thread
        or vault.split not in SPLITS
        or type(slot_identity) is not int
        or slot_identity != id(vault)
    ):
        _scrub_materializer_vault(registration, state="failed")
        port_registration.state = "failed"
        raise PermissionError("materializer split vault binding differs")
    return registration


def _open_materializer_split_vault(
    port: _TrustedMaterializerPort,
    *,
    split: Split,
) -> _MaterializerSplitVault:
    port_registration = _trusted_materializer_port_registration(port)
    ledger = port_registration.ledger
    registry_error = _quarantine_malformed_materializer_child_registries()
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        registry_error = vault_registry_error
    if registry_error is not None:
        _raise_materializer_registry_corruption(
            registry_error,
            ledger=ledger,
            port=port,
        )
    if type(split) is not str or split not in SPLITS or split not in ledger._record["splits"]:
        raise ValueError("materializer vault split differs")
    state = ledger._record["splits"][split]
    slot = (id(ledger), split)
    if (
        state["status"] != "public_evaluating"
        or state["public_next_ordinal"] != 0
        or state["public_active_batch"] is not None
        or slot in _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY
        or any(
            registration.ledger is ledger and _materializer_vault_requires_cleanup(registration)
            for registration in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
        )
    ):
        raise PermissionError("materializer vault requires one newly opened public split")
    vault = _MaterializerSplitVault(
        port_identity=id(port),
        ledger_identity=id(ledger),
        split=split,
        owner_thread=threading.get_ident(),
        nonce=object(),
        _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
    )
    if id(vault) in _MATERIALIZER_SPLIT_VAULT_REGISTRY:
        raise PermissionError("materializer vault identity already exists")
    registration = _MaterializerVaultRegistration(
        vault=vault,
        port=port,
        ledger=ledger,
        envelopes=[],
        sensor_batches=[],
        task_batches=[],
        rows=[],
        next_ordinal=0,
        commitment_inventory_sha256=None,
        private_request=None,
        private_request_binding=None,
        binding=_materializer_vault_binding(vault),
        terminal_marker=None,
        state="collecting_public",
    )
    _MATERIALIZER_SPLIT_VAULT_REGISTRY[id(vault)] = registration
    _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY[slot] = id(vault)
    return vault


def _validated_materializer_blinding_nonces(
    value: Any,
) -> tuple[bytes, bytes, bytes, bytes]:
    if (
        type(value) is not tuple
        or len(value) != BATCH_SIZE
        or any(type(item) is not bytes or len(item) != 32 for item in value)
        or len(set(value)) != BATCH_SIZE
    ):
        raise ValueError("materializer blinding nonces must be four distinct 32-byte values")
    return value


def _generate_materializer_blinding_nonces(
    *,
    _urandom: Any = os.urandom,
) -> tuple[bytes, bytes, bytes, bytes]:
    return _validated_materializer_blinding_nonces(tuple(_urandom(32) for _ in range(BATCH_SIZE)))


def _validated_materializer_issue_payload(
    *,
    split: Split,
    ordinals: tuple[int, int, int, int],
    sensor_tensors: Mapping[str, Any],
    safe_task_tensors: Mapping[str, Any],
    public_runtime_tensors: Mapping[str, Any],
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    tuple[bytes, bytes, bytes, bytes],
]:
    _require_materializer_source_tensor_metadata(
        sensor_tensors,
        (
            ("rgb", (BATCH_SIZE, HISTORY_FRAME_COUNT, 3, 64, 64), torch.float32),
            ("depth", (BATCH_SIZE, HISTORY_FRAME_COUNT, 1, 64, 64), torch.float32),
            ("timestamps", (BATCH_SIZE, HISTORY_FRAME_COUNT), torch.float32),
            (
                "world_from_camera",
                (BATCH_SIZE, HISTORY_FRAME_COUNT, 4, 4),
                torch.float32,
            ),
            ("intrinsics", (BATCH_SIZE, HISTORY_FRAME_COUNT, 3, 3), torch.float32),
        ),
        label="public sensor tensor",
    )
    _require_materializer_source_tensor_metadata(
        safe_task_tensors,
        (
            ("observable_handle_prototype", (BATCH_SIZE, 3), torch.float32),
            (
                "candidate_timestamps",
                (BATCH_SIZE, CANDIDATE_COUNT),
                torch.float32,
            ),
            (
                "candidate_impulses_world",
                (BATCH_SIZE, CANDIDATE_COUNT, 3),
                torch.float32,
            ),
            ("goal_positions_world", (BATCH_SIZE, 3), torch.float32),
            ("opposite_goal_positions_world", (BATCH_SIZE, 3), torch.float32),
            ("alternate_handle_prototype", (BATCH_SIZE, 3), torch.float32),
        ),
        label="safe task tensor",
    )
    horizon_count = len(HORIZONS_SECONDS)
    _require_materializer_source_tensor_metadata(
        public_runtime_tensors,
        (
            ("resolved_persistent_id", (BATCH_SIZE,), torch.int64),
            ("persistent_id_by_slot", (BATCH_SIZE, 2), torch.int64),
            (
                "candidate_positions",
                (BATCH_SIZE, CANDIDATE_COUNT, horizon_count, 2, 3),
                torch.float32,
            ),
            (
                "candidate_velocities",
                (BATCH_SIZE, CANDIDATE_COUNT, horizon_count, 2, 3),
                torch.float32,
            ),
            (
                "candidate_total_cost",
                (BATCH_SIZE, CANDIDATE_COUNT),
                torch.float32,
            ),
            ("selected_display_index", (BATCH_SIZE,), torch.int64),
            (
                "none_positions",
                (BATCH_SIZE, horizon_count, 2, 3),
                torch.float32,
            ),
            (
                "none_velocities",
                (BATCH_SIZE, horizon_count, 2, 3),
                torch.float32,
            ),
        ),
        label="public runtime tensor",
    )
    _materializer_tensor_storage_inventory(
        {
            "runtime": public_runtime_tensors,
            "sensors": sensor_tensors,
            "tasks": safe_task_tensors,
        },
        label="materializer input",
    )
    sensor_clones = _clone_materializer_tensor_mapping(sensor_tensors)
    task_clones = _clone_materializer_tensor_mapping(safe_task_tensors)
    runtime_clones = _clone_materializer_tensor_mapping(public_runtime_tensors)
    _materializer_tensor_storage_inventory(
        {
            "input_runtime": public_runtime_tensors,
            "input_sensors": sensor_tensors,
            "input_tasks": safe_task_tensors,
            "retained_runtime": runtime_clones,
            "retained_sensors": sensor_clones,
            "retained_tasks": task_clones,
        },
        label="materializer input/retained cut",
    )
    sensor_clones = _validated_public_sensor_tensors(sensor_clones)
    task_clones = _validated_safe_task_batch_tensors(task_clones)
    runtime_clones = _validated_public_runtime_tensors(runtime_clones)
    _materializer_tensor_storage_inventory(
        {
            "runtime": runtime_clones,
            "sensors": sensor_clones,
            "tasks": task_clones,
        },
        label="materializer clone",
    )
    _validate_exact_materializer_safe_rows(
        task_clones,
        split=split,
        ordinals=ordinals,
    )
    if not bool(
        task_clones["candidate_timestamps"].gt(sensor_clones["timestamps"][:, -1, None]).all()
    ):
        raise ValueError("candidate actions must be strictly post-anchor")
    action_offsets = task_clones["candidate_timestamps"][:, 0] - sensor_clones["timestamps"][:, -1]
    ordinal_stratum_size = SCENES_PER_SPLIT // len(ACTION_OFFSETS_SECONDS)
    expected_offsets = torch.tensor(
        [ACTION_OFFSETS_SECONDS[ordinal // ordinal_stratum_size] for ordinal in ordinals],
        dtype=torch.float32,
    )
    if not torch.allclose(action_offsets, expected_offsets, rtol=0.0, atol=1.0e-7):
        raise ValueError("candidate action timestamps differ from the exact B=4 offsets")
    return (
        sensor_clones,
        task_clones,
        runtime_clones,
        _generate_materializer_blinding_nonces(),
    )


def _materializer_public_surface_body(
    *,
    port: _TrustedMaterializerPort,
    split: Split,
    ordinal: int,
    row_index: int,
    token_receipt_sha256: str,
    sensor_tensors: Mapping[str, Any],
    safe_task_tensors: Mapping[str, Any],
    public_runtime_tensors: Mapping[str, Any],
) -> dict[str, Any]:
    return _validated_public_materialization_surface(
        {
            "schema": "rgbd_known_action_public_materialization_surface_v1",
            "split": split,
            "ordinal": ordinal,
            "batch_index": ordinal // BATCH_SIZE,
            "fixed_goal_horizon_seconds": MATERIALIZER_FIXED_GOAL_HORIZON_SECONDS,
            "materializer_port_sha256": _materializer_port_public_sha256(port),
            "token_receipt_sha256": token_receipt_sha256,
            "sensor_sha256": _materializer_row_tensor_sha256(
                sensor_tensors,
                row_index=row_index,
                namespace="sensor",
                keys=PUBLIC_SENSOR_TENSOR_KEYS,
            ),
            "safe_task_sha256": _materializer_row_tensor_sha256(
                safe_task_tensors,
                row_index=row_index,
                namespace="safe_task",
                keys=SAFE_TASK_TENSOR_KEYS,
            ),
            "public_runtime_sha256": _materializer_row_tensor_sha256(
                public_runtime_tensors,
                row_index=row_index,
                namespace="public_runtime",
                keys=PUBLIC_RUNTIME_TENSOR_KEYS,
            ),
        }
    )


def _issue_public_materialization_envelope(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    request: PublicBatchEvaluationRequest,
    *,
    sensor_tensors: Mapping[str, Any],
    safe_task_tensors: Mapping[str, Any],
    public_runtime_tensors: Mapping[str, Any],
    preauthorized_token_receipts: Sequence[Mapping[str, Any]] | None = None,
    evaluation: Mapping[str, Any] | None = None,
) -> _PublicMaterializationEnvelope:
    direct_evaluation = preauthorized_token_receipts is not None and evaluation is not None
    if (preauthorized_token_receipts is None) != (evaluation is None):
        raise ValueError(
            "preauthorized materialization requires token receipts and evaluation together"
        )
    vault_registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset(
            {"checking_public_issue"} if direct_evaluation else {"collecting_public"}
        ),
    )
    ledger = vault_registration.ledger
    if type(request) is not PublicBatchEvaluationRequest:
        raise PermissionError("materializer envelope requires one exact public request")
    expected_ordinals = tuple(
        range(vault_registration.next_ordinal, vault_registration.next_ordinal + BATCH_SIZE)
    )
    if (
        type(request.split) is not str
        or request.split not in SPLITS
        or type(request.ordinals) is not tuple
        or len(request.ordinals) != BATCH_SIZE
        or any(type(ordinal) is not int for ordinal in request.ordinals)
        or type(request.tokens) is not tuple
        or len(request.tokens) != BATCH_SIZE
        or any(type(token) is not _OrdinalCapability for token in request.tokens)
        or type(request._manifest) is not _ManifestCapability
        or type(request._batch) is not _BatchCapability
        or type(request._batch.ordinals) is not tuple
        or len(request._batch.ordinals) != BATCH_SIZE
        or any(type(ordinal) is not int for ordinal in request._batch.ordinals)
    ):
        raise PermissionError("materializer request/vault/ledger batch binding differs")
    batch_registration = _BATCH_REGISTRY.get(id(request._batch))
    token_registrations = tuple(_TOKEN_REGISTRY.get(id(token)) for token in request.tokens)
    expected_token_state = "consumed" if direct_evaluation else "issued"
    state = ledger._record["splits"][vault.split]
    if (
        request.split != vault.split
        or request._manifest._ledger is not ledger
        or request._manifest.split != vault.split
        or request.ordinals != expected_ordinals
        or request._batch.ordinals != expected_ordinals
        or request._manifest._active is not request._batch
        or batch_registration is None
        or batch_registration.batch is not request._batch
        or batch_registration.manifest is not request._manifest
        or any(
            request_token is not batch_token
            for request_token, batch_token in zip(
                request.tokens,
                request._batch.tokens,
                strict=True,
            )
        )
        or any(
            type(token_registration) is not tuple
            or len(token_registration) != 3
            or token_registration[0] is not request.tokens[index]
            or token_registration[1] is not batch_registration
            or type(token_registration[2]) is not str
            or token_registration[2] != expected_token_state
            for index, token_registration in enumerate(token_registrations)
        )
        or type(batch_registration.status) is not str
        or batch_registration.status != "issued"
        or (direct_evaluation and batch_registration.consumed != set(expected_ordinals))
        or (not direct_evaluation and bool(batch_registration.consumed))
        or state["status"] != "public_evaluating"
        or state["public_next_ordinal"] != vault_registration.next_ordinal
        or state["public_active_batch"] != list(expected_ordinals)
        or len(vault_registration.envelopes) != vault_registration.next_ordinal // BATCH_SIZE
    ):
        raise PermissionError("materializer request/vault/ledger batch binding differs")
    failure_owner = _capture_materializer_failure_owner(vault_registration)
    core_owner_witness = (
        request._manifest,
        request._batch,
        batch_registration,
        request.tokens,
        token_registrations,
    )
    authorities: tuple[_ConsumedOrdinalAuthority, ...] = ()
    vault_registration.state = "checking_public_issue"
    try:
        (
            sensor_clones,
            task_clones,
            runtime_clones,
            nonce_values,
        ) = _validated_materializer_issue_payload(
            split=vault.split,
            ordinals=expected_ordinals,
            sensor_tensors=sensor_tensors,
            safe_task_tensors=safe_task_tensors,
            public_runtime_tensors=public_runtime_tensors,
        )
        nonce_sha256s = tuple(sha256_bytes(value) for value in nonce_values)
        if any(value in _MATERIALIZER_BLINDING_NONCE_SHA256_REGISTRY for value in nonce_sha256s):
            raise PermissionError("materializer blinding nonce was replayed")
        _MATERIALIZER_BLINDING_NONCE_SHA256_REGISTRY.update(nonce_sha256s)
        if direct_evaluation:
            if (
                type(preauthorized_token_receipts) not in {list, tuple}
                or len(preauthorized_token_receipts) != BATCH_SIZE
            ):
                raise TypeError(
                    "preauthorized materialization token receipts must be one B=4 sequence"
                )
            reservation = ledger.record
            token_receipts = tuple(
                _validated_token_receipt(
                    copy.deepcopy(dict(item)),
                    split=vault.split,
                    ordinal=expected_ordinals[index],
                )
                for index, item in enumerate(preauthorized_token_receipts)
            )
            if any(
                receipt["reservation_generation"] != reservation["generation"]
                or receipt["reservation_sha256"] != canonical_sha256(reservation)
                or receipt["capability_nonce"] != request._batch.capability_nonces[index]
                for index, receipt in enumerate(token_receipts)
            ):
                raise PermissionError("preauthorized materialization token receipt binding differs")
        else:
            authorities = _authorize_formal_batch(request)
            token_receipts = tuple(copy.deepcopy(item.token_receipt) for item in authorities)
        token_hashes = tuple(
            validated_sha256(item["receipt_sha256"], label="materializer token receipt")
            for item in token_receipts
        )
        public_bodies: list[dict[str, Any]] = []
        public_hashes: list[str] = []
        commitments: list[str] = []
        for row_index, ordinal in enumerate(expected_ordinals):
            body = _materializer_public_surface_body(
                port=port,
                split=vault.split,
                ordinal=ordinal,
                row_index=row_index,
                token_receipt_sha256=token_hashes[row_index],
                sensor_tensors=sensor_clones,
                safe_task_tensors=task_clones,
                public_runtime_tensors=runtime_clones,
            )
            public_bodies.append(body)
            public_hashes.append(canonical_sha256(body))
            commitments.append(_blinded_materialization_commitment(body, nonce_values[row_index]))
        sensor_batch = _PublicSensorBatch(
            port_identity=id(port),
            vault_identity=id(vault),
            split=vault.split,
            ordinals=expected_ordinals,
            owner_thread=threading.get_ident(),
            nonce=object(),
            _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
        )
        task_batch = _SafeTaskBatch(
            port_identity=id(port),
            vault_identity=id(vault),
            split=vault.split,
            ordinals=expected_ordinals,
            fixed_goal_horizon_seconds=MATERIALIZER_FIXED_GOAL_HORIZON_SECONDS,
            owner_thread=threading.get_ident(),
            nonce=object(),
            _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
        )
        envelope = _PublicMaterializationEnvelope(
            port_identity=id(port),
            vault_identity=id(vault),
            split=vault.split,
            ordinals=expected_ordinals,
            token_receipt_sha256=token_hashes,
            public_surface_sha256=tuple(public_hashes),
            blinded_commitments=tuple(commitments),
            owner_thread=threading.get_ident(),
            nonce=object(),
            _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
        )
        rows = tuple(
            _SealedMaterializationRow(
                port_identity=id(port),
                vault_identity=id(vault),
                envelope_identity=id(envelope),
                split=vault.split,
                ordinal=ordinal,
                token_receipt_sha256=token_hashes[row_index],
                public_surface_sha256=public_hashes[row_index],
                blinded_commitment=commitments[row_index],
                owner_thread=threading.get_ident(),
                nonce=object(),
                _factory_nonce=_MATERIALIZER_FACTORY_NONCE,
            )
            for row_index, ordinal in enumerate(expected_ordinals)
        )
        identities = {id(sensor_batch), id(task_batch), id(envelope), *(id(row) for row in rows)}
        if len(identities) != 3 + BATCH_SIZE or any(
            identity in registry
            for identity, registry in (
                (id(sensor_batch), _PUBLIC_SENSOR_BATCH_REGISTRY),
                (id(task_batch), _SAFE_TASK_BATCH_REGISTRY),
                (id(envelope), _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY),
                *((id(row), _SEALED_MATERIALIZATION_ROW_REGISTRY) for row in rows),
            )
        ):
            raise PermissionError("materializer envelope identity already exists")
        direct_hashes = (
            _public_materializer_evaluation_hashes(
                evaluation,
                split=vault.split,
                ordinals=expected_ordinals,
            )
            if direct_evaluation
            else None
        )
        if direct_hashes is not None:
            validated_direct_evaluation = _validated_public_batch_evaluation(
                evaluation,
                split=vault.split,
                ordinals=expected_ordinals,
            )
            evidence_rows = validated_direct_evaluation["public_evidence"]["row_receipts"]
            if tuple(row["token_receipt"]["receipt_sha256"] for row in evidence_rows) != tuple(
                token_hashes
            ):
                raise PermissionError("preauthorized public evaluation token receipts differ")
        child_state = "evaluated" if direct_evaluation else "issued"
        sensor_registration = _MaterializerTensorBatchRegistration(
            batch=sensor_batch,
            port=port,
            vault=vault,
            envelope=envelope,
            tensors=sensor_clones,
            binding=_materializer_tensor_batch_binding(sensor_batch),
            state=child_state,
        )
        task_registration = _MaterializerTensorBatchRegistration(
            batch=task_batch,
            port=port,
            vault=vault,
            envelope=envelope,
            tensors=task_clones,
            binding=_materializer_tensor_batch_binding(task_batch),
            state=child_state,
        )
        envelope_registration = _MaterializerEnvelopeRegistration(
            envelope=envelope,
            port=port,
            vault=vault,
            request=None if direct_evaluation else request,
            sensor_batch=sensor_batch,
            task_batch=task_batch,
            runtime_tensors=runtime_clones,
            public_bodies=tuple(public_bodies),
            blinding_nonces=nonce_values,
            rows=rows,
            evaluation_hashes=direct_hashes,
            evaluation_hashes_binding_sha256=(
                canonical_sha256(direct_hashes) if direct_hashes is not None else None
            ),
            binding=_materializer_envelope_binding(envelope),
            state=child_state,
        )
        _PUBLIC_SENSOR_BATCH_REGISTRY[id(sensor_batch)] = sensor_registration
        _SAFE_TASK_BATCH_REGISTRY[id(task_batch)] = task_registration
        _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY[id(envelope)] = envelope_registration
        for row in rows:
            _SEALED_MATERIALIZATION_ROW_REGISTRY[id(row)] = _MaterializerRowRegistration(
                row=row,
                envelope=envelope,
                vault=vault,
                binding=_materializer_row_binding(row),
                state=child_state,
            )
        vault_registration.envelopes.append(envelope)
        vault_registration.sensor_batches.append(sensor_batch)
        vault_registration.task_batches.append(task_batch)
        if direct_hashes is not None:
            vault_registration.rows.extend(rows)
            vault_registration.next_ordinal += BATCH_SIZE
            _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY[id(request._batch)] = (
                request._batch,
                request._manifest,
                envelope,
                direct_hashes["public_evaluation_sha256"],
            )
        vault_registration.state = "collecting_public"
        _validated_materializer_global_registry_cut(
            ledger=ledger,
            port=port,
        )
        return envelope
    except BaseException as error:
        cleanup_error: BaseException | None = None
        # The authorization call can complete its registry transition and then
        # raise before its return value is assigned to ``authorities``.  Sweep
        # by the already-authenticated request identity, never by that local.
        try:
            _retire_failed_materialization_request_capabilities(
                request,
                owner_witness=core_owner_witness,
            )
        except BaseException as caught:
            cleanup_error = caught
        try:
            _fail_materializer_vault(
                vault_registration,
                owner_witness=failure_owner,
                core_owner_witness=core_owner_witness,
            )
        except BaseException as caught:
            cleanup_error = caught
        if cleanup_error is not None:
            raise cleanup_error from error
        raise


def _validated_open_materializer_envelope(
    port: _TrustedMaterializerPort,
    vault_registration: _MaterializerVaultRegistration,
    registration: _MaterializerEnvelopeRegistration,
    *,
    expected_evaluation: Mapping[str, Any] | None = None,
) -> None:
    envelope = registration.envelope
    vault = vault_registration.vault
    if (
        type(registration) is not _MaterializerEnvelopeRegistration
        or type(envelope) is not _PublicMaterializationEnvelope
        or type(vault) is not _MaterializerSplitVault
        or registration.port is not port
        or registration.vault is not vault
        or not _exact_native_binding_equal(
            registration.binding,
            _materializer_envelope_binding(envelope),
        )
        or envelope.port_identity != id(port)
        or envelope.vault_identity != id(vault)
        or envelope.split != vault.split
        or envelope.owner_thread != threading.get_ident()
        or registration.sensor_batch is None
        or registration.task_batch is None
        or registration.runtime_tensors is None
        or type(registration.public_bodies) is not tuple
        or len(registration.public_bodies) != BATCH_SIZE
        or type(registration.blinding_nonces) is not tuple
        or len(registration.blinding_nonces) != BATCH_SIZE
        or type(registration.rows) is not tuple
        or len(registration.rows) != BATCH_SIZE
        or type(registration.state) is not str
        or registration.state not in {"issued", "evaluated", "public_finalized"}
    ):
        raise PermissionError("open materializer envelope binding differs")
    if (
        type(registration.sensor_batch) is not _PublicSensorBatch
        or type(registration.task_batch) is not _SafeTaskBatch
    ):
        raise PermissionError("open materializer tensor batch binding differs")
    sensor_registration = _PUBLIC_SENSOR_BATCH_REGISTRY.get(id(registration.sensor_batch))
    task_registration = _SAFE_TASK_BATCH_REGISTRY.get(id(registration.task_batch))
    if (
        type(sensor_registration) is not _MaterializerTensorBatchRegistration
        or type(task_registration) is not _MaterializerTensorBatchRegistration
        or sensor_registration.batch is not registration.sensor_batch
        or task_registration.batch is not registration.task_batch
        or sensor_registration.port is not port
        or task_registration.port is not port
        or sensor_registration.vault is not vault
        or task_registration.vault is not vault
        or sensor_registration.envelope is not envelope
        or task_registration.envelope is not envelope
        or registration.sensor_batch.port_identity != id(port)
        or registration.sensor_batch.vault_identity != id(vault)
        or registration.sensor_batch.split != vault.split
        or registration.sensor_batch.owner_thread != threading.get_ident()
        or registration.task_batch.port_identity != id(port)
        or registration.task_batch.vault_identity != id(vault)
        or registration.task_batch.split != vault.split
        or registration.task_batch.owner_thread != threading.get_ident()
        or not _exact_native_binding_equal(
            sensor_registration.binding,
            _materializer_tensor_batch_binding(registration.sensor_batch),
        )
        or not _exact_native_binding_equal(
            task_registration.binding,
            _materializer_tensor_batch_binding(registration.task_batch),
        )
        or registration.sensor_batch.ordinals != envelope.ordinals
        or registration.task_batch.ordinals != envelope.ordinals
        or registration.task_batch.fixed_goal_horizon_seconds
        != MATERIALIZER_FIXED_GOAL_HORIZON_SECONDS
        or sensor_registration.tensors is None
        or task_registration.tensors is None
        or type(sensor_registration.state) is not str
        or sensor_registration.state not in {"issued", "evaluated", "public_finalized"}
        or type(task_registration.state) is not str
        or task_registration.state not in {"issued", "evaluated", "public_finalized"}
    ):
        raise PermissionError("open materializer tensor batch binding differs")
    sensors = _validated_public_sensor_tensors(sensor_registration.tensors)
    tasks = _validated_safe_task_batch_tensors(task_registration.tensors)
    runtime = _validated_public_runtime_tensors(registration.runtime_tensors)
    _validate_exact_materializer_safe_rows(
        tasks,
        split=vault.split,
        ordinals=envelope.ordinals,
    )
    _materializer_tensor_storage_inventory(
        {"runtime": runtime, "sensors": sensors, "tasks": tasks},
        label="open materializer envelope",
    )
    expected_nonces = _validated_materializer_blinding_nonces(registration.blinding_nonces)
    if any(
        sha256_bytes(value) not in _MATERIALIZER_BLINDING_NONCE_SHA256_REGISTRY
        for value in expected_nonces
    ):
        raise PermissionError("materializer blinding nonce inventory differs")
    for row_index, (ordinal, row) in enumerate(
        zip(envelope.ordinals, registration.rows, strict=True)
    ):
        row_registration = _SEALED_MATERIALIZATION_ROW_REGISTRY.get(id(row))
        if (
            type(row_registration) is not _MaterializerRowRegistration
            or row_registration.row is not row
            or row_registration.envelope is not envelope
            or row_registration.vault is not vault
            or not _exact_native_binding_equal(
                row_registration.binding,
                _materializer_row_binding(row),
            )
            or row.port_identity != id(port)
            or row.vault_identity != id(vault)
            or row.envelope_identity != id(envelope)
            or row.split != vault.split
            or row.ordinal != ordinal
            or row.owner_thread != threading.get_ident()
            or type(row_registration.state) is not str
            or row_registration.state not in {"issued", "evaluated", "public_finalized"}
        ):
            raise PermissionError("open materializer row binding differs")
        expected_body = _materializer_public_surface_body(
            port=port,
            split=vault.split,
            ordinal=ordinal,
            row_index=row_index,
            token_receipt_sha256=envelope.token_receipt_sha256[row_index],
            sensor_tensors=sensors,
            safe_task_tensors=tasks,
            public_runtime_tensors=runtime,
        )
        _exact_equal(
            registration.public_bodies[row_index],
            expected_body,
            label="open materializer public body",
        )
        expected_public_sha256 = canonical_sha256(expected_body)
        expected_commitment = _blinded_materialization_commitment(
            expected_body,
            expected_nonces[row_index],
        )
        if (
            envelope.public_surface_sha256[row_index] != expected_public_sha256
            or envelope.blinded_commitments[row_index] != expected_commitment
            or row.token_receipt_sha256 != envelope.token_receipt_sha256[row_index]
            or row.public_surface_sha256 != expected_public_sha256
            or row.blinded_commitment != expected_commitment
        ):
            raise PermissionError("open materializer row payload differs")
    if registration.evaluation_hashes is None:
        if (
            registration.evaluation_hashes_binding_sha256 is not None
            or expected_evaluation is not None
        ):
            raise PermissionError("materializer evaluation hash binding is premature")
    else:
        validated_hashes = _validated_public_materializer_evaluation_hashes(
            registration.evaluation_hashes
        )
        if registration.evaluation_hashes_binding_sha256 != canonical_sha256(validated_hashes):
            raise PermissionError("materializer evaluation hash binding differs")
        if expected_evaluation is not None:
            if type(expected_evaluation) is not dict:
                raise TypeError("pending materializer evaluation must be one exact dictionary")
            expected_hashes = _public_materializer_evaluation_hashes(
                expected_evaluation,
                split=vault.split,
                ordinals=envelope.ordinals,
            )
        else:
            batch_index = envelope.ordinals[0] // BATCH_SIZE
            ledger_state = vault_registration.ledger._record["splits"][vault.split]
            durable_receipts = ledger_state["public_batch_receipts"]
            if type(durable_receipts) is not list or len(durable_receipts) <= batch_index:
                raise PermissionError("materializer evaluation lacks its durable public receipt")
            durable_receipt = _validate_batch_receipt(
                durable_receipts[batch_index],
                split=vault.split,
                batch_index=batch_index,
            )
            expected_hashes = _public_materializer_evaluation_hashes(
                durable_receipt["public_evaluation"],
                split=vault.split,
                ordinals=envelope.ordinals,
            )
        if not _exact_native_binding_equal(
            tuple(validated_hashes.items()),
            tuple(expected_hashes.items()),
        ):
            raise PermissionError(
                "materializer evaluation hashes differ from the durable public receipt"
            )


def _validated_formal_materializer_batch_precommit(
    manifest: _ManifestCapability,
    batch: _BatchCapability,
) -> tuple[
    tuple[
        _BatchCapability,
        _ManifestCapability,
        _PublicMaterializationEnvelope,
        str,
    ],
    _MaterializerVaultRegistration,
    _MaterializerEnvelopeRegistration,
]:
    if (
        type(manifest) is not _ManifestCapability
        or type(batch) is not _BatchCapability
        or manifest._ledger._record["execution_mode"] != "formal"
    ):
        raise PermissionError("formal materializer precommit binding differs")
    value = _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.get(id(batch))
    vault_registration: _MaterializerVaultRegistration | None = None
    try:
        if (
            type(value) is not tuple
            or len(value) != 4
            or value[0] is not batch
            or value[1] is not manifest
            or type(value[2]) is not _PublicMaterializationEnvelope
            or not _exact_lower_sha256(value[3])
        ):
            raise PermissionError("formal materializer evaluation binding differs")
        envelope = value[2]
        envelope_registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(id(envelope))
        if type(envelope_registration) is not _MaterializerEnvelopeRegistration:
            raise PermissionError("formal materializer envelope registry differs")
        vault_registration = _materializer_vault_registration(
            envelope_registration.vault,
            port=envelope_registration.port,
            expected_states=frozenset({"collecting_public"}),
        )
        hashes = _validated_public_materializer_evaluation_hashes(
            envelope_registration.evaluation_hashes
        )
        if (
            envelope_registration.envelope is not envelope
            or envelope_registration.request is not None
            or type(envelope_registration.state) is not str
            or envelope_registration.state != "evaluated"
            or vault_registration.ledger is not manifest._ledger
            or envelope.split != manifest.split
            or envelope.ordinals != batch.ordinals
            or hashes["public_evaluation_sha256"] != value[3]
        ):
            raise PermissionError("formal materializer evaluation binding differs")
        return value, vault_registration, envelope_registration
    except BaseException:
        if type(vault_registration) is _MaterializerVaultRegistration:
            _fail_materializer_vault(vault_registration)
        else:
            for candidate in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
                if (
                    type(candidate) is _MaterializerVaultRegistration
                    and candidate.ledger is manifest._ledger
                    and _materializer_vault_requires_cleanup(candidate)
                ):
                    _fail_materializer_vault(candidate)
        raise


def _validated_formal_materializer_before_batch_reserve(
    manifest: _ManifestCapability,
    ordinals: tuple[int, int, int, int],
) -> None:
    if (
        type(manifest) is not _ManifestCapability
        or type(ordinals) is not tuple
        or len(ordinals) != BATCH_SIZE
        or any(type(ordinal) is not int for ordinal in ordinals)
        or type(manifest._ledger) is not _AccessLedger
        or manifest._ledger._record.get("execution_mode") != "formal"
    ):
        raise PermissionError("formal materializer reserve binding differs")
    slot = (id(manifest._ledger), manifest.split)
    vault_identity = _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(slot)
    if vault_identity is None:
        return
    registry_error = _quarantine_malformed_materializer_child_registries()
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        registry_error = vault_registry_error
    if registry_error is not None:
        _raise_materializer_registry_corruption(
            registry_error,
            ledger=manifest._ledger,
        )
    registration = (
        _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(vault_identity)
        if type(vault_identity) is int
        else None
    )
    if (
        type(registration) is not _MaterializerVaultRegistration
        or registration.ledger is not manifest._ledger
        or registration.vault.split != manifest.split
        or registration.state != "collecting_public"
        or registration.next_ordinal != ordinals[0]
        or ordinals != tuple(range(ordinals[0], ordinals[0] + BATCH_SIZE))
        or not _exact_materializer_vault_root_registration(
            id(registration.vault),
            registration,
        )
    ):
        if type(registration) is _MaterializerVaultRegistration:
            _fail_materializer_vault(registration)
        raise PermissionError("formal materializer reserve root binding differs")


def _capture_materializer_failure_owner(
    registration: _MaterializerVaultRegistration,
    *,
    require_exact_binding: bool = True,
) -> tuple[
    _MaterializerSplitVault,
    _TrustedMaterializerPort,
    _AccessLedger,
    _MaterializerPortRegistration,
    str,
    tuple[Any, ...],
]:
    if (
        type(registration) is not _MaterializerVaultRegistration
        or type(registration.vault) is not _MaterializerSplitVault
        or type(registration.vault.port_identity) is not int
        or type(registration.vault.ledger_identity) is not int
        or type(registration.vault.split) is not str
        or registration.vault.split not in SPLITS
    ):
        raise PermissionError("materializer failure owner is forged")
    matching_ports = [
        port_registration
        for identity, port_registration in tuple(_TRUSTED_MATERIALIZER_PORT_REGISTRY.items())
        if type(identity) is int
        and identity == registration.vault.port_identity
        and type(port_registration) is _MaterializerPortRegistration
        and type(port_registration.port) is _TrustedMaterializerPort
        and id(port_registration.port) == registration.vault.port_identity
        and type(port_registration.ledger) is _AccessLedger
        and id(port_registration.ledger) == registration.vault.ledger_identity
    ]
    if len(matching_ports) != 1:
        raise PermissionError("materializer failure owner port is not canonical")
    live_binding = _materializer_vault_binding(registration.vault)
    if require_exact_binding and not _exact_native_binding_equal(
        registration.binding,
        live_binding,
    ):
        raise PermissionError("materializer failure owner root binding differs")
    binding = live_binding
    return (
        registration.vault,
        matching_ports[0].port,
        matching_ports[0].ledger,
        matching_ports[0],
        registration.vault.split,
        binding,
    )


def _fail_materializer_vault(
    registration: _MaterializerVaultRegistration,
    *,
    owner_witness: tuple[
        _MaterializerSplitVault,
        _TrustedMaterializerPort,
        _AccessLedger,
        _MaterializerPortRegistration,
        str,
        tuple[Any, ...],
    ]
    | None = None,
    core_owner_witness: tuple[
        _ManifestCapability,
        _BatchCapability,
        _BatchRegistration,
        tuple[_OrdinalCapability, ...],
        tuple[tuple[_OrdinalCapability, _BatchRegistration, str], ...],
    ]
    | None = None,
    preserve_registered_binding: bool = False,
) -> None:
    if type(registration) is not _MaterializerVaultRegistration:
        raise PermissionError("materializer failure target is not one exact vault registration")
    if type(preserve_registered_binding) is not bool:
        raise TypeError("materializer binding-preservation flag must be bool")
    registered_binding = registration.binding
    explicit_owner_witness = owner_witness is not None
    if owner_witness is None:
        owner_witness = _capture_materializer_failure_owner(
            registration,
            require_exact_binding=False,
        )
        if preserve_registered_binding and type(registered_binding) is tuple:
            owner_witness = (*owner_witness[:-1], registered_binding)
    if (
        type(owner_witness) is not tuple
        or len(owner_witness) != 6
        or type(owner_witness[0]) is not _MaterializerSplitVault
        or type(owner_witness[1]) is not _TrustedMaterializerPort
        or type(owner_witness[2]) is not _AccessLedger
        or type(owner_witness[3]) is not _MaterializerPortRegistration
        or type(owner_witness[4]) is not str
        or owner_witness[4] not in SPLITS
        or type(owner_witness[5]) is not tuple
    ):
        raise PermissionError("materializer failure owner witness is forged")
    (
        witnessed_vault,
        witnessed_port,
        witnessed_ledger,
        witnessed_port_registration,
        split,
        witnessed_binding,
    ) = owner_witness
    registry_error, ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    root_pointer_changed = registration.vault is not witnessed_vault
    port_pointer_changed = registration.port is not witnessed_port
    ledger_pointer_changed = registration.ledger is not witnessed_ledger
    vault = witnessed_vault
    binding = registration.binding
    canonical_root = bool(
        type(vault) is _MaterializerSplitVault
        and any(
            type(identity) is int and identity == id(vault) and candidate is registration
            for identity, candidate in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items())
        )
    )
    try:
        live_vault_binding = _materializer_vault_binding(vault)
    except BaseException:
        live_vault_binding = None
    slot_is_exact = bool(
        any(
            type(slot) is tuple
            and len(slot) == 2
            and type(slot[0]) is int
            and type(slot[1]) is str
            and type(vault_identity) is int
            and slot[0] == id(witnessed_ledger)
            and slot[1] == split
            and vault_identity == id(vault)
            for slot, vault_identity in tuple(_MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.items())
        )
    )
    selected_registration = ports.get(id(witnessed_port))
    selected_port = (
        selected_registration.port
        if type(selected_registration) is _MaterializerPortRegistration
        and type(selected_registration.port) is _TrustedMaterializerPort
        and selected_registration.port is witnessed_port
        and selected_registration.ledger is witnessed_ledger
        and canonical_root
        and slot_is_exact
        else None
    )
    if selected_port is None:
        selected_registration = witnessed_port_registration
        selected_port = witnessed_port
    live_binding_matches = bool(
        type(live_vault_binding) is tuple
        and _exact_native_binding_equal(binding, witnessed_binding)
        and _exact_native_binding_equal(live_vault_binding, witnessed_binding)
    )
    crossbound = bool(
        not live_binding_matches
        or root_pointer_changed
        or port_pointer_changed
        or ledger_pointer_changed
        or not canonical_root
        or not slot_is_exact
        or selected_port is not witnessed_port
    )
    # Fail-closing uses the pre-callback owner witness, never mutable root
    # pointers or the attacker-controlled saved binding.
    if not root_pointer_changed:
        registration.vault = witnessed_vault
    if not port_pointer_changed:
        registration.port = witnessed_port
    if not ledger_pointer_changed:
        registration.ledger = witnessed_ledger
    registration.binding = (
        registered_binding
        if (preserve_registered_binding or explicit_owner_witness)
        and type(registered_binding) is tuple
        else witnessed_binding
    )
    scrub_error: BaseException | None = None
    try:
        _scrub_materializer_vault(registration, state="failed")
    except BaseException as caught:
        scrub_error = caught
    burn_error = _burn_materializer_core_capabilities(
        ledger=witnessed_ledger,
        split=split,
        owner_witness=core_owner_witness,
    )
    if burn_error is not None:
        registry_error = burn_error
    witnessed_port_registration.state = "failed"
    post_error, ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    if post_error is not None:
        registry_error = post_error
    port_registration = ports.get(id(witnessed_port))
    if (
        type(port_registration) is _MaterializerPortRegistration
        and port_registration.port is witnessed_port
    ):
        port_registration.state = "failed"
    elif registry_error is None:
        registry_error = PermissionError("materializer failure port registry binding differs")
    if crossbound:
        raise PermissionError("materializer failure root/port binding differs")
    if registry_error is not None:
        raise registry_error
    if scrub_error is not None:
        raise scrub_error


def _register_public_materializer_evaluation(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    envelope: _PublicMaterializationEnvelope,
    evaluation: Mapping[str, Any],
) -> dict[str, Any]:
    vault_registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset({"collecting_public"}),
    )
    vault_registration.state = "checking_public_evaluation"
    registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(id(envelope))
    try:
        if (
            type(envelope) is not _PublicMaterializationEnvelope
            or registration is None
            or registration.envelope is not envelope
            or registration.port is not port
            or registration.vault is not vault
            or registration.state != "issued"
            or registration.request is None
            or not vault_registration.envelopes
            or vault_registration.envelopes[-1] is not envelope
            or envelope.ordinals
            != tuple(
                range(
                    vault_registration.next_ordinal,
                    vault_registration.next_ordinal + BATCH_SIZE,
                )
            )
        ):
            raise PermissionError("public materializer evaluation envelope binding differs")
        _validated_open_materializer_envelope(port, vault_registration, registration)
        request = registration.request
        ledger_state = vault_registration.ledger._record["splits"][vault.split]
        sensor_registration = _PUBLIC_SENSOR_BATCH_REGISTRY.get(id(registration.sensor_batch))
        task_registration = _SAFE_TASK_BATCH_REGISTRY.get(id(registration.task_batch))
        if (
            request._manifest._active is not request._batch
            or ledger_state["status"] != "public_evaluating"
            or ledger_state["public_next_ordinal"] != vault_registration.next_ordinal
            or ledger_state["public_active_batch"] != list(envelope.ordinals)
            or sensor_registration is None
            or task_registration is None
            or sensor_registration.state != "issued"
            or task_registration.state != "issued"
            or any(
                _SEALED_MATERIALIZATION_ROW_REGISTRY[id(row)].state != "issued"
                for row in registration.rows
            )
            or id(request._batch) in _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY
        ):
            raise PermissionError("public evaluation no longer has its durable reservation")
        if type(evaluation) is not dict:
            raise TypeError("public materializer evaluation must be one exact dictionary")
        validated_evaluation = _validated_public_batch_evaluation(
            evaluation,
            split=vault.split,
            ordinals=envelope.ordinals,
        )
        evidence_rows = validated_evaluation["public_evidence"]["row_receipts"]
        evaluation_token_hashes = tuple(
            row["token_receipt"]["receipt_sha256"] for row in evidence_rows
        )
        if evaluation_token_hashes != envelope.token_receipt_sha256:
            raise PermissionError("public evaluation token receipts differ from materialization")
        evaluation_hashes = _validated_public_materializer_evaluation_hashes(
            {
                "schema": "rgbd_known_action_public_materializer_evaluation_hashes_v1",
                "public_evaluation_sha256": canonical_sha256(validated_evaluation),
                "public_evidence_sha256": canonical_sha256(validated_evaluation["public_evidence"]),
                "public_metrics_sha256": canonical_sha256(validated_evaluation["public_metrics"]),
                "public_resources_sha256": canonical_sha256(
                    validated_evaluation["public_resources"]
                ),
            }
        )
        evaluation_sha256 = evaluation_hashes["public_evaluation_sha256"]
        evaluation_hashes_binding_sha256 = canonical_sha256(evaluation_hashes)
        returned_hashes = copy.deepcopy(evaluation_hashes)
        next_rows = [*vault_registration.rows, *registration.rows]
        _revoke_materialization_authorities(request)
        registration.request = None
        registration.evaluation_hashes = evaluation_hashes
        registration.evaluation_hashes_binding_sha256 = evaluation_hashes_binding_sha256
        registration.state = "evaluated"
        sensor_registration.state = "evaluated"
        task_registration.state = "evaluated"
        for row in registration.rows:
            _SEALED_MATERIALIZATION_ROW_REGISTRY[id(row)].state = "evaluated"
        vault_registration.rows = next_rows
        vault_registration.next_ordinal += BATCH_SIZE
        vault_registration.state = "collecting_public"
        _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY[id(request._batch)] = (
            request._batch,
            request._manifest,
            envelope,
            evaluation_sha256,
        )
        _validated_materializer_global_registry_cut(
            ledger=vault_registration.ledger,
            port=port,
        )
    except BaseException:
        _fail_materializer_vault(vault_registration)
        raise
    return returned_hashes


def _materializer_commitment_inventory(
    registration: _MaterializerVaultRegistration,
) -> list[dict[str, Any]]:
    inventory: list[dict[str, Any]] = []
    for row in registration.rows:
        row_binding = _materializer_row_binding(row)
        row_registration = _SEALED_MATERIALIZATION_ROW_REGISTRY.get(id(row))
        envelope_registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(row.envelope_identity)
        if (
            type(row_registration) is not _MaterializerRowRegistration
            or row_registration.row is not row
            or row_registration.vault is not registration.vault
            or not _exact_native_binding_equal(row_registration.binding, row_binding)
            or type(envelope_registration) is not _MaterializerEnvelopeRegistration
            or envelope_registration.envelope is not row_registration.envelope
            or not _exact_native_binding_equal(
                envelope_registration.binding,
                _materializer_envelope_binding(envelope_registration.envelope),
            )
            or envelope_registration.evaluation_hashes is None
        ):
            raise PermissionError("materializer commitment inventory registry differs")
        evaluation_hashes = _validated_public_materializer_evaluation_hashes(
            envelope_registration.evaluation_hashes
        )
        inventory.append(
            {
                "ordinal": row.ordinal,
                "token_receipt_sha256": row.token_receipt_sha256,
                "public_surface_sha256": row.public_surface_sha256,
                "blinded_commitment": row.blinded_commitment,
                "evaluation_hashes_sha256": canonical_sha256(evaluation_hashes),
            }
        )
    return inventory


def _validated_materializer_public_inventory(
    port: _TrustedMaterializerPort,
    registration: _MaterializerVaultRegistration,
    *,
    expected_child_state: Literal["evaluated", "public_finalized"],
    require_bound_digest: bool,
) -> tuple[list[dict[str, Any]], str]:
    batch_count = SCENES_PER_SPLIT // BATCH_SIZE
    if (
        type(port) is not _TrustedMaterializerPort
        or type(registration) is not _MaterializerVaultRegistration
        or registration.port is not port
        or type(registration.envelopes) is not list
        or type(registration.sensor_batches) is not list
        or type(registration.task_batches) is not list
        or type(registration.rows) is not list
        or registration.next_ordinal != SCENES_PER_SPLIT
        or len(registration.envelopes) != batch_count
        or len(registration.sensor_batches) != batch_count
        or len(registration.task_batches) != batch_count
        or len(registration.rows) != SCENES_PER_SPLIT
        or [row.ordinal for row in registration.rows] != list(ORDINALS)
    ):
        raise PermissionError("materializer public inventory is incomplete")
    flattened_rows: list[_SealedMaterializationRow] = []
    for batch_index, (envelope, sensor_batch, task_batch) in enumerate(
        zip(
            registration.envelopes,
            registration.sensor_batches,
            registration.task_batches,
            strict=True,
        )
    ):
        expected_ordinals = tuple(range(batch_index * BATCH_SIZE, (batch_index + 1) * BATCH_SIZE))
        envelope_registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(id(envelope))
        sensor_registration = _PUBLIC_SENSOR_BATCH_REGISTRY.get(id(sensor_batch))
        task_registration = _SAFE_TASK_BATCH_REGISTRY.get(id(task_batch))
        if (
            type(envelope_registration) is not _MaterializerEnvelopeRegistration
            or envelope_registration.envelope is not envelope
            or envelope_registration.port is not port
            or envelope_registration.vault is not registration.vault
            or envelope_registration.sensor_batch is not sensor_batch
            or envelope_registration.task_batch is not task_batch
            or type(envelope_registration.state) is not str
            or envelope_registration.state != expected_child_state
            or type(sensor_registration) is not _MaterializerTensorBatchRegistration
            or sensor_registration.batch is not sensor_batch
            or sensor_registration.envelope is not envelope
            or sensor_registration.vault is not registration.vault
            or type(sensor_registration.state) is not str
            or sensor_registration.state != expected_child_state
            or type(task_registration) is not _MaterializerTensorBatchRegistration
            or task_registration.batch is not task_batch
            or task_registration.envelope is not envelope
            or task_registration.vault is not registration.vault
            or type(task_registration.state) is not str
            or task_registration.state != expected_child_state
            or envelope.ordinals != expected_ordinals
            or type(envelope_registration.rows) is not tuple
            or len(envelope_registration.rows) != BATCH_SIZE
        ):
            raise PermissionError("materializer public child inventory differs")
        for row_index, row in enumerate(envelope_registration.rows):
            row_registration = _SEALED_MATERIALIZATION_ROW_REGISTRY.get(id(row))
            if (
                type(row_registration) is not _MaterializerRowRegistration
                or row_registration.row is not row
                or row_registration.envelope is not envelope
                or row_registration.vault is not registration.vault
                or type(row_registration.state) is not str
                or row_registration.state != expected_child_state
                or row.ordinal != expected_ordinals[row_index]
            ):
                raise PermissionError("materializer public row inventory differs")
            flattened_rows.append(row)
        _validated_open_materializer_envelope(
            port,
            registration,
            envelope_registration,
        )
    if any(
        left is not right for left, right in zip(registration.rows, flattened_rows, strict=True)
    ):
        raise PermissionError("materializer public row ordering differs")
    inventory = _materializer_commitment_inventory(registration)
    digest = canonical_sha256(inventory)
    if require_bound_digest:
        if (
            not _exact_lower_sha256(registration.commitment_inventory_sha256)
            or registration.commitment_inventory_sha256 != digest
        ):
            raise PermissionError("materializer public commitment inventory digest differs")
    elif registration.commitment_inventory_sha256 is not None:
        raise PermissionError("materializer public commitment inventory bound prematurely")
    return inventory, digest


def _finalize_materializer_public_split(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
) -> str:
    registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset({"collecting_public"}),
    )
    registration.state = "checking_public_finalize"
    try:
        ledger_state = registration.ledger._record["splits"][vault.split]
        if (
            registration.next_ordinal != SCENES_PER_SPLIT
            or len(registration.envelopes) != SCENES_PER_SPLIT // BATCH_SIZE
            or len(registration.sensor_batches) != SCENES_PER_SPLIT // BATCH_SIZE
            or len(registration.task_batches) != SCENES_PER_SPLIT // BATCH_SIZE
            or len(registration.rows) != SCENES_PER_SPLIT
            or [row.ordinal for row in registration.rows] != list(ORDINALS)
            or ledger_state["status"] != "public_evaluating"
            or ledger_state["public_next_ordinal"] != SCENES_PER_SPLIT
            or ledger_state["public_active_batch"] is not None
        ):
            raise PermissionError("materializer public split is incomplete")
        _inventory, digest = _validated_materializer_public_inventory(
            port,
            registration,
            expected_child_state="evaluated",
            require_bound_digest=False,
        )
        for envelope in registration.envelopes:
            envelope_registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY[id(envelope)]
            envelope_registration.state = "public_finalized"
            sensor_registration = _PUBLIC_SENSOR_BATCH_REGISTRY[
                id(envelope_registration.sensor_batch)
            ]
            task_registration = _SAFE_TASK_BATCH_REGISTRY[id(envelope_registration.task_batch)]
            sensor_registration.state = "public_finalized"
            task_registration.state = "public_finalized"
            for row in envelope_registration.rows:
                _SEALED_MATERIALIZATION_ROW_REGISTRY[id(row)].state = "public_finalized"
        registration.commitment_inventory_sha256 = digest
        registration.state = "public_finalized"
        _validated_materializer_public_inventory(
            port,
            registration,
            expected_child_state="public_finalized",
            require_bound_digest=True,
        )
        _validated_materializer_global_registry_cut(
            ledger=registration.ledger,
            port=port,
        )
    except BaseException:
        _fail_materializer_vault(registration)
        raise
    return digest


def _validated_formal_materializer_public_seal(
    manifest: _ManifestCapability,
) -> _MaterializerVaultRegistration:
    if (
        type(manifest) is not _ManifestCapability
        or type(manifest.split) is not str
        or manifest.split not in SPLITS
        or manifest._ledger._record["execution_mode"] != "formal"
    ):
        raise PermissionError("formal materializer public seal binding differs")
    registry_error = _quarantine_malformed_materializer_child_registries()
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        registry_error = vault_registry_error
    if registry_error is not None:
        _raise_materializer_registry_corruption(
            registry_error,
            ledger=manifest._ledger,
        )
    slot = (id(manifest._ledger), manifest.split)
    vault_identity = _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(slot)
    registration = (
        _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(vault_identity)
        if type(vault_identity) is int
        else None
    )
    if type(registration) is not _MaterializerVaultRegistration:
        raise PermissionError("formal materializer public seal lacks its exact vault")
    ledger_state = manifest._ledger._record["splits"][manifest.split]
    if (
        type(ledger_state) is not dict
        or type(ledger_state.get("status")) is not str
        or ledger_state.get("status") != "public_evaluating"
    ):
        raise PermissionError("formal materializer public split already crossed its seal cut")
    try:
        if (
            registration.ledger is not manifest._ledger
            or registration.vault.split != manifest.split
            or type(registration.state) is not str
            or registration.state != "public_finalized"
        ):
            raise PermissionError("formal materializer public split was not finalized")
        _materializer_vault_registration(
            registration.vault,
            port=registration.port,
            expected_states=frozenset({"public_finalized"}),
        )
        registration.state = "checking_public_seal"
        _validated_materializer_public_inventory(
            registration.port,
            registration,
            expected_child_state="public_finalized",
            require_bound_digest=True,
        )
        return registration
    except BaseException:
        _fail_materializer_vault(registration)
        raise


def _materializer_private_request_binding(
    request: PrivateSplitScoringRequest,
) -> tuple[Any, ...]:
    if type(request) is not PrivateSplitScoringRequest:
        raise PermissionError("materializer private request is forged")
    authority = request._authority
    manifest = request._manifest
    if (
        type(authority) is not _SplitTruthAuthority
        or type(manifest) is not _ManifestCapability
        or type(request.split) is not str
        or request.split not in SPLITS
        or type(request.public_seal_sha256) is not str
        or type(request.request_sha256) is not str
    ):
        raise PermissionError("materializer private request capability is forged")
    _split_truth_authority_binding(authority)
    return (
        id(request),
        request.split,
        request.public_seal_sha256,
        request.request_sha256,
        id(manifest),
        manifest.split,
        id(manifest._ledger),
        id(authority),
        authority.split,
        id(authority.directory_pin),
        authority.ledger_identity,
        authority.ledger_file_identity,
        authority.ledger_generation,
        authority.ledger_record_sha256,
        authority.public_seal_sha256,
        authority.request_bytes,
        authority.request_sha256,
        authority.owner_thread,
        id(authority.nonce),
    )


def _bind_materializer_private_request(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    request: PrivateSplitScoringRequest,
) -> dict[str, Any]:
    registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset({"public_sealed"}),
    )
    failure_owner = _capture_materializer_failure_owner(registration)
    registration.state = "checking_private_bind"
    try:
        if type(request) is not PrivateSplitScoringRequest:
            raise PermissionError("materializer private request is forged")
        _inventory, commitment_digest = _validated_materializer_public_inventory(
            port,
            registration,
            expected_child_state="public_finalized",
            require_bound_digest=True,
        )
        ledger_state = registration.ledger._record["splits"][vault.split]
        truth_registration = _TRUTH_AUTHORITY_REGISTRY.get(id(request._authority))
        if (
            request.split != vault.split
            or request._manifest._ledger is not registration.ledger
            or request._manifest.split != vault.split
            or request.public_seal_sha256 != ledger_state["public_seal_sha256"]
            or ledger_state["status"] != "truth_evaluating"
            or registration.commitment_inventory_sha256 != commitment_digest
            or type(truth_registration) is not tuple
            or len(truth_registration) != 5
            or truth_registration[0] is not request._authority
            or truth_registration[1] is not request._manifest
            or truth_registration[2] is not request
            or type(truth_registration[3]) is not str
            or truth_registration[3] != "issued"
            or not _exact_native_binding_equal(
                _TRUTH_AUTHORITY_BINDING_REGISTRY.get(id(request._authority)),
                _split_truth_authority_binding(request._authority),
            )
        ):
            raise PermissionError("materializer private request/seal/vault binding differs")
        request_binding = _materializer_private_request_binding(request)
        durable_latch = _capture_materializer_durable_latch(registration.ledger)
        binding = request.consume()
        # Truth-authority consumption is read-only with respect to the durable
        # ledger.  Authenticate that exact no-change cut before inspecting any
        # callback-controlled return value or mutable global registry.
        _verify_materializer_durable_latch(registration.ledger, durable_latch)
        _validated_materializer_global_registry_cut(
            ledger=registration.ledger,
            port=port,
        )
        if type(binding) is not dict:
            raise PermissionError("materializer private consume returned a forged binding")
        returned_binding = _validated_truth_request_binding(binding, split=vault.split)
        authority_request_binding = _validated_truth_request_binding(
            _strict_json_loads(
                request._authority.request_bytes,
                label="materializer private authority request",
            ),
            split=vault.split,
        )
        _exact_equal(
            returned_binding,
            authority_request_binding,
            label="materializer private consumed request",
        )
        if (
            canonical_sha256(returned_binding) != request.request_sha256
            or canonical_sha256(authority_request_binding) != request._authority.request_sha256
        ):
            raise PermissionError("materializer private consumed request hash differs")
        registration.ledger._verify_disk()
        _inventory, post_consume_commitment_digest = _validated_materializer_public_inventory(
            port,
            registration,
            expected_child_state="public_finalized",
            require_bound_digest=True,
        )
        consumed_truth_registration = _TRUTH_AUTHORITY_REGISTRY.get(id(request._authority))
        consumed_truth_binding = _TRUTH_AUTHORITY_BINDING_REGISTRY.get(id(request._authority))
        post_consume_ledger_state = registration.ledger._record["splits"][vault.split]
        if (
            registration.commitment_inventory_sha256 != post_consume_commitment_digest
            or not _exact_native_binding_equal(
                request_binding,
                _materializer_private_request_binding(request),
            )
            or type(consumed_truth_registration) is not tuple
            or len(consumed_truth_registration) != 5
            or consumed_truth_registration[0] is not request._authority
            or consumed_truth_registration[1] is not request._manifest
            or consumed_truth_registration[2] is not request
            or type(consumed_truth_registration[3]) is not str
            or consumed_truth_registration[3] != "consumed"
            or consumed_truth_registration[4] is not None
            or type(post_consume_ledger_state) is not dict
            or type(post_consume_ledger_state.get("status")) is not str
            or post_consume_ledger_state.get("status") != "truth_evaluating"
            or type(post_consume_ledger_state.get("public_seal_sha256")) is not str
            or post_consume_ledger_state.get("public_seal_sha256") != request.public_seal_sha256
            or request._authority.directory_pin is not registration.ledger._pin
            or request._authority.ledger_identity != id(registration.ledger)
            or request._authority.ledger_file_identity != registration.ledger._last_identity
            or request._authority.ledger_generation != registration.ledger._record["generation"]
            or request._authority.ledger_record_sha256
            != canonical_sha256(registration.ledger._record)
            or not _exact_native_binding_equal(
                consumed_truth_binding,
                _split_truth_authority_binding(request._authority),
            )
            or registration.state != "checking_private_bind"
            or not _exact_materializer_vault_root_registration(
                id(registration.vault),
                registration,
            )
        ):
            raise PermissionError(
                "materializer private request changed while its one-shot authority was consumed"
            )
        _validated_materializer_global_registry_cut(
            ledger=registration.ledger,
            port=port,
        )
        _verify_materializer_durable_latch(registration.ledger, durable_latch)
        registration.private_request = request
        registration.private_request_binding = request_binding
        registration.state = "private_consuming"
    except BaseException:
        _fail_materializer_vault(
            registration,
            owner_witness=failure_owner,
        )
        raise
    return binding


def _formal_materializer_private_rows(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    request: PrivateSplitScoringRequest,
) -> list[dict[str, Any]]:
    """Reveal the exact public commitments only after the durable public seal."""

    registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset({"private_consuming"}),
    )
    if (
        registration.private_request is not request
        or registration.private_request_binding is None
        or not _exact_native_binding_equal(
            registration.private_request_binding,
            _materializer_private_request_binding(request),
        )
    ):
        raise PermissionError("formal private commitment request differs")
    _validated_materializer_public_inventory(
        port,
        registration,
        expected_child_state="public_finalized",
        require_bound_digest=True,
    )
    rows: list[dict[str, Any]] = []
    for envelope in registration.envelopes:
        envelope_registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(id(envelope))
        if type(envelope_registration) is not _MaterializerEnvelopeRegistration:
            raise PermissionError("formal private commitment envelope differs")
        _validated_open_materializer_envelope(
            port,
            registration,
            envelope_registration,
        )
        if (
            type(envelope_registration.public_bodies) is not tuple
            or type(envelope_registration.blinding_nonces) is not tuple
            or envelope_registration.evaluation_hashes is None
        ):
            raise PermissionError("formal private commitment payload is absent")
        evaluation_hashes = _validated_public_materializer_evaluation_hashes(
            envelope_registration.evaluation_hashes
        )
        evaluation_hashes_sha256 = canonical_sha256(evaluation_hashes)
        for surface, nonce, sealed_row in zip(
            envelope_registration.public_bodies,
            envelope_registration.blinding_nonces,
            envelope_registration.rows,
            strict=True,
        ):
            validated_surface = _validated_public_materialization_surface(surface)
            row = {
                "schema": "rgbd_known_action_formal_private_row_commitment_v1",
                "split": vault.split,
                "ordinal": sealed_row.ordinal,
                "public_surface": validated_surface,
                "public_surface_sha256": canonical_sha256(validated_surface),
                "evaluation_hashes_sha256": evaluation_hashes_sha256,
                "blinding_nonce_hex": nonce.hex(),
                "blinded_commitment": sealed_row.blinded_commitment,
            }
            rows.append(row)
    return _validated_formal_private_row_commitments(rows, split=vault.split)


def _validate_formal_private_receipt_materializer_binding(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    request: PrivateSplitScoringRequest,
    receipt: Mapping[str, Any],
) -> dict[str, Any]:
    validated = _validated_private_scoring_receipt(
        copy.deepcopy(dict(receipt)),
        split=vault.split,
        public_seal_sha256=request.public_seal_sha256,
    )
    if validated["schema"] != "rgbd_known_action_formal_private_scoring_receipt_v1":
        raise PermissionError("formal materializer requires one formal private receipt")
    expected_rows = _formal_materializer_private_rows(port, vault, request)
    _exact_equal(
        validated["private_row_commitments"],
        expected_rows,
        label="formal private receipt/materializer commitments",
    )
    return validated


def _retire_materializer_vault(
    registration: _MaterializerVaultRegistration,
    *,
    state: Literal["consumed", "failed", "revoked"],
) -> None:
    if (
        type(registration) is not _MaterializerVaultRegistration
        or type(registration.port) is not _TrustedMaterializerPort
        or type(registration.ledger) is not _AccessLedger
        or type(state) is not str
        or state not in {"consumed", "failed", "revoked"}
    ):
        raise PermissionError("materializer retirement target is forged")
    selected_port = registration.port
    ports, _batches, _tokens, _consumed = _validated_materializer_global_registry_cut(
        ledger=registration.ledger,
        port=selected_port,
    )
    canonical_registration = _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(id(registration.vault))
    slot_identity = _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(
        (id(registration.ledger), registration.vault.split)
    )
    port_registration = ports.get(id(selected_port))
    predecessor_is_exact = bool(
        registration.state == "checking_private_complete"
        if state == "consumed"
        else registration.state in MATERIALIZER_LIVE_VAULT_STATES
    )
    if (
        canonical_registration is not registration
        or type(slot_identity) is not int
        or slot_identity != id(registration.vault)
        or type(port_registration) is not _MaterializerPortRegistration
        or port_registration.port is not selected_port
        or port_registration.ledger is not registration.ledger
        or not predecessor_is_exact
    ):
        if canonical_registration is registration:
            _fail_materializer_vault(registration)
        raise PermissionError("materializer retirement root/slot predecessor differs")
    try:
        if not _exact_native_binding_equal(
            registration.binding,
            _materializer_vault_binding(registration.vault),
        ):
            raise PermissionError("materializer retirement vault binding differs")
        if not (
            len(registration.envelopes)
            == len(registration.sensor_batches)
            == len(registration.task_batches)
        ):
            raise PermissionError("materializer retirement child inventory differs")
        for envelope, sensor_batch, task_batch in zip(
            registration.envelopes,
            registration.sensor_batches,
            registration.task_batches,
            strict=True,
        ):
            envelope_registration = _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(id(envelope))
            if (
                envelope_registration is None
                or envelope_registration.envelope is not envelope
                or envelope_registration.vault is not registration.vault
                or envelope_registration.sensor_batch is not sensor_batch
                or envelope_registration.task_batch is not task_batch
            ):
                raise PermissionError("materializer envelope ownership changed during retirement")
            for batch, registry in (
                (sensor_batch, _PUBLIC_SENSOR_BATCH_REGISTRY),
                (task_batch, _SAFE_TASK_BATCH_REGISTRY),
            ):
                if batch is None:
                    continue
                batch_registration = registry.get(id(batch))
                if (
                    batch_registration is None
                    or batch_registration.batch is not batch
                    or batch_registration.envelope is not envelope
                    or batch_registration.vault is not registration.vault
                ):
                    raise PermissionError("materializer tensor ownership changed during retirement")
            for row in envelope_registration.rows:
                row_registration = _SEALED_MATERIALIZATION_ROW_REGISTRY.get(id(row))
                if (
                    row_registration is None
                    or row_registration.row is not row
                    or row_registration.envelope is not envelope
                    or row_registration.vault is not registration.vault
                ):
                    raise PermissionError("materializer row ownership changed during retirement")
    except BaseException:
        _fail_materializer_vault(registration)
        raise
    if (
        type(port_registration) is not _MaterializerPortRegistration
        or port_registration.port is not selected_port
        or registration.port is not selected_port
    ):
        _fail_materializer_vault(registration)
        raise PermissionError("materializer retirement port registry binding differs")
    _scrub_materializer_vault(registration, state=state)
    _validated_materializer_global_registry_cut(
        ledger=registration.ledger,
        port=selected_port,
    )


def _scrub_materializer_vault(
    registration: _MaterializerVaultRegistration,
    *,
    state: Literal["consumed", "failed", "revoked"],
) -> None:
    effective_state: Literal["consumed", "failed", "revoked"] = state
    if state != "failed" and (
        type(registration.ledger) is not _AccessLedger
        or type(registration.vault) is not _MaterializerSplitVault
        or type(registration.vault.split) is not str
        or registration.vault.split not in SPLITS
        or _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(
            (id(registration.ledger), registration.vault.split)
        )
        != id(registration.vault)
    ):
        # A clean consumed/revoked tombstone must retain its exact reverse
        # ownership edge.  If that edge never existed or was corrupted, scrub
        # payloads but classify the root as failed, whose absent slot remains a
        # terminal fail-closed cut rather than fabricating provenance.
        effective_state = "failed"
    tensor_state = "retired" if effective_state == "consumed" else "revoked"
    row_state = "retired" if effective_state == "consumed" else "revoked"
    registry_corruption = _quarantine_malformed_materializer_child_registries()
    owned_envelopes = (
        {id(envelope) for envelope in registration.envelopes}
        if type(registration.envelopes) is list
        else set()
    )
    owned_sensor_batches = (
        {id(batch) for batch in registration.sensor_batches}
        if type(registration.sensor_batches) is list
        else set()
    )
    owned_task_batches = (
        {id(batch) for batch in registration.task_batches}
        if type(registration.task_batches) is list
        else set()
    )
    owned_rows = (
        {id(row) for row in registration.rows} if type(registration.rows) is list else set()
    )
    owned_envelopes.update(
        identity
        for identity, envelope_registration in (_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items())
        if envelope_registration.vault is registration.vault
        or (
            envelope_registration.port is registration.port
            and (
                envelope_registration.request is not None
                or envelope_registration.sensor_batch is not None
                or envelope_registration.task_batch is not None
                or envelope_registration.runtime_tensors is not None
                or envelope_registration.public_bodies is not None
                or envelope_registration.blinding_nonces is not None
                or envelope_registration.evaluation_hashes is not None
                or type(envelope_registration.state) is not str
                or envelope_registration.state in MATERIALIZER_LIVE_CHILD_STATES
            )
        )
    )
    owned_sensor_batches.update(
        identity
        for identity, batch_registration in _PUBLIC_SENSOR_BATCH_REGISTRY.items()
        if batch_registration.vault is registration.vault
        or (
            batch_registration.port is registration.port
            and (
                batch_registration.tensors is not None
                or type(batch_registration.state) is not str
                or batch_registration.state in MATERIALIZER_LIVE_CHILD_STATES
            )
        )
    )
    owned_task_batches.update(
        identity
        for identity, batch_registration in _SAFE_TASK_BATCH_REGISTRY.items()
        if batch_registration.vault is registration.vault
        or (
            batch_registration.port is registration.port
            and (
                batch_registration.tensors is not None
                or type(batch_registration.state) is not str
                or batch_registration.state in MATERIALIZER_LIVE_CHILD_STATES
            )
        )
    )
    owned_rows.update(
        identity
        for identity, row_registration in _SEALED_MATERIALIZATION_ROW_REGISTRY.items()
        if (
            id(row_registration.envelope) in owned_envelopes
            or row_registration.vault is registration.vault
            or (
                (
                    type(row_registration.state) is not str
                    or row_registration.state in MATERIALIZER_LIVE_CHILD_STATES
                )
                and _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.get(id(row_registration.envelope))
                is not None
                and _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY[id(row_registration.envelope)].port
                is registration.port
            )
        )
    )
    if type(registration.envelopes) is not list:
        registration.envelopes = [
            envelope_registration.envelope
            for identity, envelope_registration in (
                _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items()
            )
            if identity in owned_envelopes
        ]
    if type(registration.sensor_batches) is not list:
        registration.sensor_batches = [
            batch_registration.batch
            for identity, batch_registration in _PUBLIC_SENSOR_BATCH_REGISTRY.items()
            if identity in owned_sensor_batches
        ]
    if type(registration.task_batches) is not list:
        registration.task_batches = [
            batch_registration.batch
            for identity, batch_registration in _SAFE_TASK_BATCH_REGISTRY.items()
            if identity in owned_task_batches
        ]
    if type(registration.rows) is not list:
        registration.rows = [
            row_registration.row
            for identity, row_registration in _SEALED_MATERIALIZATION_ROW_REGISTRY.items()
            if identity in owned_rows
        ]
    retained_materializer_evaluations = []
    for identity, materializer_evaluation in tuple(
        _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.items()
    ):
        if (
            type(identity) is not int
            or type(materializer_evaluation) is not tuple
            or len(materializer_evaluation) != 4
            or type(materializer_evaluation[0]) is not _BatchCapability
            or type(materializer_evaluation[1]) is not _ManifestCapability
            or type(materializer_evaluation[2]) is not _PublicMaterializationEnvelope
            or type(materializer_evaluation[3]) is not str
            or len(materializer_evaluation[3]) != 64
            or any(character not in "0123456789abcdef" for character in materializer_evaluation[3])
        ):
            registry_corruption = PermissionError(
                "materializer evaluation registry was corrupted during scrub"
            )
            continue
        if id(materializer_evaluation[2]) not in owned_envelopes:
            retained_materializer_evaluations.append((identity, materializer_evaluation))
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.clear()
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.update(retained_materializer_evaluations)
    for identity, envelope_registration in _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items():
        if identity not in owned_envelopes:
            continue
        request = envelope_registration.request
        if request is not None:
            with contextlib.suppress(BaseException):
                _revoke_materialization_authorities(request)
        envelope_registration.request = None
        envelope_registration.sensor_batch = None
        envelope_registration.task_batch = None
        envelope_registration.runtime_tensors = None
        envelope_registration.public_bodies = None
        envelope_registration.blinding_nonces = None
        envelope_registration.evaluation_hashes = None
        envelope_registration.evaluation_hashes_binding_sha256 = None
        envelope_registration.state = "retired"
    for identity, batch_registration in _PUBLIC_SENSOR_BATCH_REGISTRY.items():
        if identity in owned_sensor_batches:
            batch_registration.tensors = None
            batch_registration.state = tensor_state
    for identity, batch_registration in _SAFE_TASK_BATCH_REGISTRY.items():
        if identity in owned_task_batches:
            batch_registration.tensors = None
            batch_registration.state = tensor_state
    for identity, row_registration in _SEALED_MATERIALIZATION_ROW_REGISTRY.items():
        if identity in owned_rows:
            row_registration.state = row_state
    registration.private_request = None
    registration.private_request_binding = None
    registration.commitment_inventory_sha256 = None
    registration.terminal_marker = _MATERIALIZER_VAULT_TERMINAL_MARKER
    registration.state = effective_state
    if registry_corruption is not None:
        raise registry_corruption


def _complete_materializer_private_consumption(
    port: _TrustedMaterializerPort,
    vault: _MaterializerSplitVault,
    request: PrivateSplitScoringRequest,
) -> None:
    registration = _materializer_vault_registration(
        vault,
        port=port,
        expected_states=frozenset({"private_consuming"}),
    )
    registration.state = "checking_private_complete"
    try:
        if type(request) is not PrivateSplitScoringRequest:
            raise PermissionError("materializer private consumption request is forged")
        authority = request._authority
        truth_registration = _TRUTH_AUTHORITY_REGISTRY.get(id(request._authority))
        ledger = registration.ledger
        ledger_state = ledger._record["splits"][registration.vault.split]
        if (
            registration.private_request is not request
            or registration.private_request_binding is None
            or not _exact_native_binding_equal(
                registration.private_request_binding,
                _materializer_private_request_binding(request),
            )
            or type(truth_registration) is not tuple
            or len(truth_registration) != 5
            or truth_registration[0] is not authority
            or truth_registration[1] is not request._manifest
            or truth_registration[2] is not request
            or type(truth_registration[3]) is not str
            or truth_registration[3] != "receipt_bound"
            or not _exact_lower_sha256(truth_registration[4])
            or not _exact_native_binding_equal(
                _TRUTH_AUTHORITY_BINDING_REGISTRY.get(id(authority)),
                _split_truth_authority_binding(authority),
            )
            or request._manifest._ledger is not ledger
            or request._manifest.split != registration.vault.split
            or request.split != registration.vault.split
            or request.public_seal_sha256 != ledger_state["public_seal_sha256"]
            or ledger_state["status"] != "truth_evaluating"
            or authority.directory_pin is not ledger._pin
            or authority.ledger_identity != id(ledger)
            or authority.ledger_file_identity != ledger._last_identity
            or authority.ledger_generation != ledger._record["generation"]
            or authority.ledger_record_sha256 != canonical_sha256(ledger._record)
            or authority.public_seal_sha256 != ledger_state["public_seal_sha256"]
            or authority.owner_thread != threading.get_ident()
        ):
            raise PermissionError("materializer private consumption binding differs")
        _inventory, commitment_digest = _validated_materializer_public_inventory(
            port,
            registration,
            expected_child_state="public_finalized",
            require_bound_digest=True,
        )
        if registration.commitment_inventory_sha256 != commitment_digest:
            raise PermissionError("materializer private commitment inventory differs")
        _retire_materializer_vault(registration, state="consumed")
    except BaseException:
        if type(registration.state) is not str or registration.state != "consumed":
            _fail_materializer_vault(registration)
        raise


def _abort_materializer_split(
    port: _TrustedMaterializerPort,
    *,
    split: str,
) -> None:
    if type(port) is not _TrustedMaterializerPort:
        raise PermissionError("materializer abort port is forged")
    core_error, ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    port_registration = ports.get(id(port))
    if type(port_registration) is not _MaterializerPortRegistration:
        cleanup_error: BaseException | None = None
        recovered_ledger: _AccessLedger | None = None
        for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
            if (
                type(vault_registration) is _MaterializerVaultRegistration
                and type(vault_registration.vault) is _MaterializerSplitVault
                and (
                    vault_registration.port is port
                    or (
                        type(vault_registration.vault.port_identity) is int
                        and vault_registration.vault.port_identity == id(port)
                    )
                )
            ):
                if type(vault_registration.ledger) is _AccessLedger:
                    if recovered_ledger is None:
                        recovered_ledger = vault_registration.ledger
                    elif recovered_ledger is not vault_registration.ledger:
                        cleanup_error = PermissionError(
                            "materializer abort recovered multiple ledger owners"
                        )
                try:
                    _scrub_materializer_vault(vault_registration, state="failed")
                except BaseException as caught:
                    cleanup_error = caught
        terminal_error = (
            core_error
            if core_error is not None
            else PermissionError("malformed materializer port registry was rejected")
        )
        if recovered_ledger is not None:
            _raise_materializer_registry_corruption(
                terminal_error,
                ledger=recovered_ledger,
                port=port,
            )
        if cleanup_error is not None:
            raise cleanup_error
        raise terminal_error
    if type(split) is not str or split not in SPLITS:
        raise PermissionError("materializer abort binding differs")
    validation_error: BaseException | None = core_error
    child_error = _quarantine_malformed_materializer_child_registries()
    if child_error is not None:
        validation_error = child_error
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        validation_error = vault_registry_error
    port_rebound = port_registration.port is not port
    if port_rebound:
        validation_error = PermissionError("materializer abort port binding differs")
    if (
        type(port_registration.ledger) is not _AccessLedger
        or port_registration.ledger._owner_thread != threading.get_ident()
    ):
        validation_error = PermissionError("materializer abort ledger binding differs")
    port_state = port_registration.state
    if type(port_state) is not str:
        validation_error = PermissionError("materializer abort port state differs")
    elif port_state == "active":
        try:
            _trusted_materializer_port_registration(port)
        except BaseException as error:
            validation_error = error
    elif port_state not in {"failed", "revoked", "closed"}:
        validation_error = PermissionError("materializer abort port state differs")
    cleanup_error: BaseException | None = None
    for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
        vault_state = vault_registration.state
        if _materializer_vault_is_owned_by_port(
            vault_registration,
            port_registration,
            expected_port=port,
        ) and _materializer_vault_requires_cleanup(vault_registration):
            direct_scrub = False
            if (
                port_rebound
                or vault_registration.port is not port
                or vault_registration.ledger is not port_registration.ledger
            ):
                validation_error = PermissionError("materializer abort vault ownership differs")
                direct_scrub = True
            if type(vault_state) is not str or vault_state not in MATERIALIZER_LIVE_VAULT_STATES:
                validation_error = PermissionError("materializer abort vault state differs")
                direct_scrub = True
            binding = vault_registration.binding
            if (
                type(binding) is not tuple
                or len(binding) != 6
                or type(binding[0]) is not int
                or type(binding[1]) is not int
                or type(binding[2]) is not str
                or type(binding[3]) is not int
                or type(binding[4]) is not int
                or type(binding[5]) is not int
                or binding[2] != split
            ):
                validation_error = PermissionError(
                    "materializer abort split differs from its one live vault"
                )
                direct_scrub = True
            try:
                if direct_scrub:
                    _scrub_materializer_vault(vault_registration, state="failed")
                else:
                    _retire_materializer_vault(vault_registration, state="revoked")
            except BaseException as error:
                cleanup_error = error
    if type(port_registration.state) is not str or port_registration.state not in {
        "revoked",
        "closed",
    }:
        port_registration.state = "failed"
    if cleanup_error is not None:
        raise cleanup_error
    if validation_error is not None:
        raise validation_error
    if type(port_registration.ledger) is _AccessLedger:
        slot = (id(port_registration.ledger), split)
        vault_identity = _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.get(slot)
        if vault_identity is not None:
            vault_registration = _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(vault_identity)
            if vault_registration is None or vault_registration.port is not port:
                port_registration.state = "failed"
                raise PermissionError("materializer abort vault ownership differs")


def _close_trusted_materializer_port(port: _TrustedMaterializerPort) -> None:
    # Preserve an observed root/port crossbinding as a terminal corruption
    # witness when close itself triggers fail-burn.  Ordinary materializer
    # operations repair that mutable registry pointer after revocation, but a
    # close request must not make test-only disposal indistinguishable from a
    # clean close until the detected pointer is explicitly restored.
    crossbound_root_ports = [
        (identity, root.port)
        for identity, root in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items())
        if type(identity) is int
        and type(root) is _MaterializerVaultRegistration
        and type(root.vault) is _MaterializerSplitVault
        and id(root.vault) == identity
        and type(root.vault.port_identity) is int
        and root.vault.port_identity == id(port)
        and root.port is not port
    ]
    try:
        registration = _trusted_materializer_port_registration(port)
    except BaseException:
        for identity, observed_port in crossbound_root_ports:
            terminal_root = _MATERIALIZER_SPLIT_VAULT_REGISTRY.get(identity)
            if (
                type(terminal_root) is _MaterializerVaultRegistration
                and type(terminal_root.state) is str
                and terminal_root.state in MATERIALIZER_TERMINAL_VAULT_STATES
            ):
                terminal_root.port = observed_port
        raise
    registry_error = _quarantine_malformed_materializer_child_registries()
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        registry_error = vault_registry_error
    if registry_error is not None:
        _raise_materializer_registry_corruption(
            registry_error,
            ledger=registration.ledger,
            port=port,
        )
    if any(
        _materializer_vault_is_owned_by_port(
            item,
            registration,
            expected_port=port,
        )
        and _materializer_vault_requires_cleanup(item)
        for item in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
    ):
        raise PermissionError("materializer port cannot close with a live split vault")
    registration.state = "closed"


def _revoke_trusted_materializer_port(port: _TrustedMaterializerPort) -> None:
    if type(port) is not _TrustedMaterializerPort:
        raise PermissionError("materializer port revocation is forged")
    core_error, ports, _batches, _tokens, _consumed = (
        _partition_exact_materializer_core_registries()
    )
    registration = ports.get(id(port))
    if type(registration) is not _MaterializerPortRegistration:
        cleanup_error: BaseException | None = None
        recovered_ledger: _AccessLedger | None = None
        for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
            if (
                type(vault_registration) is _MaterializerVaultRegistration
                and type(vault_registration.vault) is _MaterializerSplitVault
                and (
                    vault_registration.port is port
                    or (
                        type(vault_registration.vault.port_identity) is int
                        and vault_registration.vault.port_identity == id(port)
                    )
                )
            ):
                if type(vault_registration.ledger) is _AccessLedger:
                    if recovered_ledger is None:
                        recovered_ledger = vault_registration.ledger
                    elif recovered_ledger is not vault_registration.ledger:
                        cleanup_error = PermissionError(
                            "materializer port revocation recovered multiple ledger owners"
                        )
                try:
                    _scrub_materializer_vault(vault_registration, state="failed")
                except BaseException as caught:
                    cleanup_error = caught
        terminal_error = (
            core_error
            if core_error is not None
            else PermissionError("malformed materializer port registry was rejected")
        )
        if recovered_ledger is not None:
            _raise_materializer_registry_corruption(
                terminal_error,
                ledger=recovered_ledger,
                port=port,
            )
        if cleanup_error is not None:
            raise cleanup_error
        raise terminal_error
    port_rebound = registration.port is not port
    validation_error: BaseException | None = core_error
    if port_rebound:
        validation_error = PermissionError("materializer port revocation binding differs")
    if type(registration.ledger) is not _AccessLedger:
        validation_error = PermissionError("materializer port revocation ledger differs")
    cleanup_error: BaseException | None = _quarantine_malformed_materializer_child_registries()
    vault_registry_error = _quarantine_malformed_materializer_vault_registry()
    if vault_registry_error is not None:
        cleanup_error = vault_registry_error
    for vault_registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.values()):
        vault_state = vault_registration.state
        if _materializer_vault_is_owned_by_port(
            vault_registration,
            registration,
            expected_port=port,
        ) and _materializer_vault_requires_cleanup(vault_registration):
            try:
                if (
                    port_rebound
                    or vault_registration.port is not port
                    or vault_registration.ledger is not registration.ledger
                    or type(vault_state) is not str
                    or vault_state not in MATERIALIZER_LIVE_VAULT_STATES
                ):
                    _scrub_materializer_vault(vault_registration, state="failed")
                else:
                    _retire_materializer_vault(vault_registration, state="revoked")
            except BaseException as error:
                cleanup_error = error
    if cleanup_error is not None:
        registration.state = "failed"
        raise cleanup_error
    if validation_error is not None:
        registration.state = "failed"
        raise validation_error
    if type(registration.state) is not str or registration.state == "active":
        registration.state = "revoked"


def _revoke_materializer_construction_authority(
    authority: _MaterializerConstructionAuthority,
) -> None:
    if type(authority) is not _MaterializerConstructionAuthority:
        raise PermissionError("materializer authority revocation is forged")
    registration = _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.get(id(authority))
    if (
        type(registration) is not _MaterializerConstructionRegistration
        or registration.authority is not authority
    ):
        raise PermissionError("materializer authority revocation binding differs")
    if type(registration.state) is not str:
        registration.state = "failed"
        raise PermissionError("materializer authority revocation state differs")
    if registration.state == "issued":
        registration.state = "revoked"


def _formal_materializer_tensor_payload(
    record: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Extract and isolate only the public tensors retained by the materializer."""

    batch = record["batch"]
    safe = record["safe"]
    plan = record["plan"]
    none = record["none"]
    history = slice(0, HISTORY_FRAME_COUNT)
    sensors = {
        "rgb": _clone_materializer_tensor(batch["rgb"][:, history]),
        "depth": _clone_materializer_tensor(batch["depth"][:, history]),
        "timestamps": _clone_materializer_tensor(batch["timestamps"][:, history]),
        "world_from_camera": _clone_materializer_tensor(
            batch["camera"]["world_from_camera"][:, history]
        ),
        "intrinsics": _clone_materializer_tensor(batch["camera"]["intrinsics"][:, history]),
    }
    tasks = {
        "observable_handle_prototype": _clone_materializer_tensor(
            safe["observable_handle_prototype"]
        ),
        "candidate_timestamps": _clone_materializer_tensor(safe["candidate_timestamps"]),
        "candidate_impulses_world": _clone_materializer_tensor(safe["candidate_impulses_world"]),
        "goal_positions_world": _clone_materializer_tensor(safe["goal_positions_world"]),
        "opposite_goal_positions_world": _clone_materializer_tensor(
            record["opposite_goal_positions_world"]
        ),
        "alternate_handle_prototype": _clone_materializer_tensor(
            record["alternate_handle_prototype"]
        ),
    }
    runtime = {
        "resolved_persistent_id": _clone_materializer_tensor(record["resolved_id"]),
        "persistent_id_by_slot": _clone_materializer_tensor(plan.object_id_by_slot),
        "candidate_positions": _clone_materializer_tensor(
            torch.stack([trajectory.positions for trajectory in plan.trajectories], dim=1)
        ),
        "candidate_velocities": _clone_materializer_tensor(
            torch.stack([trajectory.velocities for trajectory in plan.trajectories], dim=1)
        ),
        "candidate_total_cost": _clone_materializer_tensor(plan.total_cost),
        "selected_display_index": _clone_materializer_tensor(plan.selected_index),
        "none_positions": _clone_materializer_tensor(none.positions),
        "none_velocities": _clone_materializer_tensor(none.velocities),
    }
    return sensors, tasks, runtime


class _FormalKnownActionEvaluator:
    """Ledger-bound formal evaluator with a sealed public/private materializer cut."""

    def __init__(
        self,
        config: OrpheusConfig,
        *,
        authority: _EvaluatorConstructionAuthority,
    ) -> None:
        if (
            type(self) is not _FormalKnownActionEvaluator
            or type(authority) is not _EvaluatorConstructionAuthority
            or id(self) in _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS
        ):
            raise PermissionError("formal evaluator constructor type or state differs")
        instance_state = object.__getattribute__(self, "__dict__")
        if type(instance_state) is not dict:
            raise PermissionError("formal evaluator instance storage differs")
        initialized_identity_present = id(self) in _FORMAL_EVALUATOR_INITIALIZATION_REGISTRY
        if (
            initialized_identity_present
            or "_materializer_initialization_nonce" in instance_state
            or "_materializer_port" in instance_state
            or any(
                type(registration) is _MaterializerPortRegistration
                and registration.evaluator is self
                for registration in _TRUSTED_MATERIALIZER_PORT_REGISTRY.values()
            )
        ):
            authority_registration = _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.get(id(authority))
            if (
                type(authority_registration) is tuple
                and len(authority_registration) == 5
                and authority_registration[0] is authority
                and type(authority_registration[3]) is str
                and authority_registration[3] == "issued"
            ):
                _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
                    authority,
                    authority_registration[1],
                    authority_registration[2],
                    "failed",
                    authority_registration[4],
                )
            raise PermissionError("formal evaluator instance is already initialized")
        _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS[id(self)] = (self, authority, None)
        materializer_authority: _MaterializerConstructionAuthority | None = None
        try:
            ledger, materializer_authority = _consume_formal_evaluator_authority(
                authority,
                config=config,
                evaluator=self,
            )
            materializer_port = _construct_trusted_materializer_port(
                materializer_authority,
                config=config,
                evaluator=self,
            )
            object.__setattr__(self, "_ledger", ledger)
            object.__setattr__(self, "_config", config)
            object.__setattr__(self, "_config_binding_sha256", materializer_port.config_sha256)
            object.__setattr__(self, "_materializer_port", materializer_port)
            object.__setattr__(self, "_records", {})
            object.__setattr__(self, "_manifest_rows", {})
            object.__setattr__(self, "_truth_registry", {})
            object.__setattr__(self, "_vaults", {})
            object.__setattr__(self, "_closed", set())
            object.__setattr__(
                self,
                "_materializer_initialization_nonce",
                _MATERIALIZER_FACTORY_NONCE,
            )
            if id(self) in _FORMAL_EVALUATOR_INITIALIZATION_REGISTRY:
                raise PermissionError("formal evaluator initialization identity already exists")
            _FORMAL_EVALUATOR_INITIALIZATION_REGISTRY[id(self)] = self
        except BaseException:
            progress = _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS.get(id(self))
            if (
                materializer_authority is None
                and type(progress) is tuple
                and len(progress) == 3
                and progress[0] is self
                and progress[1] is authority
                and type(progress[2]) is _MaterializerConstructionAuthority
            ):
                materializer_authority = progress[2]
            for port_registration in tuple(_TRUSTED_MATERIALIZER_PORT_REGISTRY.values()):
                if (
                    type(port_registration) is _MaterializerPortRegistration
                    and port_registration.evaluator is self
                ):
                    with contextlib.suppress(BaseException):
                        _revoke_trusted_materializer_port(port_registration.port)
                    port_registration.state = "failed"
            if materializer_authority is not None:
                materializer_registration = _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.get(
                    id(materializer_authority)
                )
                if (
                    type(materializer_registration) is _MaterializerConstructionRegistration
                    and materializer_registration.authority is materializer_authority
                ):
                    materializer_registration.state = "failed"
                _MATERIALIZER_CONSTRUCTION_IN_PROGRESS.discard(id(materializer_authority))
            evaluator_registration = _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.get(id(authority))
            if (
                type(evaluator_registration) is tuple
                and len(evaluator_registration) == 5
                and evaluator_registration[0] is authority
            ):
                _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY[id(authority)] = (
                    authority,
                    evaluator_registration[1],
                    evaluator_registration[2],
                    "failed",
                    evaluator_registration[4],
                )
            raise
        finally:
            _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS.pop(id(self), None)

    def _initialize_formal_science(self) -> None:
        if hasattr(self, "_scene"):
            if not all(
                hasattr(self, name) for name in ("_owner", "_runtime_config", "_accepted_config")
            ):
                raise PermissionError("formal evaluator science binding is partial")
            return
        _trusted_materializer_port_registration(
            self._materializer_port,
            evaluator=self,
        )
        runtime_config = require_frozen_config(_frozen_config_path())
        materializer_config = asdict(runtime_config)
        if _materializer_config_sha256(
            materializer_config
        ) != self._config_binding_sha256 or _materializer_config_native(
            materializer_config,
            label="formal runtime config",
        ) != _materializer_config_native(
            self._config,
            label="formal materializer config",
        ):
            raise PermissionError("formal evaluator runtime config differs from its authority")
        scene = _formal_scene_module()
        owner = _accepted_orbital_owner()
        accepted_config = _accepted_config_for_inherited_surface(
            runtime_config,
            owner,
        )
        object.__setattr__(self, "_runtime_config", runtime_config)
        object.__setattr__(self, "_scene", scene)
        object.__setattr__(self, "_owner", owner)
        object.__setattr__(self, "_accepted_config", accepted_config)

    def evaluate_public_batch(
        self,
        request: PublicBatchEvaluationRequest,
    ) -> Mapping[str, Any]:
        _trusted_materializer_port_registration(
            self._materializer_port,
            evaluator=self,
        )
        if (
            type(request) is not PublicBatchEvaluationRequest
            or request.split in self._closed
            or request._manifest._ledger is not self._ledger
        ):
            raise PermissionError("formal public evaluator request differs")
        self._initialize_formal_science()
        vault = self._vaults.get(request.split)
        if vault is None:
            vault = _open_materializer_split_vault(
                self._materializer_port,
                split=request.split,
            )
            self._vaults[request.split] = vault
        authorities = _begin_formal_public_science_materialization(
            self._materializer_port,
            vault,
            request,
        )
        evaluation = self._evaluate_formal_public_batch(
            request,
            authorities=authorities,
        )
        record = self._records[request.split][-1]
        sensors, tasks, runtime = _formal_materializer_tensor_payload(record)
        _issue_public_materialization_envelope(
            self._materializer_port,
            vault,
            request,
            sensor_tensors=sensors,
            safe_task_tensors=tasks,
            public_runtime_tensors=runtime,
            preauthorized_token_receipts=record["token_receipts"],
            evaluation=evaluation,
        )
        return evaluation

    def finalize_public_split(
        self,
        split: str,
        batch_results: Sequence[Mapping[str, Any]],
    ) -> Mapping[str, Any]:
        _trusted_materializer_port_registration(
            self._materializer_port,
            evaluator=self,
        )
        if split in self._closed or split not in self._vaults:
            raise PermissionError("formal evaluator split was finalized twice or never opened")
        records = self._records.get(split, [])
        rows = self._manifest_rows.get(split, [])
        if (
            len(records) != SCENES_PER_SPLIT // BATCH_SIZE
            or len(rows) != SCENES_PER_SPLIT
            or len(batch_results) != SCENES_PER_SPLIT // BATCH_SIZE
            or any(key[0] == split for key in self._truth_registry)
        ):
            raise RuntimeError("formal evaluator split inventory is incomplete")
        for batch_index, (result, record) in enumerate(zip(batch_results, records, strict=True)):
            expected_ordinals = tuple(
                range(batch_index * BATCH_SIZE, (batch_index + 1) * BATCH_SIZE)
            )
            validated = _validated_batch_evaluation(
                copy.deepcopy(dict(result)),
                split=split,
                ordinals=expected_ordinals,
            )
            _exact_equal(
                validated["public_evidence"],
                record["numeric_evidence"],
                label=f"{split} in-memory/durable batch evidence {batch_index}",
            )
        if canonical_sha256(rows) != SPLIT_ADDRESS_SHA256[split]:
            raise RuntimeError("materialized rows differ from the frozen scene manifest")
        _finalize_materializer_public_split(
            self._materializer_port,
            self._vaults[split],
        )
        validated_results = [
            _validated_public_batch_evaluation(
                copy.deepcopy(dict(result)),
                split=split,
                ordinals=tuple(range(index * BATCH_SIZE, (index + 1) * BATCH_SIZE)),
            )
            for index, result in enumerate(batch_results)
        ]
        return {
            "schema": "rgbd_known_action_public_split_finalization_v1",
            "split": split,
            "public_call_count": SCENES_PER_SPLIT // BATCH_SIZE,
            "public_call_sha256": canonical_sha256(_public_call_rows(validated_results)),
            "public_evidence_sha256": canonical_sha256(
                [result["public_evidence"] for result in validated_results]
            ),
            "public_metrics_sha256": canonical_sha256(
                [result["public_metrics"] for result in validated_results]
            ),
            "public_resources_sha256": canonical_sha256(
                [result["public_resources"] for result in validated_results]
            ),
            "truth_access_count": 0,
        }

    def score_private_split(
        self,
        request: PrivateSplitScoringRequest,
    ) -> Mapping[str, Any]:
        _trusted_materializer_port_registration(
            self._materializer_port,
            evaluator=self,
        )
        if (
            type(request) is not PrivateSplitScoringRequest
            or request.split in self._closed
            or request.split not in self._vaults
            or request._manifest._ledger is not self._ledger
        ):
            raise PermissionError("formal private evaluator request differs")
        truth_request = _bind_materializer_private_request(
            self._materializer_port,
            self._vaults[request.split],
            request,
        )
        records = self._records.get(request.split, [])
        if (
            len(records) != SCENES_PER_SPLIT // BATCH_SIZE
            or any(
                any(
                    key in record
                    for key in (
                        "truth_position",
                        "truth_velocity",
                        "truth_none_position",
                        "truth_none_velocity",
                        "truth_cost",
                        "opposite_truth_cost",
                        "canonical_order",
                    )
                )
                for record in records
            )
            or any(key[0] == request.split for key in self._truth_registry)
        ):
            raise PermissionError("private truth predecessor inventory differs")
        query_indices = torch.tensor(self._scene.QUERY_FRAME_INDICES, dtype=torch.int64)
        for record in records:
            specifications = record["specifications"]
            physical_by_slot = record["physical_by_slot"]
            truth_positions: list[torch.Tensor] = []
            truth_velocities: list[torch.Tensor] = []
            truth_none_positions: list[torch.Tensor] = []
            truth_none_velocities: list[torch.Tensor] = []
            truth_costs: list[torch.Tensor] = []
            opposite_truth_costs: list[torch.Tensor] = []
            canonical_orders: list[torch.Tensor] = []
            for specification, row in zip(
                specifications,
                record["scene_rows"],
                strict=True,
            ):
                no_action_truth = self._scene.manual_prefix_trajectory(specification)
                truth_none_positions.append(
                    no_action_truth.positions.index_select(0, query_indices)
                )
                truth_none_velocities.append(
                    no_action_truth.velocities.index_select(0, query_indices)
                )
                candidate_positions: list[torch.Tensor] = []
                candidate_velocities: list[torch.Tensor] = []
                for display in range(CANDIDATE_COUNT):
                    canonical = self._scene.display_to_canonical(
                        specification.camera_stratum,
                        display,
                        order="pi",
                    )
                    trajectory = self._scene.manual_candidate_trajectory(
                        specification,
                        canonical,
                    )
                    candidate_positions.append(trajectory.positions.index_select(0, query_indices))
                    candidate_velocities.append(
                        trajectory.velocities.index_select(0, query_indices)
                    )
                truth_positions.append(torch.stack(candidate_positions))
                truth_velocities.append(torch.stack(candidate_velocities))
                costs = self._scene.candidate_costs(specification, order="pi")
                truth_costs.append(costs)
                opposite_truth_costs.append(
                    self._scene.candidate_costs(
                        specification,
                        order="pi",
                        opposite_goal=True,
                    )
                )
                canonical_orders.append(
                    torch.tensor(
                        self._scene.candidate_order(
                            specification.camera_stratum,
                            order="pi",
                        ),
                        dtype=torch.int64,
                    )
                )
                truth_key = (request.split, specification.ordinal)
                if truth_key in self._truth_registry:
                    raise PermissionError("formal truth row was materialized twice")
                self._truth_registry[truth_key] = {
                    "scene_metadata_sha256": canonical_sha256(row),
                    "canonical_winner": specification.optimal_canonical_index,
                    "truth_costs": costs.clone(),
                }
            record["truth_position"] = _gather_truth_by_slot(
                torch.stack(truth_positions),
                physical_by_slot,
            )
            record["truth_velocity"] = _gather_truth_by_slot(
                torch.stack(truth_velocities),
                physical_by_slot,
            )
            record["truth_none_position"] = _gather_truth_by_slot(
                torch.stack(truth_none_positions),
                physical_by_slot,
            )
            record["truth_none_velocity"] = _gather_truth_by_slot(
                torch.stack(truth_none_velocities),
                physical_by_slot,
            )
            record["truth_cost"] = torch.stack(truth_costs)
            record["opposite_truth_cost"] = torch.stack(opposite_truth_costs)
            record["canonical_order"] = torch.stack(canonical_orders)
        if sum(1 for key in self._truth_registry if key[0] == request.split) != SCENES_PER_SPLIT:
            raise RuntimeError("private truth inventory is incomplete")
        action_metrics = _aggregate_action_metrics(
            records,
            self._scene,
            owner=self._owner,
            config=self._accepted_config,
        )
        inherited_metrics = _aggregate_inherited_orbital_metrics(
            records,
            owner=self._owner,
            config=self._accepted_config,
            split=request.split,
        )
        inherited = _inherited_orbital_evidence(inherited_metrics)
        commitments = _formal_materializer_private_rows(
            self._materializer_port,
            self._vaults[request.split],
            request,
        )
        receipt = _formal_private_scoring_receipt(
            split=request.split,
            public_seal_sha256=request.public_seal_sha256,
            truth_request=truth_request,
            private_row_commitments=commitments,
            metrics=action_metrics,
            inherited_orbital_evidence=inherited,
        )
        self._closed.add(request.split)
        self._records.pop(request.split, None)
        self._manifest_rows.pop(request.split, None)
        for key in tuple(self._truth_registry):
            if key[0] == request.split:
                self._truth_registry.pop(key, None)
        return receipt

    def abort_split(self, split: str) -> None:
        try:
            _abort_materializer_split(self._materializer_port, split=split)
        finally:
            self._closed.add(split)
            self._records.pop(split, None)
            self._manifest_rows.pop(split, None)
            self._vaults.pop(split, None)
            for key in tuple(self._truth_registry):
                if key[0] == split:
                    self._truth_registry.pop(key, None)

    def _planning_inputs(
        self,
        *,
        model: Any,
        safe: Mapping[str, torch.Tensor],
        prototype: torch.Tensor | None = None,
        goal_positions: torch.Tensor | None = None,
    ) -> tuple[torch.Tensor, tuple[Any, ...], Any]:
        planning_module = importlib.import_module("world_model.planning")
        belief = model.belief
        if belief is None:
            raise RuntimeError("public model did not retain a causal belief")
        resolved = planning_module.resolve_appearance_handle(
            belief,
            (safe["observable_handle_prototype"] if prototype is None else prototype).to(
                device=belief.device, dtype=belief.dtype
            ),
            minimum_cosine_margin=0.10,
        )
        actions = _materialize_actions(safe=safe, object_id=resolved, belief=belief)
        goal = planning_module.TerminalWorldPositionGoal(
            object_id=resolved.clone(),
            position_world=(
                safe["goal_positions_world"] if goal_positions is None else goal_positions
            )
            .to(device=belief.device, dtype=belief.dtype)
            .clone(),
        )
        return resolved, actions, goal

    def _evaluate_formal_public_batch(
        self,
        request: BatchEvaluationRequest,
        *,
        authorities: tuple[
            _ConsumedOrdinalAuthority,
            _ConsumedOrdinalAuthority,
            _ConsumedOrdinalAuthority,
            _ConsumedOrdinalAuthority,
        ],
    ) -> dict[str, Any]:
        if request.split in self._closed:
            raise PermissionError("formal evaluator split is already closed")
        scene = self._scene
        (
            specifications,
            episodes,
            palette_episodes,
            token_receipts,
        ) = _construct_authorized_formal_batch(
            request,
            authorities=authorities,
            scene=scene,
            owner=self._owner,
            config=self._accepted_config,
        )
        rows = [scene.scene_metadata(specification) for specification in specifications]
        if [row["ordinal"] for row in rows] != list(request.ordinals):
            raise RuntimeError("scene metadata address differs from authorized ordinals")
        datasets = importlib.import_module("world_model.datasets")
        batch = datasets.collate_episodes(episodes)
        output = self._owner._run_public_batch(batch, self._accepted_config)
        model = output["model"]
        belief = model.belief
        if belief is None:
            raise RuntimeError("public model did not retain a causal belief")
        source_belief = belief.clone()
        safe = scene.collate_observable_tasks(specifications, order="pi")
        _validate_safe_task_tensors(safe)
        resolved_id, actions, goal = self._planning_inputs(model=model, safe=safe)

        rss_before = _process_max_rss_bytes()
        started = time.perf_counter()
        plan = model.plan(HORIZONS_SECONDS, actions, goal)
        elapsed = time.perf_counter() - started
        rss_after = _process_max_rss_bytes()
        none = model.predict(HORIZONS_SECONDS, action=None)
        none_repeat = model.predict(HORIZONS_SECONDS, action=None)
        zero_action = replace(actions[0], impulse_world=torch.zeros_like(actions[0].impulse_world))
        zero = model.predict(HORIZONS_SECONDS, action=zero_action)

        safe_rho = scene.collate_observable_tasks(specifications, order="rho")
        _validate_safe_task_tensors(safe_rho)
        rho_id, rho_actions, rho_goal = self._planning_inputs(model=model, safe=safe_rho)
        if not torch.equal(rho_id, resolved_id):
            raise RuntimeError("candidate permutation changed appearance resolution")
        rho_plan = model.plan(HORIZONS_SECONDS, rho_actions, rho_goal)

        opposite_positions = torch.stack(
            [scene.terminal_goal(specification, opposite=True) for specification in specifications]
        )
        _, _, opposite_goal = self._planning_inputs(
            model=model,
            safe=safe,
            goal_positions=opposite_positions,
        )
        opposite_plan = model.plan(HORIZONS_SECONDS, actions, opposite_goal)

        other_prototype = torch.tensor(
            [
                scene.HANDLE_PROTOTYPES[1 - specification.handle_role]
                for specification in specifications
            ],
            dtype=torch.float32,
        )
        wrong_id, wrong_actions, _ = self._planning_inputs(
            model=model,
            safe=safe,
            prototype=other_prototype,
        )
        if bool(wrong_id.eq(resolved_id).any()):
            raise RuntimeError("opposite observable handle did not resolve to a distinct ID")
        wrong_plan = model.plan(HORIZONS_SECONDS, wrong_actions, goal)

        planning_module = importlib.import_module("world_model.planning")
        active_appearance = belief.objects.appearance.masked_fill(
            ~belief.objects.active.unsqueeze(-1), 0.0
        )
        norms = torch.linalg.vector_norm(active_appearance, dim=-1, keepdim=True).clamp_min(1.0e-12)
        normalised = active_appearance / norms
        ambiguous = normalised.sum(dim=1)
        tensor_utils = importlib.import_module("world_model.utils.tensors")

        def one_row(value: Any, row_index: int) -> Any:
            return tensor_utils.map_tensors(
                value,
                lambda tensor: (
                    tensor[row_index : row_index + 1].clone()
                    if tensor.ndim and tensor.shape[0] == BATCH_SIZE
                    else tensor.clone()
                ),
            )

        rejection_counts = {
            "ambiguous": 0,
            "invalid": 0,
            "pre_anchor": 0,
            "equal_anchor": 0,
            "inactive": 0,
            "duplicate": 0,
            "non_free": 0,
        }
        for row_index in range(BATCH_SIZE):
            row_belief = one_row(belief, row_index)
            row_action = replace(
                actions[0],
                timestamp=actions[0].timestamp[row_index : row_index + 1].clone(),
                object_id=actions[0].object_id[row_index : row_index + 1].clone(),
                impulse_world=actions[0].impulse_world[row_index : row_index + 1].clone(),
            )
            latest_timestamp = row_belief.timestamp + HORIZONS_SECONDS[-1]

            def action_rejected(
                candidate: Any,
                candidate_belief: Any,
                candidate_latest_timestamp: torch.Tensor,
            ) -> bool:
                try:
                    candidate.validate_for(
                        candidate_belief,
                        latest_timestamp=candidate_latest_timestamp,
                    )
                except ValueError:
                    return True
                return False

            try:
                planning_module.resolve_appearance_handle(
                    row_belief,
                    ambiguous[row_index : row_index + 1].clone(),
                    minimum_cosine_margin=0.10,
                )
            except ValueError:
                rejection_counts["ambiguous"] += 1
            invalid_id = row_belief.objects.object_id.max(dim=-1).values + 1
            rejection_counts["invalid"] += int(
                action_rejected(
                    replace(row_action, object_id=invalid_id),
                    row_belief,
                    latest_timestamp,
                )
            )
            rejection_counts["pre_anchor"] += int(
                action_rejected(
                    replace(
                        row_action,
                        timestamp=row_belief.timestamp
                        - row_belief.timestamp.new_full(
                            row_belief.timestamp.shape,
                            MATERIALIZER_SENSOR_TIMESTEP_SECONDS,
                        ),
                    ),
                    row_belief,
                    latest_timestamp,
                )
            )
            rejection_counts["equal_anchor"] += int(
                action_rejected(
                    replace(row_action, timestamp=row_belief.timestamp.clone()),
                    row_belief,
                    latest_timestamp,
                )
            )
            target_mask = (
                row_belief.objects.object_id.eq(row_action.object_id[:, None])
                & row_belief.objects.active
            )
            if int(target_mask.sum()) != 1:
                raise RuntimeError("public action target did not resolve uniquely for controls")
            target_slot_for_control = int(target_mask.to(torch.int64).argmax(dim=-1)[0])
            distractor_slot_for_control = 1 - target_slot_for_control
            inactive_objects = row_belief.objects.clone()
            inactive_objects.active[0, target_slot_for_control] = False
            rejection_counts["inactive"] += int(
                action_rejected(
                    row_action,
                    row_belief.replace(objects=inactive_objects),
                    latest_timestamp,
                )
            )
            duplicate_objects = row_belief.objects.clone()
            duplicate_objects.object_id[0, distractor_slot_for_control] = row_action.object_id[0]
            rejection_counts["duplicate"] += int(
                action_rejected(
                    row_action,
                    row_belief.replace(objects=duplicate_objects),
                    latest_timestamp,
                )
            )
            non_free_objects = row_belief.objects.clone()
            non_free_objects.motion_mode_logits[0, target_slot_for_control] = -100.0
            non_free_objects.motion_mode_logits[0, target_slot_for_control, 1] = 100.0
            rejection_counts["non_free"] += int(
                action_rejected(
                    row_action,
                    row_belief.replace(objects=non_free_objects),
                    latest_timestamp,
                )
            )

        physical_by_slot = _physical_by_slot(output, batch, self._owner)
        palette_batch = datasets.collate_episodes(palette_episodes)
        palette_output = self._owner._run_public_batch(palette_batch, self._accepted_config)
        palette_model = palette_output["model"]
        palette_id, palette_actions, palette_goal = self._planning_inputs(
            model=palette_model,
            safe=safe,
            prototype=other_prototype,
        )
        palette_plan = palette_model.plan(HORIZONS_SECONDS, palette_actions, palette_goal)
        palette_mapping = _physical_by_slot(palette_output, palette_batch, self._owner)

        public_positions = torch.stack(
            [trajectory.positions for trajectory in plan.trajectories], 1
        )
        public_velocities = torch.stack(
            [trajectory.velocities for trajectory in plan.trajectories], 1
        )
        none_positions = none.positions[:, None]
        none_velocities = none.velocities[:, None]
        palette_positions = torch.stack(
            [trajectory.positions for trajectory in palette_plan.trajectories], 1
        )
        palette_velocities = torch.stack(
            [trajectory.velocities for trajectory in palette_plan.trajectories], 1
        )
        original_by_physical_position = _slot_values_by_physical(public_positions, physical_by_slot)
        original_by_physical_velocity = _slot_values_by_physical(
            public_velocities, physical_by_slot
        )
        palette_by_physical_position = _slot_values_by_physical(palette_positions, palette_mapping)
        palette_by_physical_velocity = _slot_values_by_physical(palette_velocities, palette_mapping)

        target_slot = (plan.object_id_by_slot == resolved_id[:, None]).to(torch.int64).argmax(-1)
        wrong_slot = (plan.object_id_by_slot == wrong_id[:, None]).to(torch.int64).argmax(-1)
        batch_index = torch.arange(BATCH_SIZE)
        wrong_positions = torch.stack(
            [trajectory.positions for trajectory in wrong_plan.trajectories], 1
        )
        wrong_intended_delta = (
            wrong_positions[batch_index, :, :, target_slot]
            - none.positions[batch_index, None, :, target_slot]
        )
        wrong_other_delta = (
            wrong_positions[batch_index, :, :, wrong_slot]
            - none.positions[batch_index, None, :, wrong_slot]
        )

        handle_prototype = safe["observable_handle_prototype"].to(belief.dtype)
        appearance_norm = belief.objects.appearance / torch.linalg.vector_norm(
            belief.objects.appearance, dim=-1, keepdim=True
        ).clamp_min(1.0e-12)
        prototype_norm = handle_prototype / torch.linalg.vector_norm(
            handle_prototype, dim=-1, keepdim=True
        ).clamp_min(1.0e-12)
        cosine = torch.einsum("bd,bnd->bn", prototype_norm, appearance_norm).masked_fill(
            ~belief.objects.active, -torch.inf
        )
        handle_margin = torch.topk(cosine, k=2, dim=-1).values
        handle_margin = handle_margin[:, 0] - handle_margin[:, 1]

        preflight = [
            self._owner.preflight_two_visible_orbital_camera_episode(
                episode,
                config=self._accepted_config,
                specification=_accepted_specification_view(scene, self._owner, specification),
            )
            for episode, specification in zip(episodes, specifications, strict=True)
        ]
        observation_hashes = [_observation_prefix_sha256(episode) for episode in episodes]
        record = {
            "split": request.split,
            "ordinals": request.ordinals,
            "specifications": specifications,
            "scene_rows": rows,
            "episodes": episodes,
            "batch": batch,
            "output": output,
            "safe": safe,
            "safe_rho": safe_rho,
            "opposite_goal_positions_world": opposite_positions,
            "alternate_handle_prototype": other_prototype,
            "token_receipts": token_receipts,
            "resolved_id": resolved_id,
            "rho_id": rho_id,
            "wrong_id": wrong_id,
            "palette_id": palette_id,
            "plan": plan,
            "rho_plan": rho_plan,
            "opposite_plan": opposite_plan,
            "wrong_plan": wrong_plan,
            "palette_plan": palette_plan,
            "none": none,
            "zero": zero,
            "physical_by_slot": physical_by_slot,
            "public_positions": public_positions,
            "public_velocities": public_velocities,
            "none_positions": none_positions,
            "none_velocities": none_velocities,
            "wrong_intended_delta": wrong_intended_delta,
            "wrong_other_delta": wrong_other_delta,
            "palette_position_error": (
                original_by_physical_position - palette_by_physical_position
            ).abs(),
            "palette_velocity_error": (
                original_by_physical_velocity - palette_by_physical_velocity
            ).abs(),
            "palette_cost_error": (plan.total_cost - palette_plan.total_cost).abs(),
            "palette_choice_match": plan.selected_index.eq(palette_plan.selected_index),
            "handle_margin": handle_margin,
            "rejection_counts": rejection_counts,
            "none_repeat_mismatch": _tensor_structure_mismatch_count(
                none,
                none_repeat,
                label="repeated no-action trajectory",
            ),
            "preflight": preflight,
            "observation_hashes": observation_hashes,
            "planning_seconds": float(elapsed),
            "planning_rss_delta_bytes": float(max(0, rss_after - rss_before)),
            "process_max_rss_bytes": float(rss_after),
            "live_result_storage_bytes": float(_live_tensor_bytes(plan)),
            "source_belief": source_belief,
            "source_belief_bit_mismatch_count": _tensor_structure_mismatch_count(
                source_belief,
                belief,
                label="public planning source belief",
            ),
        }
        row_receipts = [
            _numeric_row_evidence(
                split=request.split,
                ordinal=ordinal,
                row_index=row_index,
                token_receipt=token_receipts[row_index],
                scene_row=rows[row_index],
                episode=episodes[row_index],
                safe=safe,
                output=output,
                plan=plan,
                rho_plan=rho_plan,
                opposite_plan=opposite_plan,
                wrong_plan=wrong_plan,
                palette_plan=palette_plan,
            )
            for row_index, ordinal in enumerate(request.ordinals)
        ]
        numeric_evidence = _validated_numeric_batch_evidence(
            {
                "schema": "rgbd_known_action_public_numeric_batch_evidence_v2",
                "split": request.split,
                "ordinals": list(request.ordinals),
                "batch_index": request.ordinals[0] // BATCH_SIZE,
                "tensor_digest_recipe": ("length_framed_little_endian_dtype_shape_C_order_v1"),
                "row_receipts": row_receipts,
                "ordered_row_receipts_sha256": canonical_sha256(
                    [row["receipt_sha256"] for row in row_receipts]
                ),
                "restricted_rows_exposed": False,
            },
            split=request.split,
            ordinals=request.ordinals,
        )
        record["numeric_evidence"] = numeric_evidence
        self._records.setdefault(request.split, []).append(record)
        self._manifest_rows.setdefault(request.split, []).extend(rows)

        return {
            "schema": "rgbd_known_action_public_batch_evaluation_v2",
            "split": request.split,
            "ordinals": list(request.ordinals),
            "bundle_count": BATCH_SIZE,
            "candidate_count": BATCH_SIZE * CANDIDATE_COUNT,
            "public_evidence": numeric_evidence,
            "public_evidence_sha256": canonical_sha256(numeric_evidence),
            "public_metrics": {
                "schema": "rgbd_known_action_public_batch_metrics_v1",
                "public_numeric_evidence_sha256": canonical_sha256(numeric_evidence),
                "public_row_count": BATCH_SIZE,
                "public_candidate_count": BATCH_SIZE * CANDIDATE_COUNT,
            },
            "public_resources": {
                "schema": "rgbd_known_action_public_resource_observation_v1",
                "planning_seconds": float(elapsed),
                "planning_rss_delta_bytes": float(max(0, rss_after - rss_before)),
                "process_max_rss_bytes": float(rss_after),
                "live_result_storage_bytes": float(_live_tensor_bytes(plan)),
                "public_call_count": 1,
            },
        }


def _action_gradient_metrics(record: Mapping[str, Any]) -> dict[str, float]:
    """Audit the exact row-local action Jacobian and candidate graph topology."""

    model = record["output"]["model"]
    belief = model.belief
    if belief is None:
        raise RuntimeError("action gradient audit requires a public belief")
    safe = record["safe"]
    object_id = record["resolved_id"]
    base_actions = _materialize_actions(safe=safe, object_id=object_id, belief=belief)
    delay = base_actions[0].timestamp - belief.timestamp
    boundary_queries = torch.stack(
        (
            torch.full_like(delay, 0.10),
            torch.full_like(delay, 0.25),
            delay,
            torch.full_like(delay, 1.0),
            torch.full_like(delay, 2.0),
        ),
        dim=-1,
    )
    impulse = base_actions[0].impulse_world.detach().clone().requires_grad_(True)

    def response(value: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        trajectory = model.predict(
            boundary_queries,
            action=replace(base_actions[0], impulse_world=value),
        )
        return trajectory.positions, trajectory.velocities

    jacobian_position, jacobian_velocity = torch.autograd.functional.jacobian(
        response,
        impulse,
        create_graph=False,
        strict=True,
        vectorize=False,
    )
    # [B,T,N,xyz,B,input_xyz]
    expected_position = torch.zeros_like(jacobian_position)
    expected_velocity = torch.zeros_like(jacobian_velocity)
    target_slot = (belief.objects.object_id == object_id[:, None]).to(torch.int64).argmax(dim=-1)
    for batch_index in range(BATCH_SIZE):
        slot = int(target_slot[batch_index])
        mass = belief.objects.mass[batch_index, slot, 0]
        drag = belief.objects.drag[batch_index, slot, 0]
        for query_index in range(boundary_queries.shape[1]):
            elapsed = boundary_queries[batch_index, query_index] - delay[batch_index]
            if float(elapsed) < 0.0:
                continue
            decay = torch.exp(-drag * elapsed)
            displacement = torch.where(
                drag >= 1.0e-5,
                -torch.expm1(-drag * elapsed) / drag.clamp_min(1.0e-12),
                elapsed,
            )
            for axis in range(3):
                expected_position[batch_index, query_index, slot, axis, batch_index, axis] = (
                    displacement / mass
                )
                expected_velocity[batch_index, query_index, slot, axis, batch_index, axis] = (
                    decay / mass
                )

    batch_axis = torch.arange(BATCH_SIZE)
    boundary_velocity_error = (
        jacobian_velocity[batch_axis, 2, target_slot, :, batch_axis]
        - expected_velocity[batch_axis, 2, target_slot, :, batch_axis]
    ).abs()
    cross_bundle_mask = torch.ones_like(jacobian_position, dtype=torch.bool)
    for batch_index in range(BATCH_SIZE):
        cross_bundle_mask[batch_index, ..., batch_index, :] = False
    distractor_mask = torch.zeros_like(jacobian_position, dtype=torch.bool)
    for batch_index in range(BATCH_SIZE):
        distractor_mask[batch_index, :, 1 - int(target_slot[batch_index]), ...] = True
    off_axis_mask = torch.zeros_like(jacobian_position, dtype=torch.bool)
    for axis in range(3):
        off_axis_mask[:, :, :, axis, :, :] |= torch.arange(3) != axis
    pre_mask = boundary_queries < delay[:, None]
    pre_position = jacobian_position[pre_mask]
    pre_velocity = jacobian_velocity[pre_mask]
    boundary_position = jacobian_position[:, 2]

    variables = tuple(
        action.impulse_world.detach().clone().requires_grad_(True) for action in base_actions
    )
    differentiable_actions = tuple(
        replace(action, impulse_world=value)
        for action, value in zip(base_actions, variables, strict=True)
    )
    planning_module = importlib.import_module("world_model.planning")
    goal = planning_module.TerminalWorldPositionGoal(
        object_id=object_id.clone(),
        position_world=record["safe"]["goal_positions_world"].to(belief.dtype).clone(),
    )
    differentiable_plan = model.plan(HORIZONS_SECONDS, differentiable_actions, goal)
    cross_candidate_max = 0.0
    own_cost_finite = 0
    own_cost_connected = 0
    own_cost_max_l1 = 0.0
    for candidate in range(CANDIDATE_COUNT):
        gradients = torch.autograd.grad(
            differentiable_plan.total_cost[:, candidate].sum(),
            variables,
            retain_graph=candidate + 1 < CANDIDATE_COUNT,
            allow_unused=True,
        )
        for other, gradient in enumerate(gradients):
            if other == candidate:
                if gradient is None:
                    continue
                per_row_l1 = gradient.abs().sum(dim=-1)
                own_cost_finite += int(torch.isfinite(gradient).all(dim=-1).sum())
                own_cost_connected += int(per_row_l1.gt(0.0).sum())
                own_cost_max_l1 = max(own_cost_max_l1, float(per_row_l1.max()))
                continue
            if gradient is None:
                continue
            cross_candidate_max = max(cross_candidate_max, float(gradient.abs().max()))

    connected = 0
    finite = 0
    vjp_values: list[float] = []
    coefficients = belief.objects.position.new_tensor((0.5, -0.75, 1.25))
    for action in base_actions:
        candidate_impulse = action.impulse_world.detach().clone().requires_grad_(True)
        trajectory = model.predict(
            HORIZONS_SECONDS,
            action=replace(action, impulse_world=candidate_impulse),
        )
        selected = trajectory.positions[batch_axis, -1, target_slot]
        selected = selected + trajectory.velocities[batch_axis, -1, target_slot]
        gradient = torch.autograd.grad((selected * coefficients).sum(), candidate_impulse)[0]
        finite += int(torch.isfinite(gradient).all(dim=-1).sum())
        connected += int(gradient.abs().sum(dim=-1).gt(0.0).sum())
        vjp_values.extend(gradient.abs().sum(dim=-1).detach().cpu().tolist())

    allowed = torch.cat(
        (
            jacobian_position[:, 3:].reshape(-1),
            jacobian_velocity[:, 3:].reshape(-1),
        )
    )
    if not bool(torch.isfinite(allowed).all()):
        raise FloatingPointError("action Jacobian contains nonfinite entries")
    return {
        "action_jacobian_position_max_abs_error": float(
            (jacobian_position - expected_position).abs().max()
        ),
        "action_jacobian_velocity_max_abs_error": float(
            (jacobian_velocity - expected_velocity).abs().max()
        ),
        "action_boundary_velocity_jacobian_error": float(boundary_velocity_error.max()),
        "action_pre_boundary_gradient_max_abs": float(
            max(float(pre_position.abs().max()), float(pre_velocity.abs().max()))
        ),
        "action_boundary_position_gradient_max_abs": float(boundary_position.abs().max()),
        "action_cross_bundle_gradient_max_abs": float(
            max(
                float(jacobian_position[cross_bundle_mask].abs().max()),
                float(jacobian_velocity[cross_bundle_mask].abs().max()),
            )
        ),
        "action_cross_candidate_cost_gradient_max_abs": cross_candidate_max,
        "action_own_cost_gradient_finite_fraction": float(
            own_cost_finite / (BATCH_SIZE * CANDIDATE_COUNT)
        ),
        "action_own_cost_graph_connected_fraction": float(
            own_cost_connected / (BATCH_SIZE * CANDIDATE_COUNT)
        ),
        "action_own_cost_gradient_max_l1": float(own_cost_max_l1),
        "action_distractor_gradient_max_abs": float(
            max(
                float(jacobian_position[distractor_mask].abs().max()),
                float(jacobian_velocity[distractor_mask].abs().max()),
            )
        ),
        "action_off_axis_gradient_max_abs": float(
            max(
                float(jacobian_position[off_axis_mask].abs().max()),
                float(jacobian_velocity[off_axis_mask].abs().max()),
            )
        ),
        "action_candidate_gradient_finite_fraction": float(finite / (BATCH_SIZE * CANDIDATE_COUNT)),
        "action_candidate_graph_connected_fraction": float(
            connected / (BATCH_SIZE * CANDIDATE_COUNT)
        ),
        "minimum_post_action_impulse_vjp_l1": float(min(vjp_values)),
        "maximum_post_action_impulse_vjp_l1": float(max(vjp_values)),
    }


def _action_sensor_vjp_metrics(
    records: Sequence[Mapping[str, Any]],
    *,
    scene: Any,
    owner: Any,
    config: OrpheusConfig,
) -> dict[str, float]:
    """Audit eight action-conditioned sensor VJPs in two fresh public B=4 calls."""

    if len(records) != SCENES_PER_SPLIT // BATCH_SIZE:
        raise RuntimeError("action sensor VJP audit requires sixteen public records")
    by_ordinal: dict[int, tuple[Any, Mapping[str, Any]]] = {}
    for record in records:
        ordinals = record["ordinals"]
        specifications = record["specifications"]
        episodes = record["episodes"]
        if (
            type(ordinals) is not tuple
            or len(ordinals) != BATCH_SIZE
            or len(specifications) != BATCH_SIZE
            or len(episodes) != BATCH_SIZE
        ):
            raise RuntimeError("action sensor VJP source record is malformed")
        for ordinal, specification, episode in zip(
            ordinals,
            specifications,
            episodes,
            strict=True,
        ):
            if type(ordinal) is not int or ordinal in by_ordinal:
                raise RuntimeError("action sensor VJP ordinal inventory is not unique")
            by_ordinal[ordinal] = (specification, episode)
    if set(by_ordinal) != set(ORDINALS):
        raise RuntimeError("action sensor VJP source inventory is incomplete")

    datasets = importlib.import_module("world_model.datasets")
    planning_module = importlib.import_module("world_model.planning")
    modality_l1: dict[str, list[float]] = {
        "rgb": [],
        "depth": [],
        "world_from_camera": [],
        "intrinsics": [],
    }
    finite_count = 0
    connected_count = 0
    supported_history_frames: list[int] = []
    cross_scene_max_l1 = 0.0
    homogeneous_last_row_max_abs = 0.0
    packet_count = 0
    plan_count = 0
    audited_specifications: list[Any] = []
    audited_displays: list[int] = []
    display_by_ordinal = dict(
        zip(ACTION_SENSOR_VJP_ORDINALS, ACTION_SENSOR_VJP_DISPLAY_INDICES, strict=True)
    )
    coefficients: torch.Tensor | None = None

    for group in ACTION_SENSOR_VJP_GROUPS:
        specifications = [by_ordinal[ordinal][0] for ordinal in group]
        episodes = [by_ordinal[ordinal][1] for ordinal in group]
        audited_specifications.extend(specifications)
        displays = [display_by_ordinal[ordinal] for ordinal in group]
        audited_displays.extend(displays)
        batch = datasets.collate_episodes(episodes)
        history = torch.arange(HISTORY_FRAME_COUNT, dtype=torch.int64)
        differentiable = dict(batch)
        differentiable["rgb"] = batch["rgb"].index_select(1, history).clone().requires_grad_(True)
        differentiable["depth"] = (
            batch["depth"].index_select(1, history).clone().requires_grad_(True)
        )
        differentiable["timestamps"] = batch["timestamps"].index_select(1, history).clone()
        differentiable_camera: dict[str, Any] = {}
        for name, value in batch["camera"].items():
            selected = (
                value.index_select(1, history.to(value.device)).clone()
                if isinstance(value, torch.Tensor)
                else value
            )
            if name in {"world_from_camera", "intrinsics"}:
                selected.requires_grad_(True)
            differentiable_camera[name] = selected
        differentiable["camera"] = differentiable_camera

        output = owner._run_public_batch(differentiable, config)
        if type(output.get("packet_count")) is not int:
            raise RuntimeError("action sensor VJP public ingest count is malformed")
        packet_count += output["packet_count"]
        model = output["model"]
        belief = model.belief
        if belief is None:
            raise RuntimeError("action sensor VJP public model retained no belief")
        safe = scene.collate_observable_tasks(specifications, order="pi")
        _validate_safe_task_tensors(safe)
        resolved = planning_module.resolve_appearance_handle(
            belief,
            safe["observable_handle_prototype"].to(
                device=belief.device,
                dtype=belief.dtype,
            ),
            minimum_cosine_margin=0.10,
        )
        actions = _materialize_actions(safe=safe, object_id=resolved, belief=belief)
        goal = planning_module.TerminalWorldPositionGoal(
            object_id=resolved.clone(),
            position_world=safe["goal_positions_world"].to(
                device=belief.device,
                dtype=belief.dtype,
            ),
        )
        plan = model.plan(HORIZONS_SECONDS, actions, goal)
        plan_count += 1
        target_slot = belief.objects.object_id.eq(resolved[:, None]).to(torch.int64).argmax(-1)
        if coefficients is None:
            coefficients = belief.objects.position.new_tensor((0.5, -0.75, 1.25))
        inputs = (
            differentiable["rgb"],
            differentiable["depth"],
            differentiable["camera"]["world_from_camera"],
            differentiable["camera"]["intrinsics"],
        )
        for row_index, display in enumerate(displays):
            trajectory = plan.trajectories[display]
            slot = int(target_slot[row_index])
            selected = (
                trajectory.positions[row_index, -1, slot]
                + trajectory.velocities[row_index, -1, slot]
            )
            loss = (selected * coefficients).mean()
            gradient_values = torch.autograd.grad(
                loss,
                inputs,
                retain_graph=row_index + 1 < BATCH_SIZE,
                allow_unused=True,
            )
            for modality, source, gradient in zip(
                modality_l1,
                inputs,
                gradient_values,
                strict=True,
            ):
                resolved_gradient = torch.zeros_like(source) if gradient is None else gradient
                is_finite = bool(torch.isfinite(resolved_gradient).all())
                finite_count += int(is_finite)
                if not is_finite:
                    raise FloatingPointError(
                        f"action sensor VJP {modality} contains a nonfinite value"
                    )
                per_scene_l1 = resolved_gradient.abs().reshape(BATCH_SIZE, -1).sum(dim=-1)
                own_l1 = float(per_scene_l1[row_index])
                modality_l1[modality].append(own_l1)
                connected_count += int(own_l1 >= 1.0e-8)
                cross_scene = torch.cat((per_scene_l1[:row_index], per_scene_l1[row_index + 1 :]))
                cross_scene_max_l1 = max(
                    cross_scene_max_l1,
                    float(cross_scene.max()) if cross_scene.numel() else 0.0,
                )
                target_gradient = resolved_gradient[row_index]
                per_frame_l1 = target_gradient.abs().reshape(HISTORY_FRAME_COUNT, -1).sum(-1)
                supported_history_frames.append(int(per_frame_l1.ge(1.0e-8).sum()))
                if modality == "world_from_camera":
                    homogeneous_last_row_max_abs = max(
                        homogeneous_last_row_max_abs,
                        float(target_gradient[..., 3, :].abs().max()),
                    )

    primitive_counts = {
        index: sum(
            specification.primitive_index == index for specification in audited_specifications
        )
        for index in range(4)
    }
    role_counts = {
        index: sum(specification.handle_role == index for specification in audited_specifications)
        for index in range(2)
    }
    camera_counts = {
        index: sum(
            specification.camera_stratum == index for specification in audited_specifications
        )
        for index in range(8)
    }
    delay_values = sorted(
        {specification.action_delay_numerator for specification in audited_specifications}
    )
    delay_counts = {
        value: sum(
            specification.action_delay_numerator == value
            for specification in audited_specifications
        )
        for value in delay_values
    }
    display_counts = {
        index: sum(display == index for display in audited_displays)
        for index in range(CANDIDATE_COUNT)
    }
    denominator = len(audited_specifications) * len(modality_l1)
    if denominator != 32 or any(not values for values in modality_l1.values()):
        raise RuntimeError("action sensor VJP audit coverage is malformed")
    return {
        "action_sensor_vjp_audit_ordinal_count": float(len(audited_specifications)),
        "action_sensor_vjp_audit_group_count": float(len(ACTION_SENSOR_VJP_GROUPS)),
        "action_sensor_vjp_primitive_coverage_per_index": float(min(primitive_counts.values())),
        "action_sensor_vjp_role_coverage_per_value": float(min(role_counts.values())),
        "action_sensor_vjp_camera_coverage_per_index": float(min(camera_counts.values())),
        "action_sensor_vjp_delay_rank_coverage_per_index": float(min(delay_counts.values())),
        "action_sensor_vjp_candidate_coverage_per_index": float(min(display_counts.values())),
        "action_sensor_vjp_extra_public_ingest_count": float(packet_count),
        "action_sensor_vjp_extra_public_plan_count": float(plan_count),
        "action_sensor_vjp_finite_fraction": float(finite_count / denominator),
        "action_sensor_vjp_connected_fraction": float(connected_count / denominator),
        "action_sensor_vjp_min_supported_history_frames": float(min(supported_history_frames)),
        "action_sensor_vjp_cross_scene_max_l1": float(cross_scene_max_l1),
        "action_sensor_vjp_wfc_homogeneous_last_row_max_abs": float(homogeneous_last_row_max_abs),
        "action_sensor_vjp_rgb_min_l1": float(min(modality_l1["rgb"])),
        "action_sensor_vjp_rgb_max_l1": float(max(modality_l1["rgb"])),
        "action_sensor_vjp_depth_min_l1": float(min(modality_l1["depth"])),
        "action_sensor_vjp_depth_max_l1": float(max(modality_l1["depth"])),
        "action_sensor_vjp_world_from_camera_min_l1": float(min(modality_l1["world_from_camera"])),
        "action_sensor_vjp_world_from_camera_max_l1": float(max(modality_l1["world_from_camera"])),
        "action_sensor_vjp_intrinsics_min_l1": float(min(modality_l1["intrinsics"])),
        "action_sensor_vjp_intrinsics_max_l1": float(max(modality_l1["intrinsics"])),
    }


def _aggregate_action_metrics(
    records: Sequence[Mapping[str, Any]],
    scene: Any,
    *,
    owner: Any = None,
    config: OrpheusConfig | None = None,
    action_gradient_metrics: Mapping[str, Any] | None = None,
    action_sensor_metrics: Mapping[str, Any] | None = None,
) -> dict[str, float]:
    if len(records) != SCENES_PER_SPLIT // BATCH_SIZE:
        raise RuntimeError("action aggregation requires sixteen complete B=4 records")
    planning_seconds = sorted(float(record["planning_seconds"]) for record in records)
    p95_index = max(0, math.ceil(0.95 * len(planning_seconds)) - 1)
    action_delta_position_errors: list[torch.Tensor] = []
    action_delta_velocity_errors: list[torch.Tensor] = []
    conditioned_position_errors: list[torch.Tensor] = []
    conditioned_velocity_errors: list[torch.Tensor] = []
    cost_errors: list[torch.Tensor] = []
    truth_gaps: list[torch.Tensor] = []
    public_gaps: list[torch.Tensor] = []
    optimal_errors: list[torch.Tensor] = []
    optimal_costs: list[torch.Tensor] = []
    handle_margins: list[torch.Tensor] = []
    resolution_count = 0
    unique_resolution_count = 0
    pi_matches = 0
    rho_matches = 0
    opposite_matches = 0
    wrong_distinct = 0
    wrong_other_nonzero = 0
    wrong_cost_worse = 0
    invalid_rejected = 0
    ambiguous_rejected = 0
    pre_anchor_rejected = 0
    equal_anchor_rejected = 0
    inactive_rejected = 0
    duplicate_rejected = 0
    non_free_rejected = 0
    none_mismatch = 0
    zero_none_max = 0.0
    zero_none_bit_mismatch = 0
    zero_auxiliary_mismatch = 0
    rho_schedule_timestamp_mismatch = 0
    rho_schedule_object_id_mismatch = 0
    rho_schedule_impulse_max = 0.0
    rho_position_max = 0.0
    rho_velocity_max = 0.0
    rho_cost_max = 0.0
    opposite_trajectory_mismatch = 0
    opposite_uncertainty_mismatch = 0
    opposite_active_event_mismatch = 0
    opposite_truth_cost_max = 0.0
    pre_position_max = 0.0
    pre_velocity_max = 0.0
    distractor_position_max = 0.0
    distractor_velocity_max = 0.0
    variance_max = 0.0
    controlled_events = 0
    distractor_events = 0
    non_action_events = 0
    terminal_free = 0
    terminal_free_total = 0
    action_terminal_active_mismatch = 0
    source_belief_mismatch = 0
    source_belief_aliases = 0
    cross_candidate_aliases = 0
    sign_impulse_max = 0.0
    sign_position_max = 0.0
    sign_velocity_max = 0.0
    palette_position_max = 0.0
    palette_velocity_max = 0.0
    palette_cost_max = 0.0
    palette_choice_matches = 0
    palette_choice_total = 0
    ordinal_evidence: dict[int, tuple[str, int]] = {}
    optimum_histogram = torch.zeros(CANDIDATE_COUNT, dtype=torch.int64)
    belief_module = importlib.import_module("world_model.belief")

    for record in records:
        plan = record["plan"]
        public_position = record["public_positions"]
        public_velocity = record["public_velocities"]
        none_position = record["none_positions"]
        none_velocity = record["none_velocities"]
        truth_position = record["truth_position"]
        truth_velocity = record["truth_velocity"]
        truth_none_position = record["truth_none_position"][:, None]
        truth_none_velocity = record["truth_none_velocity"][:, None]
        action_delta_position_errors.append(
            ((public_position - none_position) - (truth_position - truth_none_position)).abs()
        )
        action_delta_velocity_errors.append(
            ((public_velocity - none_velocity) - (truth_velocity - truth_none_velocity)).abs()
        )
        conditioned_position_errors.append((public_position - truth_position).abs())
        conditioned_velocity_errors.append((public_velocity - truth_velocity).abs())
        cost_errors.append((plan.total_cost - record["truth_cost"]).abs())
        truth_sorted = record["truth_cost"].sort(dim=-1).values
        public_sorted = plan.total_cost.sort(dim=-1).values
        truth_gaps.append(truth_sorted[:, 1] - truth_sorted[:, 0])
        public_gaps.append(public_sorted[:, 1] - public_sorted[:, 0])
        handle_margins.append(record["handle_margin"])

        canonical_order = record["canonical_order"]
        pi_selected = canonical_order.gather(1, plan.selected_index[:, None]).squeeze(1)
        rho_orders = torch.stack(
            [
                torch.tensor(
                    scene.candidate_order(specification.camera_stratum, order="rho"),
                    dtype=torch.int64,
                )
                for specification in record["specifications"]
            ]
        )
        rho_selected = rho_orders.gather(1, record["rho_plan"].selected_index[:, None]).squeeze(1)
        opposite_selected = canonical_order.gather(
            1, record["opposite_plan"].selected_index[:, None]
        ).squeeze(1)
        rho_for_pi = rho_orders[:, None].eq(canonical_order[:, :, None]).to(torch.int64).argmax(-1)
        rho_positions = torch.stack(
            [trajectory.positions for trajectory in record["rho_plan"].trajectories],
            dim=1,
        )
        rho_velocities = torch.stack(
            [trajectory.velocities for trajectory in record["rho_plan"].trajectories],
            dim=1,
        )
        aligned_rho_positions = torch.gather(
            rho_positions,
            1,
            rho_for_pi[..., None, None, None].expand_as(rho_positions),
        )
        aligned_rho_velocities = torch.gather(
            rho_velocities,
            1,
            rho_for_pi[..., None, None, None].expand_as(rho_velocities),
        )
        aligned_rho_cost = torch.gather(record["rho_plan"].total_cost, 1, rho_for_pi)
        rho_position_max = max(
            rho_position_max,
            float((aligned_rho_positions - public_position).abs().max()),
        )
        rho_velocity_max = max(
            rho_velocity_max,
            float((aligned_rho_velocities - public_velocity).abs().max()),
        )
        rho_cost_max = max(
            rho_cost_max,
            float((aligned_rho_cost - plan.total_cost).abs().max()),
        )
        safe = record["safe"]
        safe_rho = record["safe_rho"]
        aligned_rho_timestamps = torch.gather(
            safe_rho["candidate_timestamps"],
            1,
            rho_for_pi,
        )
        aligned_rho_impulses = torch.gather(
            safe_rho["candidate_impulses_world"],
            1,
            rho_for_pi[..., None].expand_as(safe_rho["candidate_impulses_world"]),
        )
        rho_schedule_timestamp_mismatch += _exact_tensor_mismatch_count(
            aligned_rho_timestamps,
            safe["candidate_timestamps"],
        )
        rho_schedule_impulse_max = max(
            rho_schedule_impulse_max,
            float((aligned_rho_impulses - safe["candidate_impulses_world"]).abs().max()),
        )
        rho_schedule_object_id_mismatch += int(record["rho_id"].ne(record["resolved_id"]).sum())

        for ordinary_trajectory, opposite_trajectory in zip(
            plan.trajectories,
            record["opposite_plan"].trajectories,
            strict=True,
        ):
            opposite_trajectory_mismatch += sum(
                _exact_tensor_mismatch_count(
                    getattr(ordinary_trajectory, name),
                    getattr(opposite_trajectory, name),
                )
                for name in (
                    "timestamps",
                    "positions",
                    "velocities",
                    "orientations",
                    "motion_mode_logits",
                )
            )
            opposite_uncertainty_mismatch += _exact_tensor_mismatch_count(
                ordinary_trajectory.fast_log_variance,
                opposite_trajectory.fast_log_variance,
            )
            opposite_active_event_mismatch += sum(
                _exact_tensor_mismatch_count(
                    getattr(ordinary_trajectory, name),
                    getattr(opposite_trajectory, name),
                )
                for name in ("active_mask", "event_logits")
            )
            opposite_active_event_mismatch += _tensor_structure_mismatch_count(
                ordinary_trajectory.auxiliary,
                opposite_trajectory.auxiliary,
                label="ordinary/opposite trajectory auxiliary",
            )
        opposite_uncertainty_mismatch += _exact_tensor_mismatch_count(
            plan.terminal_position_variance,
            record["opposite_plan"].terminal_position_variance,
        )
        opposite_truth_cost_max = max(
            opposite_truth_cost_max,
            float((record["opposite_plan"].total_cost - record["opposite_truth_cost"]).abs().max()),
        )
        expected = torch.tensor(
            [specification.optimal_canonical_index for specification in record["specifications"]],
            dtype=torch.int64,
        )
        opposite_expected = expected ^ 7
        pi_matches += int(pi_selected.eq(expected).sum())
        rho_matches += int(rho_selected.eq(expected).sum())
        opposite_matches += int(opposite_selected.eq(opposite_expected).sum())
        optimum_histogram.scatter_add_(0, expected, torch.ones_like(expected))
        expected_display = canonical_order.eq(expected[:, None]).to(torch.int64).argmax(-1)
        batch_index = torch.arange(BATCH_SIZE)
        optimal_errors.append(
            plan.terminal_squared_error[batch_index, expected_display].clamp_min(0.0).sqrt()
        )
        optimal_costs.append(plan.total_cost[batch_index, expected_display])

        ids = record["resolved_id"]
        object_ids = plan.object_id_by_slot
        matches = object_ids.eq(ids[:, None])
        resolution_count += int(ids.ge(0).sum())
        unique_resolution_count += int(matches.sum(dim=-1).eq(1).sum())
        wrong_distinct += int(record["wrong_id"].ne(ids).sum())
        wrong_other_nonzero += int(
            record["wrong_other_delta"]
            .abs()
            .reshape(BATCH_SIZE, -1)
            .max(dim=-1)
            .values.gt(0.0)
            .sum()
        )
        wrong_cost_worse += int(
            record["wrong_plan"]
            .total_cost.min(dim=-1)
            .values.gt(plan.total_cost.min(dim=-1).values)
            .sum()
        )
        rejection_counts = record["rejection_counts"]
        if type(rejection_counts) is not dict or set(rejection_counts) != {
            "ambiguous",
            "invalid",
            "pre_anchor",
            "equal_anchor",
            "inactive",
            "duplicate",
            "non_free",
        }:
            raise RuntimeError("action rejection control inventory differs")
        if any(
            type(value) is not int or not 0 <= value <= BATCH_SIZE
            for value in rejection_counts.values()
        ):
            raise RuntimeError("action rejection control count is malformed")
        invalid_rejected += rejection_counts["invalid"]
        ambiguous_rejected += rejection_counts["ambiguous"]
        pre_anchor_rejected += rejection_counts["pre_anchor"]
        equal_anchor_rejected += rejection_counts["equal_anchor"]
        inactive_rejected += rejection_counts["inactive"]
        duplicate_rejected += rejection_counts["duplicate"]
        non_free_rejected += rejection_counts["non_free"]
        none_mismatch += int(record["none_repeat_mismatch"])
        zero = record["zero"]
        none = record["none"]
        zero_none_max = max(
            zero_none_max,
            float((zero.positions - none.positions).abs().max()),
            float((zero.velocities - none.velocities).abs().max()),
            float((zero.fast_log_variance - none.fast_log_variance).abs().max()),
            float((zero.event_logits - none.event_logits).abs().max()),
        )
        zero_none_bit_mismatch += sum(
            _exact_tensor_mismatch_count(getattr(zero, name), getattr(none, name))
            for name in (
                "timestamps",
                "positions",
                "velocities",
                "orientations",
                "motion_mode_logits",
                "fast_log_variance",
                "active_mask",
                "event_logits",
            )
        )
        known_action_auxiliary = frozenset({"known_action_applied", "known_impulse_world"})
        zero_auxiliary = {
            key: value for key, value in zero.auxiliary.items() if key not in known_action_auxiliary
        }
        none_auxiliary = {
            key: value for key, value in none.auxiliary.items() if key not in known_action_auxiliary
        }
        if set(zero_auxiliary) != set(none_auxiliary):
            zero_auxiliary_mismatch += max(
                len(set(zero_auxiliary) ^ set(none_auxiliary)),
                1,
            )
        zero_auxiliary_mismatch += sum(
            _exact_tensor_mismatch_count(zero_auxiliary[name], none_auxiliary[name])
            for name in set(zero_auxiliary) & set(none_auxiliary)
        )
        for auxiliary in (zero.auxiliary, none.auxiliary):
            for name in known_action_auxiliary & set(auxiliary):
                value = auxiliary[name]
                if not isinstance(value, torch.Tensor):
                    zero_auxiliary_mismatch += 1
                else:
                    zero_auxiliary_mismatch += int(value.ne(0).sum().detach().cpu())
        pre_position_max = max(
            pre_position_max,
            float((public_position[:, :, :2] - none_position[:, :, :2]).abs().max()),
        )
        pre_velocity_max = max(
            pre_velocity_max,
            float((public_velocity[:, :, :2] - none_velocity[:, :, :2]).abs().max()),
        )
        target_slot = matches.to(torch.int64).argmax(-1)
        for batch_index_value in range(BATCH_SIZE):
            distractor = 1 - int(target_slot[batch_index_value])
            distractor_position_max = max(
                distractor_position_max,
                float(
                    (
                        public_position[batch_index_value, :, :, distractor]
                        - none_position[batch_index_value, :, :, distractor]
                    )
                    .abs()
                    .max()
                ),
            )
            distractor_velocity_max = max(
                distractor_velocity_max,
                float(
                    (
                        public_velocity[batch_index_value, :, :, distractor]
                        - none_velocity[batch_index_value, :, :, distractor]
                    )
                    .abs()
                    .max()
                ),
            )
        action_variances = torch.stack(
            [trajectory.fast_log_variance for trajectory in plan.trajectories], dim=1
        )
        variance_max = max(
            variance_max,
            float((action_variances - none.fast_log_variance[:, None]).abs().max()),
        )
        for trajectory in plan.trajectories:
            applied = trajectory.auxiliary.get("known_action_applied")
            if not isinstance(applied, torch.Tensor) or applied.shape != (BATCH_SIZE, 5, 2):
                raise RuntimeError("known-action trajectory omitted typed event auxiliaries")
            controlled_events += int(
                applied.gather(
                    2,
                    target_slot[:, None, None].expand(BATCH_SIZE, 5, 1),
                ).sum()
            )
            distractor_events += int(applied.sum()) - int(
                applied.gather(
                    2,
                    target_slot[:, None, None].expand(BATCH_SIZE, 5, 1),
                ).sum()
            )
        none_modes = none.event_logits.argmax(dim=-1)
        non_action_events += int(none_modes.ne(int(belief_module.MotionMode.FREE)).sum())
        final_modes = torch.stack(
            [trajectory.event_logits[:, -1].argmax(dim=-1) for trajectory in plan.trajectories],
            dim=1,
        )
        active = torch.stack(
            [trajectory.active_mask[:, -1] for trajectory in plan.trajectories], dim=1
        )
        action_terminal_active_mismatch += sum(
            _exact_tensor_mismatch_count(
                trajectory.active_mask[:, -1],
                none.active_mask[:, -1],
            )
            for trajectory in plan.trajectories
        )
        terminal_free += int((final_modes.eq(int(belief_module.MotionMode.FREE)) & active).sum())
        terminal_free_total += int(active.sum())

        source_belief_mismatch += int(record["source_belief_bit_mismatch_count"])
        live_belief = record["output"]["model"].belief
        if live_belief is None:
            raise RuntimeError("source-belief alias audit requires a live public belief")
        rollout_outputs = (
            *plan.trajectories,
            *record["rho_plan"].trajectories,
            *record["opposite_plan"].trajectories,
            *record["wrong_plan"].trajectories,
            none,
            zero,
        )
        source_belief_aliases += sum(
            _tensor_structure_storage_alias_count(
                live_belief,
                trajectory,
                label="source belief/rollout output",
            )
            for trajectory in rollout_outputs
        )
        cross_candidate_aliases += sum(
            _tensor_structure_storage_alias_count(
                plan.trajectories[left],
                plan.trajectories[right],
                label="cross-candidate rollout outputs",
            )
            for left in range(CANDIDATE_COUNT)
            for right in range(left + 1, CANDIDATE_COUNT)
        )

        impulses = record["safe"]["candidate_impulses_world"]
        for batch_index_value in range(BATCH_SIZE):
            for display in range(CANDIDATE_COUNT):
                negative = (
                    impulses[batch_index_value]
                    .eq(-impulses[batch_index_value, display])
                    .all(dim=-1)
                )
                if int(negative.sum()) != 1:
                    raise RuntimeError("candidate impulse family lacks one exact sign partner")
                partner = int(torch.nonzero(negative).item())
                sign_impulse_max = max(
                    sign_impulse_max,
                    float(
                        (
                            impulses[batch_index_value, display]
                            + impulses[batch_index_value, partner]
                        )
                        .abs()
                        .max()
                    ),
                )
                sign_position_max = max(
                    sign_position_max,
                    float(
                        (
                            public_position[batch_index_value, display]
                            + public_position[batch_index_value, partner]
                            - 2.0 * none.positions[batch_index_value]
                        )
                        .abs()
                        .max()
                    ),
                )
                sign_velocity_max = max(
                    sign_velocity_max,
                    float(
                        (
                            public_velocity[batch_index_value, display]
                            + public_velocity[batch_index_value, partner]
                            - 2.0 * none.velocities[batch_index_value]
                        )
                        .abs()
                        .max()
                    ),
                )
        palette_position_max = max(
            palette_position_max, float(record["palette_position_error"].max())
        )
        palette_velocity_max = max(
            palette_velocity_max, float(record["palette_velocity_error"].max())
        )
        palette_cost_max = max(palette_cost_max, float(record["palette_cost_error"].max()))
        palette_choice_matches += int(record["palette_choice_match"].sum())
        palette_choice_total += int(record["palette_choice_match"].numel())
        for offset, ordinal in enumerate(record["ordinals"]):
            ordinal_evidence[int(ordinal)] = (
                record["observation_hashes"][offset],
                int(record["resolved_id"][offset]),
            )

    role_observation_matches = 0
    role_distinct_ids = 0
    for ordinal in range(SCENES_PER_SPLIT):
        twin = ordinal ^ 8
        if ordinal < twin:
            left = ordinal_evidence[ordinal]
            right = ordinal_evidence[twin]
            role_observation_matches += int(left[0] == right[0])
            role_distinct_ids += int(left[1] != right[1])

    palette = torch.tensor(scene.HANDLE_PROTOTYPES, dtype=torch.float64)
    palette = palette / torch.linalg.vector_norm(palette, dim=-1, keepdim=True)
    certificate_palette_margin = float(1.0 - (palette[0] * palette[1]).sum())
    first_model = records[0]["output"]["model"]
    learned = tuple(parameter for parameter in first_model.parameters() if parameter.requires_grad)
    buffers = tuple(first_model.buffers())
    state_values = tuple(first_model.state_dict().values())
    if terminal_free_total <= 0:
        raise RuntimeError("action aggregation observed no active terminal object")
    metrics: dict[str, float] = {
        "batched_k8_planning_median_seconds": float(median(planning_seconds)),
        "batched_k8_planning_p95_seconds": float(planning_seconds[p95_index]),
        "batched_k8_planning_rss_delta_bytes": float(
            max(record["planning_rss_delta_bytes"] for record in records)
        ),
        "batched_k8_process_max_rss_bytes": float(
            max(record["process_max_rss_bytes"] for record in records)
        ),
        "batched_k8_live_result_storage_bytes": float(
            max(record["live_result_storage_bytes"] for record in records)
        ),
        "public_action_delta_position_max_abs_m": float(
            torch.cat([value.reshape(-1) for value in action_delta_position_errors]).max()
        ),
        "public_action_delta_velocity_max_abs_mps": float(
            torch.cat([value.reshape(-1) for value in action_delta_velocity_errors]).max()
        ),
        "public_action_conditioned_position_max_abs_m": float(
            torch.cat([value.reshape(-1) for value in conditioned_position_errors]).max()
        ),
        "public_action_conditioned_velocity_max_abs_mps": float(
            torch.cat([value.reshape(-1) for value in conditioned_velocity_errors]).max()
        ),
        "public_planner_cost_max_abs_error_m2": float(
            torch.cat([value.reshape(-1) for value in cost_errors]).max()
        ),
        "certificate_minimum_truth_cost_gap_m2": float(torch.cat(truth_gaps).min()),
        "minimum_end_to_end_winner_cost_gap_m2": float(torch.cat(public_gaps).min()),
        "winner_accuracy_fraction": float(pi_matches / SCENES_PER_SPLIT),
        "optimal_candidate_terminal_error_l2_max_m": float(torch.cat(optimal_errors).max()),
        "optimal_candidate_terminal_cost_max_m2": float(torch.cat(optimal_costs).max()),
        "certificate_minimum_palette_handle_margin": certificate_palette_margin,
        "minimum_observed_appearance_handle_margin": float(torch.cat(handle_margins).min()),
        "appearance_handle_resolution_fraction": float(resolution_count / SCENES_PER_SPLIT),
        "appearance_handle_persistent_id_uniqueness": float(
            unique_resolution_count / SCENES_PER_SPLIT
        ),
        "runtime_truth_mapping_access_count": 0.0,
        "opposite_goal_winner_switch_fraction": float(opposite_matches / SCENES_PER_SPLIT),
        "pi_permutation_winner_match_fraction": float(pi_matches / SCENES_PER_SPLIT),
        "rho_permutation_winner_match_fraction": float(rho_matches / SCENES_PER_SPLIT),
        "rho_schedule_timestamp_mismatch_count": float(rho_schedule_timestamp_mismatch),
        "rho_schedule_object_id_mismatch_count": float(rho_schedule_object_id_mismatch),
        "rho_schedule_impulse_max_abs": float(rho_schedule_impulse_max),
        "rho_permutation_position_max_abs_m": float(rho_position_max),
        "rho_permutation_velocity_max_abs_mps": float(rho_velocity_max),
        "rho_permutation_cost_max_abs_m2": float(rho_cost_max),
        "opposite_goal_trajectory_bit_mismatch_count": float(opposite_trajectory_mismatch),
        "opposite_goal_uncertainty_bit_mismatch_count": float(opposite_uncertainty_mismatch),
        "opposite_goal_active_event_bit_mismatch_count": float(opposite_active_event_mismatch),
        "opposite_goal_truth_cost_max_abs_error_m2": float(opposite_truth_cost_max),
        "zero_impulse_none_max_abs": float(zero_none_max),
        "zero_impulse_none_bit_mismatch_count": float(zero_none_bit_mismatch),
        "zero_impulse_auxiliary_mismatch_count": float(zero_auxiliary_mismatch),
        "none_action_bit_mismatch_count": float(none_mismatch),
        "wrong_handle_resolution_to_distinct_id_fraction": float(wrong_distinct / SCENES_PER_SPLIT),
        "wrong_handle_intended_object_delta_max_abs": float(
            max(float(record["wrong_intended_delta"].abs().max()) for record in records)
        ),
        "wrong_handle_other_object_nonzero_fraction": float(wrong_other_nonzero / SCENES_PER_SPLIT),
        "wrong_handle_cost_worsening_fraction": float(wrong_cost_worse / SCENES_PER_SPLIT),
        "invalid_persistent_id_rejection_fraction": float(invalid_rejected / SCENES_PER_SPLIT),
        "ambiguous_appearance_handle_rejection_fraction": float(
            ambiguous_rejected / SCENES_PER_SPLIT
        ),
        "pre_anchor_timestamp_rejection_fraction": float(pre_anchor_rejected / SCENES_PER_SPLIT),
        "equal_anchor_timestamp_rejection_fraction": float(
            equal_anchor_rejected / SCENES_PER_SPLIT
        ),
        "inactive_target_rejection_fraction": float(inactive_rejected / SCENES_PER_SPLIT),
        "duplicate_active_persistent_id_rejection_fraction": float(
            duplicate_rejected / SCENES_PER_SPLIT
        ),
        "non_free_target_rejection_fraction": float(non_free_rejected / SCENES_PER_SPLIT),
        "sign_flip_impulse_max_abs": float(sign_impulse_max),
        "sign_flip_position_antisymmetry_max_abs": float(sign_position_max),
        "sign_flip_velocity_antisymmetry_max_abs": float(sign_velocity_max),
        "pre_action_position_delta_max_abs_m": float(pre_position_max),
        "pre_action_velocity_delta_max_abs_mps": float(pre_velocity_max),
        "distractor_position_delta_max_abs_m": float(distractor_position_max),
        "distractor_velocity_delta_max_abs_mps": float(distractor_velocity_max),
        "fast_variance_action_delta_max_abs": float(variance_max),
        "known_action_events_per_nonzero_candidate": float(
            controlled_events / (SCENES_PER_SPLIT * CANDIDATE_COUNT)
        ),
        "known_action_events_on_distractor": float(distractor_events),
        "non_action_future_event_count": float(non_action_events),
        "terminal_free_mode_fraction": float(terminal_free / terminal_free_total),
        "action_terminal_active_mask_mismatch_count": float(action_terminal_active_mismatch),
        "source_belief_bit_mismatch_count": float(source_belief_mismatch),
        "source_belief_trajectory_storage_alias_count": float(source_belief_aliases),
        "cross_candidate_trajectory_storage_alias_count": float(cross_candidate_aliases),
        "task_bundle_count": float(SCENES_PER_SPLIT),
        "role_twin_pair_count": 32.0,
        "candidates_evaluated": float(SCENES_PER_SPLIT * CANDIDATE_COUNT),
        "certificate_candidate_profile_count": 2048.0,
        "role_twin_observation_identity_fraction": float(role_observation_matches / 32),
        "role_twin_resolved_id_distinct_fraction": float(role_distinct_ids / 32),
        "palette_twin_position_invariance_max_abs_m": float(palette_position_max),
        "palette_twin_velocity_invariance_max_abs_mps": float(palette_velocity_max),
        "palette_twin_cost_invariance_max_abs_m2": float(palette_cost_max),
        "palette_twin_choice_match_fraction": float(palette_choice_matches / palette_choice_total),
        "minimum_canonical_optimum_coverage_per_q": float(optimum_histogram.min()),
        "learned_parameter_count": float(sum(value.numel() for value in learned)),
        "module_tensor_buffer_count": float(len(buffers)),
        "persistent_module_state_key_count": float(len(state_values)),
        "optimizer_updates": 0.0,
        "optimizer_state_entry_count": 0.0,
        "rng_state_entry_count": 0.0,
    }
    gradient_metrics = (
        _action_gradient_metrics(records[0])
        if action_gradient_metrics is None
        else dict(action_gradient_metrics)
    )
    if action_sensor_metrics is None:
        if owner is None or config is None:
            raise RuntimeError("action sensor VJP audit requires its public owner and config")
        sensor_metrics = _action_sensor_vjp_metrics(
            records,
            scene=scene,
            owner=owner,
            config=config,
        )
    else:
        sensor_metrics = dict(action_sensor_metrics)
    for fragment_name, fragment in (
        ("action-gradient", gradient_metrics),
        ("action-sensor", sensor_metrics),
    ):
        overlap = set(metrics) & set(fragment)
        if overlap:
            raise RuntimeError(
                f"{fragment_name} metric fragment overlaps base metrics: {sorted(overlap)!r}"
            )
        metrics.update(fragment)
    if set(metrics) != set(GATE_METRIC_SCHEMA):
        raise RuntimeError(
            "action metric reducer differs from the exact schema: "
            f"missing={sorted(set(GATE_METRIC_SCHEMA) - set(metrics))!r}, "
            f"extra={sorted(set(metrics) - set(GATE_METRIC_SCHEMA))!r}"
        )
    metrics = {name: metrics[name] for name in GATE_METRIC_SCHEMA}
    for name, value in metrics.items():
        if type(value) is not float or not math.isfinite(value):
            raise FloatingPointError(f"action metric {name!r} is not an exact finite float")
    return metrics


def _exact_materializer_terminal_tombstone_cut() -> bool:
    """Pure deep check before test-only terminal registry disposal."""

    if (
        type(_MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY) is not dict
        or type(_TRUSTED_MATERIALIZER_PORT_REGISTRY) is not dict
        or type(_MATERIALIZER_SPLIT_VAULT_REGISTRY) is not dict
        or type(_MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY) is not dict
        or type(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY) is not dict
        or type(_PUBLIC_SENSOR_BATCH_REGISTRY) is not dict
        or type(_SAFE_TASK_BATCH_REGISTRY) is not dict
        or type(_SEALED_MATERIALIZATION_ROW_REGISTRY) is not dict
        or type(_MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY) is not dict
        or type(_FORMAL_EVALUATOR_INITIALIZATION_REGISTRY) is not dict
        or type(_MATERIALIZER_BLINDING_NONCE_SHA256_REGISTRY) is not set
        or _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY
        or _CONSUMED_ORDINAL_REGISTRY
        or _BATCH_REGISTRY
        or _TOKEN_REGISTRY
        or any(
            type(value) is not str or not _exact_lower_sha256(value)
            for value in _MATERIALIZER_BLINDING_NONCE_SHA256_REGISTRY
        )
    ):
        return False
    initialized_evaluators: dict[int, _FormalKnownActionEvaluator] = {}
    for identity, evaluator in tuple(_FORMAL_EVALUATOR_INITIALIZATION_REGISTRY.items()):
        if (
            type(identity) is not int
            or type(evaluator) is not _FormalKnownActionEvaluator
            or identity != id(evaluator)
            or identity in initialized_evaluators
        ):
            return False
        initialized_evaluators[identity] = evaluator
    construction_registrations: dict[int, _MaterializerConstructionRegistration] = {}
    for identity, registration in tuple(_MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.items()):
        if (
            not _exact_materializer_construction_registration(identity, registration)
            or identity in construction_registrations
        ):
            return False
        construction_registrations[identity] = registration
    ports: dict[int, _MaterializerPortRegistration] = {}
    for identity, registration in tuple(_TRUSTED_MATERIALIZER_PORT_REGISTRY.items()):
        if (
            type(identity) is not int
            or type(registration) is not _MaterializerPortRegistration
            or type(registration.port) is not _TrustedMaterializerPort
            or identity != id(registration.port)
            or type(registration.authority) is not _MaterializerConstructionAuthority
            or type(registration.ledger) is not _AccessLedger
            or type(registration.config) is not dict
            or type(registration.evaluator) is not _FormalKnownActionEvaluator
            or type(registration.binding) is not tuple
            or type(registration.state) is not str
            or registration.state not in {"closed", "failed", "revoked"}
            or identity in ports
        ):
            return False
        construction = construction_registrations.get(id(registration.authority))
        try:
            binding_matches = _exact_native_binding_equal(
                registration.binding,
                _trusted_materializer_port_binding(registration.port),
            )
            config_matches = registration.port.config_sha256 == _materializer_config_sha256(
                registration.config
            )
        except BaseException:
            return False
        if (
            type(construction) is not _MaterializerConstructionRegistration
            or construction.authority is not registration.authority
            or construction.ledger is not registration.ledger
            or construction.config is not registration.config
            or not binding_matches
            or not config_matches
            or registration.port.construction_authority_identity != id(registration.authority)
            or registration.port.construction_authority_nonce is not registration.authority.nonce
            or registration.port.ledger_identity != id(registration.ledger)
            or registration.port.directory_pin is not registration.ledger._pin
            or registration.port.ledger_path != registration.ledger.path
            or registration.port.config_identity != id(registration.config)
            or registration.port.owner_thread != registration.ledger._owner_thread
            or (registration.state in {"closed", "revoked"} and construction.state != "consumed")
            or (registration.state == "failed" and construction.state not in {"consumed", "failed"})
        ):
            return False
        ports[identity] = registration
    ports_by_authority: dict[int, list[_MaterializerPortRegistration]] = {}
    for registration in ports.values():
        ports_by_authority.setdefault(id(registration.authority), []).append(registration)
    for identity, construction in construction_registrations.items():
        owned_ports = ports_by_authority.get(identity, [])
        if construction.state == "consumed":
            if len(owned_ports) != 1:
                return False
            evaluator = owned_ports[0].evaluator
            if (
                type(evaluator) is not _FormalKnownActionEvaluator
                or initialized_evaluators.get(id(evaluator)) is not evaluator
            ):
                return False
        elif construction.state == "failed":
            if len(owned_ports) > 1 or any(
                registration.state != "failed" for registration in owned_ports
            ):
                return False
        elif construction.state == "revoked":
            if owned_ports:
                return False
        else:
            return False
    allowed_initialized_evaluators = {id(registration.evaluator) for registration in ports.values()}
    required_initialized_evaluators = {
        id(registration.evaluator)
        for registration in ports.values()
        if construction_registrations[id(registration.authority)].state == "consumed"
    }
    if not (
        required_initialized_evaluators
        <= set(initialized_evaluators)
        <= allowed_initialized_evaluators
    ):
        return False
    child_specifications = (
        (_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY, "envelope"),
        (_PUBLIC_SENSOR_BATCH_REGISTRY, "sensor"),
        (_SAFE_TASK_BATCH_REGISTRY, "task"),
        (_SEALED_MATERIALIZATION_ROW_REGISTRY, "row"),
    )
    for registry, kind in child_specifications:
        for identity, registration in tuple(registry.items()):
            if not _exact_materializer_child_registration(
                identity,
                registration,
                kind=kind,
            ):
                return False
    roots: dict[int, _MaterializerVaultRegistration] = {}
    for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items()):
        if (
            not _exact_materializer_vault_root_registration(identity, registration)
            or type(registration) is not _MaterializerVaultRegistration
            or registration.state not in MATERIALIZER_TERMINAL_VAULT_STATES
            or id(registration.port) not in ports
            or ports[id(registration.port)].port is not registration.port
            or ports[id(registration.port)].ledger is not registration.ledger
            or identity in roots
        ):
            return False
        roots[identity] = registration
    allowed_slots = {
        (id(registration.ledger), registration.vault.split): identity
        for identity, registration in roots.items()
    }
    required_slots = {
        slot: identity
        for slot, identity in allowed_slots.items()
        if roots[identity].state != "failed"
    }
    actual_slots: dict[tuple[int, str], int] = {}
    for slot, identity in tuple(_MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.items()):
        if (
            type(slot) is not tuple
            or len(slot) != 2
            or type(slot[0]) is not int
            or type(slot[1]) is not str
            or slot[1] not in SPLITS
            or type(identity) is not int
            or slot in actual_slots
        ):
            return False
        actual_slots[slot] = identity
    if any(actual_slots.get(slot) != identity for slot, identity in required_slots.items()) or any(
        allowed_slots.get(slot) != identity for slot, identity in actual_slots.items()
    ):
        return False
    expected_envelopes = {
        id(value) for registration in roots.values() for value in registration.envelopes
    }
    expected_sensor_batches = {
        id(value) for registration in roots.values() for value in registration.sensor_batches
    }
    expected_task_batches = {
        id(value) for registration in roots.values() for value in registration.task_batches
    }
    expected_rows = {id(value) for registration in roots.values() for value in registration.rows}
    # An interrupted issued B=4 envelope has four sealed row registrations
    # before those rows join the durable/evaluated root prefix.  Terminal
    # cleanup still owns and must authenticate that envelope-local inventory.
    expected_rows.update(
        id(row)
        for envelope_identity in expected_envelopes
        for row in _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY[envelope_identity].rows
    )
    return bool(
        set(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY) == expected_envelopes
        and set(_PUBLIC_SENSOR_BATCH_REGISTRY) == expected_sensor_batches
        and set(_SAFE_TASK_BATCH_REGISTRY) == expected_task_batches
        and set(_SEALED_MATERIALIZATION_ROW_REGISTRY) == expected_rows
    )


def _clear_ephemeral_registries_for_tests() -> None:
    # Materializer registries are formal-only.  Scan them without lookups or
    # rich equality: a completely scrubbed terminal tombstone may be cleared,
    # but every live/malformed/orphan payload must block cleanup itself.
    materializer_registries_present = bool(
        _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY
        or _TRUSTED_MATERIALIZER_PORT_REGISTRY
        or _MATERIALIZER_SPLIT_VAULT_REGISTRY
        or _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY
        or _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY
        or _PUBLIC_SENSOR_BATCH_REGISTRY
        or _SAFE_TASK_BATCH_REGISTRY
        or _SEALED_MATERIALIZATION_ROW_REGISTRY
        or _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY
    )
    materializer_state_present = bool(
        _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY
        or (materializer_registries_present and not _exact_materializer_terminal_tombstone_cut())
    )
    if not materializer_state_present:
        for identity, registration in tuple(_TRUSTED_MATERIALIZER_PORT_REGISTRY.items()):
            if (
                type(identity) is not int
                or type(registration) is not _MaterializerPortRegistration
                or type(registration.port) is not _TrustedMaterializerPort
                or identity != id(registration.port)
                or type(registration.state) is not str
                or registration.state not in {"closed", "failed", "revoked"}
            ):
                materializer_state_present = True
                break
    if not materializer_state_present:
        for identity, registration in tuple(_MATERIALIZER_SPLIT_VAULT_REGISTRY.items()):
            if (
                type(identity) is not int
                or type(registration) is not _MaterializerVaultRegistration
                or type(registration.vault) is not _MaterializerSplitVault
                or identity != id(registration.vault)
                or type(registration.state) is not str
                or registration.state not in MATERIALIZER_TERMINAL_VAULT_STATES
                or registration.terminal_marker is not _MATERIALIZER_VAULT_TERMINAL_MARKER
                or registration.private_request is not None
                or registration.private_request_binding is not None
                or registration.commitment_inventory_sha256 is not None
            ):
                materializer_state_present = True
                break
    if not materializer_state_present:
        for identity, registration in tuple(_PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.items()):
            if (
                type(identity) is not int
                or type(registration) is not _MaterializerEnvelopeRegistration
                or type(registration.envelope) is not _PublicMaterializationEnvelope
                or identity != id(registration.envelope)
                or type(registration.state) is not str
                or registration.state != "retired"
                or registration.request is not None
                or registration.sensor_batch is not None
                or registration.task_batch is not None
                or registration.runtime_tensors is not None
                or registration.public_bodies is not None
                or registration.blinding_nonces is not None
                or registration.evaluation_hashes is not None
                or registration.evaluation_hashes_binding_sha256 is not None
            ):
                materializer_state_present = True
                break
    if not materializer_state_present:
        for registry in (_PUBLIC_SENSOR_BATCH_REGISTRY, _SAFE_TASK_BATCH_REGISTRY):
            for identity, registration in tuple(registry.items()):
                if (
                    type(identity) is not int
                    or type(registration) is not _MaterializerTensorBatchRegistration
                    or identity != id(registration.batch)
                    or type(registration.state) is not str
                    or registration.state not in {"retired", "revoked"}
                    or registration.tensors is not None
                ):
                    materializer_state_present = True
                    break
            if materializer_state_present:
                break
    if not materializer_state_present:
        for identity, registration in tuple(_SEALED_MATERIALIZATION_ROW_REGISTRY.items()):
            if (
                type(identity) is not int
                or type(registration) is not _MaterializerRowRegistration
                or type(registration.row) is not _SealedMaterializationRow
                or identity != id(registration.row)
                or type(registration.state) is not str
                or registration.state not in {"retired", "revoked"}
            ):
                materializer_state_present = True
                break
    if not materializer_state_present:
        terminal_vault_identities = {
            identity
            for identity, registration in _MATERIALIZER_SPLIT_VAULT_REGISTRY.items()
            if type(identity) is int and type(registration) is _MaterializerVaultRegistration
        }
        for slot, vault_identity in tuple(_MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.items()):
            if (
                type(slot) is not tuple
                or len(slot) != 2
                or type(slot[0]) is not int
                or type(slot[1]) is not str
                or slot[1] not in SPLITS
                or type(vault_identity) is not int
                or vault_identity not in terminal_vault_identities
            ):
                materializer_state_present = True
                break
    formal_state_present = materializer_state_present or (
        any(seal.execution_mode == "formal" for seal, _ in _INVOCATION_SEAL_REGISTRY.values())
        or any(
            authorization.execution_mode == "formal"
            for authorization, _ in _RUN_AUTHORIZATION_REGISTRY.values()
        )
        or bool(_OUTER_RUNNER_AUTHORITY_REGISTRY)
        or bool(_OUTER_RECEIPT_IDENTITY_REGISTRY)
        or bool(_OUTER_AUTHORIZATION_IDENTITY_REGISTRY)
        or bool(_FORMAL_PIN_AUTHORITY_REGISTRY)
        or bool(_LEDGER_RECOVERY_AUTHORIZATION_REGISTRY)
        or any(
            type(registration[3]) is not str or registration[3] in {"issued", "consuming"}
            for registration in _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.values()
        )
        or any(
            type(registration.state) is not str or registration.state == "issued"
            for registration in _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.values()
        )
        or bool(_FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS)
        or bool(_MATERIALIZER_CONSTRUCTION_IN_PROGRESS)
        or any(
            type(registration.state) is not str or registration.state == "active"
            for registration in _TRUSTED_MATERIALIZER_PORT_REGISTRY.values()
        )
        or any(
            _materializer_vault_requires_cleanup(registration)
            for registration in _MATERIALIZER_SPLIT_VAULT_REGISTRY.values()
        )
        or any(
            type(registration.state) is not str
            or registration.state in MATERIALIZER_LIVE_CHILD_STATES
            for registration in _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.values()
        )
        or any(
            type(registration.state) is not str
            or registration.state in MATERIALIZER_LIVE_CHILD_STATES
            for registration in (
                *_PUBLIC_SENSOR_BATCH_REGISTRY.values(),
                *_SAFE_TASK_BATCH_REGISTRY.values(),
            )
        )
        or any(
            type(registration.state) is not str
            or registration.state in MATERIALIZER_LIVE_CHILD_STATES
            for registration in _SEALED_MATERIALIZATION_ROW_REGISTRY.values()
        )
        or any(
            registration[1]._ledger._record.get("execution_mode") == "formal"
            for registration in _TRUTH_AUTHORITY_REGISTRY.values()
        )
        or any(
            registration.manifest._ledger._record.get("execution_mode") == "formal"
            for registration in _BATCH_REGISTRY.values()
        )
        or any(
            registration[1].manifest._ledger._record.get("execution_mode") == "formal"
            for registration in _TOKEN_REGISTRY.values()
        )
        or any(
            registration[1]._manifest._ledger._record.get("execution_mode") == "formal"
            for registration in _CONSUMED_ORDINAL_REGISTRY.values()
        )
        or any(
            registration[1]._ledger._record.get("execution_mode") == "formal"
            for registration in _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.values()
        )
        or any(
            pin.ledger._record.get("execution_mode") == "formal"
            for pin in _LEDGER_REGISTRY.values()
        )
        or any(seal.execution_mode == "formal" for seal in _REVIEW_SEAL_REGISTRY.values())
    )
    if formal_state_present:
        raise PermissionError("test cleanup cannot mutate formal authority or ledger registries")
    _BATCH_REGISTRY.clear()
    _TOKEN_REGISTRY.clear()
    _TRUTH_AUTHORITY_REGISTRY.clear()
    _TRUTH_AUTHORITY_BINDING_REGISTRY.clear()
    _CONSUMED_ORDINAL_REGISTRY.clear()
    _REVIEW_SEAL_REGISTRY.clear()
    _INVOCATION_SEAL_REGISTRY.clear()
    _RUN_AUTHORIZATION_REGISTRY.clear()
    _LEDGER_RECOVERY_AUTHORIZATION_REGISTRY.clear()
    _EVALUATOR_CONSTRUCTION_AUTHORITY_REGISTRY.clear()
    _MATERIALIZER_CONSTRUCTION_AUTHORITY_REGISTRY.clear()
    _FORMAL_EVALUATOR_CONSTRUCTION_IN_PROGRESS.clear()
    _FORMAL_EVALUATOR_INITIALIZATION_REGISTRY.clear()
    _MATERIALIZER_CONSTRUCTION_IN_PROGRESS.clear()
    _TRUSTED_MATERIALIZER_PORT_REGISTRY.clear()
    _PUBLIC_SENSOR_BATCH_REGISTRY.clear()
    _SAFE_TASK_BATCH_REGISTRY.clear()
    _PUBLIC_MATERIALIZATION_ENVELOPE_REGISTRY.clear()
    _SEALED_MATERIALIZATION_ROW_REGISTRY.clear()
    _MATERIALIZER_SPLIT_VAULT_REGISTRY.clear()
    _MATERIALIZER_SPLIT_VAULT_SLOT_REGISTRY.clear()
    _MATERIALIZER_BLINDING_NONCE_SHA256_REGISTRY.clear()
    _MATERIALIZER_PUBLIC_BATCH_EVALUATION_REGISTRY.clear()
    _LEDGER_REGISTRY.clear()
    _LEDGER_SLOT_REGISTRY.clear()


def _formal_materializer_config(config: OrpheusConfig) -> dict[str, Any]:
    assert_known_action_config(config)
    value = asdict(config)
    if type(value) is not dict or not value:
        raise TypeError("formal resolved config did not produce one exact dictionary")
    _materializer_config_sha256(value)
    return value


def _guard_formal_inputs(
    *,
    ledger: _AccessLedger,
    source_provenance: Mapping[str, Any],
    config: OrpheusConfig,
) -> None:
    ledger._verify_disk()
    _require_scene_freeze()
    _activate_runtime_dependencies()
    assert_known_action_config(config)
    _exact_equal(
        capture_published_source(REPOSITORY_ROOT),
        _validated_source_provenance(copy.deepcopy(dict(source_provenance))),
        label="formal boundary source provenance",
    )


def run_development(*_args: Any, **kwargs: Any) -> int:
    """Run or recover the single governed known-action development attempt."""

    authority = kwargs.get("runner_authority")
    source = kwargs.get("source_provenance")
    if type(authority) is not _OuterRunnerAuthority or type(source) is not dict:
        raise PermissionError("development requires one outer-runner authority")
    _validate_outer_runner_authority(
        authority,
        stage="development",
        source_provenance=source,
    )
    directory_pin: _PinnedDirectory | None = None
    recovery_authorization: _LedgerRecoveryAuthorization | None = None
    ledger: _AccessLedger | None = None
    evaluator: _FormalKnownActionEvaluator | None = None
    results: list[dict[str, Any]] = []
    checkpoint: dict[str, Any] | None = None
    try:
        directory_pin = _acquire_pinned_directory(
            _canonical_run_directory(),
            create=True,
            canonical=True,
            outer_authority=authority,
        )
        disposition = _validated_invocation_inventory(
            directory_pin,
            stage="development",
        )
        if disposition == "recovery":
            recovery_authorization = _mint_ledger_recovery_authorization(
                authority,
                stage="development",
                directory_pin=directory_pin,
                source_provenance=source,
            )
            return _recover_existing_formal_attempt(
                directory_pin=directory_pin,
                stage="development",
                source_provenance=source,
                authorization=recovery_authorization,
            )
        _require_scene_freeze()
        _activate_runtime_dependencies()
        config = require_frozen_config(_frozen_config_path())
        materializer_config = _formal_materializer_config(config)
        formal_authorization = _formal_authorization_binding(authority)
        invocation_seal = _mint_runner_invocation_seal_from_outer(
            authority,
            stage="development",
            directory_pin=directory_pin,
            source_provenance=source,
        )
        bindings = _ledger_bindings(
            stage="development",
            execution_mode="formal",
            directory_pin=directory_pin,
            source_provenance=source,
            formal_authorization=formal_authorization,
        )
        authorization = _authorize_ledger_creation(
            invocation_seal=invocation_seal,
            stage="development",
            directory_pin=directory_pin,
            source_provenance=source,
            bindings=bindings,
            ledger_path=_artifact_paths(directory_pin)["development_ledger"],
        )
        ledger = _AccessLedger(
            _artifact_paths(directory_pin)["development_ledger"],
            stage="development",
            bindings=bindings,
            directory_pin=directory_pin,
            authorization=authorization,
        )
        evaluator_authority = ledger.mint_formal_evaluator_authority(materializer_config)
        evaluator = _FormalKnownActionEvaluator(
            materializer_config,
            authority=evaluator_authority,
        )

        def guard(_label: str) -> None:
            assert ledger is not None
            _guard_formal_inputs(
                ledger=ledger,
                source_provenance=source,
                config=config,
            )

        result = _evaluate_split(
            split="development",
            ledger=ledger,
            evaluator=evaluator,
            boundary_guard=guard,
        )
        results.append(result)
        _close_trusted_materializer_port(evaluator._materializer_port)
        guard("before development checkpoint and publication")
        if result["passed"]:
            checkpoint = _save_review_checkpoint(
                directory_pin,
                development_result=result,
                source_provenance=source,
                execution_mode="formal",
                formal_authorization=formal_authorization,
            )
        report_template = _report_root(
            stage="development",
            execution_mode="formal",
            source_provenance=source,
            results=results,
            pending_ledger_sha256=None,
            checkpoint=checkpoint,
            formal_authorization=formal_authorization,
        )
        ledger.prepare_publication(report_template)
        ledger.publish_prepared_report()
        ledger.finish()
        return 0 if result["passed"] else 1
    except BaseException as error:
        if evaluator is not None:
            with contextlib.suppress(BaseException):
                _revoke_trusted_materializer_port(evaluator._materializer_port)
        if directory_pin is not None:
            _persist_exception_report(
                directory_pin=directory_pin,
                stage="development",
                source_provenance=source,
                ledger=ledger,
                error=error,
                results=results,
                checkpoint=checkpoint,
            )
        raise
    finally:
        if recovery_authorization is not None:
            _revoke_ledger_recovery_authorization(recovery_authorization)
        if directory_pin is not None and _PIN_REGISTRY.get(id(directory_pin)) is directory_pin:
            _release_pinned_directory(directory_pin)


def run_qualification(*_args: Any, **kwargs: Any) -> int:
    """Run or recover selector, confirmation, then final exactly once."""

    authority = kwargs.get("runner_authority")
    source = kwargs.get("source_provenance")
    if type(authority) is not _OuterRunnerAuthority or type(source) is not dict:
        raise PermissionError("qualification requires one outer-runner authority")
    _validate_outer_runner_authority(
        authority,
        stage="qualification",
        source_provenance=source,
    )
    reviewed = _validated_reviewed_development(
        {
            "checkpoint_sha256": kwargs.get("reviewed_checkpoint_sha256"),
            "report_sha256": kwargs.get("reviewed_report_sha256"),
            "ledger_sha256": kwargs.get("reviewed_development_ledger_sha256"),
        }
    )
    directory_pin: _PinnedDirectory | None = None
    recovery_authorization: _LedgerRecoveryAuthorization | None = None
    ledger: _AccessLedger | None = None
    evaluator: _FormalKnownActionEvaluator | None = None
    results: list[dict[str, Any]] = []
    seal: _ReviewedDevelopmentSeal | None = None
    try:
        directory_pin = _acquire_pinned_directory(
            _canonical_run_directory(),
            create=True,
            canonical=True,
            outer_authority=authority,
        )
        disposition = _validated_invocation_inventory(
            directory_pin,
            stage="qualification",
        )
        if disposition == "recovery":
            recovery_authorization = _mint_ledger_recovery_authorization(
                authority,
                stage="qualification",
                directory_pin=directory_pin,
                source_provenance=source,
            )
            return _recover_existing_formal_attempt(
                directory_pin=directory_pin,
                stage="qualification",
                source_provenance=source,
                authorization=recovery_authorization,
                reviewed_development=reviewed,
            )
        _require_scene_freeze()
        _activate_runtime_dependencies()
        config = require_frozen_config(_frozen_config_path())
        materializer_config = _formal_materializer_config(config)
        reviewed, _, seal = _review_development_bundle(
            directory_pin=directory_pin,
            reviewed_checkpoint_sha256=reviewed["checkpoint_sha256"],
            reviewed_report_sha256=reviewed["report_sha256"],
            reviewed_development_ledger_sha256=reviewed["ledger_sha256"],
            expected_source=source,
            expected_execution_mode="formal",
        )
        formal_authorization = _formal_authorization_binding(authority)
        invocation_seal = _mint_runner_invocation_seal_from_outer(
            authority,
            stage="qualification",
            directory_pin=directory_pin,
            source_provenance=source,
            reviewed_development=reviewed,
        )
        bindings = _ledger_bindings(
            stage="qualification",
            execution_mode="formal",
            directory_pin=directory_pin,
            source_provenance=source,
            reviewed_development=reviewed,
            formal_authorization=formal_authorization,
        )
        authorization = _authorize_ledger_creation(
            invocation_seal=invocation_seal,
            stage="qualification",
            directory_pin=directory_pin,
            source_provenance=source,
            bindings=bindings,
            ledger_path=_artifact_paths(directory_pin)["qualification_ledger"],
            reviewed_development=reviewed,
        )
        ledger = _AccessLedger(
            _artifact_paths(directory_pin)["qualification_ledger"],
            stage="qualification",
            bindings=bindings,
            directory_pin=directory_pin,
            authorization=authorization,
        )
        evaluator_authority = ledger.mint_formal_evaluator_authority(materializer_config)
        evaluator = _FormalKnownActionEvaluator(
            materializer_config,
            authority=evaluator_authority,
        )

        def guard(_label: str) -> None:
            assert ledger is not None
            assert seal is not None
            _guard_formal_inputs(
                ledger=ledger,
                source_provenance=source,
                config=config,
            )
            _revalidate_reviewed_development(
                seal,
                expected_source=source,
                qualification_active=True,
            )

        for split in PROTECTED_SPLITS:
            result = _evaluate_split(
                split=split,
                ledger=ledger,
                evaluator=evaluator,
                boundary_guard=guard,
            )
            results.append(result)
            if not result["passed"]:
                break
        _close_trusted_materializer_port(evaluator._materializer_port)
        guard("before protected terminal publication")
        report_template = _report_root(
            stage="qualification",
            execution_mode="formal",
            source_provenance=source,
            results=results,
            pending_ledger_sha256=None,
            reviewed_development=reviewed,
            formal_authorization=formal_authorization,
        )
        _revalidate_reviewed_development(
            seal,
            expected_source=source,
            qualification_active=True,
        )
        ledger.prepare_publication(report_template)
        _, report, _ = ledger.publish_prepared_report()
        ledger.finish()
        return 0 if report["passed"] else 1
    except BaseException as error:
        if evaluator is not None:
            with contextlib.suppress(BaseException):
                _revoke_trusted_materializer_port(evaluator._materializer_port)
        if directory_pin is not None:
            _persist_exception_report(
                directory_pin=directory_pin,
                stage="qualification",
                source_provenance=source,
                ledger=ledger,
                error=error,
                results=results,
                reviewed_development=reviewed,
                reviewed_seal=seal,
            )
        raise
    finally:
        if recovery_authorization is not None:
            _revoke_ledger_recovery_authorization(recovery_authorization)
        if directory_pin is not None and _PIN_REGISTRY.get(id(directory_pin)) is directory_pin:
            _release_pinned_directory(directory_pin)


